struct PaginationParams {
    limit: Option<usize>,
    offset: Option<usize>,
}

/// Return the opaque, registry-assigned principal carried by an admitted
/// session. Compatibility display strings must never be promoted back into
/// authorization, ownership, separation-of-duties, or audit identity.
fn authenticated_principal_id(
    session: &AuthSession,
) -> Result<PrincipalId, (StatusCode, Json<Value>)> {
    session.principal_id.ok_or_else(status_403)
}

/// Test-only stand-in for the random opaque registry allocator. Reusing a
/// label within one test process returns the same independently random ID;
/// the label is never copied or hashed into principal authority.
#[cfg(test)]
fn test_principal_id(label: &str) -> PrincipalId {
    static IDS: OnceLock<std::sync::Mutex<std::collections::HashMap<String, PrincipalId>>> =
        OnceLock::new();
    let ids = IDS.get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()));
    let mut ids = ids.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
    *ids.entry(label.to_string()).or_insert_with(|| {
        PrincipalId::from_uuid(Uuid::new_v4()).expect("generated test principal is non-nil")
    })
}

#[cfg(test)]
fn bind_test_principal(session: &mut AuthSession, label: &str) -> PrincipalId {
    let principal_id = test_principal_id(label);
    session.display_user_id = principal_id.to_string();
    session.principal_id = Some(principal_id);
    principal_id
}

/// DB-backed proofs for the firmware exception maker/checker and atomic-audit
/// boundary. They skip only when no database URL was supplied.
#[cfg(test)]
mod firmware_exception_handler_security_tests {
    use super::*;
    use crate::database::DB_TEST_SERIAL;
    use ryuki_engine::auth::{APP_ROLE_DATACENTER_APPROVER, APP_ROLE_WINTEL_LINUX_OPERATOR};
    use sqlx::PgPool;

    async fn global_pool() -> Option<&'static PgPool> {
        let url = std::env::var("RYUKI_DATABASE_URL").ok()?;
        crate::database::try_connect_with_url(&url, 5, 1, 300, 30, 1800).await;
        let pool = crate::database::get_db().expect("configured DB must connect");
        crate::database::run_migrations(pool)
            .await
            .expect("firmware lifecycle migrations must apply");
        Some(pool)
    }

    fn actor(display_user_id: &str, roles: &[&str]) -> AuthSession {
        let principal_id =
            PrincipalId::from_uuid(Uuid::new_v4()).expect("test UUID is a non-nil principal");
        AuthSession {
            display_user_id: display_user_id.into(),
            principal_id: Some(principal_id),
            display_name: format!("Firmware test actor {display_user_id}"),
            roles: roles.iter().map(|role| (*role).to_string()).collect(),
            token_valid: true,
            actor_class: ryuki_engine::auth::ActorClass::VerifiedHuman,
            provider_mode: "test-verified".into(),
            site_scope: vec![],
            environment_scope: vec![],
        }
    }

    async fn seed_device(pool: &PgPool, id: &str) {
        sqlx::query("SELECT purge_firmware_exceptions_for_maintenance($1)")
            .bind(id)
            .execute(pool)
            .await
            .expect("clear firmware exception history for test device");
        sqlx::query("DELETE FROM firmware_records WHERE id = $1")
            .bind(id)
            .execute(pool)
            .await
            .expect("clear firmware test device");
        sqlx::query(
            "INSERT INTO firmware_records \
                (id, device_type, vendor, model, current_version, minimum_version, \
                 latest_version, eol_date, site, compliance_status) \
             VALUES ($1, 'Server', 'TestVendor', 'TestModel', '1.0', '2.0', '2.0', \
                     to_char(CURRENT_DATE + 365, 'YYYY-MM-DD'), 'TEST', 'NonCompliant')",
        )
        .bind(id)
        .execute(pool)
        .await
        .expect("seed firmware test device");
    }

    async fn cleanup_device(pool: &PgPool, id: &str) {
        sqlx::query("SELECT purge_firmware_exceptions_for_maintenance($1)")
            .bind(id)
            .execute(pool)
            .await
            .expect("clean firmware exception history");
        sqlx::query("DELETE FROM firmware_records WHERE id = $1")
            .bind(id)
            .execute(pool)
            .await
            .expect("clean firmware test device");
    }

    #[tokio::test]
    async fn execute_only_firmware_operator_cannot_enter_approval_boundary() {
        let operator = actor("firmware-execute-only", &[APP_ROLE_WINTEL_LINUX_OPERATOR]);
        let result = firmware_approve_exception(
            AuthExtractor(operator),
            Path("fwex-not-looked-up".into()),
            Json(FirmwareExceptionApprovalRequest {
                expected_version: 1,
            }),
        )
        .await;
        assert!(matches!(result, Err((StatusCode::FORBIDDEN, _))));
    }

    #[tokio::test]
    async fn firmware_exception_self_approval_fails_and_distinct_checker_succeeds() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set");
            return;
        };
        let device_id = format!("fw-security-sod-{}", Uuid::new_v4());
        seed_device(pool, &device_id).await;
        let maker = actor(
            "firmware-maker-checker-combined",
            &[APP_ROLE_WINTEL_LINUX_OPERATOR, APP_ROLE_DATACENTER_APPROVER],
        );
        let maker_principal_id = maker
            .principal_id
            .expect("verified test maker has an opaque principal")
            .to_string();
        let Json(created) = firmware_request_exception(
            AuthExtractor(maker.clone()),
            Json(FirmwareExceptionRequest {
                device_id: device_id.clone(),
                reason: "Temporary compatibility review".into(),
                expiry_days: 14,
            }),
        )
        .await
        .expect("verified maker creates Pending request");
        let exception_id = created["exception"]["id"]
            .as_str()
            .expect("exception id")
            .to_string();
        assert_eq!(
            created["exception"]["requested_by"].as_str(),
            Some(maker_principal_id.as_str()),
            "maker identity comes only from the verified session"
        );
        assert_eq!(created["exception"]["status"], "Pending");
        assert_eq!(created["device_status"], "NonCompliant");

        let self_approval = firmware_approve_exception(
            AuthExtractor(maker),
            Path(exception_id.clone()),
            Json(FirmwareExceptionApprovalRequest {
                expected_version: 1,
            }),
        )
        .await;
        assert!(
            matches!(self_approval, Err((StatusCode::FORBIDDEN, _))),
            "even a principal holding both roles cannot check their own request"
        );
        let still_pending: (String, i64, Option<String>) = sqlx::query_as(
            "SELECT status, version, approved_by FROM firmware_exceptions WHERE id = $1",
        )
        .bind(&exception_id)
        .fetch_one(pool)
        .await
        .expect("read denied self-approval state");
        assert_eq!(still_pending, ("Pending".into(), 1, None));

        let checker = actor("firmware-distinct-checker", &[APP_ROLE_DATACENTER_APPROVER]);
        let checker_principal_id = checker
            .principal_id
            .expect("verified test checker has an opaque principal")
            .to_string();
        let Json(approved) = firmware_approve_exception(
            AuthExtractor(checker.clone()),
            Path(exception_id.clone()),
            Json(FirmwareExceptionApprovalRequest {
                expected_version: 1,
            }),
        )
        .await
        .expect("distinct approval-capable checker succeeds");
        assert_eq!(
            approved["exception"]["approved_by"].as_str(),
            Some(checker_principal_id.as_str())
        );
        assert_eq!(approved["exception"]["status"], "Approved");
        assert_eq!(approved["exception"]["version"], 2);
        assert_eq!(approved["device_status"], "Exception");

        let approval_evidence: (String, chrono::DateTime<chrono::Utc>) = sqlx::query_as(
            "SELECT approved_by, approved_at \
             FROM firmware_exceptions WHERE id = $1",
        )
        .bind(&exception_id)
        .fetch_one(pool)
        .await
        .expect("read durable firmware approval evidence");
        let forged_revoke = sqlx::query(
            "UPDATE firmware_exceptions \
             SET status = 'Revoked', approved_by = 'replacement-checker', \
                 approved_at = TIMESTAMPTZ '2000-01-01 00:00:00+00', \
                 revoked_at = TIMESTAMPTZ '2000-01-01 00:00:00+00', \
                 version = version + 1 \
             WHERE id = $1",
        )
        .bind(&exception_id)
        .execute(pool)
        .await;
        assert!(
            forged_revoke.is_err(),
            "revocation must not rewrite the original checker or approval time"
        );

        let _ = firmware_revoke_exception(AuthExtractor(checker), Path(exception_id.clone()))
            .await
            .expect("verified checker revokes the approved exception");
        let revoked_evidence: (
            String,
            String,
            chrono::DateTime<chrono::Utc>,
            chrono::DateTime<chrono::Utc>,
        ) = sqlx::query_as(
            "SELECT status, approved_by, approved_at, revoked_at \
             FROM firmware_exceptions WHERE id = $1",
        )
        .bind(&exception_id)
        .fetch_one(pool)
        .await
        .expect("read durable firmware revocation evidence");
        assert_eq!(revoked_evidence.0, "Revoked");
        assert_eq!(revoked_evidence.1, approval_evidence.0);
        assert_eq!(revoked_evidence.2, approval_evidence.1);
        assert!(revoked_evidence.3 >= revoked_evidence.2);

        let hard_delete = sqlx::query("DELETE FROM firmware_exceptions WHERE id = $1")
            .bind(&exception_id)
            .execute(pool)
            .await
            .expect_err("ordinary writers cannot erase firmware exception history");
        assert!(hard_delete
            .to_string()
            .contains("firmware exception history is append-only"));
        let truncate = sqlx::query("TRUNCATE TABLE firmware_exceptions")
            .execute(pool)
            .await
            .expect_err("ordinary writers cannot truncate firmware exception history");
        assert!(truncate
            .to_string()
            .contains("firmware exception history is append-only"));
        cleanup_device(pool, &device_id).await;
    }

    #[tokio::test]
    async fn firmware_exception_audit_failure_rolls_approval_back() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set");
            return;
        };
        let device_id = format!("fw-security-audit-{}", Uuid::new_v4());
        seed_device(pool, &device_id).await;
        let maker = actor("firmware-audit-maker", &[APP_ROLE_WINTEL_LINUX_OPERATOR]);
        let Json(created) = firmware_request_exception(
            AuthExtractor(maker),
            Json(FirmwareExceptionRequest {
                device_id: device_id.clone(),
                reason: "Audit atomicity review".into(),
                expiry_days: 14,
            }),
        )
        .await
        .expect("create audit rollback fixture");
        let exception_id = created["exception"]["id"]
            .as_str()
            .expect("exception id")
            .to_string();

        let suffix = Uuid::new_v4().simple().to_string();
        let function_name = format!("reject_firmware_audit_{suffix}");
        let trigger_name = format!("reject_firmware_audit_trigger_{suffix}");
        sqlx::query(&format!(
            "CREATE FUNCTION {function_name}() RETURNS trigger LANGUAGE plpgsql AS $$ \
             BEGIN \
               IF NEW.action = 'firmware-exception-approve' \
                  AND NEW.actor_principal = 'firmware-audit-checker' THEN \
                 RAISE EXCEPTION 'injected firmware audit failure' USING ERRCODE = '23514'; \
               END IF; \
               RETURN NEW; \
             END $$"
        ))
        .execute(pool)
        .await
        .expect("create audit failure function");
        sqlx::query(&format!(
            "CREATE TRIGGER {trigger_name} BEFORE INSERT ON audit_log \
             FOR EACH ROW EXECUTE FUNCTION {function_name}()"
        ))
        .execute(pool)
        .await
        .expect("create audit failure trigger");

        let checker = actor("firmware-audit-checker", &[APP_ROLE_DATACENTER_APPROVER]);
        let result = firmware_approve_exception(
            AuthExtractor(checker),
            Path(exception_id.clone()),
            Json(FirmwareExceptionApprovalRequest {
                expected_version: 1,
            }),
        )
        .await;

        sqlx::query(&format!("DROP TRIGGER {trigger_name} ON audit_log"))
            .execute(pool)
            .await
            .expect("drop audit failure trigger");
        sqlx::query(&format!("DROP FUNCTION {function_name}()"))
            .execute(pool)
            .await
            .expect("drop audit failure function");

        assert!(
            matches!(result, Err((StatusCode::INTERNAL_SERVER_ERROR, _))),
            "audit failure must make the approval fail"
        );
        let state: (String, i64, Option<String>) = sqlx::query_as(
            "SELECT status, version, approved_by FROM firmware_exceptions WHERE id = $1",
        )
        .bind(&exception_id)
        .fetch_one(pool)
        .await
        .expect("read rolled-back exception");
        assert_eq!(state, ("Pending".into(), 1, None));
        let device_status: String =
            sqlx::query_scalar("SELECT compliance_status FROM firmware_records WHERE id = $1")
                .bind(&device_id)
                .fetch_one(pool)
                .await
                .expect("read rolled-back device");
        assert_eq!(device_status, "NonCompliant");
        cleanup_device(pool, &device_id).await;
    }

    #[tokio::test]
    async fn expired_approved_exception_reenters_lists_and_cannot_be_revived() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set");
            return;
        };
        let device_id = format!("fw-security-expiry-{}", Uuid::new_v4());
        seed_device(pool, &device_id).await;
        let maker = actor("firmware-expiry-maker", &[APP_ROLE_WINTEL_LINUX_OPERATOR]);
        let Json(created) = firmware_request_exception(
            AuthExtractor(maker),
            Json(FirmwareExceptionRequest {
                device_id: device_id.clone(),
                reason: "Expiry boundary review".into(),
                expiry_days: 14,
            }),
        )
        .await
        .expect("create expiry fixture");
        let exception_id = created["exception"]["id"]
            .as_str()
            .expect("exception id")
            .to_string();
        let checker = actor("firmware-expiry-checker", &[APP_ROLE_DATACENTER_APPROVER]);
        let _ = firmware_approve_exception(
            AuthExtractor(checker.clone()),
            Path(exception_id.clone()),
            Json(FirmwareExceptionApprovalRequest {
                expected_version: 1,
            }),
        )
        .await
        .expect("approve expiry fixture");
        let original_checker_evidence: (String, chrono::DateTime<chrono::Utc>) = sqlx::query_as(
            "SELECT approved_by, approved_at \
                 FROM firmware_exceptions WHERE id = $1",
        )
        .bind(&exception_id)
        .fetch_one(pool)
        .await
        .expect("read checker evidence before expiry");

        // Simulate ordinary passage of database time: the row shape after the
        // date rolls over is Approved with an expiry before CURRENT_DATE. The
        // trigger is disabled only while constructing that otherwise natural
        // persisted fixture.
        sqlx::query(
            "ALTER TABLE firmware_exceptions DISABLE TRIGGER firmware_exception_transition_guard",
        )
        .execute(pool)
        .await
        .expect("disable lifecycle trigger for clock-passage fixture");
        sqlx::query("UPDATE firmware_exceptions SET expiry_date = CURRENT_DATE - 1 WHERE id = $1")
            .bind(&exception_id)
            .execute(pool)
            .await
            .expect("move fixture beyond expiry boundary");
        sqlx::query(
            "ALTER TABLE firmware_exceptions ENABLE TRIGGER firmware_exception_transition_guard",
        )
        .execute(pool)
        .await
        .expect("re-enable lifecycle trigger");

        let forged_expiry = sqlx::query(
            "UPDATE firmware_exceptions \
             SET status = 'Expired', approved_by = 'replacement-checker', \
                 approved_at = TIMESTAMPTZ '2000-01-01 00:00:00+00', \
                 expired_at = TIMESTAMPTZ '2000-01-01 00:00:00+00', \
                 version = version + 1 \
             WHERE id = $1",
        )
        .bind(&exception_id)
        .execute(pool)
        .await;
        assert!(
            forged_expiry.is_err(),
            "expiry must preserve the original checker attribution"
        );

        sqlx::query(
            "UPDATE firmware_exceptions \
             SET status = 'Expired', \
                 expired_at = TIMESTAMPTZ '2000-01-01 00:00:00+00', \
                 version = version + 1 \
             WHERE id = $1",
        )
        .bind(&exception_id)
        .execute(pool)
        .await
        .expect("database owns the valid expiry transition timestamp");

        let effective = crate::repos::firmware_lifecycle::get_device(pool, &device_id)
            .await
            .expect("read effective device")
            .expect("expiry device exists");
        assert_eq!(
            effective.compliance_status,
            firmware_lifecycle::ComplianceStatus::NonCompliant
        );
        let noncompliant = crate::repos::firmware_lifecycle::list_noncompliant(pool)
            .await
            .expect("list effective noncompliance");
        assert!(noncompliant.iter().any(|device| device.id == device_id));
        let report = crate::repos::firmware_lifecycle::list_all_for_report(pool)
            .await
            .expect("build effective report");
        assert_eq!(
            report
                .iter()
                .find(|device| device.id == device_id)
                .expect("expiry device in report")
                .compliance_status,
            firmware_lifecycle::ComplianceStatus::NonCompliant
        );
        let active = crate::repos::firmware_lifecycle::list_active_exceptions(pool)
            .await
            .expect("list active exceptions");
        assert!(!active.iter().any(|exception| exception.id == exception_id));

        let stale = firmware_approve_exception(
            AuthExtractor(checker.clone()),
            Path(exception_id.clone()),
            Json(FirmwareExceptionApprovalRequest {
                expected_version: 2,
            }),
        )
        .await;
        assert!(matches!(stale, Err((StatusCode::CONFLICT, _))));

        let recalculator = actor(
            "firmware-expiry-recalculator",
            &[APP_ROLE_WINTEL_LINUX_OPERATOR],
        );
        let _ = firmware_check_compliance(AuthExtractor(recalculator), Path(device_id.clone()))
            .await
            .expect("reconcile expired lifecycle");
        let persisted: (
            String,
            i64,
            String,
            chrono::DateTime<chrono::Utc>,
            chrono::DateTime<chrono::Utc>,
        ) = sqlx::query_as(
            "SELECT status, version, approved_by, approved_at, expired_at \
             FROM firmware_exceptions WHERE id = $1",
        )
        .bind(&exception_id)
        .fetch_one(pool)
        .await
        .expect("read reconciled exception");
        assert_eq!(persisted.0, "Expired");
        assert_eq!(persisted.1, 3);
        assert_eq!(persisted.2, original_checker_evidence.0);
        assert_eq!(persisted.3, original_checker_evidence.1);
        assert!(
            persisted.4 >= persisted.3,
            "database-owned expiry time must follow the preserved approval time"
        );
        cleanup_device(pool, &device_id).await;
    }
}
