fn access_control_roles_json() -> Vec<Value> {
    let runtime_roles = get_rbac_roles();
    ACCESS_ROLE_PRESENTATIONS
        .iter()
        .map(|presentation| {
            let role = runtime_roles
                .iter()
                .find(|role| role.name == presentation.runtime_role)
                .expect("every presented access role must exist in the runtime registry");
            let is_admin = role
                .permissions
                .iter()
                .any(|permission| permission == "admin");
            let permits = |permission: &str| {
                is_admin || role.permissions.iter().any(|held| held == permission)
            };
            json!({
                "id": presentation.id,
                "runtimeRole": &role.name,
                "title": presentation.title,
                "visibility": presentation.visibility,
                "canRequest": permits("request"),
                "canApprove": permits("approve"),
                "canExecute": permits("execute"),
                "canAdmin": permits("admin"),
                "canAudit": permits("audit"),
                "executionDomains": &role.execution_domains,
                "operationCapabilities": role
                    .capabilities
                    .iter()
                    .map(|capability| capability.as_str())
                    .collect::<Vec<_>>(),
            })
        })
        .collect()
}

