// ─── gMSA lifecycle handlers ───

async fn gmsa_create(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<GmsaCreateRequest>,
) -> ApiResult {
    // Resolve the global name's owner from the complete governed site registry.
    // The declared body site is only a compatibility assertion.
    let account = gmsa_lifecycle::create_gmsa(&body.name, body.hosts, body.spns, &body.site)
        .map_err(|e| status_400(&e))?;
    guard_body_site_scope(&session, &account.site)?;

    let pool = get_db().ok_or_else(status_503_no_db)?;
    let mut tx = pool.begin().await.map_err(db_error)?;
    if !crate::repos::site_registry::lock_active(&mut tx, &account.site)
        .await
        .map_err(db_error)?
    {
        return Err(status_409(
            "directory namespace owner site is no longer active; reload and retry",
        ));
    }
    crate::repos::gmsa_accounts::insert(&mut tx, &account)
        .await
        .map_err(|e| {
            // Only the account-name UNIQUE constraint is a "duplicate name". The
            // child-host UNIQUE can't be hit here (the repo dedups + ON CONFLICTs
            // the host inserts), but checking the constraint name keeps the 409
            // honest if that ever changes.
            if let Some(d) = e.as_database_error() {
                if d.is_unique_violation() && d.constraint() == Some("gmsa_accounts_name_key") {
                    return status_409("a gMSA with that name already exists");
                }
            }
            db_error(e)
        })?;
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "gmsa-create",
            None,
            "created",
            json!({
                "gmsa_name": &account.name,
                "owner_site": &account.site,
                "namespace_policy_version": ryuki_engine::site_registry::DIRECTORY_NAMESPACE_POLICY_VERSION
            }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;

    // Re-read post-commit to return DB-authoritative timestamps.
    let persisted = crate::repos::gmsa_accounts::get_by_name(pool, &account.name)
        .await
        .map_err(db_error)?
        .ok_or_else(|| {
            (
                axum::http::StatusCode::INTERNAL_SERVER_ERROR,
                Json(serde_json::json!({"error":"INTERNAL_ERROR","message":"gMSA not found after insert commit"})),
            )
        })?;

    Ok(Json(serde_json::to_value(persisted).unwrap_or_default()))
}

