const SHIFT_QUEUE_DEFAULT_LIMIT: i64 = 50;
const SHIFT_QUEUE_MAX_LIMIT: i64 = 200;
const SHIFT_QUEUE_MAX_TYPE_BUCKETS: i64 = 200;
// Handover is an operational summary, not a raw queue export. Each projected
// text value is sliced by PostgreSQL to at most one character beyond its
// response budget; Rust removes that look-ahead character and emits an
// explicit truncation flag. This keeps both sections bounded even when a
// legacy or compromised writer stores very wide TEXT/JSONB values.
const SHIFT_HANDOVER_ITEM_TYPE_MAX_CHARS: i32 = 128;
const SHIFT_HANDOVER_TITLE_MAX_CHARS: i32 = 256;
const SHIFT_HANDOVER_DESCRIPTION_MAX_CHARS: i32 = 1_024;
const SHIFT_HANDOVER_PRIORITY_MAX_CHARS: i32 = 16;
const SHIFT_HANDOVER_ASSIGNEE_MAX_CHARS: i32 = 512;
const SHIFT_HANDOVER_ESCALATION_REASON_MAX_CHARS: i32 = 1_024;
const SHIFT_HANDOVER_RESOLUTION_MAX_CHARS: i32 = 2_048;
// Reuse the established principal/justification byte budgets for the two
// temporary fleet-global shift mutations. These inputs remain bounded until a
// typed destination-principal and transition-policy model replaces the
// explicit Global verified-human admin exception.
const SHIFT_ASSIGNMENT_TARGET_MAX_BYTES: usize = MAX_LOCAL_REQUEST_PRINCIPAL_BYTES;
const SHIFT_RESOLUTION_MAX_BYTES: usize = MAX_LOCAL_REQUEST_JUSTIFICATION_BYTES;

/// Assignment and resolution cannot be delegated safely while the queue has no
/// authoritative assignee directory or support-group/state transition policy.
/// Admit only the existing strongest platform-global human-admin authority;
/// callers with bare execute, machine/simulated authority, or either scope axis
/// are denied before input validation, item lookup, or persistence behavior.
fn require_shift_global_verified_human_admin(
    session: &AuthSession,
) -> Result<(), (StatusCode, Json<Value>)> {
    require_global_verified_human_admin_permission(session).map_err(|_| {
        (
            StatusCode::FORBIDDEN,
            Json(json!({
                "error": "shift assignment and resolution require a verified human administrator with Global authority"
            })),
        )
    })
}

fn validate_canonical_shift_text(
    field: &str,
    value: &str,
    max_bytes: usize,
) -> Result<(), (StatusCode, Json<Value>)> {
    if value.len() > max_bytes {
        return Err(status_400(&format!(
            "{field} must be at most {max_bytes} bytes"
        )));
    }
    reject_control_chars(field, value)?;
    if value.trim().is_empty() || value != value.trim() {
        return Err(status_400(&format!(
            "{field} must be nonblank and have no surrounding whitespace"
        )));
    }
    Ok(())
}

/// Server-derived shift-queue resource policy. Empty scope axes retain the
/// platform's established "unrestricted on this axis" meaning; a global row is
/// visible only when BOTH axes are unrestricted. Typed row ownership, when set,
/// narrows ordinary operators further and can be bypassed only by `admin`.
struct ShiftQueuePolicy {
    sites: Vec<String>,
    environments: Vec<String>,
    principal: String,
    all_sites: bool,
    all_environments: bool,
    allow_global: bool,
    bypass_owner: bool,
}

impl ShiftQueuePolicy {
    fn from_session(session: &AuthSession) -> Option<Self> {
        let principal = session.principal_id?.to_string();
        let normalize = |values: &[String]| {
            let mut result: Vec<String> = values
                .iter()
                .map(|value| value.trim())
                .filter(|value| !value.is_empty())
                .map(str::to_string)
                .collect();
            result.sort();
            result.dedup();
            result
        };
        let sites = normalize(&session.site_scope);
        let environments = normalize(&session.environment_scope);
        let all_sites = sites.is_empty();
        let all_environments = environments.is_empty();
        Some(Self {
            sites,
            environments,
            principal,
            all_sites,
            all_environments,
            allow_global: all_sites && all_environments,
            bypass_owner: check_permission(session, "admin"),
        })
    }

    fn repository_access(&self) -> crate::repos::shift_queue::ShiftQueueAccess<'_> {
        crate::repos::shift_queue::ShiftQueueAccess {
            sites: &self.sites,
            environments: &self.environments,
            principal: &self.principal,
            all_sites: self.all_sites,
            all_environments: self.all_environments,
            allow_global: self.allow_global,
            bypass_owner: self.bypass_owner,
        }
    }
}

fn shift_queue_admit(session: &AuthSession) -> Result<ShiftQueuePolicy, (StatusCode, Json<Value>)> {
    if !check_permission(session, "execute") {
        return Err(status_403());
    }
    ShiftQueuePolicy::from_session(session).ok_or_else(status_403)
}

fn shift_queue_limit(limit: Option<i64>) -> i64 {
    limit
        .unwrap_or(SHIFT_QUEUE_DEFAULT_LIMIT)
        .clamp(1, SHIFT_QUEUE_MAX_LIMIT)
}

fn shift_queue_after(after: Option<&str>) -> Result<Option<Uuid>, (StatusCode, Json<Value>)> {
    after
        .map(|value| {
            Uuid::parse_str(value.trim()).map_err(|_| status_400("invalid shift queue cursor"))
        })
        .transpose()
}

const SHIFT_QUEUE_SCOPE_SQL: &str = "(\
    (visibility_kind = 'resource' \
     AND EXISTS (SELECT 1 FROM site_registry AS authorized_site \
                 WHERE authorized_site.unlocode = shift_queue.site \
                   AND authorized_site.active = true) \
     AND ($1::bool OR site = ANY($2::text[])) \
     AND ($3::bool OR environment = ANY($4::text[])) \
     AND ($5::bool OR owner_principal IS NULL OR owner_principal = $6)) \
    OR (visibility_kind = 'global' AND $7::bool)\
)";

const SHIFT_QUEUE_SCOPE_AFTER_ID_SQL: &str = "(\
    (visibility_kind = 'resource' \
     AND EXISTS (SELECT 1 FROM site_registry AS authorized_site \
                 WHERE authorized_site.unlocode = shift_queue.site \
                   AND authorized_site.active = true) \
     AND ($2::bool OR site = ANY($3::text[])) \
     AND ($4::bool OR environment = ANY($5::text[])) \
     AND ($6::bool OR owner_principal IS NULL OR owner_principal = $7)) \
    OR (visibility_kind = 'global' AND $8::bool)\
)";

/// One persisted `shift_queue` row (migration 029). JSONB `metadata` is
/// selected as `::text` and parsed back so `to_json` reproduces the engine
/// `ShiftItem` serde shape (snake_case fields, ISO-8601 timestamps).
#[derive(sqlx::FromRow)]
#[allow(dead_code)]
struct ShiftQueueRow {
    id: String,
    item_type: String,
    title: String,
    description: String,
    priority: String,
    assigned_to: Option<String>,
    assigned_by: Option<String>,
    created_at: chrono::DateTime<chrono::Utc>,
    acknowledged: bool,
    acknowledged_by: Option<String>,
    acknowledged_at: Option<chrono::DateTime<chrono::Utc>>,
    resolved: bool,
    resolution: Option<String>,
    resolved_at: Option<chrono::DateTime<chrono::Utc>>,
    escalated: bool,
    escalation_reason: Option<String>,
    escalated_at: Option<chrono::DateTime<chrono::Utc>>,
    metadata: String,
    updated_at: chrono::DateTime<chrono::Utc>,
}

const SHIFT_QUEUE_COLUMNS: &str =
    "id::text AS id, item_type, title, description, priority, assigned_to, assigned_by, \
     created_at, acknowledged, acknowledged_by, acknowledged_at, resolved, resolution, \
     resolved_at, escalated, escalation_reason, escalated_at, metadata::text AS metadata, \
     updated_at";

/// Narrow, bounded projection for the open half of a handover. Deliberately
/// absent are `metadata` and lifecycle columns that the response never uses.
/// The SQL query returns at most `MAX + 1` characters for each text field so
/// truncation can be detected without asking PostgreSQL to scan the complete
/// value with `char_length`.
#[derive(sqlx::FromRow)]
struct ShiftHandoverOpenRow {
    id: String,
    item_type: String,
    title: String,
    description: String,
    priority: String,
    assigned_to: Option<String>,
    acknowledged: bool,
    escalated: bool,
    escalation_reason: Option<String>,
    created_at: chrono::DateTime<chrono::Utc>,
}

/// Narrow, bounded projection for the recently-resolved half of a handover.
#[derive(sqlx::FromRow)]
struct ShiftHandoverResolvedRow {
    id: String,
    title: String,
    resolution: Option<String>,
    resolved_at: chrono::DateTime<chrono::Utc>,
}

fn finalize_shift_handover_text(mut value: String, max_chars: i32) -> (String, bool) {
    let max_chars = usize::try_from(max_chars).expect("handover text limit must be positive");
    let Some((truncate_at, _)) = value.char_indices().nth(max_chars) else {
        return (value, false);
    };
    value.truncate(truncate_at);
    (value, true)
}

fn finalize_optional_shift_handover_text(
    value: Option<String>,
    max_chars: i32,
) -> (Option<String>, bool) {
    match value {
        Some(value) => {
            let (value, truncated) = finalize_shift_handover_text(value, max_chars);
            (Some(value), truncated)
        }
        None => (None, false),
    }
}

fn shift_handover_open_page_sql() -> String {
    format!(
        "WITH cursor AS ( \
             SELECT LEFT(priority, $13) AS priority, created_at, id FROM shift_queue \
             WHERE resolved = false AND {SHIFT_QUEUE_SCOPE_SQL} AND id = $8 \
         ) \
         SELECT id::text AS id, \
                LEFT(item_type, $10) AS item_type, \
                LEFT(title, $11) AS title, \
                LEFT(description, $12) AS description, \
                LEFT(priority, $13) AS priority, \
                LEFT(assigned_to, $14) AS assigned_to, \
                acknowledged, escalated, \
                LEFT(escalation_reason, $15) AS escalation_reason, \
                created_at \
         FROM shift_queue \
         WHERE resolved = false AND {SHIFT_QUEUE_SCOPE_SQL} \
           AND ($8::uuid IS NULL OR (LEFT(priority, $13), created_at, id) > \
                (SELECT priority, created_at, id FROM cursor)) \
         ORDER BY LEFT(shift_queue.priority, $13) ASC, shift_queue.created_at ASC, \
                  shift_queue.id ASC LIMIT $9"
    )
}

fn shift_handover_resolved_page_sql() -> String {
    format!(
        "WITH cursor AS ( \
             SELECT resolved_at, id FROM shift_queue \
             WHERE resolved = true \
               AND resolved_at IS NOT NULL \
               AND resolved_at >= NOW() - INTERVAL '12 hours' \
               AND {SHIFT_QUEUE_SCOPE_SQL} AND id = $8 \
         ) \
         SELECT id::text AS id, \
                LEFT(title, $10) AS title, \
                LEFT(resolution, $11) AS resolution, \
                resolved_at \
         FROM shift_queue \
         WHERE resolved = true \
           AND resolved_at IS NOT NULL \
           AND resolved_at >= NOW() - INTERVAL '12 hours' \
           AND {SHIFT_QUEUE_SCOPE_SQL} \
           AND ($8::uuid IS NULL OR (resolved_at, id) < \
                (SELECT resolved_at, id FROM cursor)) \
         ORDER BY shift_queue.resolved_at DESC, shift_queue.id DESC LIMIT $9"
    )
}

async fn shift_queue_lock_authorized_row(
    tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
    policy: &ShiftQueuePolicy,
    id: Uuid,
) -> Result<Option<ShiftQueueRow>, (StatusCode, Json<Value>)> {
    sqlx::query_as(&format!(
        "SELECT {SHIFT_QUEUE_COLUMNS} FROM shift_queue \
         WHERE id = $1 AND {SHIFT_QUEUE_SCOPE_AFTER_ID_SQL} FOR UPDATE"
    ))
    .bind(id)
    .bind(policy.all_sites)
    .bind(&policy.sites)
    .bind(policy.all_environments)
    .bind(&policy.environments)
    .bind(policy.bypass_owner)
    .bind(&policy.principal)
    .bind(policy.allow_global)
    .fetch_optional(&mut **tx)
    .await
    .map_err(db_error)
}

async fn shift_summary(
    AuthExtractor(session): AuthExtractor,
    Query(params): Query<ShiftPageQuery>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let policy = shift_queue_admit(&session)?;
    let limit = shift_queue_limit(params.limit);
    let after = shift_queue_after(params.after.as_deref())?;
    let Some(pool) = get_db() else {
        // The static fallback has no typed resource binding. Preserve it only
        // for an unrestricted development principal; scoped callers fail closed.
        if is_scoped(&session) {
            return Err(status_503_no_db());
        }
        return Ok(Json(shift_queue::get_shift_summary()));
    };

    // Counts are computed by PostgreSQL over the authorized relation. The API
    // never materializes the entire queue merely to count or group it.
    let (total_open, p1_open, p2_open, unacknowledged): (i64, i64, i64, i64) =
        sqlx::query_as(&format!(
            "SELECT COUNT(*)::bigint, \
                    COUNT(*) FILTER (WHERE priority = 'P1')::bigint, \
                    COUNT(*) FILTER (WHERE priority = 'P2')::bigint, \
                    COUNT(*) FILTER (WHERE acknowledged = false)::bigint \
             FROM shift_queue WHERE resolved = false AND {SHIFT_QUEUE_SCOPE_SQL}"
        ))
        .bind(policy.all_sites)
        .bind(&policy.sites)
        .bind(policy.all_environments)
        .bind(&policy.environments)
        .bind(policy.bypass_owner)
        .bind(&policy.principal)
        .bind(policy.allow_global)
        .fetch_one(pool)
        .await
        .map_err(db_error)?;

    let mut type_counts: Vec<(String, i64, i64, i64, i64)> = sqlx::query_as(&format!(
        "SELECT item_type, COUNT(*)::bigint, \
                COUNT(*) FILTER (WHERE priority = 'P1')::bigint, \
                COUNT(*) FILTER (WHERE priority = 'P2')::bigint, \
                COUNT(*) FILTER (WHERE acknowledged = false)::bigint \
         FROM shift_queue WHERE resolved = false AND {SHIFT_QUEUE_SCOPE_SQL} \
         GROUP BY item_type ORDER BY item_type LIMIT $8"
    ))
    .bind(policy.all_sites)
    .bind(&policy.sites)
    .bind(policy.all_environments)
    .bind(&policy.environments)
    .bind(policy.bypass_owner)
    .bind(&policy.principal)
    .bind(policy.allow_global)
    .bind(SHIFT_QUEUE_MAX_TYPE_BUCKETS + 1)
    .fetch_all(pool)
    .await
    .map_err(db_error)?;
    let type_buckets_truncated = type_counts.len() as i64 > SHIFT_QUEUE_MAX_TYPE_BUCKETS;
    type_counts.truncate(SHIFT_QUEUE_MAX_TYPE_BUCKETS as usize);

    // One bounded keyset page supplies item detail. An absent, foreign, or
    // denied cursor resolves to no anchor and therefore the same empty page.
    let mut rows: Vec<ShiftQueueRow> = sqlx::query_as(&format!(
        "WITH authorized AS ( \
             SELECT * FROM shift_queue WHERE resolved = false AND {SHIFT_QUEUE_SCOPE_SQL} \
         ), cursor AS ( \
             SELECT priority, created_at, id FROM authorized WHERE id = $8 \
         ) \
         SELECT {SHIFT_QUEUE_COLUMNS} FROM authorized \
         WHERE ($8::uuid IS NULL OR (priority, created_at, id) > \
                (SELECT priority, created_at, id FROM cursor)) \
         ORDER BY priority ASC, created_at ASC, id ASC LIMIT $9"
    ))
    .bind(policy.all_sites)
    .bind(&policy.sites)
    .bind(policy.all_environments)
    .bind(&policy.environments)
    .bind(policy.bypass_owner)
    .bind(&policy.principal)
    .bind(policy.allow_global)
    .bind(after)
    .bind(limit + 1)
    .fetch_all(pool)
    .await
    .map_err(db_error)?;
    let has_more = rows.len() as i64 > limit;
    rows.truncate(limit as usize);
    let next_cursor = if has_more {
        rows.last().map(|row| row.id.clone())
    } else {
        None
    };

    let mut by_type: std::collections::HashMap<String, Value> = type_counts
        .into_iter()
        .map(|(item_type, count, p1_count, p2_count, unacknowledged)| {
            (
                item_type,
                json!({
                    "count": count,
                    "items": [],
                    "p1_count": p1_count,
                    "p2_count": p2_count,
                    "unacknowledged": unacknowledged,
                }),
            )
        })
        .collect();
    for row in &rows {
        let bucket = by_type.entry(row.item_type.clone()).or_insert_with(|| {
            json!({
                "count": null,
                "items": [],
                "p1_count": null,
                "p2_count": null,
                "unacknowledged": null,
                "aggregate_truncated": true,
            })
        });
        if let Some(items) = bucket
            .as_object_mut()
            .and_then(|bucket| bucket.get_mut("items"))
            .and_then(Value::as_array_mut)
        {
            items.push(json!({
                "id": row.id,
                "title": row.title,
                "priority": row.priority,
                "assigned_to": row.assigned_to,
                "assigned_by": row.assigned_by,
                "acknowledged": row.acknowledged,
                "escalated": row.escalated,
                "created_at": row.created_at.to_rfc3339(),
            }));
        }
    }

    Ok(Json(json!({
        "source": "database",
        "total_open": total_open,
        "p1_open": p1_open,
        "p2_open": p2_open,
        "unacknowledged": unacknowledged,
        "by_type": by_type,
        "type_buckets_truncated": type_buckets_truncated,
        "page": {
            "limit": limit,
            "count": rows.len(),
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    })))
}

async fn shift_acknowledge(
    Path(id): Path<String>,
    AuthExtractor(session): AuthExtractor,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let policy = shift_queue_admit(&session)?;
    // Acknowledger = authenticated caller (from request extensions), never a
    // client body field — the audit trail must name the real principal.
    if let Some(pool) = get_db() {
        // The shift_queue.id column is UUID; bind a parsed Uuid (not the raw
        // path String) or Postgres rejects the comparison with `uuid = text`.
        let uid = Uuid::parse_str(&id).map_err(|_| status_404(&id))?;
        // Scope/owner authorization is part of the locking SELECT. Missing and
        // denied rows therefore share the same 404 and cannot be enumerated.
        let mut tx = pool.begin().await.map_err(db_error)?;
        let row = shift_queue_lock_authorized_row(&mut tx, &policy, uid).await?;

        let row = row.ok_or_else(|| {
            (
                StatusCode::NOT_FOUND,
                Json(json!({"error": format!("Shift item not found: {}", id)})),
            )
        })?;

        if row.resolved {
            return Err((
                StatusCode::BAD_REQUEST,
                Json(json!({"error": "Cannot acknowledge a resolved item"})),
            ));
        }
        if row.acknowledged {
            return Err((
                StatusCode::BAD_REQUEST,
                Json(json!({"error": format!("Item {} is already acknowledged", id)})),
            ));
        }

        let now = chrono::Utc::now();
        // CAS: include state guard in WHERE so a concurrent resolve or
        // double-acknowledge between the pre-read and this UPDATE cannot
        // both succeed.  rows_affected == 0 means the state changed under us.
        let result = sqlx::query(
            "UPDATE shift_queue SET acknowledged = true, acknowledged_by = $1, \
             acknowledged_at = $2, updated_at = $2 \
             WHERE id = $3 AND resolved = false AND acknowledged = false",
        )
        .bind(&policy.principal)
        .bind(now)
        .bind(uid)
        .execute(&mut *tx)
        .await
        .map_err(db_error)?;

        if result.rows_affected() == 0 {
            return Err((
                StatusCode::CONFLICT,
                Json(json!({"error": "state changed concurrently; reload and retry"})),
            ));
        }

        audit::record_audit_tx(
            &mut tx,
            &session,
            &audit::security_audit(
                "shift-acknowledge",
                None,
                "acknowledged",
                json!({ "shift_item_id": &id }),
            ),
        )
        .await
        .map_err(db_error)?;
        tx.commit().await.map_err(db_error)?;

        return Ok(Json(json!({
            "status": "acknowledged",
            "id": id,
            "acknowledged_by": &policy.principal,
            "acknowledged_at": now.to_rfc3339(),
            "source": "database",
        })));
    }
    if is_scoped(&session) {
        return Err(status_404(&id));
    }
    shift_queue::acknowledge_item(&id, &policy.principal)
        .map(Json)
        .map_err(|e| (StatusCode::BAD_REQUEST, Json(json!({"error": e}))))
}

async fn shift_assign(
    Path(id): Path<String>,
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<ShiftActionRequest>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    require_shift_global_verified_human_admin(&session)?;
    validate_canonical_shift_text(
        "shift assignment target",
        &body.user,
        SHIFT_ASSIGNMENT_TARGET_MAX_BYTES,
    )?;
    let policy = shift_queue_admit(&session)?;
    // assigned_to (body.user) is the ASSIGNEE; assigned_by is the actor that
    // performed the assignment — taken from the authenticated session, never a
    // client field, mirroring shift_acknowledge's acknowledged_by.
    if let Some(pool) = get_db() {
        // shift_queue.id is UUID — parse before binding (see shift_acknowledge).
        let uid = Uuid::parse_str(&id).map_err(|_| status_404(&id))?;
        let mut tx = pool.begin().await.map_err(db_error)?;
        let row = shift_queue_lock_authorized_row(&mut tx, &policy, uid).await?;

        let row = row.ok_or_else(|| {
            (
                StatusCode::NOT_FOUND,
                Json(json!({"error": format!("Shift item not found: {}", id)})),
            )
        })?;

        if row.resolved {
            return Err((
                StatusCode::BAD_REQUEST,
                Json(json!({"error": "Cannot assign a resolved item"})),
            ));
        }

        let now = chrono::Utc::now();
        // CAS: only assign if still unresolved.
        let result = sqlx::query(
            "UPDATE shift_queue SET assigned_to = $1, assigned_by = $2, updated_at = $3 \
             WHERE id = $4 AND resolved = false",
        )
        .bind(&body.user)
        .bind(&policy.principal)
        .bind(now)
        .bind(uid)
        .execute(&mut *tx)
        .await
        .map_err(db_error)?;

        if result.rows_affected() == 0 {
            return Err((
                StatusCode::CONFLICT,
                Json(json!({"error": "state changed concurrently; reload and retry"})),
            ));
        }

        audit::record_audit_tx(
            &mut tx,
            &session,
            &audit::security_audit(
                "shift-assign",
                None,
                "assigned",
                json!({ "shift_item_id": &id }),
            ),
        )
        .await
        .map_err(db_error)?;
        tx.commit().await.map_err(db_error)?;

        return Ok(Json(json!({
            "status": "assigned",
            "id": id,
            "assigned_to": body.user,
            "assigned_by": &policy.principal,
            "source": "database",
        })));
    }
    if is_scoped(&session) {
        return Err(status_404(&id));
    }
    shift_queue::assign_item(&id, &body.user)
        .map(Json)
        .map_err(|e| (StatusCode::BAD_REQUEST, Json(json!({"error": e}))))
}

async fn shift_escalate(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
    Json(body): Json<ShiftEscalateRequest>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let policy = shift_queue_admit(&session)?;
    reject_control_chars("escalation reason", &body.reason)?;
    if let Some(pool) = get_db() {
        // shift_queue.id is UUID — parse before binding (see shift_acknowledge).
        let uid = Uuid::parse_str(&id).map_err(|_| status_404(&id))?;
        let mut tx = pool.begin().await.map_err(db_error)?;
        let row = shift_queue_lock_authorized_row(&mut tx, &policy, uid).await?;

        let row = row.ok_or_else(|| {
            (
                StatusCode::NOT_FOUND,
                Json(json!({"error": format!("Shift item not found: {}", id)})),
            )
        })?;

        if row.resolved {
            return Err((
                StatusCode::BAD_REQUEST,
                Json(json!({"error": "Cannot escalate a resolved item"})),
            ));
        }
        if row.escalated {
            return Err((
                StatusCode::BAD_REQUEST,
                Json(json!({"error": format!("Item {} is already escalated", id)})),
            ));
        }

        let now = chrono::Utc::now();
        // CAS: only escalate if still unresolved and not already escalated.
        let result = sqlx::query(
            "UPDATE shift_queue SET escalated = true, escalation_reason = $1, \
             escalated_at = $2, updated_at = $2 \
             WHERE id = $3 AND resolved = false AND escalated = false",
        )
        .bind(&body.reason)
        .bind(now)
        .bind(uid)
        .execute(&mut *tx)
        .await
        .map_err(db_error)?;

        if result.rows_affected() == 0 {
            return Err((
                StatusCode::CONFLICT,
                Json(json!({"error": "state changed concurrently; reload and retry"})),
            ));
        }

        audit::record_audit_tx(
            &mut tx,
            &session,
            &audit::security_audit(
                "shift-escalate",
                None,
                "escalated",
                json!({ "shift_item_id": &id }),
            ),
        )
        .await
        .map_err(db_error)?;
        tx.commit().await.map_err(db_error)?;

        return Ok(Json(json!({
            "status": "escalated",
            "id": id,
            "reason": body.reason,
            "escalated_at": now.to_rfc3339(),
            "source": "database",
        })));
    }
    if is_scoped(&session) {
        return Err(status_404(&id));
    }
    shift_queue::escalate_item(&id, &body.reason)
        .map(Json)
        .map_err(|e| (StatusCode::BAD_REQUEST, Json(json!({"error": e}))))
}

