async fn shift_handover(
    AuthExtractor(session): AuthExtractor,
    Query(params): Query<ShiftHandoverQuery>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let policy = shift_queue_admit(&session)?;
    let limit = shift_queue_limit(params.limit);
    let open_after = shift_queue_after(params.open_after.as_deref())?;
    let resolved_after = shift_queue_after(params.resolved_after.as_deref())?;
    let Some(pool) = get_db() else {
        if is_scoped(&session) {
            return Err(status_503_no_db());
        }
        return Ok(Json(shift_queue::get_handover_report()));
    };

    let (total_open, p1_count, p2_count, unacknowledged_count, escalated_count): (
        i64,
        i64,
        i64,
        i64,
        i64,
    ) = sqlx::query_as(&format!(
        "SELECT COUNT(*)::bigint, \
                COUNT(*) FILTER (WHERE LEFT(priority, 3) = 'P1')::bigint, \
                COUNT(*) FILTER (WHERE LEFT(priority, 3) = 'P2')::bigint, \
                COUNT(*) FILTER (WHERE acknowledged = false)::bigint, \
                COUNT(*) FILTER (WHERE escalated = true)::bigint \
         FROM shift_queue WHERE resolved = false AND {SHIFT_QUEUE_SCOPE_SQL}"
    ))
    .bind(policy.all_sites)
    .bind(&policy.sites)
    .bind(policy.all_environments)
    .bind(&policy.environments)
    .bind(policy.bypass_owner)
    .bind(&policy.principal)
    .bind(policy.allow_global)
    .fetch_one(pool)
    .await
    .map_err(db_error)?;

    let open_page_sql = shift_handover_open_page_sql();
    let mut open_rows: Vec<ShiftHandoverOpenRow> = sqlx::query_as(&open_page_sql)
        .bind(policy.all_sites)
        .bind(&policy.sites)
        .bind(policy.all_environments)
        .bind(&policy.environments)
        .bind(policy.bypass_owner)
        .bind(&policy.principal)
        .bind(policy.allow_global)
        .bind(open_after)
        .bind(limit + 1)
        .bind(SHIFT_HANDOVER_ITEM_TYPE_MAX_CHARS + 1)
        .bind(SHIFT_HANDOVER_TITLE_MAX_CHARS + 1)
        .bind(SHIFT_HANDOVER_DESCRIPTION_MAX_CHARS + 1)
        .bind(SHIFT_HANDOVER_PRIORITY_MAX_CHARS + 1)
        .bind(SHIFT_HANDOVER_ASSIGNEE_MAX_CHARS + 1)
        .bind(SHIFT_HANDOVER_ESCALATION_REASON_MAX_CHARS + 1)
        .fetch_all(pool)
        .await
        .map_err(db_error)?;
    let open_has_more = open_rows.len() as i64 > limit;
    open_rows.truncate(limit as usize);
    let next_open_cursor = if open_has_more {
        open_rows.last().map(|row| row.id.clone())
    } else {
        None
    };

    let resolved_page_sql = shift_handover_resolved_page_sql();
    let mut recently_resolved_rows: Vec<ShiftHandoverResolvedRow> =
        sqlx::query_as(&resolved_page_sql)
            .bind(policy.all_sites)
            .bind(&policy.sites)
            .bind(policy.all_environments)
            .bind(&policy.environments)
            .bind(policy.bypass_owner)
            .bind(&policy.principal)
            .bind(policy.allow_global)
            .bind(resolved_after)
            .bind(limit + 1)
            .bind(SHIFT_HANDOVER_TITLE_MAX_CHARS + 1)
            .bind(SHIFT_HANDOVER_RESOLUTION_MAX_CHARS + 1)
            .fetch_all(pool)
            .await
            .map_err(db_error)?;
    let resolved_has_more = recently_resolved_rows.len() as i64 > limit;
    recently_resolved_rows.truncate(limit as usize);
    let next_resolved_cursor = if resolved_has_more {
        recently_resolved_rows.last().map(|row| row.id.clone())
    } else {
        None
    };

    let open_items: Vec<Value> = open_rows
        .into_iter()
        .map(|row| {
            let (item_type, item_type_truncated) =
                finalize_shift_handover_text(row.item_type, SHIFT_HANDOVER_ITEM_TYPE_MAX_CHARS);
            let (title, title_truncated) =
                finalize_shift_handover_text(row.title, SHIFT_HANDOVER_TITLE_MAX_CHARS);
            let (description, description_truncated) =
                finalize_shift_handover_text(row.description, SHIFT_HANDOVER_DESCRIPTION_MAX_CHARS);
            let (priority, priority_truncated) =
                finalize_shift_handover_text(row.priority, SHIFT_HANDOVER_PRIORITY_MAX_CHARS);
            let (assigned_to, assigned_to_truncated) = finalize_optional_shift_handover_text(
                row.assigned_to,
                SHIFT_HANDOVER_ASSIGNEE_MAX_CHARS,
            );
            let (escalation_reason, escalation_reason_truncated) =
                finalize_optional_shift_handover_text(
                    row.escalation_reason,
                    SHIFT_HANDOVER_ESCALATION_REASON_MAX_CHARS,
                );
            json!({
                "id": row.id,
                "item_type": item_type,
                "item_type_truncated": item_type_truncated,
                "title": title,
                "title_truncated": title_truncated,
                "description": description,
                "description_truncated": description_truncated,
                "priority": priority,
                "priority_truncated": priority_truncated,
                "assigned_to": assigned_to,
                "assigned_to_truncated": assigned_to_truncated,
                "acknowledged": row.acknowledged,
                "escalated": row.escalated,
                "escalation_reason": escalation_reason,
                "escalation_reason_truncated": escalation_reason_truncated,
                "created_at": row.created_at.to_rfc3339(),
            })
        })
        .collect();
    let recently_resolved: Vec<Value> = recently_resolved_rows
        .into_iter()
        .map(|row| {
            let (title, title_truncated) =
                finalize_shift_handover_text(row.title, SHIFT_HANDOVER_TITLE_MAX_CHARS);
            let (resolution, resolution_truncated) = finalize_optional_shift_handover_text(
                row.resolution,
                SHIFT_HANDOVER_RESOLUTION_MAX_CHARS,
            );
            json!({
                "id": row.id,
                "title": title,
                "title_truncated": title_truncated,
                "resolution": resolution,
                "resolution_truncated": resolution_truncated,
                "resolved_at": row.resolved_at.to_rfc3339(),
            })
        })
        .collect();

    Ok(Json(json!({
        "source": "database",
        "generated_at": chrono::Utc::now().to_rfc3339(),
        "shift_summary": {
            "total_open": total_open,
            "p1_count": p1_count,
            "p2_count": p2_count,
            "unacknowledged_count": unacknowledged_count,
            "escalated_count": escalated_count,
        },
        "open_items": open_items,
        "recently_resolved": recently_resolved,
        "handover_notes": [],
        "page": {
            "limit": limit,
            "open_has_more": open_has_more,
            "next_open_cursor": next_open_cursor,
            "resolved_has_more": resolved_has_more,
            "next_resolved_cursor": next_resolved_cursor,
        },
    })))
}

async fn shift_my_items(
    AuthExtractor(session): AuthExtractor,
    Query(params): Query<ShiftMyItemsQuery>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let policy = shift_queue_admit(&session)?;
    let requested = params
        .user
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let user = match requested {
        None => policy.principal.clone(),
        Some(value) if value == policy.principal => policy.principal.clone(),
        Some(value) if check_permission(&session, "admin") => value.to_string(),
        Some(_) => return Err(status_403()),
    };
    let limit = shift_queue_limit(params.limit);
    let after = shift_queue_after(params.after.as_deref())?;
    let Some(pool) = get_db() else {
        if is_scoped(&session) {
            return Err(status_503_no_db());
        }
        return Ok(Json(shift_queue::get_my_items(&user)));
    };

    // Assignee and resource policy are both inside the relation before keyset
    // ordering and LIMIT; a caller-selected `user` can never widen an ordinary
    // operator beyond the verified session principal.
    let mut rows: Vec<ShiftQueueRow> = sqlx::query_as(&format!(
        "WITH authorized AS ( \
             SELECT * FROM shift_queue \
             WHERE resolved = false AND assigned_to = $8 AND {SHIFT_QUEUE_SCOPE_SQL} \
         ), cursor AS ( \
             SELECT priority, created_at, id FROM authorized WHERE id = $9 \
         ) \
         SELECT {SHIFT_QUEUE_COLUMNS} FROM authorized \
         WHERE ($9::uuid IS NULL OR (priority, created_at, id) > \
                (SELECT priority, created_at, id FROM cursor)) \
         ORDER BY priority ASC, created_at ASC, id ASC LIMIT $10"
    ))
    .bind(policy.all_sites)
    .bind(&policy.sites)
    .bind(policy.all_environments)
    .bind(&policy.environments)
    .bind(policy.bypass_owner)
    .bind(&policy.principal)
    .bind(policy.allow_global)
    .bind(&user)
    .bind(after)
    .bind(limit + 1)
    .fetch_all(pool)
    .await
    .map_err(db_error)?;
    let has_more = rows.len() as i64 > limit;
    rows.truncate(limit as usize);
    let next_cursor = if has_more {
        rows.last().map(|row| row.id.clone())
    } else {
        None
    };
    let items: Vec<Value> = rows
        .iter()
        .map(|row| {
            json!({
                "id": row.id,
                "item_type": row.item_type,
                "title": row.title,
                "priority": row.priority,
                "acknowledged": row.acknowledged,
                "escalated": row.escalated,
                "created_at": row.created_at.to_rfc3339(),
            })
        })
        .collect();

    Ok(Json(json!({
        "source": "database",
        "user": user,
        "count": items.len(),
        "items": items,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
    })))
}

async fn shift_stale(
    AuthExtractor(session): AuthExtractor,
    Query(params): Query<ShiftPageQuery>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let policy = shift_queue_admit(&session)?;
    let limit = shift_queue_limit(params.limit);
    let after = shift_queue_after(params.after.as_deref())?;
    let Some(pool) = get_db() else {
        if is_scoped(&session) {
            return Err(status_503_no_db());
        }
        return Ok(Json(shift_queue::get_stale_items()));
    };

    // Stale = unresolved, unacknowledged, and older than four hours. Scope is
    // part of the CTE, so denied rows cannot affect page fullness or cursors.
    let mut rows: Vec<ShiftQueueRow> = sqlx::query_as(&format!(
        "WITH authorized AS ( \
             SELECT * FROM shift_queue \
             WHERE resolved = false \
               AND acknowledged = false \
               AND created_at <= NOW() - INTERVAL '4 hours' \
               AND {SHIFT_QUEUE_SCOPE_SQL} \
         ), cursor AS ( \
             SELECT created_at, id FROM authorized WHERE id = $8 \
         ) \
         SELECT {SHIFT_QUEUE_COLUMNS} FROM authorized \
         WHERE ($8::uuid IS NULL OR (created_at, id) > \
                (SELECT created_at, id FROM cursor)) \
         ORDER BY created_at ASC, id ASC LIMIT $9"
    ))
    .bind(policy.all_sites)
    .bind(&policy.sites)
    .bind(policy.all_environments)
    .bind(&policy.environments)
    .bind(policy.bypass_owner)
    .bind(&policy.principal)
    .bind(policy.allow_global)
    .bind(after)
    .bind(limit + 1)
    .fetch_all(pool)
    .await
    .map_err(db_error)?;
    let has_more = rows.len() as i64 > limit;
    rows.truncate(limit as usize);
    let next_cursor = if has_more {
        rows.last().map(|row| row.id.clone())
    } else {
        None
    };
    let now = chrono::Utc::now();
    let items: Vec<Value> = rows
        .iter()
        .map(|row| {
            json!({
                "id": row.id,
                "item_type": row.item_type,
                "title": row.title,
                "priority": row.priority,
                "assigned_to": row.assigned_to,
                "created_at": row.created_at.to_rfc3339(),
                "hours_stale": (now - row.created_at).num_hours(),
            })
        })
        .collect();

    Ok(Json(json!({
        "source": "database",
        "stale_threshold_hours": 4,
        "count": items.len(),
        "items": items,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
    })))
}

async fn shift_contract() -> Json<Value> {
    Json(shift_queue::get_shift_contract())
}

/// Optional filters + pagination for the operator triage list. All filters are
/// applied as BOUND params in the repo (injection-safe); an unset field matches all.
#[derive(Debug, Deserialize, Default)]
struct ShiftListParams {
    item_type: Option<String>,
    priority: Option<String>,
    assigned_to: Option<String>,
    resolved: Option<bool>,
    acknowledged: Option<bool>,
    escalated: Option<bool>,
    /// `true` ⇒ only unassigned items; `false` ⇒ only assigned.
    unassigned: Option<bool>,
    limit: Option<i64>,
    offset: Option<i64>,
}

/// GET /api/ops/shift/items — filtered + paginated operator triage list over the
/// shift queue. Unlike `/summary` (aggregates), `/my-items` (one owner), and
/// `/stale` (one hardcoded predicate), this lets an operator triage by item_type /
/// priority / status / owner. DB-only (503 in no-DB — the engine store has no
/// generic filtered list). `limit` defaults to 50 (clamped 1..=200); `has_more` is
/// derived by over-fetching one row (no COUNT).
///
/// AUTHZ: the closed central read manifest and this handler both require
/// `execute`. The repository then applies the server-derived typed
/// site/environment/owner policy before content filters, ordering, over-fetch,
/// LIMIT, and OFFSET, so pages and `has_more` cannot include denied rows.
async fn shift_list(
    AuthExtractor(session): AuthExtractor,
    Query(p): Query<ShiftListParams>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let policy = shift_queue_admit(&session)?;
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let limit = p.limit.unwrap_or(50).clamp(1, 200);
    let offset = p.offset.unwrap_or(0).max(0);
    let filter = crate::repos::shift_queue::ShiftQueueFilter {
        item_type: p.item_type.as_deref(),
        priority: p.priority.as_deref(),
        assigned_to: p.assigned_to.as_deref(),
        resolved: p.resolved,
        acknowledged: p.acknowledged,
        escalated: p.escalated,
        unassigned: p.unassigned,
    };
    // Over-fetch one row to derive has_more without a COUNT query.
    let access = policy.repository_access();
    let mut rows =
        crate::repos::shift_queue::list_filtered(pool, &access, &filter, limit + 1, offset)
            .await
            .map_err(db_error)?;
    let has_more = rows.len() as i64 > limit;
    rows.truncate(limit as usize);
    let items: Vec<Value> = rows
        .iter()
        .map(|r| {
            json!({
                "id": r.id,
                "item_type": r.item_type,
                "title": r.title,
                "description": r.description,
                "priority": r.priority,
                "assigned_to": r.assigned_to,
                "created_at": r.created_at.to_rfc3339(),
                "acknowledged": r.acknowledged,
                "escalated": r.escalated,
                "resolved": r.resolved,
            })
        })
        .collect();
    Ok(Json(json!({
        "source": "database",
        "items": items,
        "count": items.len(),
        "limit": limit,
        "offset": offset,
        "has_more": has_more,
    })))
}

