// ─── Emergency Change (Break-Glass) handlers ───

/// By-id scope guard for the `ProblemDetails`-returning emergency-change handlers
/// (#2). Out-of-scope maps to the SAME 404 "Emergency change {id} not found" the
/// handlers use for a missing row, so there is no existence oracle. Used where the
/// row (and its site) is already in hand.
fn emergency_scope_guard(
    session: &AuthSession,
    site: &str,
    id: &str,
    code: &str,
) -> Result<(), ProblemDetails> {
    if row_scope_permits(session, site, "") {
        Ok(())
    } else {
        Err(problem_details(
            StatusCode::NOT_FOUND,
            code,
            format!("Emergency change {id} not found"),
            None::<&str>,
        ))
    }
}

/// Pre-load an emergency change's site and apply the scope guard before a CAS
/// UPDATE that has no row in hand (#2). Skips the extra read for unrestricted
/// principals; an out-of-scope OR absent row yields the canonical 404 so the CAS
/// path is never an existence oracle.
async fn emergency_scope_preload_guard(
    pool: &sqlx::PgPool,
    session: &AuthSession,
    id: &str,
    code: &str,
) -> Result<(), ProblemDetails> {
    if !is_scoped(session) {
        return Ok(());
    }
    let site: Option<String> =
        sqlx::query_scalar("SELECT site FROM emergency_changes WHERE id = $1::uuid")
            .bind(id)
            .fetch_optional(pool)
            .await
            .map_err(|e| {
                tracing::error!(error = %e, "emergency change scope pre-load DB error");
                problem_details(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    code,
                    "database error",
                    None::<&str>,
                )
            })?;
    match site {
        Some(s) if row_scope_permits(session, &s, "") => Ok(()),
        _ => Err(problem_details(
            StatusCode::NOT_FOUND,
            code,
            format!("Emergency change {id} not found"),
            None::<&str>,
        )),
    }
}

fn require_emergency_human_admin(
    session: &AuthSession,
    code: &'static str,
) -> Result<(), ProblemDetails> {
    if check_human_signoff_permission(session, "admin") {
        return Ok(());
    }
    Err(problem_details(
        StatusCode::FORBIDDEN,
        code,
        "break-glass operations require a verified human administrator",
        None::<&str>,
    ))
}

async fn emergency_initiate(
    Extension(session): Extension<AuthSession>,
    Json(body): Json<EmergencyInitiateRequest>,
) -> Result<Json<Value>, ProblemDetails> {
    require_emergency_human_admin(&session, "EMERGENCY_INITIATE_FAILED")?;
    let initiating_principal = session
        .principal_id
        .ok_or_else(|| {
            problem_details(
                StatusCode::FORBIDDEN,
                "EMERGENCY_INITIATE_FAILED",
                "break-glass operations require an opaque principal binding",
                None::<&str>,
            )
        })?
        .to_string();
    // Initiator = authenticated caller (from request extensions), never a
    // client body field — break-glass audit must name the real principal.
    // #2: scoped principals may only initiate in their own site; env-scoped
    // principals are rejected (emergency_changes is site-only). Applied before
    // both the DB and no-DB paths.
    if session
        .environment_scope
        .iter()
        .any(|s| !s.trim().is_empty())
        || !ryuki_engine::auth::scope_permits(&session.site_scope, Some(&body.site))
    {
        return Err(problem_details(
            StatusCode::FORBIDDEN,
            "EMERGENCY_INITIATE_FAILED",
            "site is outside your authorized scope",
            None::<&str>,
        ));
    }
    if let Some(pool) = get_db() {
        if body.description.is_empty() || body.reason.is_empty() || body.site.is_empty() {
            return Err(problem_details(
                StatusCode::BAD_REQUEST,
                "EMERGENCY_INITIATE_FAILED",
                "description, reason, and site are required",
                None::<&str>,
            ));
        }
        let id = Uuid::new_v4();
        let now = chrono::Utc::now();
        let mut tx = pool.begin().await.map_err(|e| {
            tracing::error!(error = %e, "emergency change DB error");
            problem_details(
                StatusCode::INTERNAL_SERVER_ERROR,
                "EMERGENCY_INITIATE_FAILED",
                "database error",
                None::<&str>,
            )
        })?;
        sqlx::query(
            "INSERT INTO emergency_changes \
             (id, change_description, affected_systems, initiated_by, reason_override, \
              status, audit_evidence, site, created_at, updated_at) \
             VALUES ($1, $2, $3, $4, $5, 'Initiated', '{}', $6, $7, $7)",
        )
        .bind(id)
        .bind(&body.description)
        .bind(&body.systems)
        .bind(&initiating_principal)
        .bind(&body.reason)
        .bind(&body.site)
        .bind(now)
        .execute(&mut *tx)
        .await
        .map_err(|e| {
            tracing::error!(error = %e, "emergency change DB error");
            problem_details(
                StatusCode::INTERNAL_SERVER_ERROR,
                "EMERGENCY_INITIATE_FAILED",
                "database error",
                None::<&str>,
            )
        })?;
        audit::record_audit_tx(
            &mut tx,
            &session,
            &audit::security_audit(
                "emergency-initiate",
                None,
                "initiated",
                json!({ "change_id": id, "site": &body.site }),
            ),
        )
        .await
        .map_err(|e| {
            tracing::error!(error = %e, "emergency change audit DB error");
            problem_details(
                StatusCode::INTERNAL_SERVER_ERROR,
                "EMERGENCY_INITIATE_FAILED",
                "database error",
                None::<&str>,
            )
        })?;
        tx.commit().await.map_err(|e| {
            tracing::error!(error = %e, "emergency change commit DB error");
            problem_details(
                StatusCode::INTERNAL_SERVER_ERROR,
                "EMERGENCY_INITIATE_FAILED",
                "database error",
                None::<&str>,
            )
        })?;
        return Ok(Json(json!({
            "source": "database",
            "change_id": id.to_string(),
            "status": "Initiated",
            "initiated_by": &initiating_principal,
            "site": body.site,
            "created_at": now.to_rfc3339(),
            "dry_run": true,
        })));
    }
    match emergency_change::initiate_emergency(
        &body.description,
        body.systems,
        &initiating_principal,
        &body.reason,
        &body.site,
    ) {
        Ok(v) => Ok(Json(v)),
        Err(e) => Err(problem_details(
            StatusCode::BAD_REQUEST,
            "EMERGENCY_INITIATE_FAILED",
            e,
            None::<&str>,
        )),
    }
}

async fn emergency_approve(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> Result<Json<Value>, ProblemDetails> {
    require_emergency_human_admin(&session, "EMERGENCY_APPROVE_FAILED")?;
    let approving_principal = session
        .principal_id
        .ok_or_else(|| {
            problem_details(
                StatusCode::FORBIDDEN,
                "EMERGENCY_APPROVE_FAILED",
                "break-glass operations require an opaque principal binding",
                None::<&str>,
            )
        })?
        .to_string();
    if let Some(pool) = get_db() {
        // #2: out-of-scope (or absent) -> the canonical 404 before the CAS.
        emergency_scope_preload_guard(pool, &session, &id, "EMERGENCY_APPROVE_FAILED").await?;
        let now = chrono::Utc::now();
        let approved_by = approving_principal;
        let audit_entry = format!(
            "EMERGENCY human approval by {} at {}",
            approved_by,
            now.to_rfc3339()
        );
        // Atomic compare-and-set: only transitions Initiated → Approved.
        let mut tx = pool.begin().await.map_err(|e| {
            tracing::error!(error = %e, "emergency change DB error");
            problem_details(
                StatusCode::INTERNAL_SERVER_ERROR,
                "EMERGENCY_APPROVE_FAILED",
                "database error",
                None::<&str>,
            )
        })?;
        let result = sqlx::query(
            "UPDATE emergency_changes \
             SET status = 'Approved', approved_by = $1, \
                 audit_evidence = audit_evidence || ARRAY[$2::text], \
                 updated_at = $3 \
             WHERE id = $4::uuid AND status = 'Initiated'",
        )
        .bind(&approved_by)
        .bind(&audit_entry)
        .bind(now)
        .bind(&id)
        .execute(&mut *tx)
        .await
        .map_err(|e| {
            tracing::error!(error = %e, "emergency change DB error");
            problem_details(
                StatusCode::INTERNAL_SERVER_ERROR,
                "EMERGENCY_APPROVE_FAILED",
                "database error",
                None::<&str>,
            )
        })?;
        if result.rows_affected() == 1 {
            audit::record_audit_tx(
                &mut tx,
                &session,
                &audit::security_audit(
                    "emergency-approve",
                    None,
                    "approved",
                    json!({ "change_id": &id }),
                ),
            )
            .await
            .map_err(|e| {
                tracing::error!(error = %e, "emergency change DB error");
                problem_details(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "EMERGENCY_APPROVE_FAILED",
                    "database error",
                    None::<&str>,
                )
            })?;
            tx.commit().await.map_err(|e| {
                tracing::error!(error = %e, "emergency change DB error");
                problem_details(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "EMERGENCY_APPROVE_FAILED",
                    "database error",
                    None::<&str>,
                )
            })?;
            return Ok(Json(json!({
                "source": "database",
                "change_id": id,
                "status": "Approved",
                "approved_by": approved_by,
                "approved_at": now.to_rfc3339(),
                "dry_run": true,
            })));
        }
        // 0 rows affected: drop tx (rolls back), then distinguish 404 vs wrong-state 409.
        drop(tx);
        let existing: Option<String> =
            sqlx::query_scalar("SELECT status FROM emergency_changes WHERE id = $1::uuid")
                .bind(&id)
                .fetch_optional(pool)
                .await
                .unwrap_or(None);
        return match existing {
            None => Err(problem_details(
                StatusCode::NOT_FOUND,
                "EMERGENCY_APPROVE_FAILED",
                format!("Emergency change {} not found", id),
                None::<&str>,
            )),
            Some(s) => Err(problem_details(
                StatusCode::CONFLICT,
                "EMERGENCY_APPROVE_FAILED",
                format!("Cannot approve change in {} status", s),
                None::<&str>,
            )),
        };
    }
    // #2: the no-DB fallback uses a process-local store with no site dimension; a
    // scoped principal fails closed rather than act on a cross-site change.
    if is_scoped(&session) {
        return Err(problem_details(
            StatusCode::SERVICE_UNAVAILABLE,
            "EMERGENCY_APPROVE_FAILED",
            "scoped access requires the database",
            None::<&str>,
        ));
    }
    match emergency_change::auto_approve(&id) {
        Ok(v) => Ok(Json(v)),
        Err(e) => Err(problem_details(
            StatusCode::BAD_REQUEST,
            "EMERGENCY_APPROVE_FAILED",
            e,
            None::<&str>,
        )),
    }
}

async fn emergency_execute(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> Result<Json<Value>, ProblemDetails> {
    require_emergency_human_admin(&session, "EMERGENCY_EXECUTE_FAILED")?;
    if let Some(pool) = get_db() {
        let now = chrono::Utc::now();
        // First: read affected_systems so we can include them in the response
        // (needed for the JSON shape parity with the engine response).
        // Pre-read stays on pool (no tx yet).
        let row: Option<EmergencyChangeRow> = sqlx::query_as(&format!(
            "SELECT {EMERGENCY_CHANGE_COLUMNS} FROM emergency_changes WHERE id = $1::uuid"
        ))
        .bind(&id)
        .fetch_optional(pool)
        .await
        .map_err(|e| {
            tracing::error!(error = %e, "emergency change DB error");
            problem_details(
                StatusCode::INTERNAL_SERVER_ERROR,
                "EMERGENCY_EXECUTE_FAILED",
                "database error",
                None::<&str>,
            )
        })?;
        let Some(row) = row else {
            return Err(problem_details(
                StatusCode::NOT_FOUND,
                "EMERGENCY_EXECUTE_FAILED",
                format!("Emergency change {} not found", id),
                None::<&str>,
            ));
        };
        // #2: out-of-scope -> 404 (same as not-found) before the status-409 leak.
        emergency_scope_guard(&session, &row.site, &id, "EMERGENCY_EXECUTE_FAILED")?;
        if row.status != "Approved" {
            return Err(problem_details(
                StatusCode::CONFLICT,
                "EMERGENCY_EXECUTE_FAILED",
                format!(
                    "Cannot execute change in {} status — approval required",
                    row.status
                ),
                None::<&str>,
            ));
        }
        let exec_entry = format!(
            "[REDACTED] Dry-run mock execution completed at {}",
            now.to_rfc3339()
        );
        let systems_entry = format!(
            "[REDACTED] Affected systems: {}",
            row.affected_systems.join(", ")
        );
        // Atomic conditional UPDATE: only transitions Approved → Executed.
        let mut tx = pool.begin().await.map_err(|e| {
            tracing::error!(error = %e, "emergency change DB error");
            problem_details(
                StatusCode::INTERNAL_SERVER_ERROR,
                "EMERGENCY_EXECUTE_FAILED",
                "database error",
                None::<&str>,
            )
        })?;
        let result = sqlx::query(
            "UPDATE emergency_changes \
             SET status = 'Executed', executed_at = $1, \
                 audit_evidence = audit_evidence || ARRAY[$2::text, $3::text], \
                 updated_at = $1 \
             WHERE id = $4::uuid AND status = 'Approved'",
        )
        .bind(now)
        .bind(&exec_entry)
        .bind(&systems_entry)
        .bind(&id)
        .execute(&mut *tx)
        .await
        .map_err(|e| {
            tracing::error!(error = %e, "emergency change DB error");
            problem_details(
                StatusCode::INTERNAL_SERVER_ERROR,
                "EMERGENCY_EXECUTE_FAILED",
                "database error",
                None::<&str>,
            )
        })?;
        if result.rows_affected() == 1 {
            audit::record_audit_tx(
                &mut tx,
                &session,
                &audit::security_audit(
                    "emergency-execute",
                    Some("Approved"),
                    "executed",
                    json!({ "change_id": &id }),
                ),
            )
            .await
            .map_err(|e| {
                tracing::error!(error = %e, "emergency change DB error");
                problem_details(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "EMERGENCY_EXECUTE_FAILED",
                    "database error",
                    None::<&str>,
                )
            })?;
            tx.commit().await.map_err(|e| {
                tracing::error!(error = %e, "emergency change DB error");
                problem_details(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "EMERGENCY_EXECUTE_FAILED",
                    "database error",
                    None::<&str>,
                )
            })?;
            let mut updated_evidence = row.audit_evidence.clone();
            updated_evidence.push(exec_entry);
            updated_evidence.push(systems_entry);
            return Ok(Json(json!({
                "source": "database",
                "change_id": id,
                "status": "Executed",
                "executed_at": now.to_rfc3339(),
                "affected_systems": row.affected_systems,
                "audit_evidence": updated_evidence,
                "dry_run": true,
            })));
        }
        // Race: another request got here first (no audit, no commit).
        return Err(problem_details(
            StatusCode::CONFLICT,
            "EMERGENCY_EXECUTE_FAILED",
            format!("Emergency change {} is no longer in Approved status", id),
            None::<&str>,
        ));
    }
    // #2: no-DB fallback can't enforce site scope on the static store.
    if is_scoped(&session) {
        return Err(problem_details(
            StatusCode::SERVICE_UNAVAILABLE,
            "EMERGENCY_EXECUTE_FAILED",
            "scoped access requires the database",
            None::<&str>,
        ));
    }
    match emergency_change::execute_emergency(&id) {
        Ok(v) => Ok(Json(v)),
        Err(e) => Err(problem_details(
            StatusCode::BAD_REQUEST,
            "EMERGENCY_EXECUTE_FAILED",
            e,
            None::<&str>,
        )),
    }
}

async fn emergency_verify(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> Result<Json<Value>, ProblemDetails> {
    require_emergency_human_admin(&session, "EMERGENCY_VERIFY_FAILED")?;
    if let Some(pool) = get_db() {
        // #2: out-of-scope (or absent) -> the canonical 404 before the CAS.
        emergency_scope_preload_guard(pool, &session, &id, "EMERGENCY_VERIFY_FAILED").await?;
        let now = chrono::Utc::now();
        let verify_entry = format!(
            "[REDACTED] Post-execution verification passed at {}",
            now.to_rfc3339()
        );
        // Atomic conditional UPDATE: only transitions Executed → Verified.
        let mut tx = pool.begin().await.map_err(|e| {
            tracing::error!(error = %e, "emergency change DB error");
            problem_details(
                StatusCode::INTERNAL_SERVER_ERROR,
                "EMERGENCY_VERIFY_FAILED",
                "database error",
                None::<&str>,
            )
        })?;
        let result = sqlx::query(
            "UPDATE emergency_changes \
             SET status = 'Verified', \
                 audit_evidence = audit_evidence || ARRAY[$1::text], \
                 updated_at = $2 \
             WHERE id = $3::uuid AND status = 'Executed'",
        )
        .bind(&verify_entry)
        .bind(now)
        .bind(&id)
        .execute(&mut *tx)
        .await
        .map_err(|e| {
            tracing::error!(error = %e, "emergency change DB error");
            problem_details(
                StatusCode::INTERNAL_SERVER_ERROR,
                "EMERGENCY_VERIFY_FAILED",
                "database error",
                None::<&str>,
            )
        })?;
        if result.rows_affected() == 1 {
            audit::record_audit_tx(
                &mut tx,
                &session,
                &audit::security_audit(
                    "emergency-verify",
                    Some("Executed"),
                    "verified",
                    json!({ "change_id": &id }),
                ),
            )
            .await
            .map_err(|e| {
                tracing::error!(error = %e, "emergency change DB error");
                problem_details(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "EMERGENCY_VERIFY_FAILED",
                    "database error",
                    None::<&str>,
                )
            })?;
            tx.commit().await.map_err(|e| {
                tracing::error!(error = %e, "emergency change DB error");
                problem_details(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "EMERGENCY_VERIFY_FAILED",
                    "database error",
                    None::<&str>,
                )
            })?;
            // Re-read audit_evidence from pool after commit for the response shape.
            let evidence: Vec<String> = sqlx::query_scalar(
                "SELECT audit_evidence FROM emergency_changes WHERE id = $1::uuid",
            )
            .bind(&id)
            .fetch_one(pool)
            .await
            .unwrap_or_default();
            return Ok(Json(json!({
                "source": "database",
                "change_id": id,
                "status": "Verified",
                "verified_at": now.to_rfc3339(),
                "audit_evidence": evidence,
                "dry_run": true,
            })));
        }
        // 0 rows affected: distinguish 404 vs wrong-state (no audit, no commit).
        drop(tx);
        let existing: Option<String> =
            sqlx::query_scalar("SELECT status FROM emergency_changes WHERE id = $1::uuid")
                .bind(&id)
                .fetch_optional(pool)
                .await
                .unwrap_or(None);
        return match existing {
            None => Err(problem_details(
                StatusCode::NOT_FOUND,
                "EMERGENCY_VERIFY_FAILED",
                format!("Emergency change {} not found", id),
                None::<&str>,
            )),
            Some(s) => Err(problem_details(
                StatusCode::CONFLICT,
                "EMERGENCY_VERIFY_FAILED",
                format!("Cannot verify change in {} status — execution required", s),
                None::<&str>,
            )),
        };
    }
    // #2: no-DB fallback can't enforce site scope on the static store.
    if is_scoped(&session) {
        return Err(problem_details(
            StatusCode::SERVICE_UNAVAILABLE,
            "EMERGENCY_VERIFY_FAILED",
            "scoped access requires the database",
            None::<&str>,
        ));
    }
    match emergency_change::verify_emergency(&id) {
        Ok(v) => Ok(Json(v)),
        Err(e) => Err(problem_details(
            StatusCode::BAD_REQUEST,
            "EMERGENCY_VERIFY_FAILED",
            e,
            None::<&str>,
        )),
    }
}

