async fn maintenance_calendar_month(
    AuthExtractor(session): AuthExtractor,
    Query(q): Query<MaintenanceCalendarMonthQuery>,
) -> ApiResult {
    // #2: a scoped principal may only see its own site's calendar month.
    guard_body_site_scope(&session, &q.site)?;
    if let Some(pool) = get_db() {
        // Validate and parse the "YYYY-MM" month string; mirrors the engine's error message.
        let month_start_rfc = format!("{}-01T00:00:00Z", q.month);
        let month_start: chrono::DateTime<chrono::Utc> =
            chrono::DateTime::parse_from_rfc3339(&month_start_rfc)
                .map_err(|e| {
                    status_400(&format!("Invalid month format (expected YYYY-MM): {}", e))
                })?
                .with_timezone(&chrono::Utc);

        // Compute the first day of the next month by parsing the YYYY-MM string directly.
        // Mirrors the engine's get_calendar logic, avoiding a Datelike trait import.
        let parts: Vec<&str> = q.month.splitn(2, '-').collect();
        let (year_str, month_str) = if parts.len() == 2 {
            (parts[0], parts[1])
        } else {
            return Err(status_400("Invalid month format (expected YYYY-MM)"));
        };
        let year: i32 = year_str
            .parse()
            .map_err(|_| status_400("Invalid month format (expected YYYY-MM)"))?;
        let month: u32 = month_str
            .parse()
            .map_err(|_| status_400("Invalid month format (expected YYYY-MM)"))?;
        let next_month_rfc = if month == 12 {
            format!("{}-01-01T00:00:00Z", year + 1)
        } else {
            format!("{}-{:02}-01T00:00:00Z", year, month + 1)
        };
        let next_month: chrono::DateTime<chrono::Utc> =
            chrono::DateTime::parse_from_rfc3339(&next_month_rfc)
                .map_err(|e| status_400(&format!("Date calculation error: {}", e)))?
                .with_timezone(&chrono::Utc);

        // Mirrors get_calendar: site + start_time in [month_start, next_month); no status filter.
        let rows: Vec<MaintWindowRow> = sqlx::query_as(&format!(
            "SELECT {MW_COLUMNS} FROM maintenance_windows \
             WHERE site = $1 AND start_time >= $2 AND start_time < $3"
        ))
        .bind(&q.site)
        .bind(month_start)
        .bind(next_month)
        .fetch_all(pool)
        .await
        .map_err(db_error)?;
        let windows: Vec<Value> = rows.iter().map(|r| r.to_value()).collect();
        return Ok(Json(json!({ "source": "database", "windows": windows })));
    }
    match maintenance_calendar::get_calendar(&q.site, &q.month) {
        Ok(windows) => Ok(Json(serde_json::to_value(windows).unwrap())),
        Err(e) => Err(status_400(&e)),
    }
}

async fn maintenance_calendar_cancel(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> ApiResult {
    if let Some(pool) = get_db() {
        // Try-parse the path param as a UUID; fall through to the engine on parse failure.
        if let Ok(uid) = Uuid::parse_str(&id) {
            // Pre-SELECT to distinguish not-found vs. already-cancelled vs. completed,
            // mirroring the engine's error strings exactly.
            let existing: Option<MaintWindowRow> = sqlx::query_as(&format!(
                "SELECT {MW_COLUMNS} FROM maintenance_windows WHERE id = $1"
            ))
            .bind(uid)
            .fetch_optional(pool)
            .await
            .map_err(db_error)?;

            match existing {
                None => {
                    return Err(status_400(&format!("Maintenance window not found: {}", id)));
                }
                // #2: an out-of-scope window is reported identically to a missing
                // one (same 400) so a scoped principal gets no existence oracle and
                // cannot cancel another site's window.
                Some(ref row) if !row_scope_permits(&session, &row.site, "") => {
                    return Err(status_400(&format!("Maintenance window not found: {}", id)));
                }
                Some(ref row) if row.status == "Completed" => {
                    return Err(status_400("Cannot cancel a completed maintenance window"));
                }
                Some(ref row) if row.status == "Cancelled" => {
                    return Err(status_400("Maintenance window is already cancelled"));
                }
                _ => {}
            }

            let mut tx = pool.begin().await.map_err(db_error)?;
            let updated: MaintWindowRow = sqlx::query_as(&format!(
                "UPDATE maintenance_windows SET status = 'Cancelled' WHERE id = $1 \
                 RETURNING {MW_COLUMNS}"
            ))
            .bind(uid)
            .fetch_one(&mut *tx)
            .await
            .map_err(db_error)?;
            audit::record_audit_tx(
                &mut tx,
                &session,
                &audit::security_audit(
                    "maintenance-window-cancel",
                    Some("scheduled"),
                    "cancelled",
                    json!({ "window_id": &id }),
                ),
            )
            .await
            .map_err(db_error)?;
            tx.commit().await.map_err(db_error)?;

            return Ok(Json(updated.to_value_with_source("database")));
        }
    }

    // #2: the engine fallback (no-DB, or a non-UUID `mw-*` id) cancels a
    // site-owned window by id with no site check, so a scoped principal fails
    // closed with the same not-found 400 rather than cancel/oracle another site's
    // in-memory window. Unrestricted principals keep the legacy engine path.
    if is_scoped(&session) {
        return Err(status_400(&format!("Maintenance window not found: {}", id)));
    }
    // No-DB or non-UUID id: engine path unchanged.
    match maintenance_calendar::cancel_window(&id) {
        Ok(window) => Ok(Json(serde_json::to_value(window).unwrap())),
        Err(e) => Err(status_400(&e)),
    }
}

async fn maintenance_calendar_contract() -> Json<Value> {
    Json(maintenance_calendar::get_calendar_contract())
}

// ─── Patch wave orchestration handlers ───

async fn patch_plan(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<PatchPlanRequest>,
) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;

    let mut wave = patch_engine::plan_patch_wave(&body.site, &body.os_family, &body.criticality)
        .map_err(|e| status_400(&e))?;

    // #2: a scoped principal may only create a wave whose entire targeting is
    // within its scope. Guard the CONSTRUCTED wave (not just body.site) so the
    // site and environment axes the engine derived are both covered.
    multi_scope_guard_or_404(
        &session,
        &wave.site_scope,
        &wave.environment_scope,
        "patch-wave",
    )?;

    // The engine generates a non-UUID id (e.g. "pw-abc12345") suitable for
    // in-memory use but not for the UUID primary key column. Replace it with a
    // proper UUID so the repo can bind it correctly.
    wave.id = Uuid::new_v4().to_string();

    let mut tx = pool.begin().await.map_err(db_error)?;
    crate::repos::patch_waves::insert(&mut *tx, &wave)
        .await
        .map_err(db_error)?;
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "patch-plan",
            None,
            "planned",
            json!({ "wave_id": &wave.id, "site": wave.site_scope.first() }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;

    Ok(Json(serde_json::to_value(&wave).unwrap_or_default()))
}

async fn patch_validate(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<PatchActionRequest>,
) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;

    let wave = crate::repos::patch_waves::get(pool, &body.wave_id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&body.wave_id))?;

    // #2: out-of-scope wave -> 404 before any state/transition leak.
    multi_scope_guard_or_404(
        &session,
        &wave.site_scope,
        &wave.environment_scope,
        &body.wave_id,
    )?;

    let before = crate::repos::patch_waves::status_str(&wave.status);

    let (updated, result) = patch_engine::validate_patch_wave(&wave).map_err(|e| status_409(&e))?;

    let mut tx = pool.begin().await.map_err(db_error)?;
    let ok = crate::repos::patch_waves::transition(&mut tx, before, &updated, None)
        .await
        .map_err(db_error)?;
    if !ok {
        return Err(status_409("state changed concurrently; reload and retry"));
    }
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "patch-validate",
            Some(before),
            "validated",
            json!({ "wave_id": &body.wave_id }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;

    Ok(Json(serde_json::to_value(&result).unwrap_or_default()))
}

async fn patch_approve(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<PatchActionRequest>,
) -> ApiResult {
    let approver_principal = authenticated_principal_id(&session)?.to_string();
    let pool = get_db().ok_or_else(status_503_no_db)?;

    let wave = crate::repos::patch_waves::get(pool, &body.wave_id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&body.wave_id))?;

    // #2: out-of-scope wave -> 404 before any state/transition leak.
    multi_scope_guard_or_404(
        &session,
        &wave.site_scope,
        &wave.environment_scope,
        &body.wave_id,
    )?;

    let before = crate::repos::patch_waves::status_str(&wave.status);

    // approver = the authenticated caller, recorded in the wave's approval audit
    // trail (never a hardcoded string).
    let approved =
        patch_engine::approve_patch_wave(&wave, &approver_principal).map_err(|e| status_409(&e))?;

    let mut tx = pool.begin().await.map_err(db_error)?;
    let ok = crate::repos::patch_waves::transition(&mut tx, before, &approved, None)
        .await
        .map_err(db_error)?;
    if !ok {
        return Err(status_409("state changed concurrently; reload and retry"));
    }
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "patch-approve",
            Some(before),
            "approved",
            json!({ "wave_id": &body.wave_id }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;

    Ok(Json(serde_json::to_value(&approved).unwrap_or_default()))
}

async fn patch_execute(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<PatchActionRequest>,
) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;

    let wave = crate::repos::patch_waves::get(pool, &body.wave_id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&body.wave_id))?;

    // #2: out-of-scope wave -> 404 before any state/transition leak.
    multi_scope_guard_or_404(
        &session,
        &wave.site_scope,
        &wave.environment_scope,
        &body.wave_id,
    )?;

    let before = crate::repos::patch_waves::status_str(&wave.status);

    let (completed, evidence) =
        patch_engine::execute_patch_wave(&wave).map_err(|e| status_409(&e))?;

    let mut tx = pool.begin().await.map_err(db_error)?;
    let ok = crate::repos::patch_waves::transition(&mut tx, before, &completed, None)
        .await
        .map_err(db_error)?;
    if !ok {
        return Err(status_409("state changed concurrently; reload and retry"));
    }
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "patch-execute",
            Some(before),
            "executed",
            json!({ "wave_id": &body.wave_id }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;

    Ok(Json(serde_json::to_value(&evidence).unwrap_or_default()))
}

async fn patch_verify(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<PatchActionRequest>,
) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;

    let wave = crate::repos::patch_waves::get(pool, &body.wave_id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&body.wave_id))?;

    // #2: out-of-scope wave -> 404 before any evidence is computed.
    multi_scope_guard_or_404(
        &session,
        &wave.site_scope,
        &wave.environment_scope,
        &body.wave_id,
    )?;

    // verify is evidence-only; it does NOT transition the wave.
    let result = patch_engine::verify_patch_wave(&wave).map_err(|e| status_409(&e))?;

    Ok(Json(serde_json::to_value(&result).unwrap_or_default()))
}

/// Produce the dry-run reboot-orchestration plan for a persisted wave. Like
/// verify, this is evidence-only: it computes the staged, BATCHED (rolling)
/// reboot plan (backup verify -> per batch: drain-batch -> reboot-batch
/// servers -> health-check-batch gate -> final fleet-wide check, all simulated)
/// and does NOT transition the wave. Batch size comes from the wave's
/// `reboot_batch_size` / `reboot_batch_percent` metadata (default: one server
/// per batch). 503 without a database, 404 when the wave is absent, 409 when
/// the engine rejects the wave (e.g. zero servers).
async fn patch_reboot(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<PatchActionRequest>,
) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;

    let wave = crate::repos::patch_waves::get(pool, &body.wave_id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&body.wave_id))?;

    // #2: out-of-scope wave -> 404 before any reboot plan is computed.
    multi_scope_guard_or_404(
        &session,
        &wave.site_scope,
        &wave.environment_scope,
        &body.wave_id,
    )?;

    let stages = patch_engine::orchestrate_reboot(&wave).map_err(|e| status_409(&e))?;

    Ok(Json(serde_json::to_value(&stages).unwrap_or_default()))
}

/// Dedicated pagination query for GET /api/maintain/patch/waves (#14) —
/// endpoint-local rather than a shared struct, so another handler's params can
/// never bleed into this list's contract (the 400-regression class).
#[derive(Debug, Deserialize)]
struct PatchWaveListQuery {
    limit: Option<i64>,
    offset: Option<i64>,
}

/// List persisted patch waves (read surface), paged (#14). Returns an empty
/// list when no database is configured (demo mode), matching the other
/// read-only GETs. The body stays a BARE array (backward-compatible); the
/// scope-filtered total rides the `X-Total-Count` header.
async fn patch_waves_list(
    AuthExtractor(session): AuthExtractor,
    Query(q): Query<PatchWaveListQuery>,
) -> Result<(HeaderMap, Json<Value>), (StatusCode, Json<Value>)> {
    // #14: bound the page (generous default keeps seed-scale callers unaffected).
    let limit = q.limit.unwrap_or(500).clamp(1, 1000);
    let offset = q.offset.unwrap_or(0).max(0);
    let Some(pool) = get_db() else {
        return Ok((
            total_count_headers(0),
            Json(serde_json::Value::Array(vec![])),
        ));
    };
    // #2: a scoped principal only sees waves whose entire targeting is within
    // its scope (env-scoped principals see none of the cross-env waves) — the
    // old in-memory `multi_scope_permits` retain, pushed INTO SQL (#14) so a
    // LIMIT/OFFSET page and the total both reflect the scope-filtered set.
    let sites = multi_scope_axis_sql_filter(&session.site_scope);
    let envs = multi_scope_axis_sql_filter(&session.environment_scope);
    let waves = crate::repos::patch_waves::list_page(
        pool,
        sites.as_deref(),
        envs.as_deref(),
        limit,
        offset,
    )
    .await
    .map_err(db_error)?;
    let total = crate::repos::patch_waves::count(pool, sites.as_deref(), envs.as_deref())
        .await
        .map_err(db_error)?;
    Ok((
        total_count_headers(total),
        Json(serde_json::to_value(&waves).unwrap_or_default()),
    ))
}

/// Fetch a single persisted patch wave by id (read surface). 404 when absent or
/// when no database is configured.
async fn patch_wave_get(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> ApiResult {
    if let Some(pool) = get_db() {
        return match crate::repos::patch_waves::get(pool, &id).await {
            Ok(Some(wave)) => {
                // #2: out-of-scope wave -> 404 (no existence oracle).
                multi_scope_guard_or_404(&session, &wave.site_scope, &wave.environment_scope, &id)?;
                Ok(Json(serde_json::to_value(&wave).unwrap_or_default()))
            }
            Ok(None) => Err(status_404(&id)),
            Err(e) => Err(db_error(e)),
        };
    }
    Err(status_404(&id))
}

/// DELETE /api/maintain/patch/waves/{id} — remove a mistaken patch wave. Only an
/// UNAPPROVED draft (`Draft`/`Validated`) is deletable at this `execute`-tier route:
/// an `Approved`/`Scheduled` wave is approver-reviewed (deleting it is an
/// approval-tier cancellation — out of scope) and an `InProgress`/`Completed`/`Failed`
/// wave has executed (its run is evidence). The `patch_wave_servers` rows cascade.
async fn patch_wave_delete(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let wave = crate::repos::patch_waves::get(pool, &id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&id))?;
    // #2: an out-of-scope wave 404s exactly like a missing one (no existence oracle).
    multi_scope_guard_or_404(&session, &wave.site_scope, &wave.environment_scope, &id)?;
    if !crate::repos::patch_waves::patch_wave_status_deletable(&wave.status) {
        return Err(status_409(
            "only a Draft or Validated patch wave can be deleted (an approved/scheduled/executed wave cannot)",
        ));
    }
    let before = crate::repos::patch_waves::status_str(&wave.status);
    let mut tx = pool.begin().await.map_err(db_error)?;
    match crate::repos::patch_waves::delete(&mut tx, &id, &wave.status)
        .await
        .map_err(db_error)?
    {
        crate::repos::patch_waves::DeleteOutcome::Deleted => {
            // Tombstone-rich audit: the row (and its cascade) is gone, so capture the
            // wave's identity + scope + size for the durable trail.
            audit::record_audit_tx(
                &mut tx,
                &session,
                &audit::security_audit(
                    "patch-wave-delete",
                    Some(before),
                    "deleted",
                    json!({
                        "wave_id": &id,
                        "name": &wave.name,
                        "site_scope": &wave.site_scope,
                        "environment_scope": &wave.environment_scope,
                        "server_count": wave.servers.len(),
                    }),
                ),
            )
            .await
            .map_err(db_error)?;
            tx.commit().await.map_err(db_error)?;
            Ok(Json(json!({ "deleted": id })))
        }
        crate::repos::patch_waves::DeleteOutcome::BlockedStatus => {
            tx.rollback().await.ok();
            Err(status_409("patch wave status does not permit deletion"))
        }
        crate::repos::patch_waves::DeleteOutcome::StaleStatus => {
            tx.rollback().await.ok();
            Err(status_409(
                "patch wave changed concurrently; reload and retry",
            ))
        }
        crate::repos::patch_waves::DeleteOutcome::NotFound => {
            tx.rollback().await.ok();
            Err(status_404(&id))
        }
    }
}

async fn patch_compliance(AuthExtractor(session): AuthExtractor) -> ApiResult {
    let mut compliance = patch_engine::get_patch_compliance().map_err(|e| status_400(&e))?;
    // #2: the dry-run report spans every site. A scoped principal sees only its
    // own sites' rows, and the cross-site `overall_compliance_percentage` is
    // dropped so it cannot leak out-of-scope posture; unrestricted sees all.
    narrow_site_aggregate(
        &session,
        &mut compliance,
        "sites",
        &["overall_compliance_percentage"],
    );
    Ok(Json(compliance))
}

async fn patch_pending_reboots(AuthExtractor(session): AuthExtractor) -> ApiResult {
    let mut reboots = patch_engine::get_pending_reboots().map_err(|e| status_400(&e))?;
    // #2: a scoped principal only sees pending reboots for its own sites; the
    // cross-site `total_pending` is dropped so it cannot leak an out-of-scope count.
    narrow_site_aggregate(
        &session,
        &mut reboots,
        "pending_reboots",
        &["total_pending"],
    );
    Ok(Json(reboots))
}

