/// Exact immutable target, package, and maker provenance needed before a
/// lifecycle transition may reveal state or mutate a deployment.
#[derive(sqlx::FromRow)]
struct SoftwareDeploymentAuthorizationRow {
    status: String,
    configuration_item_id: Uuid,
    scope_provenance: String,
    server_name: String,
    site: String,
    environment: String,
    package_id: String,
    package_name: String,
    target_version: String,
    requester: String,
    maker_user_id: String,
}

/// Load and lock one deployment only through its current exact CMDB relation.
/// Scope predicates run before decoding and the target, site-registry row, and
/// deployment remain locked through the caller's lifecycle CAS. Missing,
/// legacy, inactive, foreign, unresolved, wrong-type, and drifted targets are
/// deliberately indistinguishable.
async fn lock_software_deployment_authorization(
    connection: &mut sqlx::PgConnection,
    deployment_id: &str,
    session: &AuthSession,
) -> Result<Option<SoftwareDeploymentAuthorizationRow>, sqlx::Error> {
    let site_scope = scope_axis_sql_filter(&session.site_scope);
    let environment_scope = scope_axis_sql_filter(&session.environment_scope);
    sqlx::query_as(
        "SELECT d.status, d.configuration_item_id, d.scope_provenance, \
                d.server_name, d.site, d.environment, d.package_id, \
                d.package_name, d.target_version, d.requester, d.maker_user_id \
         FROM software_deployments AS d \
         INNER JOIN configuration_items AS ci \
                 ON ci.id = d.configuration_item_id \
                AND ci.ci_name = d.server_name \
                AND ci.site = d.site \
                AND ci.environment = d.environment \
                AND ci.ci_type = 'Server' \
         INNER JOIN site_registry AS sr \
                 ON sr.unlocode = d.site AND sr.active = true \
         WHERE d.id = $1 \
           AND d.scope_provenance = 'cmdb-configuration-item' \
           AND d.configuration_item_id IS NOT NULL \
           AND d.site = BTRIM(d.site) \
           AND NULLIF(BTRIM(d.site), '') IS NOT NULL \
           AND d.environment = BTRIM(d.environment) \
           AND NULLIF(BTRIM(d.environment), '') IS NOT NULL \
           AND d.server_name = BTRIM(d.server_name) \
           AND NULLIF(BTRIM(d.server_name), '') IS NOT NULL \
           AND d.package_id = BTRIM(d.package_id) \
           AND NULLIF(BTRIM(d.package_id), '') IS NOT NULL \
           AND d.package_name = BTRIM(d.package_name) \
           AND NULLIF(BTRIM(d.package_name), '') IS NOT NULL \
           AND d.target_version = BTRIM(d.target_version) \
           AND NULLIF(BTRIM(d.target_version), '') IS NOT NULL \
           AND d.maker_user_id = BTRIM(d.maker_user_id) \
           AND NULLIF(BTRIM(d.maker_user_id), '') IS NOT NULL \
           AND d.requester = d.maker_user_id \
           AND ($2::text[] IS NULL OR d.site = ANY($2)) \
           AND ($3::text[] IS NULL OR d.environment = ANY($3)) \
         FOR NO KEY UPDATE OF d, ci, sr",
    )
    .bind(deployment_id)
    .bind(site_scope)
    .bind(environment_scope)
    .fetch_optional(connection)
    .await
}

#[derive(Debug, Deserialize)]
struct SoftwarePackagesQuery {
    site: Option<String>,
    // #14 pagination (optional — absent = unfiltered first page, non-breaking).
    limit: Option<i64>,
    offset: Option<i64>,
}

#[derive(Debug, Deserialize)]
struct SoftwareComplianceQuery {
    site: String,
}

async fn software_packages_list(
    AuthExtractor(session): AuthExtractor,
    Query(query): Query<SoftwarePackagesQuery>,
) -> ApiResult {
    // #2: scoped-site read ("" = all sites for an unrestricted caller).
    let site_scoped = enforce_site_scope(&session, query.site.as_deref(), "")?;
    let site = site_scoped.as_str();
    if let Some(pool) = get_db() {
        // DB path: read approved_packages table (source of truth).
        // site_scope filter mirrors engine SiteScope::covers:
        //   scope='all'  → matches any site request
        //   scope='specific' → site_scope_list must contain the requested site
        // When no site filter is provided ($1 = '') all rows are returned.
        // #14: bound the page. `id` (PK) ORDER BY is unique. `count` uses the SAME
        // site-scope WHERE (bind $1=site) so the total matches the paged set.
        let limit = query.limit.unwrap_or(500).clamp(1, 1000);
        let offset = query.offset.unwrap_or(0).max(0);
        let rows: Vec<ApprovedPackageRow> = sqlx::query_as(&format!(
            "SELECT {PACKAGE_COLUMNS} FROM approved_packages \
             WHERE ($1 = '' \
                OR site_scope = 'all' \
                OR ($1 <> '' AND site_scope = 'specific' AND $1 = ANY(site_scope_list))) \
             ORDER BY id LIMIT $2 OFFSET $3"
        ))
        .bind(site)
        .bind(limit)
        .bind(offset)
        .fetch_all(pool)
        .await
        .map_err(db_error)?;
        let total: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM approved_packages \
             WHERE ($1 = '' \
                OR site_scope = 'all' \
                OR ($1 <> '' AND site_scope = 'specific' AND $1 = ANY(site_scope_list)))",
        )
        .bind(site)
        .fetch_one(pool)
        .await
        .map_err(db_error)?;
        let packages: Vec<Value> = rows.iter().map(ApprovedPackageRow::to_json).collect();
        return Ok(Json(json!({
            "source": "database",
            "packages": packages,
            "count": packages.len(),
            "total": total,
            "limit": limit,
            "offset": offset,
        })));
    }
    // No-DB: engine in-memory store (unchanged fallback).
    let site_opt = if site.is_empty() { None } else { Some(site) };
    let packages = software_deployment::get_approved_packages(site_opt);
    Ok(Json(serde_json::to_value(packages).unwrap()))
}

async fn software_validate(
    Json(mut body): Json<software_deployment::DeploymentRequest>,
) -> ApiResult {
    // Compatibility/advisory validation only. These caller fields can produce
    // validation feedback but establish no planning authority; software_plan
    // always re-resolves target scope and version from locked database rows.
    if let Ok(site) = site_registry::normalize_site_code_for_lookup(&body.site) {
        body.site = site;
    }
    body.environment = body.environment.trim().to_string();
    // DB path: check required fields inline, then query approved_packages to
    // validate the package_id exists. PACKAGE_STORE is not populated from DB rows
    // after restart, so calling validate_deployment() here would false-fail on
    // database-seeded packages.
    if let Some(pool) = get_db() {
        let mut errors: Vec<&str> = Vec::new();
        if body.server_name.is_empty() {
            errors.push("Server name is required");
        }
        if !site_registry::is_valid_site(&body.site) {
            errors.push("An active, canonical site is required");
        }
        if body.environment.is_empty() {
            errors.push("Environment is required");
        }
        if body.package_id.is_empty() {
            errors.push("Package ID is required");
        }
        if body.target_version.is_empty() {
            errors.push("Target version is required");
        }
        // Validate package_id against approved_packages table.
        let pkg_exists: bool = if body.package_id.is_empty() {
            false
        } else {
            sqlx::query_scalar::<_, bool>(
                "SELECT EXISTS(SELECT 1 FROM approved_packages WHERE id = $1)",
            )
            .bind(&body.package_id)
            .fetch_one(pool)
            .await
            .map_err(db_error)?
        };

        if !body.package_id.is_empty() && !pkg_exists {
            errors.push("Package is not in the approved catalog");
        }

        let mut warnings = vec!["DRY-RUN: Server online status verified (simulated)"];
        if body.scheduled_time.is_empty() {
            warnings.push("No scheduled time provided — deployment will be immediate (dry-run)");
        }

        return Ok(Json(json!({
            "passed": errors.is_empty(),
            "errors": errors,
            "warnings": warnings,
            "failed_rules": [],
            "remediation": [],
            "source": "database",
        })));
    }
    // No-DB fallback: engine validates against PACKAGE_STORE (current-process only).
    match software_deployment::validate_deployment(&body) {
        Ok(result) => Ok(Json(serde_json::to_value(result).unwrap())),
        Err(e) => Err(status_400(&e)),
    }
}

async fn software_plan(
    AuthExtractor(session): AuthExtractor,
    Json(mut body): Json<software_deployment::DeploymentRequest>,
) -> ApiResult {
    let principal_id = authenticated_principal_id(&session)?;
    let principal = principal_id.to_string();
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let requested_server = body.server_name.clone();
    let mut tx = pool.begin().await.map_err(db_error)?;

    // The request's server name is only a selector. Resolve it through the
    // provider-neutral CMDB repository and lock both the target and its active
    // site relation before deriving any plan facts. Body site/environment are
    // intentionally ignored and can never grant authority.
    let configuration_item =
        crate::repos::configuration_items::get_authorized_by_name_for_no_key_update(
            &mut tx,
            &requested_server,
            &session.site_scope,
            &session.environment_scope,
        )
        .await
        .map_err(db_error)?
        .ok_or_else(|| {
            if session.site_scope.is_empty() && session.environment_scope.is_empty() {
                status_404(&requested_server)
            } else {
                status_403_out_of_scope("resource")
            }
        })?;
    if configuration_item.ci_type != "Server"
        || configuration_item.ci_name.trim().is_empty()
        || configuration_item.ci_name != configuration_item.ci_name.trim()
        || configuration_item.site.trim().is_empty()
        || configuration_item.site != configuration_item.site.trim()
    {
        return Err(status_404(&requested_server));
    }
    let environment = configuration_item
        .environment
        .as_deref()
        .filter(|value| !value.trim().is_empty() && *value == value.trim())
        .ok_or_else(|| status_404(&requested_server))?
        .to_string();
    guard_body_scope_dual(&session, &configuration_item.site, &environment)?;

    // The approved catalog row is the stable version authority. Lock it in the
    // same transaction and require its current site policy to cover the target.
    let package: ApprovedPackageRow = sqlx::query_as(&format!(
        "SELECT {PACKAGE_COLUMNS} FROM approved_packages \
         WHERE id = $1 \
           AND (site_scope = 'all' \
                OR (site_scope = 'specific' AND $2 = ANY(site_scope_list))) \
         FOR NO KEY UPDATE"
    ))
    .bind(&body.package_id)
    .bind(&configuration_item.site)
    .fetch_optional(&mut *tx)
    .await
    .map_err(db_error)?
    .ok_or_else(|| status_400("Package is not approved for the authoritative target site"))?;
    if package.id.trim().is_empty()
        || package.id != package.id.trim()
        || package.name.trim().is_empty()
        || package.name != package.name.trim()
        || package.version.trim().is_empty()
        || package.version != package.version.trim()
    {
        return Err(status_400("Approved package authority is not canonical"));
    }

    // Canonical target, scope, maker, package identity, and version replace all
    // corresponding compatibility fields before the pure domain plan builder
    // runs. This avoids a second ungoverned in-memory record on the DB path.
    body.server_name = configuration_item.ci_name.clone();
    body.site = configuration_item.site.clone();
    body.environment = environment;
    body.package_id = package.id.clone();
    body.target_version = package.version.clone();
    body.requester = principal;
    let package_authority = software_deployment::DeploymentPackageAuthority {
        id: package.id.clone(),
        name: package.name.clone(),
        version: package.version.clone(),
        package_type: package.package_type.clone(),
    };
    let record = software_deployment::prepare_authorized_deployment(&body, &package_authority)
        .map_err(|error| status_400(&error))?;
    let plan_json = record
        .plan
        .as_ref()
        .and_then(|plan| serde_json::to_string(plan).ok());
    let scheduled = record
        .scheduled_time
        .parse::<chrono::DateTime<chrono::Utc>>()
        .ok();

    let row: SoftwareDeploymentRow = sqlx::query_as(&format!(
        "INSERT INTO software_deployments \
            (id, configuration_item_id, scope_provenance, server_name, site, \
             environment, package_id, package_name, target_version, \
             scheduled_time, requester, maker_user_id, status, plan_json) \
         VALUES ($1, $2::uuid, 'cmdb-configuration-item', $3, $4, $5, $6, $7, \
                 $8, $9, $10, $11, 'Planned', $12::jsonb) \
         RETURNING {DEPLOYMENT_COLUMNS}"
    ))
    .bind(&record.id)
    .bind(&configuration_item.id)
    .bind(&record.server_name)
    .bind(&record.site)
    .bind(&record.environment)
    .bind(&record.package_id)
    .bind(&record.package_name)
    .bind(&record.target_version)
    .bind(scheduled)
    .bind(&record.requester)
    .bind(&record.maker_user_id)
    .bind(plan_json)
    .fetch_one(&mut *tx)
    .await
    .map_err(db_error)?;
    let deployment_id = row.id.clone();
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "software-plan",
            None,
            "planned",
            json!({
                "deployment_id": deployment_id,
                "configuration_item_id": &configuration_item.id,
                "server_name": &record.server_name,
                "site": &record.site,
                "environment": &record.environment,
                "package_id": &record.package_id,
                "target_version": &record.target_version,
                "maker_user_id": &record.maker_user_id,
                "scope_provenance": "cmdb-configuration-item",
            }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;
    Ok(Json(row.to_json()))
}

async fn software_approve(
    Path(id): Path<String>,
    AuthExtractor(session): AuthExtractor,
) -> ApiResult {
    // The approver is the AUTHENTICATED caller (resolved by the auth middleware
    // and injected into request extensions), never a client-supplied body field.
    // Audit integrity requires attributing the approval to the real principal —
    // a caller must not be able to claim someone else (or "admin") approved.
    let approver = authenticated_principal_id(&session)?.to_string();
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let mut tx = pool.begin().await.map_err(db_error)?;
    let Some(authorization) = lock_software_deployment_authorization(&mut tx, &id, &session)
        .await
        .map_err(db_error)?
    else {
        return Err(status_404(&id));
    };
    if authorization.maker_user_id == approver {
        return Err(status_403());
    }
    if authorization.status != "Planned" {
        return Err(status_409(&format!(
            "Deployment {} is not available for approval",
            id
        )));
    }

    let site_scope = scope_axis_sql_filter(&session.site_scope);
    let environment_scope = scope_axis_sql_filter(&session.environment_scope);
    let row: Option<SoftwareDeploymentRow> = sqlx::query_as(&format!(
        "UPDATE software_deployments \
         SET status = 'Approved', approved_by = $2, updated_at = NOW() \
         WHERE id = $1 AND status = 'Planned' AND maker_user_id <> $2 \
           AND configuration_item_id = $3 AND scope_provenance = $4 \
           AND server_name = $5 AND site = $6 AND environment = $7 \
           AND package_id = $8 AND package_name = $9 AND target_version = $10 \
           AND requester = $11 AND maker_user_id = $12 \
           AND ($13::text[] IS NULL OR site = ANY($13)) \
           AND ($14::text[] IS NULL OR environment = ANY($14)) \
         RETURNING {DEPLOYMENT_COLUMNS}"
    ))
    .bind(&id)
    .bind(&approver)
    .bind(authorization.configuration_item_id)
    .bind(&authorization.scope_provenance)
    .bind(&authorization.server_name)
    .bind(&authorization.site)
    .bind(&authorization.environment)
    .bind(&authorization.package_id)
    .bind(&authorization.package_name)
    .bind(&authorization.target_version)
    .bind(&authorization.requester)
    .bind(&authorization.maker_user_id)
    .bind(site_scope)
    .bind(environment_scope)
    .fetch_optional(&mut *tx)
    .await
    .map_err(db_error)?;
    match row {
        Some(updated) => {
            audit::record_audit_tx(
                &mut tx,
                &session,
                &audit::security_audit(
                    "software-approve",
                    Some("Planned"),
                    "approved",
                    json!({
                        "deployment_id": &id,
                        "configuration_item_id": authorization.configuration_item_id,
                        "server_name": &authorization.server_name,
                        "site": &authorization.site,
                        "environment": &authorization.environment,
                        "package_id": &authorization.package_id,
                        "target_version": &authorization.target_version,
                        "maker_user_id": &authorization.maker_user_id,
                        "approved_by": &approver,
                    }),
                ),
            )
            .await
            .map_err(db_error)?;
            tx.commit().await.map_err(db_error)?;
            Ok(Json(updated.to_json()))
        }
        None => Err(status_409(&format!(
            "Deployment {} could not be approved from its current state",
            id
        ))),
    }
}

async fn software_execute(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> ApiResult {
    operation_capability_guard(&session, OperationCapability::SoftwareDeploymentExecute)?;
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let mut tx = pool.begin().await.map_err(db_error)?;
    let Some(authorization) = lock_software_deployment_authorization(&mut tx, &id, &session)
        .await
        .map_err(db_error)?
    else {
        return Err(status_404(&id));
    };
    if authorization.status != "Approved" {
        return Err(status_409(&format!(
            "Deployment {} is not available for execution",
            id
        )));
    }

    let now = chrono::Utc::now();
    let evidence_json = serde_json::to_string(&serde_json::json!([{
        "step": "execute",
        "result": "success",
        "timestamp": now.to_rfc3339(),
        "source": "database",
    }]))
    .unwrap_or_else(|_| "[]".into());
    let site_scope = scope_axis_sql_filter(&session.site_scope);
    let environment_scope = scope_axis_sql_filter(&session.environment_scope);
    let row: Option<SoftwareDeploymentRow> = sqlx::query_as(&format!(
        "UPDATE software_deployments \
         SET status = 'Executed', executed_at = $2, \
             evidence_json = $3::jsonb, updated_at = NOW() \
         WHERE id = $1 AND status = 'Approved' \
           AND configuration_item_id = $4 AND scope_provenance = $5 \
           AND server_name = $6 AND site = $7 AND environment = $8 \
           AND package_id = $9 AND package_name = $10 AND target_version = $11 \
           AND requester = $12 AND maker_user_id = $13 \
           AND ($14::text[] IS NULL OR site = ANY($14)) \
           AND ($15::text[] IS NULL OR environment = ANY($15)) \
         RETURNING {DEPLOYMENT_COLUMNS}"
    ))
    .bind(&id)
    .bind(now)
    .bind(evidence_json)
    .bind(authorization.configuration_item_id)
    .bind(&authorization.scope_provenance)
    .bind(&authorization.server_name)
    .bind(&authorization.site)
    .bind(&authorization.environment)
    .bind(&authorization.package_id)
    .bind(&authorization.package_name)
    .bind(&authorization.target_version)
    .bind(&authorization.requester)
    .bind(&authorization.maker_user_id)
    .bind(site_scope)
    .bind(environment_scope)
    .fetch_optional(&mut *tx)
    .await
    .map_err(db_error)?;
    match row {
        Some(updated) => {
            audit::record_audit_tx(
                &mut tx,
                &session,
                &audit::security_audit(
                    "software-execute",
                    Some("Approved"),
                    "executed",
                    json!({
                        "deployment_id": &id,
                        "configuration_item_id": authorization.configuration_item_id,
                        "server_name": &authorization.server_name,
                        "site": &authorization.site,
                        "environment": &authorization.environment,
                        "package_id": &authorization.package_id,
                        "target_version": &authorization.target_version,
                    }),
                ),
            )
            .await
            .map_err(db_error)?;
            tx.commit().await.map_err(db_error)?;
            Ok(Json(updated.to_json()))
        }
        None => Err(status_409(&format!(
            "Deployment {} could not be executed from its current state",
            id
        ))),
    }
}

async fn software_verify(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let mut tx = pool.begin().await.map_err(db_error)?;
    let Some(authorization) = lock_software_deployment_authorization(&mut tx, &id, &session)
        .await
        .map_err(db_error)?
    else {
        return Err(status_404(&id));
    };
    if authorization.status == "Verified" {
        tx.commit().await.map_err(db_error)?;
        return Ok(Json(json!({
            "passed": true,
            "status": "Verified",
            "note": "already verified",
            "source": "database",
        })));
    }
    if authorization.status != "Executed" {
        return Err(status_409(&format!(
            "Deployment {} is not available for verification",
            id
        )));
    }

    let now = chrono::Utc::now();
    let site_scope = scope_axis_sql_filter(&session.site_scope);
    let environment_scope = scope_axis_sql_filter(&session.environment_scope);
    let row: Option<SoftwareDeploymentRow> = sqlx::query_as(&format!(
        "UPDATE software_deployments \
         SET status = 'Verified', verified_at = $2, updated_at = NOW() \
         WHERE id = $1 AND status = 'Executed' \
           AND configuration_item_id = $3 AND scope_provenance = $4 \
           AND server_name = $5 AND site = $6 AND environment = $7 \
           AND package_id = $8 AND package_name = $9 AND target_version = $10 \
           AND requester = $11 AND maker_user_id = $12 \
           AND ($13::text[] IS NULL OR site = ANY($13)) \
           AND ($14::text[] IS NULL OR environment = ANY($14)) \
         RETURNING {DEPLOYMENT_COLUMNS}"
    ))
    .bind(&id)
    .bind(now)
    .bind(authorization.configuration_item_id)
    .bind(&authorization.scope_provenance)
    .bind(&authorization.server_name)
    .bind(&authorization.site)
    .bind(&authorization.environment)
    .bind(&authorization.package_id)
    .bind(&authorization.package_name)
    .bind(&authorization.target_version)
    .bind(&authorization.requester)
    .bind(&authorization.maker_user_id)
    .bind(site_scope)
    .bind(environment_scope)
    .fetch_optional(&mut *tx)
    .await
    .map_err(db_error)?;

    match row {
        Some(updated) => {
            audit::record_audit_tx(
                &mut tx,
                &session,
                &audit::security_audit(
                    "software-verify",
                    None,
                    "verified",
                    json!({
                        "deployment_id": &id,
                        "configuration_item_id": authorization.configuration_item_id,
                        "server_name": &authorization.server_name,
                        "site": &authorization.site,
                        "environment": &authorization.environment,
                        "package_id": &authorization.package_id,
                        "target_version": &authorization.target_version,
                    }),
                ),
            )
            .await
            .map_err(db_error)?;
            tx.commit().await.map_err(db_error)?;
            Ok(Json(json!({
                "passed": true,
                "status": "Verified",
                "deployment": updated.to_json(),
                "source": "database",
            })))
        }
        None => Err(status_409(&format!(
            "Deployment {} could not be verified from its current state",
            id
        ))),
    }
}

async fn software_history(
    AuthExtractor(session): AuthExtractor,
    Path(server): Path<String>,
) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let site_scope = scope_axis_sql_filter(&session.site_scope);
    let environment_scope = scope_axis_sql_filter(&session.environment_scope);
    let rows: Vec<SoftwareDeploymentRow> = sqlx::query_as(&format!(
        "SELECT {AUTHORIZED_DEPLOYMENT_COLUMNS} \
         FROM software_deployments AS d \
         INNER JOIN configuration_items AS ci \
                 ON ci.id = d.configuration_item_id \
                AND ci.ci_name = d.server_name \
                AND ci.site = d.site \
                AND ci.environment = d.environment \
                AND ci.ci_type = 'Server' \
         INNER JOIN site_registry AS sr \
                 ON sr.unlocode = d.site AND sr.active = true \
         WHERE d.server_name = $1 \
           AND d.scope_provenance = 'cmdb-configuration-item' \
           AND d.configuration_item_id IS NOT NULL \
           AND d.site = BTRIM(d.site) \
           AND NULLIF(BTRIM(d.site), '') IS NOT NULL \
           AND d.environment = BTRIM(d.environment) \
           AND NULLIF(BTRIM(d.environment), '') IS NOT NULL \
           AND d.server_name = BTRIM(d.server_name) \
           AND NULLIF(BTRIM(d.server_name), '') IS NOT NULL \
           AND d.package_id = BTRIM(d.package_id) \
           AND NULLIF(BTRIM(d.package_id), '') IS NOT NULL \
           AND d.package_name = BTRIM(d.package_name) \
           AND NULLIF(BTRIM(d.package_name), '') IS NOT NULL \
           AND d.target_version = BTRIM(d.target_version) \
           AND NULLIF(BTRIM(d.target_version), '') IS NOT NULL \
           AND d.maker_user_id = BTRIM(d.maker_user_id) \
           AND NULLIF(BTRIM(d.maker_user_id), '') IS NOT NULL \
           AND d.requester = d.maker_user_id \
           AND ($2::text[] IS NULL OR d.site = ANY($2)) \
           AND ($3::text[] IS NULL OR d.environment = ANY($3)) \
         ORDER BY d.created_at, d.id"
    ))
    .bind(&server)
    .bind(site_scope)
    .bind(environment_scope)
    .fetch_all(pool)
    .await
    .map_err(db_error)?;
    let records: Vec<Value> = rows.iter().map(SoftwareDeploymentRow::to_json).collect();
    Ok(Json(json!(records)))
}

async fn software_compliance(
    AuthExtractor(session): AuthExtractor,
    Query(mut query): Query<SoftwareComplianceQuery>,
) -> ApiResult {
    // #2: site-only compliance report — a scoped principal may only read its own
    // site (site is a required, caller-supplied param, so 403 is not an oracle);
    // an environment-scoped principal is denied (no environment axis here). Guards
    // both the DB and the no-DB engine fallback below.
    query.site = site_registry::normalize_site_code_for_lookup(&query.site)
        .map_err(|error| status_400(&error))?;
    guard_body_site_scope(&session, &query.site)?;
    if !site_registry::is_valid_site(&query.site) {
        return Err(status_400(&format!("Unknown site: {}", query.site)));
    }

    // DB path: query software_deployments for completed deployments at this site.
    // DEPLOYMENT_STORE / PACKAGE_STORE are not populated from DB rows after restart,
    // so calling get_package_compliance() here would miss persisted data.
    if let Some(pool) = get_db() {
        // Approximate the same fixed server list the engine uses.
        let site_lc = query.site.to_lowercase();
        let servers = vec![
            format!("w-{}-srv-01", site_lc),
            format!("w-{}-srv-02", site_lc),
            format!("l-{}-srv-01", site_lc),
        ];

        // Fetch all approved packages that cover this site.
        let pkgs: Vec<ApprovedPackageRow> = sqlx::query_as(&format!(
            "SELECT {PACKAGE_COLUMNS} FROM approved_packages \
             WHERE site_scope = 'all' \
                OR (site_scope = 'specific' AND $1 = ANY(site_scope_list))"
        ))
        .bind(&query.site)
        .fetch_all(pool)
        .await
        .map_err(db_error)?;

        // For each package, determine which servers have a Completed deployment.
        let mut package_status: Vec<Value> = Vec::new();
        for pkg in &pkgs {
            let mut compliant: Vec<String> = Vec::new();
            let mut outdated: Vec<String> = Vec::new();
            for server in &servers {
                let done: bool = sqlx::query_scalar::<_, bool>(
                    "SELECT EXISTS( \
                         SELECT 1 FROM software_deployments \
                         WHERE server_name = $1 AND package_id = $2 AND status = 'Completed' \
                     )",
                )
                .bind(server)
                .bind(&pkg.id)
                .fetch_one(pool)
                .await
                .map_err(db_error)?;
                if done {
                    compliant.push(server.clone());
                } else {
                    outdated.push(server.clone());
                }
            }
            let pct = if servers.is_empty() {
                100.0_f64
            } else {
                (compliant.len() as f64 / servers.len() as f64) * 100.0
            };
            package_status.push(json!({
                "package_id": pkg.id,
                "package_name": pkg.name,
                "required_version": pkg.version,
                "compliant_servers": compliant,
                "outdated_servers": outdated,
                "compliance_percentage": pct,
            }));
        }

        return Ok(Json(json!({
            "source": "database",
            "generated_at": chrono::Utc::now().to_rfc3339(),
            "site": query.site,
            "servers": servers,
            "packages": package_status,
            "dry_run": true,
        })));
    }
    // No-DB fallback: engine uses PACKAGE_STORE + DEPLOYMENT_STORE (current-process only).
    match software_deployment::get_package_compliance(&query.site) {
        Ok(compliance) => Ok(Json(compliance)),
        Err(e) => Err(status_400(&e)),
    }
}

async fn software_contract() -> Json<Value> {
    Json(software_deployment::get_software_contract())
}

// ─── OS baseline compliance handlers ───

#[derive(Debug, Deserialize)]
struct BaselineQuery {
    site: Option<String>,
}

/// Defense-in-depth role gate for OS-baseline handlers. Central middleware is
/// still the first admission layer; this guard prevents direct handler calls or
/// future route reclassification from bypassing the operation's coarse tier.
fn baseline_permission_guard(
    session: &AuthSession,
    permission: &str,
) -> Result<(), (StatusCode, Json<Value>)> {
    if check_permission(session, permission) {
        Ok(())
    } else {
        Err((
            StatusCode::FORBIDDEN,
            Json(json!({"error": format!("Missing required permission: {permission}")})),
        ))
    }
}

/// Resolve an optional baseline `?site` to one canonical, active site under the
/// verified session's scope before any repository call. Unscoped callers keep
/// the legacy DEFRA default; a single-site caller who omits the query narrows to
/// that site; ambiguous/mismatched scopes fail closed through
/// [`enforce_site_scope`].
fn resolve_baseline_query_site(
    session: &AuthSession,
    requested: Option<&str>,
) -> Result<String, (StatusCode, Json<Value>)> {
    let requested = requested
        .map(site_registry::normalize_site_code_for_lookup)
        .transpose()
        .map_err(|error| status_400(&error))?;
    let effective = enforce_site_scope(session, requested.as_deref(), "DEFRA")?;
    let canonical = site_registry::normalize_site_code_for_lookup(&effective)
        .map_err(|error| status_400(&error))?;
    if !site_registry::is_valid_site(&canonical) {
        return Err(status_400(&format!("Unknown site: {canonical}")));
    }
    Ok(canonical)
}

/// Validate a persisted baseline row's site as canonical and active. Invalid,
/// inactive, or non-canonical ownership is indistinguishable from a missing
/// target; a request value is never used to repair or override persisted scope.
fn canonical_baseline_row_site_or_404(
    persisted_site: &str,
    target: &str,
) -> Result<String, (StatusCode, Json<Value>)> {
    let canonical = site_registry::normalize_site_code_for_lookup(persisted_site)
        .map_err(|_| status_404(target))?;
    if canonical != persisted_site || !site_registry::is_valid_site(&canonical) {
        return Err(status_404(target));
    }
    Ok(canonical)
}

async fn baseline_check(
    AuthExtractor(session): AuthExtractor,
    Path(server): Path<String>,
) -> ApiResult {
    baseline_permission_guard(&session, "execute")?;
    if session
        .environment_scope
        .iter()
        .any(|scope| !scope.trim().is_empty())
    {
        // A by-server result has no environment relation. Deny with the same
        // non-enumerating 404 used for a missing/foreign server, even in no-DB
        // mode where there is no row to inspect.
        return Err(status_404(&server));
    }
    let Some(pool) = get_db() else {
        // Preserve the dry-run/no-DB contract: no persisted target means no
        // sensitive data is available to disclose.
        return Ok(Json(json!([])));
    };

    // Load only the server's canonical persisted site first. Missing and
    // mixed-site servers both become the same 404 as a foreign server, before
    // any compliance detail is materialised.
    let persisted_site = crate::repos::os_baseline::canonical_site_for_server(pool, &server)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&server))?;
    let site = canonical_baseline_row_site_or_404(&persisted_site, &server)?;
    site_scope_guard_or_404(&session, &site, &server)?;

    // Repeat the authorized site in SQL so a concurrent/inconsistent foreign
    // row can never enter the decoded result set.
    let results = crate::repos::os_baseline::list_results_for_server(pool, &server, &site)
        .await
        .map_err(db_error)?;
    if results.is_empty() {
        // The canonical pre-read proved at least one row existed. An empty
        // scoped detail query therefore means deletion/site reassignment or a
        // newly detected mixed-site mapping; collapse every race to the same
        // non-enumerating 404 instead of returning a partial result.
        return Err(status_404(&server));
    }
    Ok(Json(serde_json::to_value(results).unwrap_or_default()))
}

async fn baseline_compliance(
    AuthExtractor(session): AuthExtractor,
    Query(query): Query<BaselineQuery>,
) -> ApiResult {
    baseline_permission_guard(&session, "audit")?;
    let site = resolve_baseline_query_site(&session, query.site.as_deref())?;
    let results = match get_db() {
        Some(pool) => crate::repos::os_baseline::list_results_for_site(pool, &site)
            .await
            .map_err(db_error)?,
        None => Vec::new(),
    };
    match os_baseline::check_site_compliance(&results, &site) {
        Ok(summary) => Ok(Json(serde_json::to_value(summary).unwrap_or_default())),
        Err(e) => Err(status_400(&e)),
    }
}

async fn baseline_noncompliant(
    AuthExtractor(session): AuthExtractor,
    Query(query): Query<BaselineQuery>,
) -> ApiResult {
    baseline_permission_guard(&session, "audit")?;
    let site = resolve_baseline_query_site(&session, query.site.as_deref())?;
    let (checks, results) = match get_db() {
        Some(pool) => {
            let checks = crate::repos::os_baseline::list_checks(pool)
                .await
                .map_err(db_error)?;
            let results = crate::repos::os_baseline::list_results_for_site(pool, &site)
                .await
                .map_err(db_error)?;
            (checks, results)
        }
        None => (Vec::new(), Vec::new()),
    };
    match os_baseline::get_noncompliant(&checks, &results, &site) {
        Ok(servers) => Ok(Json(serde_json::to_value(servers).unwrap_or_default())),
        Err(e) => Err(status_400(&e)),
    }
}

async fn baseline_trend(
    AuthExtractor(session): AuthExtractor,
    Query(query): Query<BaselineQuery>,
) -> ApiResult {
    baseline_permission_guard(&session, "audit")?;
    let site = resolve_baseline_query_site(&session, query.site.as_deref())?;
    let trend_points = match get_db() {
        Some(pool) => crate::repos::os_baseline::compliance_trend_for_site(pool, &site)
            .await
            .map_err(db_error)?,
        None => Vec::new(),
    };
    match os_baseline::get_compliance_trend(&trend_points, &site) {
        Ok(trend) => Ok(Json(serde_json::to_value(trend).unwrap_or_default())),
        Err(e) => Err(status_400(&e)),
    }
}

async fn baseline_coverage(AuthExtractor(session): AuthExtractor) -> ApiResult {
    baseline_permission_guard(&session, "audit")?;
    if session
        .environment_scope
        .iter()
        .any(|scope| !scope.trim().is_empty())
    {
        // baseline_results has no authoritative environment relation, so this
        // site-only read cannot honor an environment-restricted principal.
        return Err(status_403_out_of_scope("environment"));
    }
    let sites: Option<Vec<String>> = match list_site_scope(&session) {
        ListSiteScope::Empty => Some(Vec::new()),
        ListSiteScope::All => None,
        ListSiteScope::Sites(sites) => Some(sites),
    };
    let (checks, results) = match get_db() {
        Some(pool) => {
            let checks = crate::repos::os_baseline::list_checks(pool)
                .await
                .map_err(db_error)?;
            let results = crate::repos::os_baseline::list_results_for_sites(pool, sites.as_deref())
                .await
                .map_err(db_error)?;
            (checks, results)
        }
        None => (Vec::new(), Vec::new()),
    };
    let coverage = os_baseline::get_check_coverage(&checks, &results);
    Ok(Json(serde_json::to_value(coverage).unwrap_or_default()))
}

async fn baseline_remediate(
    AuthExtractor(session): AuthExtractor,
    Path((server, check_id)): Path<(String, String)>,
) -> ApiResult {
    baseline_permission_guard(&session, "execute")?;
    let target_id = format!("{server}/{check_id}");
    if session
        .environment_scope
        .iter()
        .any(|scope| !scope.trim().is_empty())
    {
        return Err(status_404(&target_id));
    }
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let mut tx = pool.begin().await.map_err(db_error)?;

    // Lock and load the selected row's persisted site + check expected value in
    // this caller-owned transaction. A foreign target is authorized against the
    // locked row, not a caller-supplied or server-name-derived site.
    let target = crate::repos::os_baseline::lock_remediation_target(&mut tx, &server, &check_id)
        .await
        .map_err(db_error)?;
    let Some(target) = target else {
        tx.rollback().await.map_err(db_error)?;
        return Err(status_404(&target_id));
    };

    let authorized_site =
        canonical_baseline_row_site_or_404(target.site(), &target_id).and_then(|site| {
            site_scope_guard_or_404(&session, &site, &target_id)?;
            Ok(site)
        });
    let site = match authorized_site {
        Ok(site) => site,
        Err(response) => {
            tx.rollback().await.map_err(db_error)?;
            return Err(response);
        }
    };

    let from_status = if target.was_compliant() {
        "compliant"
    } else {
        "noncompliant"
    };
    let result = match crate::repos::os_baseline::apply_locked_remediation(&mut tx, &target).await {
        Ok(Some(result)) => result,
        Ok(None) => {
            tx.rollback().await.map_err(db_error)?;
            return Err(status_404(&target_id));
        }
        Err(error) => {
            let response = db_error(&error);
            if let Err(rollback_error) = tx.rollback().await {
                tracing::error!(
                    error = %rollback_error,
                    "baseline remediation rollback failed"
                );
            }
            return Err(response);
        }
    };

    // C267: update and actor-attributed audit append share one commit. Any audit
    // error drops/rolls back the still-open transaction, so no remediated row can
    // land without its evidence.
    if let Err(error) = audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "baseline-remediate",
            Some(from_status),
            "compliant",
            json!({
                "server_name": &server,
                "check_id": &check_id,
                "site": &site,
            }),
        ),
    )
    .await
    {
        let response = db_error(&error);
        if let Err(rollback_error) = tx.rollback().await {
            tracing::error!(error = %rollback_error, "baseline audit rollback failed");
        }
        return Err(response);
    }
    tx.commit().await.map_err(db_error)?;

    Ok(Json(serde_json::to_value(result).unwrap_or_default()))
}

async fn baseline_contract() -> Json<Value> {
    Json(json!({
        "source": "static-seed",
        "providerCallsEnabled": false,
        "liveRemediationAllowed": false,
        "dryRunRequired": true,
        "supportedWorkflows": [
            "baseline-check",
            "baseline-compliance",
            "baseline-noncompliant",
            "baseline-trend",
            "baseline-coverage",
            "baseline-remediate"
        ],
        "baselineChecks": [
            {"id": "bc-001", "check_name": "CrowdStrike Falcon Agent", "category": "Security", "severity": "Critical"},
            {"id": "bc-002", "check_name": "VMware Tools", "category": "Tools", "severity": "High"},
            {"id": "bc-003", "check_name": "Zabbix Agent", "category": "Monitoring", "severity": "High"},
            {"id": "bc-004", "check_name": "Windows Firewall", "category": "Configuration", "severity": "Critical"}
        ],
        "validSites": site_registry::get_active_site_codes().unwrap_or_default(),
        "requiredGuards": [
            "site-known",
            "server-name-known",
            "check-id-known",
            "dry-run-only",
            "evidence-redacted"
        ],
        "blockedReasons": [
            "provider-calls-disabled",
            "live-remediation-disabled",
            "unknown-site",
            "unknown-server",
            "unknown-check",
            "evidence-not-redacted"
        ]
    }))
}

#[cfg(test)]
mod os_baseline_scope_unit_tests {
    use super::*;
    use ryuki_engine::auth::{
        APP_ROLE_AUDITOR, APP_ROLE_REQUESTER, APP_ROLE_WINTEL_LINUX_OPERATOR,
    };

    fn session(role: &str, sites: &[&str], environments: &[&str]) -> AuthSession {
        let principal_id =
            PrincipalId::from_uuid(Uuid::new_v4()).expect("test UUID is a non-nil principal");
        AuthSession {
            display_user_id: format!("baseline-test-{role}"),
            principal_id: Some(principal_id),
            display_name: "Baseline Scope Test".into(),
            roles: vec![role.to_string()],
            token_valid: true,
            provider_mode: "test-verified".into(),
            actor_class: ryuki_engine::auth::ActorClass::VerifiedHuman,
            site_scope: sites.iter().map(|site| (*site).to_string()).collect(),
            environment_scope: environments
                .iter()
                .map(|environment| (*environment).to_string())
                .collect(),
        }
    }

    #[test]
    fn baseline_permission_guard_repeats_read_and_execute_tiers() {
        let auditor = session(APP_ROLE_AUDITOR, &[], &[]);
        assert!(baseline_permission_guard(&auditor, "audit").is_ok());
        assert!(baseline_permission_guard(&auditor, "execute").is_err());

        let operator = session(APP_ROLE_WINTEL_LINUX_OPERATOR, &[], &[]);
        assert!(baseline_permission_guard(&operator, "audit").is_ok());
        assert!(baseline_permission_guard(&operator, "execute").is_ok());

        let requester = session(APP_ROLE_REQUESTER, &[], &[]);
        let Err((status, _)) = baseline_permission_guard(&requester, "audit") else {
            panic!("request-only principal must fail the handler-local read gate");
        };
        assert_eq!(status, StatusCode::FORBIDDEN);
    }

    #[test]
    fn baseline_query_site_resolution_preserves_only_authorized_cases() {
        let gblon = session(APP_ROLE_AUDITOR, &["GBLON"], &[]);
        assert_eq!(
            resolve_baseline_query_site(&gblon, None).expect("single scope must narrow"),
            "GBLON"
        );
        assert_eq!(
            resolve_baseline_query_site(&gblon, Some(" gblon "))
                .expect("matching canonical query must pass"),
            "GBLON"
        );
        let Err((status, _)) = resolve_baseline_query_site(&gblon, Some("DEFRA")) else {
            panic!("foreign site must be denied");
        };
        assert_eq!(status, StatusCode::FORBIDDEN);

        let multi = session(APP_ROLE_AUDITOR, &["GBLON", "FRPAR"], &[]);
        assert!(resolve_baseline_query_site(&multi, None).is_err());
        assert_eq!(
            resolve_baseline_query_site(&multi, Some("FRPAR"))
                .expect("an explicitly selected held site must pass"),
            "FRPAR"
        );

        let environment_only = session(APP_ROLE_AUDITOR, &[], &["production"]);
        let Err((status, _)) = resolve_baseline_query_site(&environment_only, Some("DEFRA")) else {
            panic!("site-only baseline data cannot honor environment-only scope");
        };
        assert_eq!(status, StatusCode::FORBIDDEN);

        let unrestricted = session(APP_ROLE_AUDITOR, &[], &[]);
        assert_eq!(
            resolve_baseline_query_site(&unrestricted, None)
                .expect("unrestricted omission keeps the legacy default"),
            "DEFRA"
        );
        assert_eq!(
            resolve_baseline_query_site(&unrestricted, Some("FRPAR"))
                .expect("unrestricted explicit selection must pass"),
            "FRPAR"
        );
    }

    #[test]
    fn persisted_baseline_site_must_be_canonical_and_active() {
        assert_eq!(
            canonical_baseline_row_site_or_404("GBLON", "server")
                .expect("canonical active site must pass"),
            "GBLON"
        );
        for invalid in ["gblon", "UNKNOWN", "ZZZZZ", " GBLON "] {
            let Err((status, _)) = canonical_baseline_row_site_or_404(invalid, "server") else {
                panic!("invalid persisted site {invalid:?} must fail closed");
            };
            assert_eq!(status, StatusCode::NOT_FOUND);
        }
    }

    #[tokio::test]
    async fn baseline_no_db_reads_remain_empty_after_authorization() {
        if get_db().is_some() {
            eprintln!("SKIP: no-DB contract test requires an unset test pool");
            return;
        }
        let operator = session(APP_ROLE_WINTEL_LINUX_OPERATOR, &["GBLON"], &[]);
        let Json(server) = baseline_check(
            AuthExtractor(operator.clone()),
            Path("srv-gblon-db01".into()),
        )
        .await
        .expect("no-DB server read stays empty");
        assert_eq!(server, json!([]));

        let Json(summary) = baseline_compliance(
            AuthExtractor(operator.clone()),
            Query(BaselineQuery { site: None }),
        )
        .await
        .expect("no-DB scoped summary stays empty");
        assert_eq!(summary["site"], "GBLON");
        assert_eq!(summary["total_checks"], 0);

        let Json(noncompliant) = baseline_noncompliant(
            AuthExtractor(operator.clone()),
            Query(BaselineQuery { site: None }),
        )
        .await
        .expect("no-DB noncompliant read stays empty");
        assert_eq!(noncompliant, json!([]));
        let Json(trend) = baseline_trend(
            AuthExtractor(operator.clone()),
            Query(BaselineQuery { site: None }),
        )
        .await
        .expect("no-DB trend stays empty");
        assert_eq!(trend, json!([]));
        let Json(coverage) = baseline_coverage(AuthExtractor(operator))
            .await
            .expect("no-DB coverage stays empty");
        assert_eq!(coverage, json!([]));
    }
}

/// DB-backed boundary proofs for C092-C097 and the naturally adjacent
/// C267 atomic audit requirement. They skip when RYUKI_DATABASE_URL is unset.
#[cfg(test)]
mod os_baseline_handler_db_tests {
    use super::*;
    use crate::database::DB_TEST_SERIAL;
    use ryuki_engine::auth::{APP_ROLE_REQUESTER, APP_ROLE_WINTEL_LINUX_OPERATOR};
    use sqlx::PgPool;

    async fn global_pool() -> Option<&'static PgPool> {
        let url = std::env::var("RYUKI_DATABASE_URL").ok()?;
        crate::database::try_connect_with_url(&url, 5, 1, 300, 30, 1800).await;
        let pool = crate::database::get_db()?;
        crate::database::run_migrations(pool).await.ok()?;
        Some(pool)
    }

    fn operator(display_user_id: &str, site: Option<&str>) -> AuthSession {
        let principal_id =
            PrincipalId::from_uuid(Uuid::new_v4()).expect("test UUID is a non-nil principal");
        AuthSession {
            display_user_id: display_user_id.into(),
            principal_id: Some(principal_id),
            display_name: format!("Baseline Operator {display_user_id}"),
            roles: vec![APP_ROLE_WINTEL_LINUX_OPERATOR.to_string()],
            token_valid: true,
            actor_class: ryuki_engine::auth::ActorClass::VerifiedHuman,
            provider_mode: "test-verified".into(),
            site_scope: site.into_iter().map(str::to_string).collect(),
            environment_scope: vec![],
        }
    }

    fn requester(display_user_id: &str) -> AuthSession {
        let mut session = operator(display_user_id, None);
        session.roles = vec![APP_ROLE_REQUESTER.to_string()];
        session
    }

    async fn insert_result(pool: &PgPool, server: &str, site: &str) {
        sqlx::query(
            "INSERT INTO baseline_results \
             (server_name, check_id, compliant, actual_value, site) \
             VALUES ($1, 'bc-004', false, 'disabled', $2)",
        )
        .bind(server)
        .bind(site)
        .execute(pool)
        .await
        .expect("insert baseline handler fixture");
    }

    #[tokio::test]
    async fn baseline_reads_enforce_scope_before_projection() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set");
            return;
        };
        let gblon = operator("baseline-read-gblon", Some("GBLON"));

        assert!(matches!(
            baseline_coverage(AuthExtractor(requester("baseline-requester"))).await,
            Err((StatusCode::FORBIDDEN, _))
        ));
        assert!(matches!(
            baseline_check(
                AuthExtractor(requester("baseline-requester")),
                Path("srv-gblon-db01".into())
            )
            .await,
            Err((StatusCode::FORBIDDEN, _))
        ));

        let Json(summary) = baseline_compliance(
            AuthExtractor(gblon.clone()),
            Query(BaselineQuery { site: None }),
        )
        .await
        .expect("single-site omission must narrow to GBLON");
        assert_eq!(summary["site"], "GBLON");
        let rows = summary["servers"].as_array().expect("summary server rows");
        assert!(!rows.is_empty());
        assert!(rows.iter().all(|row| row["site"] == "GBLON"));

        let mut multi = gblon.clone();
        multi.site_scope = vec!["GBLON".into(), "FRPAR".into()];
        assert!(matches!(
            baseline_compliance(
                AuthExtractor(multi.clone()),
                Query(BaselineQuery { site: None })
            )
            .await,
            Err((StatusCode::FORBIDDEN, _))
        ));
        let Json(frpar) = baseline_compliance(
            AuthExtractor(multi.clone()),
            Query(BaselineQuery {
                site: Some("FRPAR".into()),
            }),
        )
        .await
        .expect("multi-site reader may explicitly select a held site");
        assert_eq!(frpar["site"], "FRPAR");
        let Json(multi_coverage) = baseline_coverage(AuthExtractor(multi))
            .await
            .expect("multi-site coverage uses the full authorized set");
        assert!(multi_coverage
            .as_array()
            .expect("multi-site coverage array")
            .iter()
            .flat_map(|check| {
                check["applied_to"]
                    .as_array()
                    .expect("multi-site coverage targets")
            })
            .all(|server| {
                server
                    .as_str()
                    .is_some_and(|name| name.contains("gblon") || name.contains("frpar"))
            }));

        let mut malformed_scope = gblon.clone();
        malformed_scope.site_scope = vec![" ".into()];
        let Json(malformed_coverage) = baseline_coverage(AuthExtractor(malformed_scope))
            .await
            .expect("malformed scope fails closed to an empty projection");
        assert!(malformed_coverage
            .as_array()
            .expect("malformed coverage array")
            .iter()
            .all(|check| check["applied_to"]
                .as_array()
                .expect("malformed coverage targets")
                .is_empty()));

        let unscoped = operator("baseline-read-unscoped", None);
        let Json(defaulted) = baseline_compliance(
            AuthExtractor(unscoped.clone()),
            Query(BaselineQuery { site: None }),
        )
        .await
        .expect("unscoped omission keeps DEFRA default");
        assert_eq!(defaulted["site"], "DEFRA");
        let Json(fleet_coverage) = baseline_coverage(AuthExtractor(unscoped.clone()))
            .await
            .expect("unscoped reader retains fleet coverage");
        let fleet_names: Vec<&str> = fleet_coverage
            .as_array()
            .expect("fleet coverage array")
            .iter()
            .flat_map(|check| {
                check["applied_to"]
                    .as_array()
                    .expect("fleet coverage targets")
            })
            .filter_map(Value::as_str)
            .collect();
        assert!(fleet_names.iter().any(|name| name.contains("defra")));
        assert!(fleet_names.iter().any(|name| name.contains("gblon")));
        let _ = baseline_check(AuthExtractor(unscoped), Path("srv-gblon-db01".into()))
            .await
            .expect("unscoped operator retains by-server access");

        for result in [
            baseline_compliance(
                AuthExtractor(gblon.clone()),
                Query(BaselineQuery {
                    site: Some("DEFRA".into()),
                }),
            )
            .await,
            baseline_noncompliant(
                AuthExtractor(gblon.clone()),
                Query(BaselineQuery {
                    site: Some("DEFRA".into()),
                }),
            )
            .await,
            baseline_trend(
                AuthExtractor(gblon.clone()),
                Query(BaselineQuery {
                    site: Some("DEFRA".into()),
                }),
            )
            .await,
        ] {
            assert!(matches!(result, Err((StatusCode::FORBIDDEN, _))));
        }

        let Json(noncompliant) = baseline_noncompliant(
            AuthExtractor(gblon.clone()),
            Query(BaselineQuery { site: None }),
        )
        .await
        .expect("own-site noncompliant list");
        assert!(noncompliant
            .as_array()
            .expect("noncompliant array")
            .iter()
            .all(|server| server["site"] == "GBLON"));

        let _ = baseline_trend(
            AuthExtractor(gblon.clone()),
            Query(BaselineQuery { site: None }),
        )
        .await
        .expect("own-site trend");

        let Json(checks) =
            baseline_check(AuthExtractor(gblon.clone()), Path("srv-gblon-db01".into()))
                .await
                .expect("own-site server detail");
        assert!(checks
            .as_array()
            .expect("server checks array")
            .iter()
            .all(|row| row["site"] == "GBLON"));

        let opaque_server = format!("baseline-read-opaque-{}", Uuid::new_v4().simple());
        insert_result(pool, &opaque_server, "GBLON").await;
        let Err((foreign_status, Json(foreign_body))) = baseline_check(
            AuthExtractor(operator("baseline-read-defra", Some("DEFRA"))),
            Path(opaque_server.clone()),
        )
        .await
        else {
            panic!("foreign server must be hidden");
        };
        sqlx::query("DELETE FROM baseline_results WHERE server_name = $1")
            .bind(&opaque_server)
            .execute(pool)
            .await
            .expect("remove opaque server before missing control");
        let Err((missing_status, Json(missing_body))) = baseline_check(
            AuthExtractor(operator("baseline-read-defra", Some("DEFRA"))),
            Path(opaque_server),
        )
        .await
        else {
            panic!("missing server must be hidden");
        };
        assert_eq!(foreign_status, StatusCode::NOT_FOUND);
        assert_eq!(missing_status, StatusCode::NOT_FOUND);
        assert_eq!(foreign_body, missing_body);

        let Json(coverage) = baseline_coverage(AuthExtractor(gblon.clone()))
            .await
            .expect("scoped coverage");
        let coverage = coverage.as_array().expect("coverage array");
        assert!(coverage.iter().all(|check| {
            check["applied_to"]
                .as_array()
                .expect("coverage targets")
                .iter()
                .all(|server| server.as_str().is_some_and(|name| name.contains("gblon")))
        }));

        let mut environment_only = gblon;
        environment_only.site_scope.clear();
        environment_only.environment_scope = vec!["production".into()];
        assert!(matches!(
            baseline_compliance(
                AuthExtractor(environment_only.clone()),
                Query(BaselineQuery {
                    site: Some("GBLON".into())
                })
            )
            .await,
            Err((StatusCode::FORBIDDEN, _))
        ));
        assert!(matches!(
            baseline_check(
                AuthExtractor(environment_only.clone()),
                Path("srv-gblon-db01".into())
            )
            .await,
            Err((StatusCode::NOT_FOUND, _))
        ));
        assert!(matches!(
            baseline_coverage(AuthExtractor(environment_only)).await,
            Err((StatusCode::FORBIDDEN, _))
        ));

        let mut mixed_axis = operator("baseline-read-mixed-axis", Some("GBLON"));
        mixed_axis.environment_scope = vec!["production".into()];
        assert!(matches!(
            baseline_compliance(
                AuthExtractor(mixed_axis.clone()),
                Query(BaselineQuery {
                    site: Some("GBLON".into()),
                }),
            )
            .await,
            Err((StatusCode::FORBIDDEN, _))
        ));
        assert!(matches!(
            baseline_check(
                AuthExtractor(mixed_axis.clone()),
                Path("srv-gblon-db01".into()),
            )
            .await,
            Err((StatusCode::NOT_FOUND, _))
        ));
        assert!(matches!(
            baseline_coverage(AuthExtractor(mixed_axis)).await,
            Err((StatusCode::FORBIDDEN, _))
        ));
    }

    #[tokio::test]
    async fn baseline_remediation_is_scoped_and_atomically_audited() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set");
            return;
        };
        let server = format!("baseline-audit-{}", Uuid::new_v4().simple());
        insert_result(pool, &server, "GBLON").await;

        assert!(matches!(
            baseline_remediate(
                AuthExtractor(requester("baseline-remediate-requester")),
                Path((server.clone(), "bc-004".into()))
            )
            .await,
            Err((StatusCode::FORBIDDEN, _))
        ));
        let mut environment_only = operator("baseline-remediate-env", None);
        environment_only.environment_scope = vec!["production".into()];
        assert!(matches!(
            baseline_remediate(
                AuthExtractor(environment_only),
                Path((server.clone(), "bc-004".into()))
            )
            .await,
            Err((StatusCode::NOT_FOUND, _))
        ));

        let foreign = baseline_remediate(
            AuthExtractor(operator("baseline-remediate-foreign", Some("DEFRA"))),
            Path((server.clone(), "bc-004".into())),
        )
        .await;
        let Err((foreign_status, Json(foreign_body))) = foreign else {
            panic!("foreign remediation must be hidden");
        };
        assert_eq!(foreign_status, StatusCode::NOT_FOUND);
        let unchanged: (bool, String) = sqlx::query_as(
            "SELECT compliant, actual_value FROM baseline_results \
             WHERE server_name = $1 AND check_id = 'bc-004'",
        )
        .bind(&server)
        .fetch_one(pool)
        .await
        .expect("read denied target");
        assert_eq!(unchanged, (false, "disabled".into()));
        let denied_audits: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM audit_log \
             WHERE action = 'baseline-remediate' AND detail->>'server_name' = $1",
        )
        .bind(&server)
        .fetch_one(pool)
        .await
        .expect("count denied audits");
        assert_eq!(denied_audits, 0);

        sqlx::query("DELETE FROM baseline_results WHERE server_name = $1")
            .bind(&server)
            .execute(pool)
            .await
            .expect("temporarily remove target");
        let Err((missing_status, Json(missing_body))) = baseline_remediate(
            AuthExtractor(operator("baseline-remediate-foreign", Some("DEFRA"))),
            Path((server.clone(), "bc-004".into())),
        )
        .await
        else {
            panic!("missing remediation target must be hidden");
        };
        assert_eq!(missing_status, StatusCode::NOT_FOUND);
        assert_eq!(foreign_body, missing_body);

        insert_result(pool, &server, "GBLON").await;
        let actor = format!("baseline-remediate-actor-{}", Uuid::new_v4().simple());
        let session = operator(&actor, Some("GBLON"));
        let Json(result) = baseline_remediate(
            AuthExtractor(session.clone()),
            Path((server.clone(), "bc-004".into())),
        )
        .await
        .expect("own-site remediation must succeed");
        assert_eq!(result["site"], "GBLON");
        assert_eq!(result["compliant"], true);
        assert_eq!(result["actual_value"], "enabled, domain profile");
        let persisted: Vec<(bool, String)> = sqlx::query_as(
            "SELECT compliant, actual_value FROM baseline_results \
             WHERE server_name = $1 AND check_id = 'bc-004'",
        )
        .bind(&server)
        .fetch_all(pool)
        .await
        .expect("read committed baseline state");
        assert_eq!(
            persisted,
            vec![(true, "enabled, domain profile".into())],
            "one persisted target must transition with the audit"
        );

        type BaselineRemediationAuditRow = (
            String,
            Option<String>,
            Vec<String>,
            String,
            Option<String>,
            String,
            String,
        );
        let audits: Vec<BaselineRemediationAuditRow> = sqlx::query_as(
            "SELECT actor_principal, actor_display, actor_roles, provider_mode, \
                    from_status, to_status, detail::text \
             FROM audit_log WHERE action = 'baseline-remediate' \
               AND detail->>'server_name' = $1 ORDER BY id",
        )
        .bind(&server)
        .fetch_all(pool)
        .await
        .expect("read baseline audit");
        assert_eq!(audits.len(), 1, "one commit must append exactly one audit");
        let audit = &audits[0];
        assert_eq!(
            audit.0,
            session
                .principal_id
                .expect("verified test operator has an opaque principal")
                .to_string()
        );
        assert_eq!(audit.1.as_deref(), Some(session.display_name.as_str()));
        assert_eq!(audit.2, session.roles);
        assert_eq!(audit.3, session.provider_mode);
        assert_eq!(audit.4.as_deref(), Some("noncompliant"));
        assert_eq!(audit.5, "compliant");
        assert!(audit.6.contains(&server));
        assert!(audit.6.contains("bc-004"));
        assert!(audit.6.contains("GBLON"));
        assert!(!audit.6.contains("disabled"));
        assert!(!audit.6.contains("enabled, domain profile"));

        let unscoped_server = format!("baseline-unscoped-{}", Uuid::new_v4().simple());
        insert_result(pool, &unscoped_server, "FRPAR").await;
        let _ = baseline_remediate(
            AuthExtractor(operator("baseline-remediate-unscoped", None)),
            Path((unscoped_server.clone(), "bc-004".into())),
        )
        .await
        .expect("explicitly unscoped operator retains remediation access");
        let unscoped_audits: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM audit_log WHERE action = 'baseline-remediate' \
             AND detail->>'server_name' = $1",
        )
        .bind(&unscoped_server)
        .fetch_one(pool)
        .await
        .expect("count unscoped remediation audit");
        assert_eq!(unscoped_audits, 1);

        let chain = audit::verify_audit_chain(pool)
            .await
            .expect("verify audit chain");
        assert!(
            chain.verified,
            "baseline audit must preserve the hash chain"
        );

        sqlx::query("DELETE FROM baseline_results WHERE server_name = $1")
            .bind(&server)
            .execute(pool)
            .await
            .expect("clean up baseline audit fixture");
        sqlx::query("DELETE FROM baseline_results WHERE server_name = $1")
            .bind(&unscoped_server)
            .execute(pool)
            .await
            .expect("clean up unscoped baseline fixture");
    }

    #[tokio::test]
    async fn baseline_mixed_and_unknown_site_targets_fail_closed() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set");
            return;
        };
        let mixed = format!("baseline-mixed-{}", Uuid::new_v4().simple());
        for (check, site) in [("bc-001", "DEFRA"), ("bc-002", "GBLON")] {
            sqlx::query(
                "INSERT INTO baseline_results \
                 (server_name, check_id, compliant, actual_value, site) \
                 VALUES ($1, $2, false, 'test', $3)",
            )
            .bind(&mixed)
            .bind(check)
            .bind(site)
            .execute(pool)
            .await
            .expect("insert mixed-site handler fixture");
        }
        let unrestricted = operator("baseline-invalid-unscoped", None);
        assert!(matches!(
            baseline_check(AuthExtractor(unrestricted.clone()), Path(mixed.clone())).await,
            Err((StatusCode::NOT_FOUND, _))
        ));
        assert!(matches!(
            baseline_remediate(
                AuthExtractor(unrestricted.clone()),
                Path((mixed.clone(), "bc-001".into()))
            )
            .await,
            Err((StatusCode::NOT_FOUND, _))
        ));

        let unknown = format!("baseline-unknown-{}", Uuid::new_v4().simple());
        insert_result(pool, &unknown, "UNKNOWN").await;
        assert!(matches!(
            baseline_check(AuthExtractor(unrestricted.clone()), Path(unknown.clone())).await,
            Err((StatusCode::NOT_FOUND, _))
        ));
        assert!(matches!(
            baseline_remediate(
                AuthExtractor(unrestricted),
                Path((unknown.clone(), "bc-004".into()))
            )
            .await,
            Err((StatusCode::NOT_FOUND, _))
        ));

        for server in [&mixed, &unknown] {
            let changed: i64 = sqlx::query_scalar(
                "SELECT COUNT(*) FROM baseline_results \
                 WHERE server_name = $1 AND compliant",
            )
            .bind(server)
            .fetch_one(pool)
            .await
            .expect("count invalid-target mutations");
            assert_eq!(changed, 0);
            let audits: i64 = sqlx::query_scalar(
                "SELECT COUNT(*) FROM audit_log WHERE action = 'baseline-remediate' \
                 AND detail->>'server_name' = $1",
            )
            .bind(server)
            .fetch_one(pool)
            .await
            .expect("count invalid-target audits");
            assert_eq!(audits, 0);
            sqlx::query("DELETE FROM baseline_results WHERE server_name = $1")
                .bind(server)
                .execute(pool)
                .await
                .expect("clean up invalid-site baseline fixture");
        }
    }

    #[tokio::test]
    async fn baseline_audit_failure_rolls_back_remediation() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set");
            return;
        };
        let server = format!("baseline-audit-rollback-{}", Uuid::new_v4().simple());
        insert_result(pool, &server, "GBLON").await;
        let before: (bool, String, chrono::DateTime<chrono::Utc>) = sqlx::query_as(
            "SELECT compliant, actual_value, last_checked FROM baseline_results \
             WHERE server_name = $1 AND check_id = 'bc-004'",
        )
        .bind(&server)
        .fetch_one(pool)
        .await
        .expect("read rollback fixture before");

        // PostgreSQL TEXT rejects NUL. The state UPDATE runs first, then the
        // actor-attributed audit insert fails, exercising the real atomic seam.
        let result = baseline_remediate(
            AuthExtractor(operator("baseline\0audit-failure", Some("GBLON"))),
            Path((server.clone(), "bc-004".into())),
        )
        .await;
        assert!(matches!(
            result,
            Err((StatusCode::INTERNAL_SERVER_ERROR, _))
        ));

        let after: (bool, String, chrono::DateTime<chrono::Utc>) = sqlx::query_as(
            "SELECT compliant, actual_value, last_checked FROM baseline_results \
             WHERE server_name = $1 AND check_id = 'bc-004'",
        )
        .bind(&server)
        .fetch_one(pool)
        .await
        .expect("read rollback fixture after");
        assert_eq!(
            after, before,
            "audit failure must roll back every state field"
        );
        let audits: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM audit_log WHERE action = 'baseline-remediate' \
             AND detail->>'server_name' = $1",
        )
        .bind(&server)
        .fetch_one(pool)
        .await
        .expect("count rollback audits");
        assert_eq!(audits, 0);

        sqlx::query("DELETE FROM baseline_results WHERE server_name = $1")
            .bind(&server)
            .execute(pool)
            .await
            .expect("clean up rollback fixture");
    }
}

