// ─── Legal Hold Engine Handlers ───

async fn legal_hold_place(
    AuthExtractor(session): AuthExtractor,
    Json(req): Json<LegalHoldPlaceRequest>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    // #2: a scoped principal may only place a legal hold in its own site.
    guard_body_site_scope(&session, &req.site)?;
    let initiating_principal = authenticated_principal_id(&session)?.to_string();
    // initiated_by = authenticated caller (from request extensions), never a client
    // body field — the hold audit must name the real principal.
    let hold_type = match req.hold_type.to_lowercase().as_str() {
        "investigation" => legal_hold::HoldType::Investigation,
        "litigation" => legal_hold::HoldType::Litigation,
        "compliance" => legal_hold::HoldType::Compliance,
        "retention" => legal_hold::HoldType::Retention,
        _ => {
            return Err((
                StatusCode::BAD_REQUEST,
                Json(
                    json!({"error": format!("Invalid hold_type: {}. Must be Investigation, Litigation, Compliance, or Retention.", req.hold_type)}),
                ),
            ));
        }
    };
    // Validate + construct via the engine (enforces the active site registry; also pushes to
    // the static, which is the no-DB fallback).
    let hold = match legal_hold::place_hold(
        &req.target,
        hold_type,
        &req.reason,
        &initiating_principal,
        &req.site,
    ) {
        Ok(hold) => hold,
        Err(e) => return Err((StatusCode::BAD_REQUEST, Json(json!({"error": e})))),
    };
    if let Some(pool) = get_db() {
        // Durable path: timestamps via ::timestamptz casts, JSONB via ::jsonb on
        // text binds. hold_type/status serialize capitalized (serde variant
        // names), matching the migration-026 CHECK constraints and seeds.
        let mut tx = pool.begin().await.map_err(db_error)?;
        sqlx::query(
            "INSERT INTO legal_holds \
                (id, server_or_app_name, hold_type, reason, initiated_by, initiated_date, \
                 expiry_date, status, affected_backups, site, audit_trail) \
             VALUES ($1, $2, $3, $4, $5, $6::timestamptz, $7::timestamptz, $8, $9::jsonb, $10, $11::jsonb)",
        )
        .bind(&hold.id)
        .bind(&hold.server_or_app_name)
        .bind(serde_enum_str(&hold.hold_type))
        .bind(&hold.reason)
        .bind(&hold.initiated_by)
        .bind(&hold.initiated_date)
        .bind(&hold.expiry_date)
        .bind(serde_enum_str(&hold.status))
        .bind(serde_json::to_string(&hold.affected_backups).unwrap_or_else(|_| "[]".into()))
        .bind(&hold.site)
        .bind(serde_json::to_string(&hold.audit_trail).unwrap_or_else(|_| "[]".into()))
        .execute(&mut *tx)
        .await
        .map_err(db_error)?;
        audit::record_audit_tx(
            &mut tx,
            &session,
            &audit::security_audit(
                "legal-hold-place",
                None,
                "placed",
                json!({ "hold_id": &hold.id }),
            ),
        )
        .await
        .map_err(db_error)?;
        tx.commit().await.map_err(db_error)?;
    }
    Ok(Json(serde_json::to_value(&hold).unwrap_or_default()))
}

/// One persisted `legal_holds` row (migration 026). JSONB columns are selected
/// as ::text and parsed back so `to_json` reproduces the engine `LegalHold`
/// serde shape (enums capitalized, dates rfc3339, JSONB arrays).
#[derive(sqlx::FromRow)]
struct LegalHoldRow {
    id: String,
    server_or_app_name: String,
    hold_type: String,
    reason: String,
    initiated_by: String,
    initiated_date: chrono::DateTime<chrono::Utc>,
    expiry_date: chrono::DateTime<chrono::Utc>,
    status: String,
    affected_backups: String,
    site: String,
    released_by: Option<String>,
    released_date: Option<chrono::DateTime<chrono::Utc>>,
    audit_trail: String,
}

impl LegalHoldRow {
    fn to_json(&self) -> Value {
        json!({
            "id": self.id,
            "server_or_app_name": self.server_or_app_name,
            "hold_type": self.hold_type,
            "reason": self.reason,
            "initiated_by": self.initiated_by,
            "initiated_date": self.initiated_date.to_rfc3339(),
            "expiry_date": self.expiry_date.to_rfc3339(),
            "status": self.status,
            "affected_backups": serde_json::from_str::<Value>(&self.affected_backups)
                .unwrap_or_else(|_| json!([])),
            "site": self.site,
            "released_by": self.released_by,
            "released_date": self.released_date.as_ref().map(|d| d.to_rfc3339()),
            "audit_trail": serde_json::from_str::<Value>(&self.audit_trail)
                .unwrap_or_else(|_| json!([])),
        })
    }
}

const LEGAL_HOLD_COLUMNS: &str = "id, server_or_app_name, hold_type, reason, initiated_by, \
     initiated_date, expiry_date, status, affected_backups::text AS affected_backups, site, \
     released_by, released_date, audit_trail::text AS audit_trail";

/// Canonical serde string for a serializable enum value ("Active", etc.).
fn serde_enum_str<T: serde::Serialize>(value: &T) -> String {
    serde_json::to_value(value)
        .ok()
        .and_then(|v| v.as_str().map(str::to_string))
        .unwrap_or_default()
}

async fn legal_hold_validate(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    if let Some(pool) = get_db() {
        // Fetch from DB so validation sees persisted state (not engine-only in-memory).
        let row: Option<LegalHoldRow> = sqlx::query_as(&format!(
            "SELECT {LEGAL_HOLD_COLUMNS} FROM legal_holds WHERE id = $1"
        ))
        .bind(&id)
        .fetch_optional(pool)
        .await
        .map_err(db_error)?;
        let Some(hold) = row else {
            return Err((
                StatusCode::BAD_REQUEST,
                Json(json!({"error": format!("Legal hold {} not found", id)})),
            ));
        };
        // #2: an out-of-scope hold is reported identically to a missing one (the
        // same 400 above) so a scoped principal gets no existence oracle.
        if !row_scope_permits(&session, &hold.site, "") {
            return Err((
                StatusCode::BAD_REQUEST,
                Json(json!({"error": format!("Legal hold {} not found", id)})),
            ));
        }
        // Validate the DB row with parity to legal_hold::validate_hold (do NOT
        // call validate_hold(&id) — it looks up the static HOLD_STORE, absent
        // for DB-seeded/restarted holds). expiry_date is a NOT NULL TIMESTAMPTZ
        // in the DB so the engine's "no expiry" warning cannot apply here.
        let mut errors: Vec<String> = Vec::new();
        let mut warnings: Vec<String> = Vec::new();
        let mut failed_rules: Vec<String> = Vec::new();
        let mut remediation: Vec<String> = Vec::new();
        if hold.server_or_app_name.is_empty() {
            errors.push("Missing server or application name".into());
            failed_rules.push("p0-target-required".into());
            remediation.push("Provide a valid target name.".into());
        }
        if hold.reason.is_empty() {
            errors.push("Missing hold reason".into());
            failed_rules.push("p0-reason-required".into());
            remediation.push("Provide a business reason for the hold.".into());
        }
        let backups_empty = serde_json::from_str::<Vec<serde_json::Value>>(&hold.affected_backups)
            .map(|v| v.is_empty())
            .unwrap_or(true);
        if backups_empty {
            warnings.push("No affected backups documented".into());
        }
        warnings.push("DRY-RUN: Backup integrity check simulated".into());
        warnings.push("DRY-RUN: Provider hold state verification simulated".into());
        let passed = errors.is_empty();
        return Ok(Json(json!({
            "hold": hold.to_json(),
            "validation": {
                "passed": passed,
                "errors": errors,
                "warnings": warnings,
                "failed_rules": failed_rules,
                "remediation": remediation,
                "source": "database",
            },
        })));
    }
    // #2: the no-DB fallback reads the process-local HOLD_STORE, which has no site
    // dimension to enforce scope on — a scoped principal cannot be served safely
    // without the database, so fail closed (503) rather than leak cross-site data.
    if is_scoped(&session) {
        return Err(status_503_no_db());
    }
    match legal_hold::validate_hold(&id) {
        Ok(result) => Ok(Json(serde_json::to_value(result).unwrap())),
        Err(e) => Err((StatusCode::BAD_REQUEST, Json(json!({"error": e})))),
    }
}

async fn legal_hold_extend(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
    Json(req): Json<LegalHoldExtendRequest>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    if let Some(pool) = get_db() {
        // DB path: validate new_expiry parses (basic sanity) then CAS-UPDATE
        // directly against the DB row.  Do NOT call extend_hold() which mutates
        // HOLD_STORE — absent for DB-seeded/restarted holds.
        if req.new_expiry.is_empty() {
            return Err((
                StatusCode::BAD_REQUEST,
                Json(json!({"error": "new_expiry is required"})),
            ));
        }
        // #2: confine to the principal's scope. Pre-load the hold's site (only for
        // a scoped principal); an out-of-scope hold returns the SAME "not found or
        // not Active" 409 the CAS below produces, so there is no existence oracle.
        if is_scoped(&session) {
            let site: Option<String> =
                sqlx::query_scalar("SELECT site FROM legal_holds WHERE id = $1")
                    .bind(&id)
                    .fetch_optional(pool)
                    .await
                    .map_err(db_error)?;
            if !site
                .map(|s| row_scope_permits(&session, &s, ""))
                .unwrap_or(false)
            {
                return Err((
                    StatusCode::CONFLICT,
                    Json(json!({"error": format!("Legal hold {} not found or not Active", id)})),
                ));
            }
        }
        let now = chrono::Utc::now().to_rfc3339();
        let audit_entry = serde_json::to_string(&serde_json::json!([{
            "timestamp": now,
            "action": "hold_extended",
            "detail": format!("Expiry extended to {}", req.new_expiry),
        }]))
        .unwrap_or_else(|_| "[]".into());

        let mut tx = pool.begin().await.map_err(db_error)?;
        // Append new audit entry to existing trail via jsonb concatenation.
        let row: Option<LegalHoldRow> = sqlx::query_as(&format!(
            "UPDATE legal_holds \
             SET expiry_date = $2::timestamptz, \
                 audit_trail = audit_trail || $3::jsonb, \
                 updated_at = NOW() \
             WHERE id = $1 AND status = 'Active' \
             RETURNING {LEGAL_HOLD_COLUMNS}"
        ))
        .bind(&id)
        .bind(&req.new_expiry)
        .bind(audit_entry)
        .fetch_optional(&mut *tx)
        .await
        .map_err(db_error)?;
        let updated = match row {
            Some(r) => r,
            None => {
                return Err((
                    StatusCode::CONFLICT,
                    Json(json!({"error": format!("Legal hold {} not found or not Active", id)})),
                ));
            }
        };
        audit::record_audit_tx(
            &mut tx,
            &session,
            &audit::security_audit(
                "legal-hold-extend",
                None,
                "extended",
                json!({ "hold_id": &id }),
            ),
        )
        .await
        .map_err(db_error)?;
        tx.commit().await.map_err(db_error)?;
        return Ok(Json(updated.to_json()));
    }
    // No-DB fallback: engine validates status=Active and parses new_expiry.
    // #2: no-DB fallback can't enforce site scope on the static HOLD_STORE.
    if is_scoped(&session) {
        return Err(status_503_no_db());
    }
    match legal_hold::extend_hold(&id, &req.new_expiry) {
        Ok(hold) => Ok(Json(serde_json::to_value(hold).unwrap())),
        Err(e) => Err((StatusCode::BAD_REQUEST, Json(json!({"error": e})))),
    }
}

async fn legal_hold_release(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    // Releasing a hold is a deliberate human attestation. Reject a workload,
    // unknown carrier, or simulated actor before any resource read or write.
    if !check_human_signoff_permission(&session, "execute") {
        return Err(status_403());
    }
    let releasing_principal = authenticated_principal_id(&session)?.to_string();
    // released_by = authenticated caller (from request extensions), never a client
    // body field — the release audit must name the real principal.
    if let Some(pool) = get_db() {
        // DB path: CAS-UPDATE directly.  Do NOT call release_hold() which
        // mutates HOLD_STORE — absent for DB-seeded/restarted holds.
        // #2: confine to the principal's scope; an out-of-scope hold returns the
        // SAME "not found or not Active" 409 the CAS below produces (no oracle).
        if is_scoped(&session) {
            let site: Option<String> =
                sqlx::query_scalar("SELECT site FROM legal_holds WHERE id = $1")
                    .bind(&id)
                    .fetch_optional(pool)
                    .await
                    .map_err(db_error)?;
            if !site
                .map(|s| row_scope_permits(&session, &s, ""))
                .unwrap_or(false)
            {
                return Err((
                    StatusCode::CONFLICT,
                    Json(json!({"error": format!("Legal hold {} not found or not Active", id)})),
                ));
            }
        }
        let now = chrono::Utc::now().to_rfc3339();
        let audit_entry = serde_json::to_string(&serde_json::json!([{
            "timestamp": now,
            "action": "hold_released",
            "by": &releasing_principal,
            "detail": "Hold released",
        }]))
        .unwrap_or_else(|_| "[]".into());

        let mut tx = pool.begin().await.map_err(db_error)?;
        let row: Option<LegalHoldRow> = sqlx::query_as(&format!(
            "UPDATE legal_holds \
             SET status = 'Released', released_by = $2, released_date = $3::timestamptz, \
                 audit_trail = audit_trail || $4::jsonb, updated_at = NOW() \
             WHERE id = $1 AND status = 'Active' \
             RETURNING {LEGAL_HOLD_COLUMNS}"
        ))
        .bind(&id)
        .bind(&releasing_principal)
        .bind(&now)
        .bind(audit_entry)
        .fetch_optional(&mut *tx)
        .await
        .map_err(db_error)?;
        let updated = match row {
            Some(r) => r,
            None => {
                return Err((
                    StatusCode::CONFLICT,
                    Json(json!({"error": format!("Legal hold {} not found or not Active", id)})),
                ));
            }
        };
        audit::record_audit_tx(
            &mut tx,
            &session,
            &audit::security_audit(
                "legal-hold-release",
                None,
                "released",
                json!({ "hold_id": &id }),
            ),
        )
        .await
        .map_err(db_error)?;
        tx.commit().await.map_err(db_error)?;
        return Ok(Json(updated.to_json()));
    }
    // No-DB fallback: engine validates status=Active and records audit entry.
    // #2: no-DB fallback can't enforce site scope on the static HOLD_STORE.
    if is_scoped(&session) {
        return Err(status_503_no_db());
    }
    match legal_hold::release_hold(&id, &releasing_principal) {
        Ok(hold) => Ok(Json(serde_json::to_value(hold).unwrap())),
        Err(e) => Err((StatusCode::BAD_REQUEST, Json(json!({"error": e})))),
    }
}

async fn legal_hold_active(
    AuthExtractor(session): AuthExtractor,
    Query(q): Query<LegalHoldActiveQuery>,
) -> ApiResult {
    // #2: narrow the site filter to the principal's scope (env-scoped -> 403;
    // unrestricted with no ?site -> "" = all sites).
    let site = enforce_site_scope(&session, q.site.as_deref(), "")?;
    if let Some(pool) = get_db() {
        let rows: Vec<LegalHoldRow> = sqlx::query_as(&format!(
            "SELECT {LEGAL_HOLD_COLUMNS} FROM legal_holds \
             WHERE status = 'Active' AND ($1 = '' OR site = $1) ORDER BY expiry_date, id"
        ))
        .bind(&site)
        .fetch_all(pool)
        .await
        .map_err(db_error)?;
        return Ok(Json(json!(rows
            .iter()
            .map(LegalHoldRow::to_json)
            .collect::<Vec<_>>())));
    }
    let holds = legal_hold::get_active_holds(&site);
    Ok(Json(serde_json::to_value(holds).unwrap()))
}

async fn legal_hold_expiring(AuthExtractor(session): AuthExtractor) -> ApiResult {
    if let Some(pool) = get_db() {
        // Same predicate as the engine: Active holds expiring within 30 days.
        let rows: Vec<LegalHoldRow> = sqlx::query_as(&format!(
            "SELECT {LEGAL_HOLD_COLUMNS} FROM legal_holds \
             WHERE status = 'Active' AND expiry_date <= NOW() + INTERVAL '30 days' \
             ORDER BY expiry_date, id"
        ))
        .fetch_all(pool)
        .await
        .map_err(db_error)?;
        // #2: a scoped principal only sees its own site's holds (env-scoped -> none).
        let rows = retain_site_scoped(&session, rows, |r| r.site.as_str());
        return Ok(Json(json!(rows
            .iter()
            .map(LegalHoldRow::to_json)
            .collect::<Vec<_>>())));
    }
    // #2: no-DB fallback can't enforce site scope on the static HOLD_STORE.
    if is_scoped(&session) {
        return Err(status_503_no_db());
    }
    let holds = legal_hold::get_expiring_holds();
    Ok(Json(serde_json::to_value(holds).unwrap()))
}

async fn legal_hold_evidence(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    if let Some(pool) = get_db() {
        // Return the audit_trail JSONB column directly from the DB.
        let row: Option<LegalHoldRow> = sqlx::query_as(&format!(
            "SELECT {LEGAL_HOLD_COLUMNS} FROM legal_holds WHERE id = $1"
        ))
        .bind(&id)
        .fetch_optional(pool)
        .await
        .map_err(db_error)?;
        return match row {
            Some(hold) => {
                // #2: out-of-scope -> 404 with the SAME body as the not-found arm
                // below. scope_guard_or_404/status_404 would say "Request ..." — a
                // body-level existence oracle — so use the handler's own message.
                if !row_scope_permits(&session, &hold.site, "") {
                    return Err((
                        StatusCode::NOT_FOUND,
                        Json(json!({"error": format!("Legal hold {} not found", id)})),
                    ));
                }
                let audit =
                    serde_json::from_str::<Value>(&hold.audit_trail).unwrap_or_else(|_| json!([]));
                Ok(Json(audit))
            }
            None => Err((
                StatusCode::NOT_FOUND,
                Json(json!({"error": format!("Legal hold {} not found", id)})),
            )),
        };
    }
    // #2: no-DB fallback can't enforce site scope on the static HOLD_STORE.
    if is_scoped(&session) {
        return Err(status_503_no_db());
    }
    match legal_hold::get_hold_evidence(&id) {
        Ok(evidence) => Ok(Json(serde_json::to_value(evidence).unwrap())),
        Err(e) => Err((StatusCode::NOT_FOUND, Json(json!({"error": e})))),
    }
}

async fn legal_hold_compliance(
    AuthExtractor(session): AuthExtractor,
    Path(server): Path<String>,
) -> ApiResult {
    if server.is_empty() {
        return Err(status_400("server_name cannot be empty"));
    }

    // DB path: query legal_holds directly. HOLD_STORE is not populated from DB
    // rows after restart, so check_compliance() would miss persisted holds.
    if let Some(pool) = get_db() {
        let rows: Vec<LegalHoldRow> = sqlx::query_as(&format!(
            "SELECT {LEGAL_HOLD_COLUMNS} FROM legal_holds \
             WHERE status = 'Active' \
               AND strpos(LOWER(server_or_app_name), LOWER($1)) > 0 \
             ORDER BY expiry_date, id"
        ))
        .bind(&server)
        .fetch_all(pool)
        .await
        .map_err(db_error)?;

        // #2: only the principal's own-site holds count toward compliance
        // (env-scoped principals see none — legal_holds is site-only).
        let rows = retain_site_scoped(&session, rows, |r| r.site.as_str());
        let under_hold = !rows.is_empty();
        let holds: Vec<Value> = rows.iter().map(LegalHoldRow::to_json).collect();
        let message = if under_hold {
            format!(
                "DRY-RUN: {} is under {} active legal hold(s). Backup deletion blocked. Decommission suspended. No provider calls made.",
                server,
                holds.len()
            )
        } else {
            format!(
                "DRY-RUN: No active legal holds found for {}. Normal operations permitted.",
                server
            )
        };

        return Ok(Json(json!({
            "server_name": server,
            "under_hold": under_hold,
            "active_holds": holds,
            "message": message,
            "source": "database",
        })));
    }
    // No-DB fallback: engine uses HOLD_STORE (current-process only).
    // #2: no-DB fallback can't enforce site scope on the static HOLD_STORE; a
    // scoped principal fails closed (503) rather than receive a possibly-false
    // "no holds, safe to proceed" answer computed from cross-site demo data.
    if is_scoped(&session) {
        return Err(status_503_no_db());
    }
    match legal_hold::check_compliance(&server) {
        Ok(result) => Ok(Json(serde_json::to_value(result).unwrap())),
        Err(e) => Err(status_400(&e)),
    }
}

