// ─── Noise remediation — DB row type ───

/// Mirrors the `noisy_triggers` table columns exactly so `sqlx::query_as` can
/// decode rows without a manual field-by-field bind.
#[derive(sqlx::FromRow)]
#[allow(dead_code)]
struct NoisyTriggerRow {
    id: sqlx::types::Uuid,
    trigger_name: String,
    host: String,
    severity: String,
    event_count_last_24h: i32,
    avg_interval_minutes: f64,
    flapping: bool,
    suggested_action: String,
    status: String,
    suppress_until: Option<chrono::DateTime<chrono::Utc>>,
    suppress_reason: Option<String>,
    resolution: Option<String>,
    created_at: chrono::DateTime<chrono::Utc>,
    updated_at: chrono::DateTime<chrono::Utc>,
}

#[derive(sqlx::FromRow)]
struct NoiseReportCounts {
    total_triggers: i64,
    noisy: i64,
    flapping: i64,
    active: i64,
    under_review: i64,
    suppressed: i64,
    resolved: i64,
}

const NOISE_COLUMNS: &str =
    "id, trigger_name, host, severity, event_count_last_24h, avg_interval_minutes, \
     flapping, suggested_action, status, suppress_until, suppress_reason, resolution, \
     created_at, updated_at";

/// Convert a DB row into the JSON shape that matches `NoisyTrigger` serialized
/// by serde (field names + types match the engine struct 1:1, including
/// `updated_at`).
fn noise_row_to_json(r: &NoisyTriggerRow) -> Value {
    json!({
        "id": r.id.to_string(),
        "trigger_name": r.trigger_name,
        "host": r.host,
        "severity": r.severity,
        "event_count_last_24h": r.event_count_last_24h,
        "avg_interval_minutes": r.avg_interval_minutes,
        "flapping": r.flapping,
        "suggested_action": r.suggested_action,
        "status": r.status,
        "suppress_until": r.suppress_until.map(|t| t.to_rfc3339()),
        "suppress_reason": r.suppress_reason,
        "resolution": r.resolution,
        "created_at": r.created_at.to_rfc3339(),
        "updated_at": r.updated_at.to_rfc3339(),
    })
}

/// Parse a path id as a UUID for the DB path. A malformed id is treated as a
/// missing trigger (404) — matching the engine fallback, which finds no match
/// for an arbitrary string — rather than letting Postgres reject the cast and
/// surface a 500 with a raw DB error.
fn parse_noise_id(id: &str) -> Result<sqlx::types::Uuid, (StatusCode, Json<Value>)> {
    sqlx::types::Uuid::parse_str(id).map_err(|_| {
        (
            StatusCode::NOT_FOUND,
            Json(json!({ "error": format!("Trigger not found: {}", id) })),
        )
    })
}

// ─── Noise remediation handlers ───

/// Confirm the requested site against the same durable active registry that
/// maintains `noisy_triggers.site`. The process-local registry remains the
/// dry-run authority, but must not be used to authorize the database path.
async fn require_active_noise_site(
    pool: &sqlx::PgPool,
    site: &str,
) -> Result<(), (StatusCode, Json<Value>)> {
    let active: bool = sqlx::query_scalar(
        "SELECT EXISTS(SELECT 1 FROM site_registry WHERE unlocode = $1 AND active)",
    )
    .bind(site)
    .fetch_one(pool)
    .await
    .map_err(db_error)?;
    if active {
        Ok(())
    } else {
        Err((
            StatusCode::BAD_REQUEST,
            Json(json!({"error": format!("Unknown site: {}", site)})),
        ))
    }
}

const NOISE_SITE_RECONCILIATION_LOOP_NAME: &str = "noisy_trigger_site_reconciliation";
const NOISE_SITE_RECONCILIATION_BATCH_ROWS: i32 = 128;

/// Advance one durable, generation-fenced reconciliation page.  Migration 181
/// enforces the 1..=256 argument bound in PostgreSQL as a second line of
/// defence; callers cannot make this worker scan or update an unbounded page.
pub(crate) async fn reconcile_noisy_trigger_sites_once(
    pool: &sqlx::PgPool,
) -> Result<i32, sqlx::Error> {
    sqlx::query_scalar("SELECT public.reconcile_noisy_trigger_sites($1)")
        .bind(NOISE_SITE_RECONCILIATION_BATCH_ROWS)
        .fetch_one(pool)
        .await
}

/// Continuously drains stale site generations in fixed transactions.  A
/// registry change invalidates old rows synchronously in O(1); this worker only
/// controls how quickly correctly reclassified rows become visible again.
pub fn spawn_noise_site_reconciliation(pool: sqlx::PgPool, interval_secs: u64) {
    tokio::spawn(async move {
        crate::background::register_loop(NOISE_SITE_RECONCILIATION_LOOP_NAME, interval_secs);
        let mut ticker = tokio::time::interval(std::time::Duration::from_secs(interval_secs));
        ticker.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
        ticker.tick().await;
        let mut consecutive_failures = 0u32;
        loop {
            ticker.tick().await;
            match crate::background::run_bounded(
                std::time::Duration::from_secs(10),
                reconcile_noisy_trigger_sites_once(&pool),
            )
            .await
            {
                Ok(_) => {
                    consecutive_failures = 0;
                    crate::background::record_loop_success(NOISE_SITE_RECONCILIATION_LOOP_NAME);
                }
                Err(error) => {
                    let backoff = crate::background::note_failure(&mut consecutive_failures);
                    match error {
                        crate::background::IterError::Failed(error) => tracing::error!(
                            error = %error,
                            consecutive_failures,
                            backoff_intervals = backoff,
                            "noisy-trigger site reconciliation failed; backing off"
                        ),
                        crate::background::IterError::TimedOut => tracing::error!(
                            consecutive_failures,
                            backoff_intervals = backoff,
                            "noisy-trigger site reconciliation timed out; backing off"
                        ),
                    }
                    tokio::time::sleep(std::time::Duration::from_secs(
                        interval_secs.saturating_mul(backoff),
                    ))
                    .await;
                }
            }
        }
    });
}

/// Aggregate one persisted canonical site in a single indexable query. Site
/// assignment is maintained by migration 181; quarantined rows have `site`
/// NULL and therefore cannot leak into any site's report.
fn noise_report_sql() -> &'static str {
    "SELECT COUNT(*) AS total_triggers, \
            COUNT(*) FILTER (WHERE event_count_last_24h > 10) AS noisy, \
            COUNT(*) FILTER (WHERE flapping) AS flapping, \
            COUNT(*) FILTER (WHERE status = 'Active') AS active, \
            COUNT(*) FILTER (WHERE status = 'UnderReview') AS under_review, \
            COUNT(*) FILTER (WHERE status = 'Suppressed') AS suppressed, \
            COUNT(*) FILTER (WHERE status = 'Resolved') AS resolved \
     FROM noisy_triggers \
     WHERE site = $1 \
       AND site_resolution_generation = ( \
           SELECT generation FROM noisy_trigger_site_authority WHERE singleton \
       )"
}

async fn noise_detect(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<NoiseSiteRequest>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let site = site_registry::normalize_site_code_for_lookup(&body.site)
        .map_err(|error| status_400(&error))?;
    // #2: a scoped principal may only run noise detection for its own site;
    // env-scoped principals are rejected (noise is site-keyed via the host).
    guard_body_site_scope(&session, &site)?;
    if let Some(pool) = get_db() {
        require_active_noise_site(pool, &site).await?;
        let rows: Vec<NoisyTriggerRow> = sqlx::query_as(&format!(
            "SELECT {NOISE_COLUMNS} FROM noisy_triggers \
             WHERE site = $1 AND event_count_last_24h > 10 \
               AND site_resolution_generation = ( \
                   SELECT generation FROM noisy_trigger_site_authority WHERE singleton \
               ) \
             ORDER BY event_count_last_24h DESC, id DESC LIMIT {MAX_LIST_ROWS}"
        ))
        .bind(&site)
        .fetch_all(pool)
        .await
        .map_err(db_error)?;
        let arr: Vec<Value> = rows.iter().map(noise_row_to_json).collect();
        return Ok(Json(Value::Array(arr)));
    }
    match noise_remediation::detect_noise(&site) {
        Ok(triggers) => Ok(Json(serde_json::to_value(triggers).unwrap_or_default())),
        Err(e) => Err((StatusCode::BAD_REQUEST, Json(json!({"error": e})))),
    }
}

