async fn noise_suggest(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    if let Some(pool) = get_db() {
        // Parse id as UUID first — malformed id → 404, not a DB cast 500
        let trigger_uuid = parse_noise_id(&id)?;
        // Put canonical-site visibility in the row-fetch itself. Quarantined
        // rows (`site IS NULL`) are invisible even to an unscoped principal,
        // and a registry reclassification cannot race a pre-load Rust guard.
        let sites = match list_site_scope(&session) {
            ListSiteScope::Empty => {
                return Err((
                    StatusCode::NOT_FOUND,
                    Json(json!({"error": format!("Trigger not found: {}", id)})),
                ));
            }
            ListSiteScope::All => None,
            ListSiteScope::Sites(sites) => Some(sites),
        };
        let row: Option<NoisyTriggerRow> = match sites.as_deref() {
            None => sqlx::query_as(&format!(
                "SELECT {NOISE_COLUMNS} FROM noisy_triggers \
                 WHERE id = $1 AND site IS NOT NULL \
                   AND site_resolution_generation = ( \
                       SELECT generation FROM noisy_trigger_site_authority WHERE singleton \
                   )"
            ))
            .bind(trigger_uuid)
            .fetch_optional(pool)
            .await
            .map_err(db_error)?,
            Some(sites) => sqlx::query_as(&format!(
                "SELECT {NOISE_COLUMNS} FROM noisy_triggers \
                 WHERE id = $1 AND site = ANY($2) \
                   AND site_resolution_generation = ( \
                       SELECT generation FROM noisy_trigger_site_authority WHERE singleton \
                   )"
            ))
            .bind(trigger_uuid)
            .bind(sites)
            .fetch_optional(pool)
            .await
            .map_err(db_error)?,
        };
        let Some(r) = row else {
            return Err((
                StatusCode::NOT_FOUND,
                Json(json!({"error": format!("Trigger not found: {}", id)})),
            ));
        };
        // Replicate engine suggestion logic field-for-field
        let suggestions: Vec<String> = if r.flapping {
            vec![
                "Add maintenance window to suppress during known change windows".to_string(),
                "Increase trigger fire threshold or adjust sensitivity".to_string(),
                "Correlate with CMDB for associated change records".to_string(),
            ]
        } else if r.event_count_last_24h > 50 {
            vec![
                "Escalate to service owner for threshold review".to_string(),
                "Check if monitoring template needs recalibration".to_string(),
                "Add maintenance window during peak hours if expected".to_string(),
            ]
        } else {
            vec![
                "Adjust threshold to reduce non-actionable alerts".to_string(),
                "Add maintenance window for scheduled activity".to_string(),
                "Correlate with known issue in CMDB".to_string(),
            ]
        };
        return Ok(Json(json!({
            "trigger_id": r.id.to_string(),
            "trigger_name": r.trigger_name,
            "host": r.host,
            "current_action": r.suggested_action,
            "suggestions": suggestions,
            "flapping": r.flapping,
            "event_count_last_24h": r.event_count_last_24h,
        })));
    }
    // #2: the engine fallback has no site dimension; a scoped principal fails closed.
    if is_scoped(&session) {
        return Err((
            StatusCode::NOT_FOUND,
            Json(json!({"error": format!("Trigger not found: {}", id)})),
        ));
    }
    match noise_remediation::suggest_remediation(&id) {
        Ok(suggestions) => Ok(Json(suggestions)),
        Err(e) => Err((StatusCode::NOT_FOUND, Json(json!({"error": e})))),
    }
}

async fn noise_suppress(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
    Json(body): Json<NoiseSuppressRequest>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    if let Some(pool) = get_db() {
        let trigger_uuid = parse_noise_id(&id)?;
        let sites = match list_site_scope(&session) {
            ListSiteScope::Empty => {
                return Err((
                    StatusCode::NOT_FOUND,
                    Json(json!({"error": format!("Trigger not found: {}", id)})),
                ));
            }
            ListSiteScope::All => None,
            ListSiteScope::Sites(sites) => Some(sites),
        };
        // A zero-length suppression is already expired when written, so the
        // expiry scan would immediately revert it — reject it up front (400).
        if body.duration_minutes == 0 {
            return Err((
                StatusCode::BAD_REQUEST,
                Json(json!({"error": "suppression duration must be at least 1 minute"})),
            ));
        }
        let now = chrono::Utc::now();
        // Reject an overflowing duration instead of clamping to `now` (which would
        // mint an already-expired suppression the scan immediately reverts).
        let suppress_until = match now
            .checked_add_signed(chrono::Duration::minutes(body.duration_minutes as i64))
        {
            Some(t) => t,
            None => {
                return Err((
                    StatusCode::BAD_REQUEST,
                    Json(json!({"error": "suppression duration overflows the supported range"})),
                ));
            }
        };
        // Atomic compare-and-set inside a tx so the audit row is written
        // atomically with the suppression (#7). The CAS UPDATE still guards
        // against double-apply; the tx is rolled back (no audit) on 404/409.
        // Only Active/UnderReview triggers are suppressible: suppressing a
        // Resolved trigger would let the expiry scan flip it back to Active,
        // resurrecting a closed trigger.
        let mut tx = pool.begin().await.map_err(db_error)?;
        // Take the authority lock in its own statement before the mutating
        // statement obtains a READ COMMITTED snapshot. This makes a registry
        // generation change and the authorization predicate strictly ordered;
        // the database statement trigger remains defense in depth for writers
        // outside this handler.
        sqlx::query(
            "SELECT pg_advisory_xact_lock( \
                 hashtextextended('ryuki.noisy-trigger-site-authority', 0) \
             )",
        )
        .execute(&mut *tx)
        .await
        .map_err(db_error)?;
        let row: Option<NoisyTriggerRow> = match sites.as_deref() {
            None => sqlx::query_as(&format!(
                "UPDATE noisy_triggers \
                 SET status = 'Suppressed', suppress_until = $1, suppress_reason = $2, \
                     updated_at = $3 \
                 WHERE id = $4 AND status IN ('Active', 'UnderReview') \
                   AND site IS NOT NULL \
                   AND site_resolution_generation = ( \
                       SELECT generation FROM noisy_trigger_site_authority WHERE singleton \
                   ) \
                 RETURNING {NOISE_COLUMNS}"
            ))
            .bind(suppress_until)
            .bind(&body.reason)
            .bind(now)
            .bind(trigger_uuid)
            .fetch_optional(&mut *tx)
            .await
            .map_err(db_error)?,
            Some(sites) => sqlx::query_as(&format!(
                "UPDATE noisy_triggers \
                 SET status = 'Suppressed', suppress_until = $1, suppress_reason = $2, \
                     updated_at = $3 \
                 WHERE id = $4 AND status IN ('Active', 'UnderReview') \
                   AND site = ANY($5) \
                   AND site_resolution_generation = ( \
                       SELECT generation FROM noisy_trigger_site_authority WHERE singleton \
                   ) \
                 RETURNING {NOISE_COLUMNS}"
            ))
            .bind(suppress_until)
            .bind(&body.reason)
            .bind(now)
            .bind(trigger_uuid)
            .bind(sites)
            .fetch_optional(&mut *tx)
            .await
            .map_err(db_error)?,
        };
        if let Some(r) = row {
            // Row returned → successful suppression; audit + commit atomically.
            audit::record_audit_tx(
                &mut tx,
                &session,
                &audit::security_audit(
                    "noise-suppress",
                    None,
                    "suppressed",
                    json!({ "trigger_id": &id }),
                ),
            )
            .await
            .map_err(db_error)?;
            tx.commit().await.map_err(db_error)?;
            return Ok(Json(noise_row_to_json(&r)));
        }
        // 0 rows returned — the trigger doesn't exist, is already Suppressed, or
        // is in a non-suppressible terminal state (Resolved). Roll back (no audit
        // row written) and disambiguate via a read on the pool.
        drop(tx);
        let existing: Option<String> = match sites.as_deref() {
            None => sqlx::query_scalar(
                "SELECT status FROM noisy_triggers \
                 WHERE id = $1 AND site IS NOT NULL \
                   AND site_resolution_generation = ( \
                       SELECT generation FROM noisy_trigger_site_authority WHERE singleton \
                   )",
            )
            .bind(trigger_uuid)
            .fetch_optional(pool)
            .await
            .map_err(db_error)?,
            Some(sites) => sqlx::query_scalar(
                "SELECT status FROM noisy_triggers \
                 WHERE id = $1 AND site = ANY($2) \
                   AND site_resolution_generation = ( \
                       SELECT generation FROM noisy_trigger_site_authority WHERE singleton \
                   )",
            )
            .bind(trigger_uuid)
            .bind(sites)
            .fetch_optional(pool)
            .await
            .map_err(db_error)?,
        };
        match existing.as_deref() {
            None => Err((
                StatusCode::NOT_FOUND,
                Json(json!({"error": format!("Trigger not found: {}", id)})),
            )),
            Some("Suppressed") => Err((
                StatusCode::BAD_REQUEST,
                Json(json!({"error": "Trigger is already suppressed"})),
            )),
            Some(status) => Err((
                StatusCode::BAD_REQUEST,
                Json(json!({
                    "error": format!(
                        "cannot suppress a trigger in status '{status}' (only Active/UnderReview)"
                    )
                })),
            )),
        }
    } else {
        // #2: the engine fallback has no site dimension; a scoped principal fails
        // closed with the same not-found rather than suppress a cross-site trigger.
        if is_scoped(&session) {
            return Err((
                StatusCode::NOT_FOUND,
                Json(json!({"error": format!("Trigger not found: {}", id)})),
            ));
        }
        match noise_remediation::suppress_trigger(&id, body.duration_minutes, &body.reason) {
            Ok(trigger) => Ok(Json(serde_json::to_value(trigger).unwrap_or_default())),
            Err(e) if e.contains("not found") || e.to_lowercase().contains("not found") => {
                Err((StatusCode::NOT_FOUND, Json(json!({"error": e}))))
            }
            Err(e) => Err((StatusCode::BAD_REQUEST, Json(json!({"error": e})))),
        }
    }
}

async fn noise_resolve(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
    Json(body): Json<NoiseResolveRequest>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    if let Some(pool) = get_db() {
        let trigger_uuid = parse_noise_id(&id)?;
        let sites = match list_site_scope(&session) {
            ListSiteScope::Empty => {
                return Err((
                    StatusCode::NOT_FOUND,
                    Json(json!({"error": format!("Trigger not found: {}", id)})),
                ));
            }
            ListSiteScope::All => None,
            ListSiteScope::Sites(sites) => Some(sites),
        };
        // Engine has NO prior-status guard for resolve — unconditional UPDATE
        // mutating exactly: status, resolution, updated_at. Wrapped in a tx
        // so the audit row is written atomically; a 404 rolls back with no audit.
        let now = chrono::Utc::now();
        let mut tx = pool.begin().await.map_err(db_error)?;
        // Acquire before the UPDATE statement so its authorization snapshot is
        // necessarily newer than any registry generation change that held the
        // same lock.
        sqlx::query(
            "SELECT pg_advisory_xact_lock( \
                 hashtextextended('ryuki.noisy-trigger-site-authority', 0) \
             )",
        )
        .execute(&mut *tx)
        .await
        .map_err(db_error)?;
        let resolved: Option<NoisyTriggerRow> = match sites.as_deref() {
            None => sqlx::query_as(&format!(
                "UPDATE noisy_triggers \
                 SET status = 'Resolved', resolution = $1, updated_at = $2 \
                 WHERE id = $3 AND site IS NOT NULL \
                   AND site_resolution_generation = ( \
                       SELECT generation FROM noisy_trigger_site_authority WHERE singleton \
                   ) \
                 RETURNING {NOISE_COLUMNS}"
            ))
            .bind(&body.resolution)
            .bind(now)
            .bind(trigger_uuid)
            .fetch_optional(&mut *tx)
            .await
            .map_err(db_error)?,
            Some(sites) => sqlx::query_as(&format!(
                "UPDATE noisy_triggers \
                 SET status = 'Resolved', resolution = $1, updated_at = $2 \
                 WHERE id = $3 AND site = ANY($4) \
                   AND site_resolution_generation = ( \
                       SELECT generation FROM noisy_trigger_site_authority WHERE singleton \
                   ) \
                 RETURNING {NOISE_COLUMNS}"
            ))
            .bind(&body.resolution)
            .bind(now)
            .bind(trigger_uuid)
            .bind(sites)
            .fetch_optional(&mut *tx)
            .await
            .map_err(db_error)?,
        };
        if let Some(row) = resolved {
            audit::record_audit_tx(
                &mut tx,
                &session,
                &audit::security_audit(
                    "noise-resolve",
                    None,
                    "resolved",
                    json!({ "trigger_id": &id }),
                ),
            )
            .await
            .map_err(db_error)?;
            tx.commit().await.map_err(db_error)?;
            return Ok(Json(noise_row_to_json(&row)));
        }
        // 0 rows → trigger not found; roll back (no audit row written).
        return Err((
            StatusCode::NOT_FOUND,
            Json(json!({"error": format!("Trigger not found: {}", id)})),
        ));
    }
    // #2: the engine fallback has no site dimension; a scoped principal fails closed.
    if is_scoped(&session) {
        return Err((
            StatusCode::NOT_FOUND,
            Json(json!({"error": format!("Trigger not found: {}", id)})),
        ));
    }
    match noise_remediation::resolve_noise(&id, &body.resolution) {
        Ok(trigger) => Ok(Json(serde_json::to_value(trigger).unwrap_or_default())),
        Err(e) => Err((StatusCode::NOT_FOUND, Json(json!({"error": e})))),
    }
}

async fn noise_report(
    AuthExtractor(session): AuthExtractor,
    Query(q): Query<NoiseSiteQuery>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    // #2: narrow the site to the principal's scope (env-scoped -> 403; an
    // unrestricted caller with no ?site keeps the legacy DEFRA default).
    let requested_site = q
        .site
        .as_deref()
        .map(site_registry::normalize_site_code_for_lookup)
        .transpose()
        .map_err(|error| status_400(&error))?;
    let site = enforce_site_scope(&session, requested_site.as_deref(), "DEFRA")?;
    if let Some(pool) = get_db() {
        require_active_noise_site(pool, &site).await?;
        let counts: NoiseReportCounts = sqlx::query_as(noise_report_sql())
            .bind(&site)
            .fetch_one(pool)
            .await
            .map_err(db_error)?;
        return Ok(Json(json!({
            "site": site,
            "total_triggers": counts.total_triggers,
            "noisy": counts.noisy,
            "flapping": counts.flapping,
            "active": counts.active,
            "under_review": counts.under_review,
            "suppressed": counts.suppressed,
            "resolved": counts.resolved,
            "dry_run": true,
        })));
    }
    match noise_remediation::get_noise_report(&site) {
        Ok(report) => Ok(Json(report)),
        Err(e) => Err((StatusCode::BAD_REQUEST, Json(json!({"error": e})))),
    }
}

/// GET /api/monitoring/noise/suppressed — suppressed triggers paged after the
/// persisted canonical-site filter. Quarantined rows are omitted from both the
/// page and total, including for otherwise-unrestricted principals.
async fn noise_suppressed_list(
    AuthExtractor(session): AuthExtractor,
    Query(page): Query<AdminListPage>,
) -> Result<(HeaderMap, Json<Value>), (StatusCode, Json<Value>)> {
    // #14: bound the page (generous default keeps seed-scale callers unaffected).
    let limit = page.limit.unwrap_or(500).clamp(1, 1000);
    let offset = page.offset.unwrap_or(0).max(0);
    if let Some(pool) = get_db() {
        // #2: env-scoped principals see none (site-only resource), an empty
        // scope vec is unrestricted, and all-blank scope fails closed.
        let sites: Option<Vec<String>> = match list_site_scope(&session) {
            ListSiteScope::Empty => {
                return Ok((total_count_headers(0), Json(Value::Array(vec![]))));
            }
            ListSiteScope::All => None,
            ListSiteScope::Sites(s) => Some(s),
        };
        // #14: `updated_at` is non-unique → the unique PK `id` tie-breaker makes
        // each LIMIT/OFFSET page a stable cut.
        let (rows, total): (Vec<NoisyTriggerRow>, i64) = match sites.as_deref() {
            None => {
                let rows: Vec<NoisyTriggerRow> = sqlx::query_as(&format!(
                    "SELECT {NOISE_COLUMNS} FROM noisy_triggers \
                     WHERE status = 'Suppressed' AND site IS NOT NULL \
                       AND site_resolution_generation = ( \
                           SELECT generation FROM noisy_trigger_site_authority WHERE singleton \
                       ) \
                     ORDER BY updated_at DESC, id DESC LIMIT $1 OFFSET $2"
                ))
                .bind(limit)
                .bind(offset)
                .fetch_all(pool)
                .await
                .map_err(db_error)?;
                let total: i64 = sqlx::query_scalar(
                    "SELECT COUNT(*) FROM noisy_triggers \
                     WHERE status = 'Suppressed' AND site IS NOT NULL \
                       AND site_resolution_generation = ( \
                           SELECT generation FROM noisy_trigger_site_authority WHERE singleton \
                       )",
                )
                .fetch_one(pool)
                .await
                .map_err(db_error)?;
                (rows, total)
            }
            Some(sites) => {
                let rows: Vec<NoisyTriggerRow> = sqlx::query_as(&format!(
                    "SELECT {NOISE_COLUMNS} FROM noisy_triggers \
                     WHERE status = 'Suppressed' AND site = ANY($1) \
                       AND site_resolution_generation = ( \
                           SELECT generation FROM noisy_trigger_site_authority WHERE singleton \
                       ) \
                     ORDER BY updated_at DESC, id DESC LIMIT $2 OFFSET $3"
                ))
                .bind(sites)
                .bind(limit)
                .bind(offset)
                .fetch_all(pool)
                .await
                .map_err(db_error)?;
                let total: i64 = sqlx::query_scalar(
                    "SELECT COUNT(*) FROM noisy_triggers \
                     WHERE status = 'Suppressed' AND site = ANY($1) \
                       AND site_resolution_generation = ( \
                           SELECT generation FROM noisy_trigger_site_authority WHERE singleton \
                       )",
                )
                .bind(sites)
                .fetch_one(pool)
                .await
                .map_err(db_error)?;
                (rows, total)
            }
        };
        let arr: Vec<Value> = rows.iter().map(noise_row_to_json).collect();
        return Ok((total_count_headers(total), Json(Value::Array(arr))));
    }
    // #2: the engine fallback can't be site-filtered; a scoped principal sees none.
    if is_scoped(&session) {
        return Ok((total_count_headers(0), Json(Value::Array(vec![]))));
    }
    match noise_remediation::get_suppressed_triggers() {
        Ok(triggers) => {
            // #14: page the in-memory fallback the same way (total = pre-page count).
            let total = triggers.len() as i64;
            let page: Vec<_> = triggers
                .into_iter()
                .skip(offset as usize)
                .take(limit as usize)
                .collect();
            Ok((
                total_count_headers(total),
                Json(serde_json::to_value(page).unwrap_or_default()),
            ))
        }
        Err(e) => Err((StatusCode::INTERNAL_SERVER_ERROR, Json(json!({"error": e})))),
    }
}

