async fn cmdb_impact_analyze(
    Json(body): Json<serde_json::Value>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let change_description = body
        .get("changeDescription")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .to_string();
    let target_cis = cmdb_impact_targets(&body)
        .map_err(|err| (StatusCode::BAD_REQUEST, Json(json!({"error": err}))))?;

    match cmdb_impact::analyze_impact(&change_description, &target_cis) {
        Ok(analysis) => Ok(Json(serde_json::to_value(analysis).unwrap_or_default())),
        Err(err) => Err((StatusCode::BAD_REQUEST, Json(json!({"error": err})))),
    }
}

fn cmdb_impact_targets(body: &Value) -> Result<Vec<String>, String> {
    let Some(raw_targets) = body.get("targetCis") else {
        return Ok(Vec::new());
    };
    let targets = raw_targets
        .as_array()
        .ok_or_else(|| "targetCis must be an array of CI names".to_string())?;

    // Enforce the wire-level budget before filtering, allocating target names,
    // or entering the engine. Otherwise a large array of non-string values can
    // bypass the engine's raw-target cap by being silently discarded here.
    if targets.len() > cmdb_impact::MAX_IMPACT_TARGETS {
        return Err(format!(
            "At most {} target CIs are allowed for impact analysis",
            cmdb_impact::MAX_IMPACT_TARGETS
        ));
    }

    targets
        .iter()
        .enumerate()
        .map(|(index, target)| {
            target
                .as_str()
                .map(String::from)
                .ok_or_else(|| format!("targetCis[{index}] must be a CI name string"))
        })
        .collect()
}

#[cfg(test)]
mod cmdb_impact_admission_tests {
    use super::*;

    #[test]
    fn test_cmdb_impact_targets_rejects_raw_array_over_budget_before_filtering() {
        let body = json!({
            "targetCis": vec![Value::Null; cmdb_impact::MAX_IMPACT_TARGETS + 1]
        });

        let error = cmdb_impact_targets(&body)
            .expect_err("the raw JSON array must be capped before values are filtered");

        assert!(error.contains(&cmdb_impact::MAX_IMPACT_TARGETS.to_string()));
    }

    #[test]
    fn test_cmdb_impact_targets_rejects_non_string_entries_at_budget() {
        let body = json!({
            "targetCis": vec![Value::Null; cmdb_impact::MAX_IMPACT_TARGETS]
        });

        let error = cmdb_impact_targets(&body)
            .expect_err("non-string entries must not disappear before engine admission");

        assert_eq!(error, "targetCis[0] must be a CI name string");
    }

    #[test]
    fn test_cmdb_impact_targets_accepts_exact_wire_budget() {
        let body = json!({
            "targetCis": vec!["app-portal"; cmdb_impact::MAX_IMPACT_TARGETS]
        });

        let targets = cmdb_impact_targets(&body)
            .expect("the exact wire-level target budget must remain supported");

        assert_eq!(targets.len(), cmdb_impact::MAX_IMPACT_TARGETS);
    }
}

