#[cfg(test)]
mod human_evidence_actor_gate_unit_tests {
    use super::*;
    use ryuki_engine::auth::{ActorClass, APP_ROLE_PLATFORM_ADMIN};

    fn actor(actor_class: ActorClass, provider_mode: &str) -> AuthSession {
        let principal_id =
            PrincipalId::from_uuid(Uuid::new_v4()).expect("test UUID is a non-nil principal");
        AuthSession {
            display_user_id: "human-shaped-subject".into(),
            principal_id: Some(principal_id),
            display_name: "Human Shaped Subject".into(),
            roles: vec![APP_ROLE_PLATFORM_ADMIN.to_string()],
            token_valid: true,
            provider_mode: provider_mode.into(),
            actor_class,
            site_scope: vec![],
            environment_scope: vec![],
        }
    }

    fn error_status(result: &ApiResult) -> Option<StatusCode> {
        result.as_ref().err().map(|(status, _)| *status)
    }

    #[tokio::test]
    async fn human_shaped_nonhuman_actors_are_denied_before_evidence_io() {
        for actor_class in [
            ActorClass::Workload,
            ActorClass::Unknown,
            ActorClass::Simulated,
        ] {
            // Keep a browser-session-looking carrier and full admin role to
            // isolate the typed actor classification as the denial reason.
            let session = actor(actor_class, "persisted-session");

            let legal_hold = legal_hold_release(
                AuthExtractor(session.clone()),
                Path("missing-legal-hold".into()),
            )
            .await;
            assert_eq!(error_status(&legal_hold), Some(StatusCode::FORBIDDEN));

            let aiops = aiops_review(
                Path("missing-aiops-suggestion".into()),
                Extension(session.clone()),
            )
            .await;
            assert_eq!(error_status(&aiops), Some(StatusCode::FORBIDDEN));

            let snapshot = snapshot_review(
                AuthExtractor(session),
                Json(SnapshotActionRequest {
                    snapshot_id: "missing-snapshot".into(),
                }),
            )
            .await;
            assert_eq!(error_status(&snapshot), Some(StatusCode::FORBIDDEN));
        }
    }

    #[tokio::test]
    async fn verified_local_and_federated_humans_pass_the_sink_actor_gate() {
        for provider_mode in ["persisted-session", "entra-id"] {
            let session = actor(ActorClass::VerifiedHuman, provider_mode);

            let legal_hold = legal_hold_release(
                AuthExtractor(session.clone()),
                Path("missing-legal-hold".into()),
            )
            .await;
            assert_ne!(error_status(&legal_hold), Some(StatusCode::FORBIDDEN));

            let aiops = aiops_review(
                Path("missing-aiops-suggestion".into()),
                Extension(session.clone()),
            )
            .await;
            assert_ne!(error_status(&aiops), Some(StatusCode::FORBIDDEN));

            let snapshot = snapshot_review(
                AuthExtractor(session),
                Json(SnapshotActionRequest {
                    snapshot_id: "missing-snapshot".into(),
                }),
            )
            .await;
            assert_ne!(error_status(&snapshot), Some(StatusCode::FORBIDDEN));
        }
    }
}

