#[serde(deny_unknown_fields)]
struct BatchApprovalItem {
    id: String,
    request_resource_version: i64,
}

/// Body for a batch approve. Every item carries the exact version rendered to
/// the approver; a stale item fails independently without weakening the rest.
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct BatchApproveRequest {
    items: Vec<BatchApprovalItem>,
}

/// POST /api/requests/batch/approve — record THIS approver's sign-off on up to 100
/// requests in one call (#17, final slice). Each id goes through the SAME
/// `approve_one` quorum/SoD core as a single approve, so a batch CANNOT bypass the
/// multi-role quorum: a `required_approval_roles > 1` request gets this approver's
/// ONE decision and stays `Planned` (`quorum_met=false`) until N distinct roles +
/// approvers approve. Items are independent; partial success is normal; HTTP 200
/// always (clients MUST inspect each result's `ok`/`quorum_met`). Duplicate ids are
/// deduped.
///
/// `approve` is a FLAT capability, checked ONCE up front: a caller lacking it gets a
/// single 403 for the WHOLE batch, audited EXACTLY ONCE with the non-id "batch"
/// sentinel. `check_sod` (approver != creator) stays the PER-ITEM gate inside
/// `approve_one`, so approving a request you created fails only that id.
async fn requests_batch_approve(
    AuthExtractor(session): AuthExtractor,
    Json(b): Json<BatchApproveRequest>,
) -> ApiResult {
    if !check_permission(&session, "approve") {
        record_transition_denied(&session, "batch", "request.approve").await;
        return Err(status_403());
    }
    let Some(role) = approval_role_for(&session) else {
        record_transition_denied(&session, "batch", "request.approve").await;
        return Err(ordinary_approval_role_required());
    };
    if b.items.is_empty() {
        return Err(status_400("items cannot be empty"));
    }
    if b.items.len() > 100 {
        return Err(status_400("a batch may contain at most 100 ids"));
    }
    // Dedupe (preserving order) so the same request is never processed twice. Dedup
    // on the CANONICAL UUID, not the raw string: UUIDs are case-insensitive and
    // multi-form, so two spellings of one id must collapse to a single decision (a
    // re-record would idempotent-short-circuit anyway, but it must not double-count
    // the result). Non-UUID ids keep their raw text (approve_one 404s them).
    let mut seen = std::collections::HashSet::new();
    let unique_items: Vec<&BatchApprovalItem> = b
        .items
        .iter()
        .filter(|item| {
            let key = Uuid::parse_str(&item.id)
                .map(|u| u.to_string())
                .unwrap_or_else(|_| item.id.clone());
            seen.insert(key)
        })
        .collect();

    let mut results: Vec<Value> = Vec::with_capacity(unique_items.len());
    let mut succeeded = 0u64;
    let mut failed = 0u64;
    let mut approved = 0u64;
    for item in unique_items {
        let id = &item.id;
        if item.request_resource_version <= 0 {
            failed += 1;
            results.push(json!({
                "id": id,
                "ok": false,
                "status": StatusCode::BAD_REQUEST.as_u16(),
                "error": {"error": "request_resource_version must be positive"},
            }));
            continue;
        }
        match approve_one(&session, id, &role, item.request_resource_version).await {
            Ok(json) => {
                succeeded += 1;
                // approve_one returns the flattened request JSON (top-level fields +
                // a `quorum` sibling), so `status` is the lifecycle status and
                // `quorum.quorum_met` is the breadth verdict.
                let quorum_met = json
                    .get("quorum")
                    .and_then(|q| q.get("quorum_met"))
                    .and_then(|m| m.as_bool())
                    .unwrap_or(false);
                if quorum_met {
                    approved += 1;
                }
                results.push(json!({
                    "id": id,
                    "ok": true,
                    "request_status": json.get("status").cloned().unwrap_or(Value::Null),
                    "quorum_met": quorum_met,
                }));
            }
            Err((status, body)) => {
                failed += 1;
                results.push(json!({
                    "id": id,
                    "ok": false,
                    "status": status.as_u16(),
                    "error": body.0,
                }));
            }
        }
    }
    Ok(Json(json!({
        "results": results,
        "succeeded": succeeded,
        "failed": failed,
        "approved": approved,
    })))
}

/// SoD gate for cancel: an admin may cancel any request; a requester may cancel
/// only their own (session principal == the request's creator).
fn cancel_permitted(session: &AuthSession, created_by: Option<&str>) -> bool {
    let created_by_principal = created_by.and_then(|value| value.parse::<PrincipalId>().ok());
    check_permission(session, "admin")
        || (check_permission(session, "request")
            && created_by_principal.is_some()
            && created_by_principal == session.principal_id)
}

/// Separation-of-duties outcome for an approve/reject decision (see
/// [`sod_decision`]).
#[derive(Debug, PartialEq, Eq)]
enum SodDecision {
    /// The approver differs from the creator — proceed.
    Allow,
    /// Self-approval, but in a dry-run mode (every caller is the shared
    /// `static-user` principal, so the rule is not meaningful) — allow, but log.
    Warn,
    /// Self-approval under live identity — block (403) and audit.
    Block,
}

/// Separation of duties: a request's creator must not also be its approver. The
/// hard `Block` applies only under live identity (`EntraId`/`Local`); in the
/// dry-run modes every caller shares the `static-user` principal, so a self-match
/// is not a real SoD violation and yields `Warn`. Pure — the mode is passed in.
fn sod_decision(session: &AuthSession, created_by: Option<&str>, mode: &AuthMode) -> SodDecision {
    let created_by_principal = created_by.and_then(|value| value.parse::<PrincipalId>().ok());
    if created_by_principal.is_none() || created_by_principal != session.principal_id {
        return SodDecision::Allow;
    }
    match mode {
        AuthMode::EntraId | AuthMode::Local => SodDecision::Block,
        AuthMode::MockDryRun | AuthMode::StaticDryRun => SodDecision::Warn,
    }
}

/// Enforce separation of duties on an approve/reject. Returns `Err(403)` (and
/// audits the denial as `outcome: "denied"`) when the principal is acting on
/// their OWN request under live identity; logs a warning and allows in dry-run;
/// allows otherwise. `created_by` is the request's creator (the DB `created_by`
/// column, or the in-memory `requester`). Called BEFORE the lifecycle mutation.
async fn check_sod(
    session: &AuthSession,
    request_id: &str,
    action: &'static str,
    created_by: Option<&str>,
) -> Result<(), (StatusCode, Json<serde_json::Value>)> {
    match sod_decision(
        session,
        created_by,
        &crate::config_store::auth_mode_or_default(),
    ) {
        SodDecision::Allow => Ok(()),
        SodDecision::Warn => {
            tracing::warn!(
                actor = %session.display_user_id,
                request = %request_id,
                action,
                "SoD: self-approval permitted in dry-run mode; would be denied under live identity"
            );
            Ok(())
        }
        SodDecision::Block => {
            audit::record_denied(
                get_db(),
                session,
                &AuditRecord {
                    action,
                    request_id: Some(request_id),
                    from_status: None,
                    to_status: "unknown",
                    from_stage: None,
                    to_stage: "unknown",
                    detail: json!({
                        "note": "separation of duties: a requester may not approve or reject \
                                 their own request; cancel it instead to withdraw"
                    }),
                    outcome: "denied",
                },
            )
            .await;
            Err((
                StatusCode::FORBIDDEN,
                Json(json!({
                    "error": "separation of duties: you may not approve or reject your own request"
                })),
            ))
        }
    }
}

/// GET /api/requests/{id}/audit — the ordered, actor-attributed audit trail for
/// one request. DB-backed entries are tagged `durable: true`; the no-DB
/// (dry-run) store is tagged `durable: false`. No secrets are ever written to
/// the trail, so this read is safe to expose.
async fn requests_audit(
    AuthExtractor(session): AuthExtractor,
    Path(request_id): Path<String>,
) -> ApiResult {
    // The audit trail is sensitive identity data — who acted, when, and why,
    // more sensitive than a request body. Gate it on audit-tier access ahead of
    // the general read-authentication wave. Static/mock sessions carry
    // PlatformAdmin (audit via the admin superuser), so the demo is unaffected.
    if !check_permission(&session, "audit") {
        return Err((
            StatusCode::FORBIDDEN,
            Json(json!({"error": "Audit-tier access is required to read the request audit trail"})),
        ));
    }
    // #2: serve the REAL trail ONLY when the request is proven in-scope. A
    // not-found request AND an out-of-scope request fail CLOSED to the SAME empty
    // (unknown-shaped) trail — so the audit endpoint is never a cross-scope
    // existence oracle. A transient scope-lookup DB error, by contrast, returns
    // 5xx (not a false-empty trail): a 5xx is request-independent, so it leaks
    // nothing about existence/scope, and — like the trail read itself — a
    // compliance audit read must never report a DB failure as "no records".
    match request_site_env(&request_id).await {
        Ok(Some((site, environment))) if row_scope_permits(&session, &site, &environment) => {
            Ok(Json(
                audit::audit_trail_for_request(get_db(), &request_id)
                    .await
                    .map_err(db_error)?,
            ))
        }
        Err(e) => Err(db_error(e)),
        Ok(_) => Ok(Json(audit::empty_request_trail(get_db(), &request_id))),
    }
}

// ─── Per-user scope preferences (#59 backend) ───

/// Body for PUT /api/me/preferences. A full replace: an absent or null field
/// clears that preference. `deny_unknown_fields` rejects typos.
#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct UserPreferencesRequest {
    preferred_site: Option<String>,
    preferred_environment: Option<String>,
}

/// Normalise a scope-preference value: reject control characters in the RAW
/// input, then trim, treat empty as "no preference" (None), bound to 64 chars.
fn normalize_scope_value(v: Option<String>) -> Result<Option<String>, (StatusCode, Json<Value>)> {
    match v {
        None => Ok(None),
        Some(s) => {
            // Reject ANY control character in the RAW input (BEFORE trimming), so
            // a stray newline/tab is rejected, not silently swallowed by trim().
            if s.chars().any(|c| c.is_control()) {
                return Err(status_400(
                    "scope value must not contain control characters",
                ));
            }
            let t = s.trim();
            if t.is_empty() {
                return Ok(None);
            }
            if t.chars().count() > 64 {
                return Err(status_400("scope value must be at most 64 characters"));
            }
            Ok(Some(t.to_string()))
        }
    }
}

/// Reject control characters (CR/LF/NUL/escape/etc.) in a free-text field (#40).
/// These values are persisted and later echoed back in JSON and logs, so an
/// embedded CR/LF could forge a log line or inject a response header, and a
/// terminal escape could corrupt an operator's console. A finite, short reason/
/// justification has no legitimate need for control characters — reject the RAW
/// value (before any trim) with a 400, mirroring `normalize_scope_value` and the
/// on-call-contact field validation.
fn reject_control_chars(field: &str, value: &str) -> Result<(), (StatusCode, Json<Value>)> {
    if value.chars().any(char::is_control) {
        return Err(status_400(&format!(
            "{field} must not contain control characters"
        )));
    }
    Ok(())
}

/// GET /api/me/preferences — the CURRENT user's scope preferences (#59).
/// Keyed on the verified opaque session principal; returns nulls when none are set.
/// Self-service (any authenticated user); empty + `durable:false` with no DB.
async fn user_preferences_get(AuthExtractor(session): AuthExtractor) -> ApiResult {
    let Some(pool) = get_db() else {
        return Ok(Json(json!({
            "preferred_site": null,
            "preferred_environment": null,
            "durable": false,
        })));
    };
    let principal = authenticated_principal_id(&session)?.to_string();
    let row: Option<(Option<String>, Option<String>)> = sqlx::query_as(
        "SELECT preferred_site, preferred_environment FROM user_preferences WHERE user_id = $1",
    )
    .bind(&principal)
    .fetch_optional(pool)
    .await
    .map_err(db_error)?;
    let (site, env) = row.unwrap_or((None, None));
    Ok(Json(json!({
        "preferred_site": site,
        "preferred_environment": env,
        "durable": true,
    })))
}

/// PUT /api/me/preferences — set the CURRENT user's scope preferences (#59).
/// Full replace (absent/null/empty clears a field). Keyed on the verified
/// opaque session principal — a client cannot write another user's preferences.
/// Self-service; 503 with no DB.
async fn user_preferences_put(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<UserPreferencesRequest>,
) -> ApiResult {
    let site = normalize_scope_value(body.preferred_site)?;
    let env = normalize_scope_value(body.preferred_environment)?;

    let Some(pool) = get_db() else {
        return Err((
            StatusCode::SERVICE_UNAVAILABLE,
            Json(json!({"error": "database not configured; cannot persist preferences"})),
        ));
    };
    let principal = authenticated_principal_id(&session)?.to_string();
    // #15: scope preferences (preferred_site/environment) gate which infrastructure
    // a principal sees — a security-relevant mutation. Persist + audit atomically so
    // a change leaves a durable trail. The detail carries only the new scope values
    // (non-secret identifiers), never credentials.
    let mut tx = pool.begin().await.map_err(db_error)?;
    sqlx::query(
        "INSERT INTO user_preferences \
         (user_id, preferred_site, preferred_environment, updated_at) \
         VALUES ($1, $2, $3, NOW()) \
         ON CONFLICT (user_id) DO UPDATE SET \
           preferred_site = EXCLUDED.preferred_site, \
           preferred_environment = EXCLUDED.preferred_environment, \
           updated_at = NOW()",
    )
    .bind(&principal)
    .bind(&site)
    .bind(&env)
    .execute(&mut *tx)
    .await
    .map_err(db_error)?;
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "user.preferences.update",
            None,
            "updated",
            json!({
                "subject_principal_id": &principal,
                "preferred_site": &site,
                "preferred_environment": &env,
            }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;

    Ok(Json(json!({
        "preferred_site": site,
        "preferred_environment": env,
        "durable": true,
    })))
}

/// Query for GET /api/requests/{id}/approval-quorum.
#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct ApprovalQuorumQuery {
    required_roles: Option<usize>,
    required_approvers: Option<usize>,
}

/// GET /api/requests/{id}/approval-quorum — multi-role approval quorum status for
/// one request (#4). Reads the recorded `request_approval_decisions` and reports
/// whether they meet a breadth quorum: distinct approving ROLES and distinct
/// APPROVERS (default 2/2, bounded 1..=10), with any rejection blocking it.
/// Audit-tier (approval identities, like the audit trail). 404 unknown request.
/// READ-ONLY: reports the same current-epoch quorum enforced by the approval
/// flow. Empty + `durable:false` with no DB.
async fn requests_approval_quorum(
    AuthExtractor(session): AuthExtractor,
    Path(request_id): Path<String>,
    Query(q): Query<ApprovalQuorumQuery>,
) -> ApiResult {
    use ryuki_engine::approval_quorum::{evaluate_quorum, ApprovalDecision};

    if !check_permission(&session, "audit") {
        return Err((
            StatusCode::FORBIDDEN,
            Json(json!({"error": "Audit-tier access is required to read approval quorum"})),
        ));
    }
    // Validate any EXPLICIT query overrides up front; the per-request DEFAULT
    // (codex fix #6) is resolved below from the row's required_approval_roles so
    // the REPORTED quorum matches the ENFORCED quorum.
    if let Some(rr) = q.required_roles {
        if !(1..=10).contains(&rr) {
            return Err(status_400("required_roles must be between 1 and 10"));
        }
    }
    if let Some(ra) = q.required_approvers {
        if !(1..=10).contains(&ra) {
            return Err(status_400("required_approvers must be between 1 and 10"));
        }
    }

    // Same shape both paths so clients never special-case no-DB.
    let render = |status: &ryuki_engine::approval_quorum::QuorumStatus, durable: bool| -> Value {
        let mut body = serde_json::to_value(status).unwrap_or_else(|_| json!({}));
        body["durable"] = json!(durable);
        body
    };

    // Validate the id format UP FRONT so a malformed request_id is a 404 in BOTH
    // the DB and no-DB paths (consistent contract regardless of DB availability).
    let uid = Uuid::parse_str(&request_id).map_err(|_| status_404(&request_id))?;

    let Some(pool) = get_db() else {
        // No-DB / dry-run: no row to read required_approval_roles from, so the
        // per-request default (codex fix #6) is DB-only — keep the historical
        // 2/2 default here when not overridden (the no-DB approve arm is
        // single-approval regardless; this read is purely informational).
        let required_roles = q.required_roles.unwrap_or(2);
        let required_approvers = q.required_approvers.unwrap_or(2);
        let status = evaluate_quorum(&[], required_roles, required_approvers);
        let mut body = render(&status, false);
        body["approval_epoch"] = Value::Null;
        return Ok(Json(body));
    };

    // 404 an unknown request so "no approvals yet" is distinguishable from "no
    // such request". The same SELECT yields site/environment for the scope guard
    // and required_approval_roles for the default thresholds.
    let exists: Option<(String, String, i32, i64, i64)> = sqlx::query_as(
        "SELECT site, environment, required_approval_roles, approval_epoch, resource_version \
         FROM requests WHERE id = $1",
    )
    .bind(uid)
    .fetch_optional(pool)
    .await
    .map_err(db_error)?;
    let Some((site, environment, required_approval_roles, approval_epoch, resource_version)) =
        exists
    else {
        return Err(status_404(&request_id));
    };
    // #2: an out-of-scope request's quorum is a 404 (same as unknown — no oracle).
    scope_guard_or_404(&session, &site, &environment, &request_id)?;

    // codex fix #6: default BOTH thresholds to the request's required_approval_roles
    // so the reported quorum matches what apply_approval_decision_audited enforces.
    let req = required_approval_roles.max(1) as usize;
    let required_roles = q.required_roles.unwrap_or(req);
    let required_approvers = q.required_approvers.unwrap_or(req);

    let rows: Vec<(String, String, String)> = sqlx::query_as(
        "SELECT d.role, d.decision, d.actor_principal_id::text AS actor \
         FROM request_approval_decisions d \
         JOIN principals p \
           ON p.principal_id = d.actor_principal_id \
          AND p.lifecycle_version = d.actor_principal_lifecycle_version \
          AND p.authority_version = d.actor_principal_authority_version \
          AND p.lifecycle_state = 'active' \
          AND p.principal_kind = 'human' \
          AND d.role = ANY(p.role_allowlist) \
         WHERE d.request_id = $1 AND d.approval_epoch = $2 \
           AND d.approval_basis_resource_version = $3 \
           AND d.principal_binding_state = 'exact-v1' \
         ORDER BY d.decided_at, d.id",
    )
    .bind(uid)
    .bind(approval_epoch)
    .bind(resource_version)
    .fetch_all(pool)
    .await
    .map_err(db_error)?;
    let decisions: Vec<ApprovalDecision> = rows
        .into_iter()
        .map(|(role, decision, actor)| ApprovalDecision {
            role,
            decision,
            actor,
        })
        .collect();

    let status = evaluate_quorum(&decisions, required_roles, required_approvers);
    let mut body = render(&status, true);
    body["approval_epoch"] = json!(approval_epoch);
    Ok(Json(body))
}

/// GET /api/requests/{id}/approval-decisions — the individual approval-decision
/// LEDGER for one request: every recorded `request_approval_decisions` row
/// (approval_epoch, current, role, decision, actor, decided_at, reason), including
/// historical cycles that no longer satisfy quorum. The companion to
/// `requests_approval_quorum`: quorum = the verdict, this = the records behind it.
///
/// Audit-tier — same identity-grade sensitivity as the quorum endpoint and the audit
/// trail. NOT approve-tier: every approve-holding role (DatacenterApprover,
/// PlatformAdmin) ALSO holds `audit`, and gating on `approve` would wrongly exclude
/// the audit-only `Auditor` from an audit ledger. `actor` is already exposed by the
/// quorum endpoint's approvers list; `reason` is the approver's free-text reject
/// justification — treat it as AUDIT-VISIBLE free text (any secret/PII redaction is a
/// write-side concern, out of scope for this read). 404 for an unknown OR out-of-scope
/// request (no oracle). Empty ledger + `durable:false` with no DB (the dry-run approve
/// arm writes no ledger), distinct from a durable-but-empty `{decisions:[],durable:true}`.
async fn requests_approval_decisions(
    AuthExtractor(session): AuthExtractor,
    Path(request_id): Path<String>,
) -> ApiResult {
    if !check_permission(&session, "audit") {
        return Err((
            StatusCode::FORBIDDEN,
            Json(json!({"error": "Audit-tier access is required to read approval decisions"})),
        ));
    }

    // Validate the id format UP FRONT so a malformed request_id is a 404 in BOTH the
    // DB and no-DB paths (consistent with the quorum endpoint).
    let uid = Uuid::parse_str(&request_id).map_err(|_| status_404(&request_id))?;

    let Some(pool) = get_db() else {
        // No-DB / dry-run: the dry-run approve arm keeps no decision ledger, so the
        // ledger is empty and non-durable. Shape parity with the quorum endpoint.
        return Ok(Json(json!({
            "decisions": [],
            "current_approval_epoch": Value::Null,
            "durable": false
        })));
    };

    // 404 an unknown request so "no decisions yet" is distinguishable from "no such
    // request"; the same SELECT yields site/environment for the scope guard.
    let exists: Option<(String, String, i64)> =
        sqlx::query_as("SELECT site, environment, approval_epoch FROM requests WHERE id = $1")
            .bind(uid)
            .fetch_optional(pool)
            .await
            .map_err(db_error)?;
    let Some((site, environment, current_approval_epoch)) = exists else {
        return Err(status_404(&request_id));
    };
    // #2: an out-of-scope request's ledger is a 404 (same as unknown — no oracle).
    scope_guard_or_404(&session, &site, &environment, &request_id)?;

    // The full historical ledger in stable epoch/time/id order. decided_at alone
    // is NOT deterministic — Postgres now() is transaction-scoped, so decisions
    // recorded in one tx can share a timestamp; BIGSERIAL id is the tie-breaker.
    #[derive(sqlx::FromRow)]
    struct DecisionRow {
        approval_epoch: i64,
        role: String,
        decision: String,
        actor: String,
        decided_at: chrono::DateTime<chrono::Utc>,
        reason: Option<String>,
    }
    let rows: Vec<DecisionRow> = sqlx::query_as(
        "SELECT approval_epoch, role, decision, actor_principal_id::text AS actor, \
                decided_at, reason \
         FROM request_approval_decisions \
         WHERE request_id = $1 AND principal_binding_state = 'exact-v1' \
         ORDER BY approval_epoch ASC, decided_at ASC, id ASC",
    )
    .bind(uid)
    .fetch_all(pool)
    .await
    .map_err(db_error)?;

    let decisions: Vec<Value> = rows
        .into_iter()
        .map(|r| {
            json!({
                "approval_epoch": r.approval_epoch,
                "current": r.approval_epoch == current_approval_epoch,
                "role": r.role,
                "decision": r.decision,
                "actor": r.actor,
                "decided_at": r.decided_at.to_rfc3339(),
                "reason": r.reason,
            })
        })
        .collect();

    Ok(Json(json!({
        "decisions": decisions,
        "current_approval_epoch": current_approval_epoch,
        "durable": true
    })))
}

/// GET /api/requests/{id}/evidence — a tamper-evident compliance evidence pack
/// for ONE persisted request: the redacted evidence pack (from the pure engine
/// pipeline, built off the REAL persisted request state) plus the durable,
/// actor-attributed audit trail, sealed with a SHA-256 digest over the stable
/// `content`. The digest deliberately excludes `generated_at`, so re-exporting
/// an unchanged request yields the SAME digest (tamper-evidence). Gated on the
/// `audit` tier — the same identity-grade sensitivity as the audit trail.
async fn request_evidence_pack(
    AuthExtractor(session): AuthExtractor,
    Path(request_id): Path<String>,
) -> ApiResult {
    if !check_permission(&session, "audit") {
        return Err((
            StatusCode::FORBIDDEN,
            Json(json!({
                "error": "Audit-tier access is required to export a request evidence pack"
            })),
        ));
    }

    // Load the REAL persisted request (DB authoritative; in-memory store in
    // no-DB / dry-run mode), mirroring requests_get.
    let request = if let Some(pool) = get_db() {
        let uid = Uuid::parse_str(&request_id).map_err(|_| status_404(&request_id))?;
        let row: DbRequestRow = sqlx::query_as(&format!(
            "SELECT {REQUEST_COLUMNS} FROM requests WHERE id = $1"
        ))
        .bind(uid)
        .fetch_optional(pool)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&request_id))?;
        db_row_to_request(&row, &request_id)
    } else {
        let store = request_store().lock().await;
        store
            .iter()
            .find(|r| r.id == request_id)
            .cloned()
            .ok_or_else(|| status_404(&request_id))?
    };
    // #2: a scoped principal may only export an in-scope request's evidence pack
    // — an out-of-scope request is a 404 (indistinguishable from a missing one).
    scope_guard_or_404(&session, &request.site, &request.environment, &request_id)?;

    // Redacted evidence pack from the pure engine pipeline (sensitive keys are
    // redacted by collect_evidence before it returns).
    let pack = evidence_pipeline::collect_evidence(&request)
        .map_err(|e| (StatusCode::BAD_REQUEST, Json(json!({"error": e}))))?;
    let mut pack_value = serde_json::to_value(&pack).map_err(|e| {
        (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(json!({"error": e.to_string()})),
        )
    })?;
    // The pack's own `id` (random uuid) and `created_at` (export instant) are
    // freshly generated on every call. Exclude them from the SEALED content so
    // the digest is reproducible for an unchanged request — the seal covers the
    // substantive evidence (items, request, audit trail), not the export moment
    // (which is reported separately as `generated_at`).
    if let Some(object) = pack_value.as_object_mut() {
        object.remove("id");
        object.remove("created_at");
    }

    // Durable, actor-attributed audit trail for the request.
    let trail = audit::audit_trail_for_request(get_db(), &request_id)
        .await
        .map_err(db_error)?;
    let durable = trail
        .get("durable")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let audit_entries = trail.get("entries").cloned().unwrap_or_else(|| json!([]));

    // The digested content. Field order is fixed here, so serialization (and the
    // digest) is deterministic and reproducible for an unchanged request.
    let content = json!({
        "request_id": request.id,
        "pack": pack_value,
        "audit_trail": audit_entries,
    });
    let canonical = serde_json::to_vec(&content).map_err(|e| {
        (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(json!({"error": e.to_string()})),
        )
    })?;
    let mut hasher = Sha256::new();
    hasher.update(&canonical);
    let digest = format!("sha256:{:x}", hasher.finalize());

    Ok(Json(json!({
        "request_id": request.id,
        "generated_at": chrono::Utc::now().to_rfc3339(),
        "algorithm": "sha256",
        "digest": digest,
        "durable": durable,
        "item_count": pack.items.len(),
        "redacted": pack.redacted,
        "content": content,
    })))
}

/// GET /api/activity/audit — the global-only, newest-first, actor-attributed
/// audit feed across all requests. Same audit-tier gate as the per-request
/// trail: who-acted-when is sensitive identity data. Principals carrying any
/// site or environment scope are refused because the global feed cannot enforce
/// that narrower authority; they must use the scoped per-request audit path.
async fn activity_audit_feed(
    AuthExtractor(session): AuthExtractor,
    Query(params): Query<PaginationParams>,
) -> ApiResult {
    if !check_permission(&session, "audit") {
        return Err((
            StatusCode::FORBIDDEN,
            Json(json!({"error": "Audit-tier access is required to read the activity audit feed"})),
        ));
    }
    if !session.site_scope.is_empty() || !session.environment_scope.is_empty() {
        return Err((
            StatusCode::FORBIDDEN,
            Json(json!({
                "error": "Global audit-feed access requires an explicit global scope"
            })),
        ));
    }
    let limit = params.limit.unwrap_or(50).clamp(1, 200) as i64;
    let offset = clamp_offset_usize(params.offset.unwrap_or(0)) as i64;
    Ok(Json(
        audit::audit_feed(get_db(), limit, offset)
            .await
            .map_err(db_error)?,
    ))
}

/// Query params for the operational event feed (#11).
#[derive(Debug, Deserialize, Default)]
struct EventsQuery {
    /// Filter to one dotted event type, e.g. `request.approve`.
    event_type: Option<String>,
    /// Filter to one aggregate's history (e.g. a request id).
    aggregate_id: Option<String>,
    /// Page size (default 50, capped 500).
    limit: Option<i64>,
}

/// GET /api/events — the operational domain-event feed (#11). Newest first, with
/// optional `event_type` / `aggregate_id` filters. Distinct from the audit feed:
/// this is the operational stream other subsystems consume (alert generation,
/// dashboards). Request-tier read, site/environment-scoped (#2): a scoped
/// principal sees only its own scope's events plus events that are platform-wide
/// (NULL) on BOTH axes. The cross-scope rule is SYMMETRIC: a SITE-ONLY event
/// (concrete site, NULL environment — e.g. a decommission) is NOT visible to an
/// environment-scoped principal, and an ENV-ONLY event (NULL site, concrete
/// environment) is NOT visible to a site-scoped one — in each case the mutating
/// handlers fail closed for that principal, so the feed must not be more
/// permissive. Empty + `durable:false` when no DB is configured.
async fn events_list(
    AuthExtractor(session): AuthExtractor,
    Query(q): Query<EventsQuery>,
) -> ApiResult {
    if !check_permission(&session, "request") {
        return Err((
            StatusCode::FORBIDDEN,
            Json(json!({"error": "authentication is required to read events"})),
        ));
    }
    let Some(pool) = get_db() else {
        return Ok(Json(json!({"events": [], "durable": false})));
    };
    let limit = q.limit.unwrap_or(50).clamp(1, 500);
    let event_type = q
        .event_type
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty());
    let aggregate_id = q
        .aggregate_id
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty());
    // #2: scope is pushed INTO the query (not filtered here after the LIMIT) so a
    // scoped principal's page is never short-counted by out-of-scope rows. A
    // scoped principal sees only in-scope events plus platform-wide (NULL-scope)
    // ones; an unrestricted principal sees all.
    let rows = crate::repos::domain_events::list(
        pool,
        event_type,
        aggregate_id,
        &session.site_scope,
        &session.environment_scope,
        limit,
    )
    .await
    .map_err(db_error)?;
    let events: Vec<Value> = rows
        .iter()
        .map(|r| {
            json!({
                "id": r.id,
                "event_type": r.event_type,
                "aggregate_type": r.aggregate_type,
                "aggregate_id": r.aggregate_id,
                "site": r.site,
                "environment": r.environment,
                "actor": r.actor,
                "payload": r.payload,
                "occurred_at": r.occurred_at.to_rfc3339(),
            })
        })
        .collect();
    Ok(Json(json!({"events": events, "durable": true})))
}

/// GET /api/events/alerts — the alert-worthy slice of the domain-event stream
/// (#11 slice 2a). Reuses the scoped feed but keeps only events the pure
/// `event_alerts` classifier flags — currently a request reaching a NEGATIVE
/// terminal state: `failed`=critical, `rejected`=warning, `cancelled`=info —
/// annotating each with its severity. The status filter is pushed into SQL (via
/// the engine's authoritative status list) so the page is not short-counted when
/// alerts are rare. The dedicated monitoring-alert read capability is checked
/// before database access; site/environment scope is then applied in SQL.
/// Empty + `durable:false` no DB.
async fn events_alerts(
    AuthExtractor(session): AuthExtractor,
    Query(q): Query<EventsQuery>,
) -> ApiResult {
    operation_capability_guard(&session, OperationCapability::MonitoringAlertRead)?;
    let Some(pool) = get_db() else {
        return Ok(Json(json!({"alerts": [], "durable": false})));
    };
    let limit = q.limit.unwrap_or(50).clamp(1, 500);
    let aggregate_id = q
        .aggregate_id
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty());
    // The alert status set comes from the engine — same source as the severity
    // label below — so the SQL filter and the classification can never drift.
    let statuses: Vec<String> = ryuki_engine::event_alerts::alert_worthy_statuses()
        .iter()
        .map(|s| s.to_string())
        .collect();
    let rows = crate::repos::domain_events::list_alerts(
        pool,
        aggregate_id,
        &statuses,
        &session.site_scope,
        &session.environment_scope,
        limit,
    )
    .await
    .map_err(db_error)?;
    // Keep only rows the precise per-aggregate classifier flags as alerts.
    let classified: Vec<(&crate::repos::domain_events::EventRow, &'static str)> = rows
        .iter()
        .filter_map(|r| {
            let to_status = r.payload.get("to_status").and_then(|v| v.as_str());
            ryuki_engine::event_alerts::classify(&r.aggregate_type, to_status)
                .map(|sev| (r, sev.as_str()))
        })
        .collect();
    // #11 slice 2e: merge in acknowledgement state for these alerts (one batched
    // lookup) so the feed shows which alerts have been seen, by whom, and when.
    let ids: Vec<i64> = classified.iter().map(|(r, _)| r.id).collect();
    let acks = crate::repos::domain_events::acks_for(pool, &ids)
        .await
        .map_err(db_error)?;
    let ack_by_id: std::collections::HashMap<i64, &crate::repos::domain_events::AckRow> =
        acks.iter().map(|a| (a.event_id, a)).collect();
    let alerts: Vec<Value> = classified
        .iter()
        .map(|(r, severity)| {
            let ack = ack_by_id.get(&r.id);
            json!({
                "id": r.id,
                "event_type": r.event_type,
                "aggregate_type": r.aggregate_type,
                "aggregate_id": r.aggregate_id,
                "site": r.site,
                "environment": r.environment,
                "actor": r.actor,
                "severity": severity,
                "payload": r.payload,
                "occurred_at": r.occurred_at.to_rfc3339(),
                "acknowledged": ack.is_some(),
                "acknowledged_by": ack.map(|a| a.acknowledged_by.clone()),
                "acknowledged_at": ack.map(|a| a.acknowledged_at.to_rfc3339()),
            })
        })
        .collect();
    Ok(Json(json!({"alerts": alerts, "durable": true})))
}

/// Body for acknowledging an alert (#11 slice 2e). The note is optional context.
#[derive(Debug, Deserialize, Default)]
#[serde(deny_unknown_fields)]
struct AlertAckBody {
    #[serde(default)]
    note: Option<String>,
}

/// POST /api/events/alerts/{event_id}/ack — acknowledge an alert (#11 slice 2e).
/// Marks the alert (a domain_events row) as seen by the acting principal; the
/// feed then shows `acknowledged` + who/when. Re-acking updates in place.
/// Requires the dedicated monitoring-alert acknowledgement capability. 404
/// when the event id is unknown, 400 on a control-character note, 503 with no
/// DB.
async fn events_alert_ack(
    AuthExtractor(session): AuthExtractor,
    Path(event_id): Path<i64>,
    Json(body): Json<AlertAckBody>,
) -> ApiResult {
    operation_capability_guard(&session, OperationCapability::MonitoringAlertAcknowledge)?;
    let note = body
        .note
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty());
    if let Some(n) = note {
        reject_control_chars("note", n)?;
    }
    let pool = get_db().ok_or_else(status_503_no_db)?;
    ack_alert_one(&session, pool, event_id, note).await?;
    let actor_principal = authenticated_principal_id(&session)?.to_string();
    Ok(Json(
        json!({"acknowledged": true, "event_id": event_id, "acknowledged_by": actor_principal}),
    ))
}

/// Acknowledge ONE alert: the shared single + batch core. Enforces the SAME visibility
/// model the alert feed uses (domain_events::list_alerts) inside the repository's
/// INSERT .. SELECT/UPSERT statement, so authorization cannot race the mutation.
/// Request-linked agent-job alerts derive scope from the authoritative request row,
/// not nullable event axes or payload JSON. Anything denied 404s like a missing id.
/// Extracted so the single + batch ack handlers share ONE scope/ack core (the batch loops
/// this), exactly as `approve_one`/`reject_one` back the request batches. The
/// shared core repeats the dedicated capability check so a future direct caller
/// cannot bypass the two public handler guards.
async fn ack_alert_one(
    session: &AuthSession,
    pool: &sqlx::PgPool,
    event_id: i64,
    note: Option<&str>,
) -> Result<(), (StatusCode, Json<Value>)> {
    operation_capability_guard(session, OperationCapability::MonitoringAlertAcknowledge)?;
    let actor_principal = authenticated_principal_id(session)?.to_string();
    // Only an alert-worthy, authorized event is ackable. The repository applies
    // both predicates in the mutating statement; false covers missing, non-alert,
    // orphaned request links, and out-of-scope rows without an existence oracle.
    let (alert_aggregate_types, alert_statuses): (Vec<String>, Vec<String>) =
        ryuki_engine::event_alerts::alert_worthy_pairs()
            .iter()
            .map(|(aggregate_type, to_status)| (aggregate_type.to_string(), to_status.to_string()))
            .unzip();
    if !crate::repos::domain_events::ack_alert(
        pool,
        event_id,
        &actor_principal,
        note,
        &alert_aggregate_types,
        &alert_statuses,
        &session.site_scope,
        &session.environment_scope,
    )
    .await
    .map_err(db_error)?
    {
        return Err(status_404(&event_id.to_string()));
    }
    Ok(())
}

/// Body for a BULK alert acknowledge (#19). Up to 100 event ids share one optional note.
#[derive(Debug, Deserialize, Default)]
#[serde(deny_unknown_fields)]
struct BatchAlertAckBody {
    event_ids: Vec<i64>,
    #[serde(default)]
    note: Option<String>,
}

/// POST /api/events/alerts/batch/ack — acknowledge up to 100 alerts in one call (#19).
/// Mirrors the `requests_batch_*` (#17) shape: the dedicated acknowledgement
/// capability is checked up front, ids are deduped + capped at 100, then each id
/// runs the SAME per-item scope/ack core (`ack_alert_one`) as the single endpoint
/// — so a batch can NEVER ack an out-of-scope alert, and one bad id never aborts
/// the rest. Per-item independent; partial success; HTTP 200 always with
/// `{results, succeeded, failed}`.
async fn events_alert_batch_ack(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<BatchAlertAckBody>,
) -> ApiResult {
    operation_capability_guard(&session, OperationCapability::MonitoringAlertAcknowledge)?;
    if body.event_ids.is_empty() {
        return Err(status_400("event_ids cannot be empty"));
    }
    if body.event_ids.len() > 100 {
        return Err(status_400("a batch may contain at most 100 ids"));
    }
    let note = body
        .note
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty());
    if let Some(n) = note {
        reject_control_chars("note", n)?;
    }
    let pool = get_db().ok_or_else(status_503_no_db)?;
    // Dedup (preserving order) so the same alert is never processed — and counted — twice.
    let mut seen = std::collections::HashSet::new();
    let unique_ids: Vec<i64> = body
        .event_ids
        .iter()
        .copied()
        .filter(|id| seen.insert(*id))
        .collect();

    let mut results: Vec<Value> = Vec::with_capacity(unique_ids.len());
    let mut succeeded = 0u64;
    let mut failed = 0u64;
    for id in unique_ids {
        match ack_alert_one(&session, pool, id, note).await {
            Ok(()) => {
                succeeded += 1;
                results.push(json!({ "event_id": id, "ok": true }));
            }
            Err((status, body)) => {
                failed += 1;
                results.push(json!({
                    "event_id": id,
                    "ok": false,
                    "status": status.as_u16(),
                    "error": body.0,
                }));
            }
        }
    }
    Ok(Json(json!({
        "results": results,
        "succeeded": succeeded,
        "failed": failed,
    })))
}

/// Query params for the SIEM audit export.
#[derive(Debug, Deserialize, Default)]
struct AuditExportParams {
    /// Inclusive lower time bound (RFC3339).
    since: Option<String>,
    /// Inclusive upper time bound (RFC3339).
    until: Option<String>,
    /// Cursor: return rows with id strictly greater than this (default 0).
    after_id: Option<i64>,
    /// Max rows per page (default 500, capped 5000).
    limit: Option<i64>,
}

/// GET /api/audit/export — export the audit trail for SIEM ingestion. Audit-tier.
/// Cursor-paginated by the monotonic row id (`after_id` → `next_after_id`), with
/// an optional `[since, until]` time window. Detail is redacted; each entry
/// carries its hash-chain `entry_hash` so the SIEM can correlate with the verify
/// endpoint. In dry-run / no-DB mode there is no durable chain, so this returns
/// an empty export. The cursor yields no duplicates; for guaranteed completeness
/// (no gaps under concurrency) periodically re-export a CLOSED time window — see
/// `audit::export_audit`. Use the cursor with a stable window, or id-only.
async fn audit_export(
    AuthExtractor(session): AuthExtractor,
    Query(params): Query<AuditExportParams>,
) -> ApiResult {
    if !check_permission(&session, "audit") {
        return Err((
            StatusCode::FORBIDDEN,
            Json(json!({"error": "Audit-tier access is required to export the audit trail"})),
        ));
    }
    let Some(pool) = get_db() else {
        return Ok(Json(json!({
            "durable": false,
            "entries": [],
            "count": 0,
            "next_after_id": null,
            "note": "no database configured; the durable audit log only exists in DB mode"
        })));
    };
    // Parse the optional time bounds; reject a malformed one rather than ignore it.
    let parse_ts = |raw: &Option<String>| -> Result<Option<chrono::DateTime<chrono::Utc>>, ()> {
        match raw.as_deref().map(str::trim).filter(|s| !s.is_empty()) {
            Some(s) => chrono::DateTime::parse_from_rfc3339(s)
                .map(|d| Some(d.with_timezone(&chrono::Utc)))
                .map_err(|_| ()),
            None => Ok(None),
        }
    };
    let since =
        parse_ts(&params.since).map_err(|_| status_400("since must be an RFC3339 timestamp"))?;
    let until =
        parse_ts(&params.until).map_err(|_| status_400("until must be an RFC3339 timestamp"))?;
    let after_id = params.after_id.unwrap_or(0).max(0);
    let limit = params.limit.unwrap_or(500).clamp(1, 5000);

    match audit::export_audit(pool, since, until, after_id, limit).await {
        Ok(export) => Ok(Json(json!({
            "durable": true,
            "entries": export.entries,
            "count": export.entries.len(),
            "next_after_id": export.next_after_id,
        }))),
        Err(e) => {
            tracing::error!(error = %e, "audit export query failed");
            Err((
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(json!({"error": "could not export the audit trail"})),
            ))
        }
    }
}

/// Query for GET /api/audit/retention.
#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct AuditRetentionQuery {
    retention_days: Option<i64>,
}

/// Retention counts query. `$1` = retention window in seconds. Returns
/// (total, entries-older-than-window, oldest-entry-age-secs|NULL). Shared with
/// the DB test so it validates the EXACT SQL the handler runs.
const AUDIT_RETENTION_SQL: &str = "SELECT count(*), \
     count(*) FILTER (WHERE occurred_at \
         < now() - make_interval(secs => $1::double precision)), \
     EXTRACT(EPOCH FROM (now() - min(occurred_at)))::bigint \
     FROM audit_log";

/// GET /api/audit/retention?retention_days=N — audit-log retention/growth report
/// (#62). The append-only, hash-chained trail only grows; this surfaces how many
/// entries have aged past a retention window (default 365d, bounded) and whether
/// archival/partitioning is due — the read input to that SEPARATE, hash-chain-
/// preserving step. Audit-tier; empty + `durable:false` with no DB.
async fn audit_retention_report(
    AuthExtractor(session): AuthExtractor,
    Query(q): Query<AuditRetentionQuery>,
) -> ApiResult {
    if !check_permission(&session, "audit") {
        return Err((
            StatusCode::FORBIDDEN,
            Json(json!({"error": "Audit-tier access is required for the retention report"})),
        ));
    }
    let retention_days = q.retention_days.unwrap_or(365);
    if !(1..=3650).contains(&retention_days) {
        return Err(status_400("retention_days must be between 1 and 3650"));
    }

    use ryuki_engine::audit_retention::{build_audit_retention, AuditRetentionReport};
    // Same JSON shape for both paths so a client never has to special-case no-DB.
    let to_json = |report: AuditRetentionReport, durable: bool| -> Value {
        json!({
            "durable": durable,
            "retention_days": report.retention_days,
            "total_entries": report.total_entries,
            "within_retention": report.within_retention,
            "beyond_retention": report.beyond_retention,
            "oldest_age_days": report.oldest_age_days,
            "status": report.status.as_str(),
        })
    };

    let Some(pool) = get_db() else {
        // Uniform shape: an EMPTY report, marked non-durable.
        let mut body = to_json(build_audit_retention(0, 0, None, retention_days), false);
        body["note"] =
            json!("no database configured; the durable audit log only exists in DB mode");
        return Ok(Json(body));
    };

    // total, entries older than the window, and the oldest entry's age in seconds
    // (NULL ⇒ empty log ⇒ Option None). All from one DB clock.
    let (total, beyond, oldest_age_secs): (i64, i64, Option<i64>) =
        sqlx::query_as(AUDIT_RETENTION_SQL)
            .bind((retention_days * 86_400) as f64)
            .fetch_one(pool)
            .await
            .map_err(db_error)?;

    let report = build_audit_retention(total, beyond, oldest_age_secs, retention_days);
    Ok(Json(to_json(report, true)))
}

// ─── On-call / escalation contact registry (#61) ───

const ON_CALL_COLUMNS: &str = "id, name, role, site, escalation_tier, email, phone, enabled";

/// One persisted on_call_contacts row.
#[derive(sqlx::FromRow)]
struct OnCallContactRow {
    id: String,
    name: String,
    role: String,
    site: Option<String>,
    escalation_tier: i32,
    email: Option<String>,
    phone: Option<String>,
    enabled: bool,
}

impl OnCallContactRow {
    fn to_json(&self) -> Value {
        json!({
            "id": self.id,
            "name": self.name,
            "role": self.role,
            "site": self.site,
            "escalation_tier": self.escalation_tier,
            "email": self.email,
            "phone": self.phone,
            "enabled": self.enabled,
        })
    }
}

/// Validate the FINAL contact fields (after any update is applied). Shared by
/// create and update so they cannot diverge. Returns the human message on
/// rejection, `None` when valid.
fn on_call_contact_rejection(
    name: &str,
    role: &str,
    site: &Option<String>,
    tier: i32,
    email: &Option<String>,
    phone: &Option<String>,
) -> Option<&'static str> {
    // Reject control characters in every field (incl. CR/LF), so a value can
    // never carry a header-injection or log-forging payload downstream.
    let has_control = |s: &str| s.chars().any(char::is_control);
    if has_control(name)
        || has_control(role)
        || site.as_deref().is_some_and(has_control)
        || email.as_deref().is_some_and(has_control)
        || phone.as_deref().is_some_and(has_control)
    {
        return Some("contact fields must not contain control characters");
    }
    if name.trim().is_empty() || name.len() > 200 {
        return Some("name must be 1..=200 characters");
    }
    if role.trim().is_empty() || role.len() > 200 {
        return Some("role must be 1..=200 characters");
    }
    if site.as_deref().is_some_and(|s| s.len() > 200) {
        return Some("site must be at most 200 characters");
    }
    if !(1..=5).contains(&tier) {
        return Some("escalation_tier must be between 1 and 5");
    }
    let has_email = email.as_deref().is_some_and(|e| !e.trim().is_empty());
    let has_phone = phone.as_deref().is_some_and(|p| !p.trim().is_empty());
    if !has_email && !has_phone {
        return Some("at least one of email or phone is required");
    }
    if let Some(e) = email.as_deref().filter(|e| !e.trim().is_empty()) {
        if !e.contains('@') || e.len() > 320 {
            return Some("email must be a valid address (at most 320 characters)");
        }
    }
    None
}

/// Body for creating an on-call contact. `deny_unknown_fields` so a typo'd field
/// (e.g. `enabld`) is a hard 422, not silently dropped from admin config.
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct OnCallContactCreateRequest {
    name: String,
    role: String,
    #[serde(default)]
    site: Option<String>,
    #[serde(default)]
    escalation_tier: Option<i32>,
    #[serde(default)]
    email: Option<String>,
    #[serde(default)]
    phone: Option<String>,
}

/// Mutable fields of an on-call contact (all optional; omitted = keep). For
/// email/phone, an empty string clears it. `deny_unknown_fields` rejects typos.
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct OnCallContactUpdateRequest {
    name: Option<String>,
    role: Option<String>,
    site: Option<String>,
    escalation_tier: Option<i32>,
    email: Option<String>,
    phone: Option<String>,
    enabled: Option<bool>,
}

/// List-filter query for on-call contacts. #14: `limit`/`offset` live on this
/// DEDICATED list struct (never shared with the by-id/mutation handlers), so a
/// bad `?limit=` can only ever 400 the list endpoint.
#[derive(Debug, Deserialize, Default)]
struct OnCallListQuery {
    site: Option<String>,
    tier: Option<i32>,
    limit: Option<i64>,
    offset: Option<i64>,
}

/// Trim an optional string to `None` when blank.
fn norm_opt(o: &Option<String>) -> Option<String> {
    o.as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(str::to_string)
}

/// POST /api/observe/oncall/contacts — register an on-call contact. Execute-tier.
async fn on_call_contact_create(
    AuthExtractor(session): AuthExtractor,
    Json(b): Json<OnCallContactCreateRequest>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let pool = get_db().ok_or_else(status_503_no_db)?;
    // #2: a scoped principal may only register a contact for a site within its
    // scope; a NULL (platform-wide) contact may be created only by an unrestricted
    // principal. Body-supplied → 403 (no existence oracle).
    match norm_opt(&b.site).as_deref() {
        Some(s) => guard_body_site_scope(&session, s)?,
        None if is_scoped(&session) => return Err(status_403_out_of_scope("site")),
        None => {}
    }
    let tier = b.escalation_tier.unwrap_or(1);
    if let Some(msg) =
        on_call_contact_rejection(&b.name, &b.role, &b.site, tier, &b.email, &b.phone)
    {
        return Err(status_400(msg));
    }
    let id = uuid::Uuid::new_v4().to_string();
    // Persist + audit ATOMICALLY: a contact never lands without its
    // durable audit_log row (#7).
    let mut tx = pool.begin().await.map_err(db_error)?;
    sqlx::query(&format!(
        "INSERT INTO on_call_contacts ({ON_CALL_COLUMNS}) \
         VALUES ($1, $2, $3, $4, $5, $6, $7, TRUE)"
    ))
    .bind(&id)
    .bind(b.name.trim())
    .bind(b.role.trim())
    .bind(norm_opt(&b.site))
    .bind(tier)
    .bind(norm_opt(&b.email))
    .bind(norm_opt(&b.phone))
    .execute(&mut *tx)
    .await
    .map_err(db_error)?;
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "oncall-contact-create",
            None,
            "created",
            json!({
                "contact_id": &id,
                "name": b.name.trim(),
                "site": norm_opt(&b.site),
            }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;
    Ok(Json(
        json!({ "source": "database", "id": id, "created": true }),
    ))
}

/// GET /api/observe/oncall/contacts — list contacts, optionally filtered by site
/// and/or escalation tier, in escalation order.
async fn on_call_contact_list(
    AuthExtractor(session): AuthExtractor,
    Query(q): Query<OnCallListQuery>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    // #14: bound the page (generous default keeps seed-scale callers unaffected).
    let limit = q.limit.unwrap_or(500).clamp(1, 1000);
    let offset = q.offset.unwrap_or(0).max(0);
    let Some(pool) = get_db() else {
        return Ok(Json(json!({
            "contacts": [], "durable": false,
            "total": 0, "limit": limit, "offset": offset,
        })));
    };
    // #2: the nullable-site containment of `nullable_site_scope_guard_or_404`
    // (previously applied row-by-row in Rust AFTER a fetch-all), pushed INTO SQL
    // (#14) so a LIMIT/OFFSET page and the total reflect the filtered set:
    //   * env-scoped principal → nothing (site-only resource; `Empty`);
    //   * UNRESTRICTED principal (LITERALLY empty site scope) → every row,
    //     INCLUDING platform-wide (NULL-site) contacts (`All`, no WHERE);
    //   * site-scoped principal → only concrete in-scope sites; a NULL-site
    //     row is never a scoped principal's (`site = ANY(..)` never matches
    //     NULL — the SQL mirror of the guard's `is_scoped()` 404).
    let sites: Option<Vec<String>> = match list_site_scope(&session) {
        ListSiteScope::Empty => {
            return Ok(Json(json!({
                "source": "database", "contacts": [], "count": 0,
                "total": 0, "limit": limit, "offset": offset,
            })));
        }
        ListSiteScope::All => None,
        ListSiteScope::Sites(s) => Some(s),
    };
    let f_site = norm_opt(&q.site);
    // Build the WHERE from ONLY the active predicates — the old
    // `($n IS NULL OR col = $n)` shape seq-scans under a GENERIC prepared plan
    // (sqlx caches prepared statements). Column names are compile-time
    // literals; every value is a BOUND parameter, so this is injection-safe.
    let mut preds: Vec<String> = Vec::new();
    let mut n = 0;
    if f_site.is_some() {
        n += 1;
        preds.push(format!("site = ${n}"));
    }
    if q.tier.is_some() {
        n += 1;
        preds.push(format!("escalation_tier = ${n}"));
    }
    if sites.is_some() {
        n += 1;
        preds.push(format!("site = ANY(${n})"));
    }
    let where_sql = if preds.is_empty() {
        String::new()
    } else {
        format!(" WHERE {}", preds.join(" AND "))
    };
    // #14: `(escalation_tier, name)` is non-unique → append the unique PK `id`
    // as the tie-breaker so LIMIT/OFFSET pages are a stable cut.
    let page_sql = format!(
        "SELECT {ON_CALL_COLUMNS} FROM on_call_contacts{where_sql} \
         ORDER BY escalation_tier ASC, name ASC, id ASC LIMIT ${} OFFSET ${}",
        n + 1,
        n + 2
    );
    let count_sql = format!("SELECT COUNT(*) FROM on_call_contacts{where_sql}");
    // Bind in the SAME order the placeholders were assigned above — the count
    // query shares the IDENTICAL WHERE and binds (minus LIMIT/OFFSET).
    let mut page_q = sqlx::query_as::<_, OnCallContactRow>(&page_sql);
    let mut count_q = sqlx::query_scalar::<_, i64>(&count_sql);
    if let Some(s) = &f_site {
        page_q = page_q.bind(s);
        count_q = count_q.bind(s);
    }
    if let Some(t) = q.tier {
        page_q = page_q.bind(t);
        count_q = count_q.bind(t);
    }
    if let Some(s) = &sites {
        page_q = page_q.bind(s);
        count_q = count_q.bind(s);
    }
    let rows: Vec<OnCallContactRow> = page_q
        .bind(limit)
        .bind(offset)
        .fetch_all(pool)
        .await
        .map_err(db_error)?;
    let total: i64 = count_q.fetch_one(pool).await.map_err(db_error)?;
    let contacts: Vec<Value> = rows.iter().map(OnCallContactRow::to_json).collect();
    Ok(Json(json!({
        "source": "database",
        "contacts": contacts,
        "count": contacts.len(),
        "total": total,
        "limit": limit,
        "offset": offset,
    })))
}

/// GET /api/observe/oncall/contacts/{id} — fetch one contact.
async fn on_call_contact_get(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let row: Option<OnCallContactRow> = sqlx::query_as(&format!(
        "SELECT {ON_CALL_COLUMNS} FROM on_call_contacts WHERE id = $1"
    ))
    .bind(&id)
    .fetch_optional(pool)
    .await
    .map_err(db_error)?;
    match row {
        Some(r) => {
            // #2: out-of-scope (or platform-wide for a scoped principal) 404s like a
            // missing one — no cross-site existence oracle.
            nullable_site_scope_guard_or_404(&session, r.site.as_deref(), &id)?;
            Ok(Json(
                json!({ "source": "database", "contact": r.to_json() }),
            ))
        }
        None => Err(status_404(&id)),
    }
}

/// PUT /api/observe/oncall/contacts/{id} — update a contact's mutable fields.
/// 404 when unknown; 503 when no DB.
async fn on_call_contact_update(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
    Json(b): Json<OnCallContactUpdateRequest>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let pool = get_db().ok_or_else(status_503_no_db)?;
    // Lock the row for the read-modify-write so two concurrent partial PUTs
    // cannot clobber each other's omitted fields (the resolve reads `existing`).
    let mut tx = pool.begin().await.map_err(db_error)?;
    let existing: OnCallContactRow = sqlx::query_as(&format!(
        "SELECT {ON_CALL_COLUMNS} FROM on_call_contacts WHERE id = $1 FOR UPDATE"
    ))
    .bind(&id)
    .fetch_optional(&mut *tx)
    .await
    .map_err(db_error)?
    .ok_or_else(|| status_404(&id))?;

    // #2: a scoped principal may only touch a contact already within its scope
    // (out-of-scope / platform-wide → 404, no oracle), and may not re-home it out
    // of scope or to platform-wide (target site guarded below).
    nullable_site_scope_guard_or_404(&session, existing.site.as_deref(), &id)?;

    // Resolve final values: omitted = keep; for site/email/phone an empty string
    // clears it. The combined email/phone is then validated for the has-method
    // rule (which a pure COALESCE could not check without the existing row).
    let final_name = b
        .name
        .as_deref()
        .map(|s| s.trim().to_string())
        .unwrap_or_else(|| existing.name.clone());
    let final_role = b
        .role
        .as_deref()
        .map(|s| s.trim().to_string())
        .unwrap_or_else(|| existing.role.clone());
    let final_site: Option<String> = match b.site {
        None => existing.site.clone(),
        Some(ref s) => norm_opt(&Some(s.clone())),
    };
    let final_tier = b.escalation_tier.unwrap_or(existing.escalation_tier);
    let final_email: Option<String> = match b.email {
        None => existing.email.clone(),
        Some(ref s) => norm_opt(&Some(s.clone())),
    };
    let final_phone: Option<String> = match b.phone {
        None => existing.phone.clone(),
        Some(ref s) => norm_opt(&Some(s.clone())),
    };
    let final_enabled = b.enabled.unwrap_or(existing.enabled);

    // #2: the resulting site must also be within the principal's scope — a scoped
    // principal cannot re-home a contact to another site or to platform-wide.
    match final_site.as_deref() {
        Some(s) => guard_body_site_scope(&session, s)?,
        None if is_scoped(&session) => return Err(status_403_out_of_scope("site")),
        None => {}
    }

    if let Some(msg) = on_call_contact_rejection(
        &final_name,
        &final_role,
        &final_site,
        final_tier,
        &final_email,
        &final_phone,
    ) {
        return Err(status_400(msg));
    }

    sqlx::query(
        "UPDATE on_call_contacts SET \
            name = $2, role = $3, site = $4, escalation_tier = $5, \
            email = $6, phone = $7, enabled = $8, updated_at = NOW() \
         WHERE id = $1",
    )
    .bind(&id)
    .bind(&final_name)
    .bind(&final_role)
    .bind(&final_site)
    .bind(final_tier)
    .bind(&final_email)
    .bind(&final_phone)
    .bind(final_enabled)
    .execute(&mut *tx)
    .await
    .map_err(db_error)?;

    let updated: OnCallContactRow = sqlx::query_as(&format!(
        "SELECT {ON_CALL_COLUMNS} FROM on_call_contacts WHERE id = $1"
    ))
    .bind(&id)
    .fetch_one(&mut *tx)
    .await
    .map_err(db_error)?;
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "oncall-contact-update",
            None,
            "updated",
            json!({ "contact_id": &id }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;
    Ok(Json(
        json!({ "source": "database", "contact": updated.to_json() }),
    ))
}

/// DELETE /api/observe/oncall/contacts/{id} — remove a contact. 404 when unknown.
async fn on_call_contact_delete(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let mut tx = pool.begin().await.map_err(db_error)?;
    // #2: pre-load the contact's site (locked) and guard BEFORE the DELETE — an
    // out-of-scope / platform-wide-for-a-scoped-principal contact 404s like a
    // missing one, never a cross-site delete or existence oracle.
    let target: Option<(Option<String>,)> =
        sqlx::query_as("SELECT site FROM on_call_contacts WHERE id = $1 FOR UPDATE")
            .bind(&id)
            .fetch_optional(&mut *tx)
            .await
            .map_err(db_error)?;
    match target {
        Some((site,)) => nullable_site_scope_guard_or_404(&session, site.as_deref(), &id)?,
        None => return Err(status_404(&id)),
    }
    let deleted: Option<(String,)> =
        sqlx::query_as("DELETE FROM on_call_contacts WHERE id = $1 RETURNING id")
            .bind(&id)
            .fetch_optional(&mut *tx)
            .await
            .map_err(db_error)?;
    if deleted.is_none() {
        return Err(status_404(&id));
    }
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "oncall-contact-delete",
            Some("active"),
            "deleted",
            json!({ "contact_id": &id }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;
    Ok(Json(
        json!({ "source": "database", "deleted": true, "id": id }),
    ))
}

fn audit_verification_job_json(job: &audit::AuditVerificationJob) -> Value {
    let verified = match job.status.as_str() {
        "verified" => Some(true),
        "divergent" => Some(false),
        _ => None,
    };
    json!({
        "job_id": job.id,
        "status": job.status,
        "verified": verified,
        "complete": job.is_terminal(),
        "checked": job.checked,
        "snapshot_tail_id": job.snapshot_tail_id,
        "verified_through_id": job.cursor_id,
        "first_divergent_id": job.first_divergent_id,
        "reason": job.reason_code,
        "requested_at": job.requested_at,
        "started_at": job.started_at,
        "updated_at": job.updated_at,
        "completed_at": job.completed_at,
        "durable": true,
    })
}

/// POST /api/audit/log/verify — enqueue or join the durable singleton verifier.
/// The request never reads audit rows; a background worker advances fixed-size
/// checkpoints. Active jobs return 202 and can be polled at the status route.
/// In no-DB mode the historical verified/no-op response remains unchanged.
async fn audit_log_verify(
    AuthExtractor(session): AuthExtractor,
) -> Result<(StatusCode, Json<Value>), (StatusCode, Json<Value>)> {
    if !check_permission(&session, "audit") {
        return Err((
            StatusCode::FORBIDDEN,
            Json(json!({"error": "Audit-tier access is required to verify the audit chain"})),
        ));
    }
    let Some(pool) = get_db() else {
        return Ok((
            StatusCode::OK,
            Json(json!({
                "verified": true,
                "checked": 0,
                "durable": false,
                "note": "no database configured; the hash chain only exists in durable mode"
            })),
        ));
    };
    let requester_principal = authenticated_principal_id(&session)?.to_string();
    match audit::enqueue_or_join_audit_verification(pool, &requester_principal).await {
        Ok(job) => {
            let status = if job.is_terminal() {
                StatusCode::OK
            } else {
                StatusCode::ACCEPTED
            };
            Ok((status, Json(audit_verification_job_json(&job))))
        }
        Err(e) => {
            tracing::error!(error = %e, "audit chain verification enqueue failed");
            Err((
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(json!({"error": "audit chain verification could not be scheduled"})),
            ))
        }
    }
}

/// GET /api/audit/log/verify/{job_id} — safe progress/terminal state only. Chain
/// hashes, checkpoint predecessors, and requester identity are never returned.
async fn audit_log_verify_status(
    AuthExtractor(session): AuthExtractor,
    Path(job_id): Path<String>,
) -> ApiResult {
    if !check_permission(&session, "audit") {
        return Err((
            StatusCode::FORBIDDEN,
            Json(json!({"error": "Audit-tier access is required to read verification status"})),
        ));
    }
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let job = audit::audit_verification_status(pool, &job_id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| {
            (
                StatusCode::NOT_FOUND,
                Json(json!({"error": "audit verification job not found"})),
            )
        })?;
    Ok(Json(audit_verification_job_json(&job)))
}

/// GET /api/ops/scheduler/schedules — list the durable scheduler's registered
/// recurring jobs (the registry of what runs and when it next/last ran).
/// Execute-tier gated; read-only. 200 with an empty list in dry-run / no-DB mode.
async fn scheduler_schedules(
    AuthExtractor(session): AuthExtractor,
    Query(page): Query<AdminListPage>,
) -> ApiResult {
    if !check_permission(&session, "execute") {
        return Err((
            StatusCode::FORBIDDEN,
            Json(json!({"error": "Execute-tier access is required to view scheduler state"})),
        ));
    }
    // #14: bound the page (generous default keeps seed-scale callers unaffected).
    let limit = page.limit.unwrap_or(500).clamp(1, 1000);
    let offset = page.offset.unwrap_or(0).max(0);
    let Some(pool) = get_db() else {
        return Ok(Json(
            json!({"schedules": [], "durable": false, "total": 0, "limit": limit, "offset": offset}),
        ));
    };
    match crate::scheduler::list_schedules(pool, limit, offset).await {
        Ok(schedules) => {
            let total = crate::scheduler::count_schedules(pool)
                .await
                .map_err(db_error)?;
            Ok(Json(json!({
                "schedules": schedules,
                "durable": true,
                "total": total,
                "limit": limit,
                "offset": offset
            })))
        }
        Err(e) => {
            tracing::error!(error = %e, "listing scheduler schedules failed");
            Err((
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(json!({"error": "could not list scheduler schedules"})),
            ))
        }
    }
}

/// GET /api/ops/scheduler/executions — list recent durable-scheduler job runs
/// (when each started/finished, its status, and a short detail). Execute-tier
/// gated; read-only. 200 with an empty list in dry-run / no-DB mode.
async fn scheduler_executions(AuthExtractor(session): AuthExtractor) -> ApiResult {
    if !check_permission(&session, "execute") {
        return Err((
            StatusCode::FORBIDDEN,
            Json(json!({"error": "Execute-tier access is required to view scheduler state"})),
        ));
    }
    let Some(pool) = get_db() else {
        return Ok(Json(json!({"executions": [], "durable": false})));
    };
    match crate::scheduler::list_recent_executions(pool, 100).await {
        Ok(executions) => Ok(Json(json!({"executions": executions, "durable": true}))),
        Err(e) => {
            tracing::error!(error = %e, "listing scheduler executions failed");
            Err((
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(json!({"error": "could not list scheduler executions"})),
            ))
        }
    }
}

/// Source of truth for the bounded READ-ONLY operational surface documented
/// in `openapi.rs` (missing-feature #64, ops-read slice). Cross-checked by
/// `openapi.rs`'s drift-guard tests: adding or removing one of these GET
/// routes without updating the OpenAPI document (or vice versa) fails those
/// tests. All four require a session (`X-Ryuki-Session-Id` / bearer / cookie)
/// plus the `execute` or `request`/`audit` permission tier enforced inside
/// each handler above — this list only tracks path shape, not authz tier.
#[allow(dead_code)]
pub const OPS_READ_ROUTE_PATHS: &[(&str, &str)] = &[
    ("GET", "/api/events"),
    ("GET", "/api/events/alerts"),
    ("GET", "/api/ops/scheduler/schedules"),
    ("GET", "/api/ops/scheduler/executions"),
];

// ─── Metric history + forecasting handlers (#34) ───

/// Body for recording one metric sample. `observed_at` is optional (defaults to
/// the server clock); `site`/`environment` are optional scope.
#[derive(Debug, Deserialize)]
struct MetricSampleRequest {
    metric_key: String,
    #[serde(default)]
    site: Option<String>,
    #[serde(default)]
    environment: Option<String>,
    value: f64,
    #[serde(default)]
    observed_at: Option<String>,
}

/// Query params for reading a metric series + its forecast.
#[derive(Debug, Deserialize, Default)]
struct MetricSeriesParams {
    metric_key: Option<String>,
    site: Option<String>,
    environment: Option<String>,
    horizon: Option<usize>,
}

/// One stored sample as queried for the series.
#[derive(sqlx::FromRow)]
struct MetricSampleRow {
    value: f64,
    observed_at: chrono::DateTime<chrono::Utc>,
}

/// Reject a malformed `metric_key`: it must be 1..=200 chars from the dotted
/// identifier alphabet `[A-Za-z0-9._:-]` (e.g. `cost.monthly_usd`). The strict
/// allowlist also means the key can never carry HTML/script characters, so it is
/// safe to embed in a generated suggestion's title/description that a UI may
/// later render. Returns the human message on rejection, `None` when valid.
/// Shared by every metric handler so they cannot diverge.
fn metric_key_rejection(key: &str) -> Option<&'static str> {
    if key.is_empty() || key.len() > 200 {
        return Some("metric_key must be 1..=200 characters");
    }
    if !key
        .chars()
        .all(|c| c.is_ascii_alphanumeric() || matches!(c, '.' | '_' | '-' | ':'))
    {
        return Some("metric_key may contain only letters, digits, and . _ - :");
    }
    None
}

/// A single scope label for a generated suggestion's `site` field, combining the
/// (optional) site and environment so two different scopes never collide in the
/// dedup. `aiops_suggestions` has no environment column, so the env is folded
/// into this label rather than silently dropped.
fn metric_scope_label(site: &Option<String>, environment: &Option<String>) -> String {
    match (site.as_deref(), environment.as_deref()) {
        (Some(s), Some(e)) => format!("{s}/{e}"),
        (Some(s), None) => s.to_string(),
        (None, Some(e)) => format!("platform/{e}"),
        (None, None) => "platform".to_string(),
    }
}

/// The forecast step for a series: its own average sample cadence, or one hour
/// when there are fewer than two points to measure a cadence from. Shared by the
/// series and what-if handlers so their projections step identically.
fn metric_series_step(points: &[ryuki_engine::metric_forecast::MetricPoint]) -> f64 {
    if points.len() >= 2 {
        let span = points.last().unwrap().t - points.first().unwrap().t;
        let s = span / (points.len() - 1) as f64;
        if s > 0.0 {
            s
        } else {
            3600.0
        }
    } else {
        3600.0
    }
}

/// True when an optional scope value (site/environment) exceeds the 200-char
/// bound. A blank/absent scope is fine.
fn metric_scope_too_long(scope: &Option<String>) -> bool {
    scope
        .as_deref()
        .map(|s| s.trim().len() > 200)
        .unwrap_or(false)
}

/// Fetch one COHERENT-scope metric series: the most-recent 10k samples for
/// `metric_key` within the given scope, returned ascending by `observed_at`.
/// `IS NOT DISTINCT FROM` means an omitted (`None`) site/environment selects the
/// platform-wide rows where that column IS NULL — never "all scopes" — so the
/// series is never a mix. Shared by the series and insights handlers so they
/// read identical data.
async fn fetch_metric_series_rows(
    pool: &sqlx::PgPool,
    metric_key: &str,
    site: &Option<String>,
    environment: &Option<String>,
) -> Result<Vec<MetricSampleRow>, sqlx::Error> {
    sqlx::query_as(
        "SELECT value, observed_at FROM ( \
             SELECT value, observed_at FROM metric_samples \
             WHERE metric_key = $1 \
               AND site IS NOT DISTINCT FROM $2 \
               AND environment IS NOT DISTINCT FROM $3 \
             ORDER BY observed_at DESC \
             LIMIT 10000 \
         ) recent \
         ORDER BY observed_at ASC",
    )
    .bind(metric_key)
    .bind(site)
    .bind(environment)
    .fetch_all(pool)
    .await
}

/// POST /api/metrics/samples — record one time-series metric sample. Execute-tier
/// (operators/collectors push samples). 503 when no database is configured.
async fn metrics_record_sample(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<MetricSampleRequest>,
) -> ApiResult {
    if !check_permission(&session, "execute") {
        return Err((
            StatusCode::FORBIDDEN,
            Json(json!({"error": "Execute-tier access is required to record metrics"})),
        ));
    }
    let metric_key = body.metric_key.trim();
    if let Some(msg) = metric_key_rejection(metric_key) {
        return Err((StatusCode::BAD_REQUEST, Json(json!({ "error": msg }))));
    }
    if metric_scope_too_long(&body.site) || metric_scope_too_long(&body.environment) {
        return Err((
            StatusCode::BAD_REQUEST,
            Json(json!({"error": "site/environment must be at most 200 characters"})),
        ));
    }
    if !body.value.is_finite() {
        return Err((
            StatusCode::BAD_REQUEST,
            Json(json!({"error": "value must be a finite number"})),
        ));
    }
    // Parse an explicit observed_at if given; reject a malformed one rather than
    // silently substituting the server clock.
    let observed_at = match body.observed_at.as_deref().map(str::trim) {
        Some(s) if !s.is_empty() => match chrono::DateTime::parse_from_rfc3339(s) {
            Ok(dt) => Some(dt.with_timezone(&chrono::Utc)),
            Err(_) => {
                return Err((
                    StatusCode::BAD_REQUEST,
                    Json(json!({"error": "observed_at must be an RFC3339 timestamp"})),
                ));
            }
        },
        _ => None,
    };

    let norm = |o: &Option<String>| {
        o.as_deref()
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(str::to_string)
    };
    // #2: enforce scope BEFORE any DB access; bind the EFFECTIVE (site,
    // environment) into the INSERT — NEVER the raw body. Out-of-scope is a 403,
    // an omitted value narrows to the principal's own scope, unrestricted writes
    // verbatim.
    let (f_site, f_env) =
        enforce_scope_filters(&session, norm(&body.site), norm(&body.environment))?;
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let id = uuid::Uuid::new_v4().to_string();
    let result = sqlx::query(
        "INSERT INTO metric_samples (id, metric_key, site, environment, value, observed_at) \
         VALUES ($1, $2, $3, $4, $5, COALESCE($6, NOW()))",
    )
    .bind(&id)
    .bind(metric_key)
    .bind(&f_site)
    .bind(&f_env)
    .bind(body.value)
    .bind(observed_at)
    .execute(pool)
    .await;
    match result {
        Ok(_) => Ok(Json(json!({"id": id, "recorded": true}))),
        Err(e) => {
            tracing::error!(error = %e, "recording metric sample failed");
            Err((
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(json!({"error": "could not record metric sample"})),
            ))
        }
    }
}

/// GET /api/metrics/series — return one metric's ordered series plus a summary,
/// trend, and a linear forecast (pure `ryuki_engine::metric_forecast`).
/// `metric_key` is required; `site`/`environment` narrow the scope; `horizon`
/// (default 3, capped 100) is the number of points to project. Request-tier read
/// (metrics are non-sensitive aggregates). 503 when no database is configured.
async fn metrics_series(
    AuthExtractor(session): AuthExtractor,
    Query(params): Query<MetricSeriesParams>,
) -> ApiResult {
    if !check_permission(&session, "request") {
        return Err((
            StatusCode::FORBIDDEN,
            Json(json!({"error": "authentication is required to read metrics"})),
        ));
    }
    let Some(metric_key) = params
        .metric_key
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
    else {
        return Err((
            StatusCode::BAD_REQUEST,
            Json(json!({"error": "metric_key is required"})),
        ));
    };
    if let Some(msg) = metric_key_rejection(metric_key) {
        return Err((StatusCode::BAD_REQUEST, Json(json!({ "error": msg }))));
    }
    if metric_scope_too_long(&params.site) || metric_scope_too_long(&params.environment) {
        return Err((
            StatusCode::BAD_REQUEST,
            Json(json!({"error": "site/environment must be at most 200 characters"})),
        ));
    }
    let norm = |o: &Option<String>| {
        o.as_deref()
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(str::to_string)
    };
    // #2: enforce the session's site/environment scopes BEFORE touching the DB.
    // A scoped principal may only read within its scopes; omitting the filter
    // narrows the read to its own scope rather than widening it to all scopes.
    let (f_site, f_env) =
        enforce_scope_filters(&session, norm(&params.site), norm(&params.environment))?;
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let rows = match fetch_metric_series_rows(pool, metric_key, &f_site, &f_env).await {
        Ok(rows) => rows,
        Err(e) => {
            // Do NOT mask a DB failure as an empty (and falsely "flat") series —
            // forecasting/budget consumers must not act on phantom data.
            tracing::error!(error = %e, "querying metric series failed");
            return Err((
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(json!({"error": "could not query metric series"})),
            ));
        }
    };

    let points: Vec<ryuki_engine::metric_forecast::MetricPoint> = rows
        .iter()
        .map(|r| ryuki_engine::metric_forecast::MetricPoint {
            t: r.observed_at.timestamp() as f64,
            value: r.value,
        })
        .collect();

    let summary = ryuki_engine::metric_forecast::summarize(&points);
    let trend = ryuki_engine::metric_forecast::trend(&points, 1e-9);
    let step = metric_series_step(&points);
    let horizon = params.horizon.unwrap_or(3).clamp(0, 100);
    let forecast = ryuki_engine::metric_forecast::project_forward(&points, step, horizon);

    let series_json: Vec<Value> = rows
        .iter()
        .map(|r| json!({"observed_at": r.observed_at.to_rfc3339(), "value": r.value}))
        .collect();
    let forecast_json: Vec<Value> = forecast
        .iter()
        .map(|p| {
            let ts = chrono::DateTime::from_timestamp(p.t as i64, 0)
                .map(|d| d.to_rfc3339())
                .unwrap_or_default();
            json!({"observed_at": ts, "value": p.value})
        })
        .collect();

    Ok(Json(json!({
        "metric_key": metric_key,
        "site": f_site,
        "environment": f_env,
        "series": series_json,
        "summary": summary,
        "trend": trend,
        "forecast": forecast_json,
    })))
}

/// Query params for the time-bucketed metric aggregation (#10).
#[derive(Debug, Deserialize, Default)]
struct MetricAggregatedParams {
    metric_key: Option<String>,
    site: Option<String>,
    environment: Option<String>,
    /// hourly | daily | weekly | monthly (allowlisted → a Postgres date_trunc field).
    granularity: Option<String>,
    /// Max buckets (default 365, clamped 1..=2000). Also bounds the scan window.
    limit: Option<usize>,
}

/// Map a client-friendly granularity to (the Postgres `date_trunc` field, the bucket
/// span in seconds). The field is a fixed `&'static str` from this allowlist — never raw
/// client text — and the span derives the scan's time-window lower bound. `None` → 400.
fn metric_granularity(granularity: &str) -> Option<(&'static str, i64)> {
    match granularity {
        "hourly" => Some(("hour", 3_600)),
        "daily" => Some(("day", 86_400)),
        "weekly" => Some(("week", 604_800)),
        "monthly" => Some(("month", 2_678_400)), // 31d — an upper bound for the window
        _ => None,
    }
}

/// One aggregated time bucket.
#[derive(sqlx::FromRow)]
struct MetricBucketRow {
    bucket: chrono::DateTime<chrono::Utc>,
    min_value: f64,
    max_value: f64,
    mean_value: f64,
    sample_count: i64,
}

/// Fetch COHERENT-scope time buckets for `metric_key`. `date_trunc($4, observed_at,
/// 'UTC')` buckets at UTC boundaries DETERMINISTICALLY (independent of the DB session
/// timezone). `observed_at >= $5` is the scan's time-window lower bound (codex: bounds
/// the otherwise-all-history aggregation; the (metric_key, site, environment,
/// observed_at) index makes it a bounded range scan). The inner `ORDER BY bucket DESC
/// LIMIT $6` keeps the NEWEST `limit` buckets (codex: the window lower-bound is NOT
/// bucket-aligned, so it can span > limit labels — taking them ASC would drop the most
/// recent ones); the outer `ORDER BY bucket ASC` returns them oldest-first.
/// `IS NOT DISTINCT FROM` → a single coherent scope (a specific site/env OR the
/// platform-wide NULL rows, never a mix).
async fn fetch_metric_buckets(
    pool: &sqlx::PgPool,
    metric_key: &str,
    site: &Option<String>,
    environment: &Option<String>,
    trunc_field: &str,
    lower_bound: chrono::DateTime<chrono::Utc>,
    limit: i64,
) -> Result<Vec<MetricBucketRow>, sqlx::Error> {
    sqlx::query_as(
        "SELECT bucket, min_value, max_value, mean_value, sample_count FROM ( \
             SELECT date_trunc($4, observed_at, 'UTC') AS bucket, \
                    MIN(value) AS min_value, MAX(value) AS max_value, \
                    AVG(value) AS mean_value, COUNT(*) AS sample_count \
             FROM metric_samples \
             WHERE metric_key = $1 \
               AND site IS NOT DISTINCT FROM $2 \
               AND environment IS NOT DISTINCT FROM $3 \
               AND observed_at >= $5 \
             GROUP BY bucket ORDER BY bucket DESC LIMIT $6 \
         ) recent ORDER BY bucket ASC",
    )
    .bind(metric_key)
    .bind(site)
    .bind(environment)
    .bind(trunc_field)
    .bind(lower_bound)
    .bind(limit)
    .fetch_all(pool)
    .await
}

/// GET /api/metrics/series/aggregated — time-bucketed (hourly/daily/weekly/monthly)
/// MIN/MAX/MEAN/COUNT rollups of a metric series for historical trend analysis. Mirrors
/// `metrics_series`'s gating + #2 coherent-scope handling. Buckets are NON-EMPTY only (no
/// gap filling); `weekly` is the ISO-8601 Monday-start week at UTC. `request`-tier (a
/// metrics read). The scan is bounded to the last `limit` buckets' worth of time.
async fn metrics_series_aggregated(
    AuthExtractor(session): AuthExtractor,
    Query(params): Query<MetricAggregatedParams>,
) -> ApiResult {
    if !check_permission(&session, "request") {
        return Err((
            StatusCode::FORBIDDEN,
            Json(json!({"error": "authentication is required to read metrics"})),
        ));
    }
    let Some(metric_key) = params
        .metric_key
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
    else {
        return Err(status_400("metric_key is required"));
    };
    if let Some(msg) = metric_key_rejection(metric_key) {
        return Err((StatusCode::BAD_REQUEST, Json(json!({ "error": msg }))));
    }
    let Some(granularity) = params
        .granularity
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
    else {
        return Err(status_400(
            "granularity is required (hourly|daily|weekly|monthly)",
        ));
    };
    let Some((trunc_field, span_secs)) = metric_granularity(granularity) else {
        return Err(status_400(
            "granularity must be one of hourly, daily, weekly, monthly",
        ));
    };
    if metric_scope_too_long(&params.site) || metric_scope_too_long(&params.environment) {
        return Err(status_400(
            "site/environment must be at most 200 characters",
        ));
    }
    let norm = |o: &Option<String>| {
        o.as_deref()
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(str::to_string)
    };
    // #2: enforce the session's site/environment scopes BEFORE touching the DB.
    let (f_site, f_env) =
        enforce_scope_filters(&session, norm(&params.site), norm(&params.environment))?;
    let limit = params.limit.unwrap_or(365).clamp(1, 2000) as i64;
    // Bound the scan to the last `limit` buckets' worth of time (codex MAJOR).
    let lower_bound = chrono::Utc::now() - chrono::Duration::seconds(span_secs * limit);
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let rows = match fetch_metric_buckets(
        pool,
        metric_key,
        &f_site,
        &f_env,
        trunc_field,
        lower_bound,
        limit,
    )
    .await
    {
        Ok(r) => r,
        Err(e) => {
            tracing::error!(error = %e, "querying aggregated metric series failed");
            return Err((
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(json!({"error": "could not query aggregated metric series"})),
            ));
        }
    };
    let buckets: Vec<Value> = rows
        .iter()
        .map(|r| {
            json!({
                "bucket_start": r.bucket.to_rfc3339(),
                "min": r.min_value,
                "max": r.max_value,
                "mean": r.mean_value,
                "count": r.sample_count,
            })
        })
        .collect();
    Ok(Json(json!({
        "metric_key": metric_key,
        "granularity": granularity,
        "site": f_site,
        "environment": f_env,
        "buckets": buckets,
    })))
}

/// Query params for metric insight detection (#35).
#[derive(Debug, Deserialize, Default)]
struct MetricInsightsParams {
    metric_key: Option<String>,
    site: Option<String>,
    environment: Option<String>,
    /// Anomaly z-score threshold (default 3.0).
    z: Option<f64>,
    /// Waste threshold: samples at or below this count toward waste (default 10.0).
    waste_threshold: Option<f64>,
    /// Fraction of samples at/below the threshold to flag waste (default 0.8).
    waste_fraction: Option<f64>,
}

/// The first non-finite tuning param (`z`/`waste_threshold`/`waste_fraction`),
/// or `None` when all present params are finite. These are untrusted query
/// inputs (unlike sample values, which the ingest CHECK already keeps finite).
fn nonfinite_insight_param(params: &MetricInsightsParams) -> Option<&'static str> {
    for (name, val) in [
        ("z", params.z),
        ("waste_threshold", params.waste_threshold),
        ("waste_fraction", params.waste_fraction),
    ] {
        if val.is_some_and(|v| !v.is_finite()) {
            return Some(name);
        }
    }
    None
}

/// GET /api/metrics/insights — anomaly + waste detection over one metric series
/// (pure `ryuki_engine::metric_anomaly`). `metric_key` is required; `site`/
/// `environment` scope the (single, coherent) series; `z` is the anomaly
/// z-threshold; `waste_threshold`/`waste_fraction` configure waste detection.
/// Request-tier read. 503 when no database is configured; 500 on a query error
/// (never a falsely-empty result).
async fn metrics_insights(
    AuthExtractor(session): AuthExtractor,
    Query(params): Query<MetricInsightsParams>,
) -> ApiResult {
    if !check_permission(&session, "request") {
        return Err((
            StatusCode::FORBIDDEN,
            Json(json!({"error": "authentication is required to read metrics"})),
        ));
    }
    let Some(metric_key) = params
        .metric_key
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
    else {
        return Err((
            StatusCode::BAD_REQUEST,
            Json(json!({"error": "metric_key is required"})),
        ));
    };
    if let Some(msg) = metric_key_rejection(metric_key) {
        return Err((StatusCode::BAD_REQUEST, Json(json!({ "error": msg }))));
    }
    if metric_scope_too_long(&params.site) || metric_scope_too_long(&params.environment) {
        return Err((
            StatusCode::BAD_REQUEST,
            Json(json!({"error": "site/environment must be at most 200 characters"})),
        ));
    }
    let norm = |o: &Option<String>| {
        o.as_deref()
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(str::to_string)
    };
    // #2: enforce the session's site/environment scopes BEFORE touching the DB.
    // A scoped principal may only read within its scopes; omitting the filter
    // narrows the read to its own scope rather than widening it to all scopes.
    let (f_site, f_env) =
        enforce_scope_filters(&session, norm(&params.site), norm(&params.environment))?;
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let rows = match fetch_metric_series_rows(pool, metric_key, &f_site, &f_env).await {
        Ok(rows) => rows,
        Err(e) => {
            tracing::error!(error = %e, "querying metric series for insights failed");
            return Err((
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(json!({"error": "could not query metric series"})),
            ));
        }
    };

    let points: Vec<ryuki_engine::metric_forecast::MetricPoint> = rows
        .iter()
        .map(|r| ryuki_engine::metric_forecast::MetricPoint {
            t: r.observed_at.timestamp() as f64,
            value: r.value,
        })
        .collect();

    // Reject a non-finite tuning param rather than letting NaN/Inf reach the
    // detectors (sample values are already finite by ingest CHECK; these query
    // params are a separate, untrusted input).
    if let Some(name) = nonfinite_insight_param(&params) {
        return Err((
            StatusCode::BAD_REQUEST,
            Json(json!({ "error": format!("{name} must be a finite number") })),
        ));
    }
    let z = params.z.unwrap_or(3.0);
    let waste_threshold = params.waste_threshold.unwrap_or(10.0);
    let waste_fraction = params.waste_fraction.unwrap_or(0.8);

    let anomalies = ryuki_engine::metric_anomaly::detect_anomalies(&points, z);
    let waste =
        ryuki_engine::metric_anomaly::detect_waste(&points, waste_threshold, waste_fraction);
    let summary = ryuki_engine::metric_forecast::summarize(&points);

    // Map each anomaly's unix-seconds `t` back to an RFC3339 timestamp.
    let anomalies_json: Vec<Value> = anomalies
        .iter()
        .map(|a| {
            let ts = chrono::DateTime::from_timestamp(a.t as i64, 0)
                .map(|d| d.to_rfc3339())
                .unwrap_or_default();
            json!({"observed_at": ts, "value": a.value, "z_score": a.z_score})
        })
        .collect();

    Ok(Json(json!({
        "metric_key": metric_key,
        "site": f_site,
        "environment": f_env,
        "sample_count": points.len(),
        "summary": summary,
        "anomalies": anomalies_json,
        "waste": waste,
    })))
}

/// POST /api/metrics/insights/generate — run detection over a metric series and
/// PERSIST the resulting suggestions into `aiops_suggestions` (the existing
/// suggestion surface). Execute-tier (it writes). Each suggestion is deduped: it
/// is skipped when an OPEN (New/Reviewed) suggestion with the same site+title
/// already exists, so repeated calls do not pile up duplicates. Returns the
/// suggestions that were newly persisted. 503 when no database is configured.
async fn metrics_generate_suggestions(
    AuthExtractor(session): AuthExtractor,
    Query(params): Query<MetricInsightsParams>,
) -> ApiResult {
    if !check_permission(&session, "execute") {
        return Err((
            StatusCode::FORBIDDEN,
            Json(json!({"error": "Execute-tier access is required to generate suggestions"})),
        ));
    }
    let Some(metric_key) = params
        .metric_key
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
    else {
        return Err((
            StatusCode::BAD_REQUEST,
            Json(json!({"error": "metric_key is required"})),
        ));
    };
    if let Some(msg) = metric_key_rejection(metric_key) {
        return Err((StatusCode::BAD_REQUEST, Json(json!({ "error": msg }))));
    }
    if metric_scope_too_long(&params.site) || metric_scope_too_long(&params.environment) {
        return Err((
            StatusCode::BAD_REQUEST,
            Json(json!({"error": "site/environment must be at most 200 characters"})),
        ));
    }
    if let Some(name) = nonfinite_insight_param(&params) {
        return Err((
            StatusCode::BAD_REQUEST,
            Json(json!({ "error": format!("{name} must be a finite number") })),
        ));
    }
    let norm = |o: &Option<String>| {
        o.as_deref()
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(str::to_string)
    };
    // #2: enforce the session's site/environment scopes BEFORE touching the DB.
    // A scoped principal may only read within its scopes; omitting the filter
    // narrows the read to its own scope rather than widening it to all scopes.
    let (f_site, f_env) =
        enforce_scope_filters(&session, norm(&params.site), norm(&params.environment))?;
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let rows = match fetch_metric_series_rows(pool, metric_key, &f_site, &f_env).await {
        Ok(rows) => rows,
        Err(e) => {
            tracing::error!(error = %e, "querying metric series for suggestion generation failed");
            return Err((
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(json!({"error": "could not query metric series"})),
            ));
        }
    };

    let points: Vec<ryuki_engine::metric_forecast::MetricPoint> = rows
        .iter()
        .map(|r| ryuki_engine::metric_forecast::MetricPoint {
            t: r.observed_at.timestamp() as f64,
            value: r.value,
        })
        .collect();

    let z = params.z.unwrap_or(3.0);
    let waste_threshold = params.waste_threshold.unwrap_or(10.0);
    let waste_fraction = params.waste_fraction.unwrap_or(0.8);
    let anomalies = ryuki_engine::metric_anomaly::detect_anomalies(&points, z);
    let waste =
        ryuki_engine::metric_anomaly::detect_waste(&points, waste_threshold, waste_fraction);
    let summary = ryuki_engine::metric_forecast::summarize(&points);
    let generated = ryuki_engine::metric_suggestions::suggest_from_findings(
        metric_key,
        summary.as_ref(),
        &anomalies,
        waste.as_ref(),
    );

    // Full scope label (site + env) so different scopes never collide in dedup;
    // aiops_suggestions.site is NOT NULL, so an unscoped metric maps to
    // "platform".
    let site = metric_scope_label(&f_site, &f_env);
    let affected = vec![metric_key.to_string()];

    // All inserts share one transaction: a failure on any one rolls back the
    // whole batch (no partial state), and the batch commits atomically.
    let mut tx = match pool.begin().await {
        Ok(tx) => tx,
        Err(e) => {
            tracing::error!(error = %e, "opening suggestion-persist transaction failed");
            return Err((
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(json!({"error": "could not persist generated suggestions"})),
            ));
        }
    };
    let mut persisted: Vec<Value> = Vec::new();
    for g in &generated {
        let id = uuid::Uuid::new_v4().to_string();
        // Dedup on a STABLE key — scope + suggestion_type + the metric_key in
        // affected_components — NOT the title (the anomaly title embeds a count
        // that changes between runs and would defeat dedup). Skip when an OPEN
        // (New/Reviewed) suggestion already covers this metric+type+scope.
        let result = sqlx::query(
            "INSERT INTO aiops_suggestions \
             (id, suggestion_type, title, description, affected_components, \
              estimated_savings, confidence_score, status, site) \
             SELECT $1, $2, $3, $4, $5, $6, $7, 'New', $8 \
             WHERE NOT EXISTS ( \
                 SELECT 1 FROM aiops_suggestions \
                 WHERE site = $8 AND suggestion_type = $2 \
                   AND $9 = ANY(affected_components) \
                   AND status IN ('New', 'Reviewed') \
             )",
        )
        .bind(&id)
        .bind(&g.suggestion_type)
        .bind(&g.title)
        .bind(&g.description)
        .bind(&affected)
        .bind(g.estimated_savings)
        .bind(g.confidence_score)
        .bind(&site)
        .bind(metric_key)
        .execute(&mut *tx)
        .await;
        match result {
            Ok(r) if r.rows_affected() > 0 => persisted.push(json!({
                "id": id,
                "suggestion_type": g.suggestion_type,
                "title": g.title,
                "confidence_score": g.confidence_score,
            })),
            // Deduped (an open suggestion already exists) — not an error.
            Ok(_) => {}
            Err(e) => {
                // Returning drops `tx`, rolling the whole batch back.
                tracing::error!(error = %e, "persisting generated suggestion failed");
                return Err((
                    StatusCode::INTERNAL_SERVER_ERROR,
                    Json(json!({"error": "could not persist generated suggestions"})),
                ));
            }
        }
    }
    if let Err(e) = tx.commit().await {
        tracing::error!(error = %e, "committing generated suggestions failed");
        return Err((
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(json!({"error": "could not persist generated suggestions"})),
        ));
    }

    Ok(Json(json!({
        "metric_key": metric_key,
        "site": site,
        "generated": generated.len(),
        "persisted": persisted.len(),
        "suggestions": persisted,
    })))
}

/// Query params for what-if capacity/cost planning (#37).
#[derive(Debug, Deserialize, Default)]
struct MetricWhatIfParams {
    metric_key: Option<String>,
    site: Option<String>,
    environment: Option<String>,
    /// Periods to project forward (default 6, capped 100).
    horizon: Option<usize>,
    /// Hypothetical load/cost multiplier on the projection (default 1.0).
    growth: Option<f64>,
    /// Capacity/cost ceiling to test the projection against (required).
    ceiling: Option<f64>,
}

/// GET /api/metrics/what-if — project a metric forward under a hypothetical
/// growth factor and report whether/when it would breach a capacity/cost
/// ceiling (pure `ryuki_engine::metric_planning`). `metric_key` and `ceiling`
/// are required. Request-tier read. 503 when no database is configured; 500 on a
/// query error.
async fn metrics_what_if(
    AuthExtractor(session): AuthExtractor,
    Query(params): Query<MetricWhatIfParams>,
) -> ApiResult {
    if !check_permission(&session, "request") {
        return Err((
            StatusCode::FORBIDDEN,
            Json(json!({"error": "authentication is required to read metrics"})),
        ));
    }
    let Some(metric_key) = params
        .metric_key
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
    else {
        return Err((
            StatusCode::BAD_REQUEST,
            Json(json!({"error": "metric_key is required"})),
        ));
    };
    if let Some(msg) = metric_key_rejection(metric_key) {
        return Err((StatusCode::BAD_REQUEST, Json(json!({ "error": msg }))));
    }
    if metric_scope_too_long(&params.site) || metric_scope_too_long(&params.environment) {
        return Err((
            StatusCode::BAD_REQUEST,
            Json(json!({"error": "site/environment must be at most 200 characters"})),
        ));
    }
    let Some(ceiling) = params.ceiling else {
        return Err((
            StatusCode::BAD_REQUEST,
            Json(json!({"error": "ceiling is required for what-if planning"})),
        ));
    };
    for (name, val) in [("growth", params.growth), ("ceiling", Some(ceiling))] {
        if val.is_some_and(|v| !v.is_finite()) {
            return Err((
                StatusCode::BAD_REQUEST,
                Json(json!({ "error": format!("{name} must be a finite number") })),
            ));
        }
    }
    let norm = |o: &Option<String>| {
        o.as_deref()
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(str::to_string)
    };
    // #2: enforce the session's site/environment scopes BEFORE touching the DB.
    // A scoped principal may only read within its scopes; omitting the filter
    // narrows the read to its own scope rather than widening it to all scopes.
    let (f_site, f_env) =
        enforce_scope_filters(&session, norm(&params.site), norm(&params.environment))?;
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let rows = match fetch_metric_series_rows(pool, metric_key, &f_site, &f_env).await {
        Ok(rows) => rows,
        Err(e) => {
            tracing::error!(error = %e, "querying metric series for what-if failed");
            return Err((
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(json!({"error": "could not query metric series"})),
            ));
        }
    };
    let points: Vec<ryuki_engine::metric_forecast::MetricPoint> = rows
        .iter()
        .map(|r| ryuki_engine::metric_forecast::MetricPoint {
            t: r.observed_at.timestamp() as f64,
            value: r.value,
        })
        .collect();

    let step = metric_series_step(&points);
    let horizon = params.horizon.unwrap_or(6).clamp(0, 100);
    let growth = params.growth.unwrap_or(1.0);
    let result = ryuki_engine::metric_planning::what_if(&points, step, horizon, growth, ceiling);

    // Map projected unix-seconds `t` back to RFC3339 timestamps. An out-of-range
    // timestamp or a non-finite (overflowed) value serialize as `null` rather
    // than an empty string / invalid JSON number.
    let projected_json: Vec<Value> = result
        .projected
        .iter()
        .map(|p| {
            let ts = chrono::DateTime::from_timestamp(p.t as i64, 0).map(|d| d.to_rfc3339());
            let value = if p.value.is_finite() {
                json!(p.value)
            } else {
                Value::Null
            };
            json!({"observed_at": ts, "value": value})
        })
        .collect();
    let first_breach_at = result
        .first_breach_t
        .and_then(|t| chrono::DateTime::from_timestamp(t as i64, 0).map(|d| d.to_rfc3339()));

    Ok(Json(json!({
        "metric_key": metric_key,
        "site": f_site,
        "environment": f_env,
        "ceiling": result.ceiling,
        "growth_factor": result.growth_factor,
        "breaches": result.breaches,
        "first_breach_at": first_breach_at,
        "peak_projected": result.peak_projected,
        "headroom": result.headroom,
        "projected": projected_json,
    })))
}

// ─── Metric budget thresholds (#53) ───

/// Body for creating a metric budget.
#[derive(Debug, Deserialize)]
struct MetricBudgetCreateRequest {
    metric_key: String,
    #[serde(default)]
    site: Option<String>,
    #[serde(default)]
    environment: Option<String>,
    threshold: f64,
    /// "above" (cost/usage cap, default) or "below" (capacity floor).
    #[serde(default)]
    comparison: Option<String>,
}

/// PATCH-style update of a budget's mutable fields (swarm #19). Every field is
/// optional; an omitted field is left unchanged. The identity/scope columns
/// (metric_key, site, environment) are NOT updatable here — recreate to re-scope.
#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct MetricBudgetUpdateRequest {
    #[serde(default)]
    threshold: Option<f64>,
    #[serde(default)]
    comparison: Option<String>,
    #[serde(default)]
    enabled: Option<bool>,
}

/// A budget row as stored.
#[derive(sqlx::FromRow)]
struct MetricBudgetRow {
    id: String,
    metric_key: String,
    site: Option<String>,
    environment: Option<String>,
    threshold: f64,
    comparison: String,
    enabled: bool,
}

type BudgetSeriesKey = (String, Option<String>, Option<String>);

#[derive(sqlx::FromRow)]
struct BudgetStatusSampleRow {
    metric_key: String,
    site: Option<String>,
    environment: Option<String>,
    value: f64,
    observed_at: chrono::DateTime<chrono::Utc>,
    sample_rank: i64,
}

#[derive(Clone)]
struct BudgetSeriesAnalysis {
    summary: Option<ryuki_engine::metric_forecast::SeriesSummary>,
    projected_min: Option<f64>,
    projected_max: Option<f64>,
    truncated: bool,
    samples_used: usize,
    oldest_included_at: Option<chrono::DateTime<chrono::Utc>>,
}

/// Status endpoints fan out into per-definition metric work. Read at most one
/// row beyond this cap so oversized configuration fails explicitly before any
/// series or aggregate queries run; ordinary deployments retain their complete
/// all-definition status response.
const MAX_STATUS_DEFINITIONS: usize = 100;
const MAX_STATUS_SCOPE_VALUES_PER_AXIS: usize = 64;
const MAX_STATUS_SCOPE_COMBINATIONS: usize = 256;
const BUDGET_STATUS_SAMPLES_PER_SERIES: i64 = 250;
const BUDGET_STATUS_MAX_SAMPLES: usize =
    MAX_STATUS_DEFINITIONS * (BUDGET_STATUS_SAMPLES_PER_SERIES as usize + 1);

fn status_definition_query_limit() -> i64 {
    (MAX_STATUS_DEFINITIONS + 1) as i64
}

fn status_definition_overflow(count: usize) -> bool {
    count > MAX_STATUS_DEFINITIONS
}

/// Scoped definition reads use one bounded index probe per authorized nullable
/// scope tuple. Keep both each axis and their Cartesian product finite before
/// issuing any query, including the implicit NULL/platform-wide value.
fn status_scope_work_is_bounded(sites: Option<&[String]>, environments: Option<&[String]>) -> bool {
    let site_count = sites.map_or(1, |values| values.len().saturating_add(1));
    let environment_count = environments.map_or(1, |values| values.len().saturating_add(1));
    sites.is_none_or(|values| values.len() <= MAX_STATUS_SCOPE_VALUES_PER_AXIS)
        && environments.is_none_or(|values| values.len() <= MAX_STATUS_SCOPE_VALUES_PER_AXIS)
        && site_count
            .checked_mul(environment_count)
            .is_some_and(|count| count <= MAX_STATUS_SCOPE_COMBINATIONS)
}

async fn fetch_budget_status_definitions(
    pool: &sqlx::PgPool,
    sites: Option<&[String]>,
    environments: Option<&[String]>,
) -> Result<Vec<MetricBudgetRow>, sqlx::Error> {
    const COLUMNS: &str = "id, metric_key, site, environment, threshold, comparison, enabled";
    let limit = status_definition_query_limit();
    match (sites, environments) {
        (None, None) => {
            sqlx::query_as(&format!(
                "SELECT {COLUMNS} FROM metric_budgets WHERE enabled \
                 ORDER BY created_at DESC, id DESC LIMIT $1"
            ))
            .bind(limit)
            .fetch_all(pool)
            .await
        }
        (Some(sites), None) => {
            sqlx::query_as(&format!(
                "WITH site_scope(site, site_present) AS ( \
                     SELECT site, TRUE FROM unnest($1::text[]) AS input(site) \
                     UNION ALL SELECT ''::text, FALSE \
                 ), candidates AS ( \
                     SELECT definition.* FROM site_scope \
                     CROSS JOIN LATERAL ( \
                         SELECT {COLUMNS}, created_at FROM metric_budgets \
                         WHERE enabled \
                           AND (metric_budgets.site IS NOT NULL) = site_scope.site_present \
                           AND COALESCE(metric_budgets.site, '') = site_scope.site \
                         ORDER BY created_at DESC, id DESC LIMIT $2 \
                     ) AS definition \
                 ) \
                 SELECT {COLUMNS} FROM candidates \
                 ORDER BY created_at DESC, id DESC LIMIT $2"
            ))
            .bind(sites)
            .bind(limit)
            .fetch_all(pool)
            .await
        }
        (None, Some(environments)) => {
            sqlx::query_as(&format!(
                "WITH environment_scope(environment, environment_present) AS ( \
                     SELECT environment, TRUE \
                     FROM unnest($1::text[]) AS input(environment) \
                     UNION ALL SELECT ''::text, FALSE \
                 ), candidates AS ( \
                     SELECT definition.* FROM environment_scope \
                     CROSS JOIN LATERAL ( \
                         SELECT {COLUMNS}, created_at FROM metric_budgets \
                         WHERE enabled \
                           AND (metric_budgets.environment IS NOT NULL) = \
                               environment_scope.environment_present \
                           AND COALESCE(metric_budgets.environment, '') = \
                               environment_scope.environment \
                         ORDER BY created_at DESC, id DESC LIMIT $2 \
                     ) AS definition \
                 ) \
                 SELECT {COLUMNS} FROM candidates \
                 ORDER BY created_at DESC, id DESC LIMIT $2"
            ))
            .bind(environments)
            .bind(limit)
            .fetch_all(pool)
            .await
        }
        (Some(sites), Some(environments)) => {
            sqlx::query_as(&format!(
                "WITH site_scope(site, site_present) AS ( \
                     SELECT site, TRUE FROM unnest($1::text[]) AS input(site) \
                     UNION ALL SELECT ''::text, FALSE \
                 ), environment_scope(environment, environment_present) AS ( \
                     SELECT environment, TRUE \
                     FROM unnest($2::text[]) AS input(environment) \
                     UNION ALL SELECT ''::text, FALSE \
                 ), authorized_scope AS ( \
                     SELECT site, site_present, environment, environment_present \
                     FROM site_scope CROSS JOIN environment_scope \
                 ), candidates AS ( \
                     SELECT definition.* FROM authorized_scope \
                     CROSS JOIN LATERAL ( \
                         SELECT {COLUMNS}, created_at FROM metric_budgets \
                         WHERE enabled \
                           AND (metric_budgets.site IS NOT NULL) = \
                               authorized_scope.site_present \
                           AND COALESCE(metric_budgets.site, '') = authorized_scope.site \
                           AND (metric_budgets.environment IS NOT NULL) = \
                               authorized_scope.environment_present \
                           AND COALESCE(metric_budgets.environment, '') = \
                               authorized_scope.environment \
                         ORDER BY created_at DESC, id DESC LIMIT $3 \
                     ) AS definition \
                 ) \
                 SELECT {COLUMNS} FROM candidates \
                 ORDER BY created_at DESC, id DESC LIMIT $3"
            ))
            .bind(sites)
            .bind(environments)
            .bind(limit)
            .fetch_all(pool)
            .await
        }
    }
}

/// Load every distinct series needed by one bounded budget page in one SQL
/// statement. The lateral LIMIT lets the existing series index stop per key;
/// the outer LIMIT is a second aggregate materialization guard.
async fn fetch_budget_status_analyses(
    pool: &sqlx::PgPool,
    series: &[BudgetSeriesKey],
) -> Result<std::collections::HashMap<BudgetSeriesKey, BudgetSeriesAnalysis>, sqlx::Error> {
    let requested_sample_rows = series
        .len()
        .checked_mul(BUDGET_STATUS_SAMPLES_PER_SERIES as usize + 1)
        .ok_or_else(|| {
            sqlx::Error::Protocol("budget status sample bound overflowed".to_string())
        })?;
    if series.len() > MAX_STATUS_DEFINITIONS || requested_sample_rows > BUDGET_STATUS_MAX_SAMPLES {
        return Err(sqlx::Error::Protocol(
            "budget status sample bound exceeded".to_string(),
        ));
    }
    let metric_keys: Vec<String> = series.iter().map(|key| key.0.clone()).collect();
    let sites: Vec<String> = series
        .iter()
        .map(|key| key.1.clone().unwrap_or_default())
        .collect();
    let site_present: Vec<bool> = series.iter().map(|key| key.1.is_some()).collect();
    let environments: Vec<String> = series
        .iter()
        .map(|key| key.2.clone().unwrap_or_default())
        .collect();
    let environment_present: Vec<bool> = series.iter().map(|key| key.2.is_some()).collect();
    let rows: Vec<BudgetStatusSampleRow> = sqlx::query_as(
        "WITH inputs AS ( \
             SELECT metric_key, site, site_present, environment, environment_present \
             FROM unnest($1::text[], $2::text[], $3::bool[], $4::text[], $5::bool[]) \
                  AS input(metric_key, site, site_present, environment, environment_present) \
         ), series_keys AS ( \
             SELECT DISTINCT metric_key, site, site_present, environment, \
                             environment_present FROM inputs \
         ) \
         SELECT series_key.metric_key, \
                CASE WHEN series_key.site_present THEN series_key.site ELSE NULL::text END \
                    AS site, \
                CASE WHEN series_key.environment_present THEN series_key.environment \
                     ELSE NULL::text END AS environment, \
                sample.value, sample.observed_at, sample.sample_rank \
         FROM series_keys AS series_key \
         CROSS JOIN LATERAL ( \
             SELECT recent.value, recent.observed_at, recent.id, \
                    ROW_NUMBER() OVER ( \
                        ORDER BY recent.observed_at DESC, recent.id DESC \
                    ) AS sample_rank \
             FROM ( \
                 SELECT value, observed_at, id FROM metric_samples \
                 WHERE metric_key = series_key.metric_key \
                   AND (metric_samples.site IS NOT NULL) = series_key.site_present \
                   AND COALESCE(metric_samples.site, '') = series_key.site \
                   AND (metric_samples.environment IS NOT NULL) = \
                       series_key.environment_present \
                   AND COALESCE(metric_samples.environment, '') = series_key.environment \
                 ORDER BY observed_at DESC, id DESC LIMIT $6 \
             ) AS recent \
         ) AS sample \
         ORDER BY series_key.metric_key, series_key.site_present, series_key.site, \
                  series_key.environment_present, series_key.environment, \
                  sample.observed_at ASC, sample.id ASC \
         LIMIT $7",
    )
    .bind(&metric_keys)
    .bind(&sites)
    .bind(&site_present)
    .bind(&environments)
    .bind(&environment_present)
    .bind(BUDGET_STATUS_SAMPLES_PER_SERIES + 1)
    .bind(BUDGET_STATUS_MAX_SAMPLES as i64)
    .fetch_all(pool)
    .await?;
    if rows.len() > BUDGET_STATUS_MAX_SAMPLES {
        return Err(sqlx::Error::Protocol(
            "budget status aggregate sample bound exceeded".to_string(),
        ));
    }

    let mut by_series: std::collections::HashMap<
        BudgetSeriesKey,
        Vec<ryuki_engine::metric_forecast::MetricPoint>,
    > = std::collections::HashMap::new();
    let mut truncated_series: std::collections::HashSet<BudgetSeriesKey> =
        std::collections::HashSet::new();
    let mut oldest_included: std::collections::HashMap<
        BudgetSeriesKey,
        chrono::DateTime<chrono::Utc>,
    > = std::collections::HashMap::new();
    for row in rows {
        let key = (row.metric_key, row.site, row.environment);
        if row.sample_rank <= BUDGET_STATUS_SAMPLES_PER_SERIES {
            oldest_included
                .entry(key.clone())
                .or_insert(row.observed_at);
            by_series
                .entry(key)
                .or_default()
                .push(ryuki_engine::metric_forecast::MetricPoint {
                    t: row.observed_at.timestamp() as f64,
                    value: row.value,
                });
        } else {
            truncated_series.insert(key);
        }
    }

    Ok(by_series
        .into_iter()
        .map(|(key, points)| {
            let summary = ryuki_engine::metric_forecast::summarize(&points);
            let step = metric_series_step(&points);
            let projection = ryuki_engine::metric_forecast::project_forward(&points, step, 6);
            let projected_min = projection
                .iter()
                .map(|point| point.value)
                .filter(|value| value.is_finite())
                .reduce(f64::min);
            let projected_max = projection
                .iter()
                .map(|point| point.value)
                .filter(|value| value.is_finite())
                .reduce(f64::max);
            let oldest_included_at = oldest_included.remove(&key);
            let samples_used = points.len();
            let truncated = truncated_series.contains(&key);
            (
                key,
                BudgetSeriesAnalysis {
                    summary,
                    projected_min,
                    projected_max,
                    truncated,
                    samples_used,
                    oldest_included_at,
                },
            )
        })
        .collect())
}

/// POST /api/metrics/budgets — define a budget threshold on a metric. Execute-tier.
/// 503 when no database is configured.
async fn metrics_budget_create(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<MetricBudgetCreateRequest>,
) -> ApiResult {
    if !check_permission(&session, "execute") {
        return Err((
            StatusCode::FORBIDDEN,
            Json(json!({"error": "Execute-tier access is required to define budgets"})),
        ));
    }
    let metric_key = body.metric_key.trim();
    if let Some(msg) = metric_key_rejection(metric_key) {
        return Err((StatusCode::BAD_REQUEST, Json(json!({ "error": msg }))));
    }
    if metric_scope_too_long(&body.site) || metric_scope_too_long(&body.environment) {
        return Err((
            StatusCode::BAD_REQUEST,
            Json(json!({"error": "site/environment must be at most 200 characters"})),
        ));
    }
    if !body.threshold.is_finite() {
        return Err((
            StatusCode::BAD_REQUEST,
            Json(json!({"error": "threshold must be a finite number"})),
        ));
    }
    let comparison = match body.comparison.as_deref() {
        None | Some("above") => "above",
        Some("below") => "below",
        Some(_) => {
            return Err((
                StatusCode::BAD_REQUEST,
                Json(json!({"error": "comparison must be 'above' or 'below'"})),
            ));
        }
    };
    let norm = |o: &Option<String>| {
        o.as_deref()
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(str::to_string)
    };
    // #2: enforce scope BEFORE any DB access; bind the EFFECTIVE (site,
    // environment) into the INSERT — NEVER the raw body — so a scoped principal
    // cannot define a budget for another scope.
    let (f_site, f_env) =
        enforce_scope_filters(&session, norm(&body.site), norm(&body.environment))?;
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let id = uuid::Uuid::new_v4().to_string();
    // Persist + audit ATOMICALLY: a budget never lands without its
    // durable audit_log row (#7).
    let mut tx = pool.begin().await.map_err(db_error)?;
    sqlx::query(
        "INSERT INTO metric_budgets \
         (id, metric_key, site, environment, threshold, comparison) \
         VALUES ($1, $2, $3, $4, $5, $6)",
    )
    .bind(&id)
    .bind(metric_key)
    .bind(&f_site)
    .bind(&f_env)
    .bind(body.threshold)
    .bind(comparison)
    .execute(&mut *tx)
    .await
    .map_err(|e| {
        tracing::error!(error = %e, "creating metric budget failed");
        (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(json!({"error": "could not create budget"})),
        )
    })?;
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "metric-budget-create",
            None,
            "created",
            json!({
                "budget_id": &id,
                "metric_key": metric_key,
                "site": &f_site,
                "environment": &f_env,
            }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;
    Ok(Json(json!({"id": id, "created": true})))
}

/// GET /api/metrics/budgets — list all defined budgets. Request-tier read.
async fn metrics_budget_list(
    AuthExtractor(session): AuthExtractor,
    Query(q): Query<AdminListPage>,
) -> ApiResult {
    if !check_permission(&session, "request") {
        return Err((
            StatusCode::FORBIDDEN,
            Json(json!({"error": "authentication is required to read budgets"})),
        ));
    }
    // #14: bound the page (generous default keeps seed-scale callers unaffected).
    let limit = q.limit.unwrap_or(500).clamp(1, 1000);
    let offset = q.offset.unwrap_or(0).max(0);
    let Some(pool) = get_db() else {
        return Ok(Json(json!({
            "budgets": [], "durable": false,
            "total": 0, "limit": limit, "offset": offset,
        })));
    };
    // #2: a scoped principal sees only in-scope (or platform-wide None) budget
    // definitions — consistent with metrics_budget_status. Previously applied
    // row-by-row in Rust after a fetch-all; #14 pushes the SAME per-axis
    // `scope_permits` containment into SQL so a LIMIT/OFFSET page and the total
    // reflect the filtered set: on each axis independently, an unrestricted
    // (LITERALLY empty) scope matches everything, and otherwise the row's axis
    // must be NULL (platform-wide passes for every principal) or a held value.
    // Built as a 4-branch (site-axis × env-axis) dynamic WHERE — each branch a
    // static shape with bound arrays, not the OR-NULL scalar antipattern that
    // seq-scans under a generic prepared plan.
    let site_vals = nullable_axis_scope_values(&session.site_scope);
    let env_vals = nullable_axis_scope_values(&session.environment_scope);
    const BUDGET_COLS: &str = "id, metric_key, site, environment, threshold, comparison, enabled";
    // #14: `created_at` is non-unique → append the unique PK `id` as the
    // tie-breaker so LIMIT/OFFSET pages are a stable cut.
    const BUDGET_ORDER: &str = "ORDER BY created_at DESC, id DESC";
    let page_res: Result<Vec<MetricBudgetRow>, sqlx::Error> = match (&site_vals, &env_vals) {
        (None, None) => {
            sqlx::query_as(&format!(
                "SELECT {BUDGET_COLS} FROM metric_budgets {BUDGET_ORDER} LIMIT $1 OFFSET $2"
            ))
            .bind(limit)
            .bind(offset)
            .fetch_all(pool)
            .await
        }
        (Some(sites), None) => {
            sqlx::query_as(&format!(
                "SELECT {BUDGET_COLS} FROM metric_budgets \
                 WHERE (site IS NULL OR site = ANY($1)) \
                 {BUDGET_ORDER} LIMIT $2 OFFSET $3"
            ))
            .bind(sites)
            .bind(limit)
            .bind(offset)
            .fetch_all(pool)
            .await
        }
        (None, Some(envs)) => {
            sqlx::query_as(&format!(
                "SELECT {BUDGET_COLS} FROM metric_budgets \
                 WHERE (environment IS NULL OR environment = ANY($1)) \
                 {BUDGET_ORDER} LIMIT $2 OFFSET $3"
            ))
            .bind(envs)
            .bind(limit)
            .bind(offset)
            .fetch_all(pool)
            .await
        }
        (Some(sites), Some(envs)) => {
            sqlx::query_as(&format!(
                "SELECT {BUDGET_COLS} FROM metric_budgets \
                 WHERE (site IS NULL OR site = ANY($1)) \
                   AND (environment IS NULL OR environment = ANY($2)) \
                 {BUDGET_ORDER} LIMIT $3 OFFSET $4"
            ))
            .bind(sites)
            .bind(envs)
            .bind(limit)
            .bind(offset)
            .fetch_all(pool)
            .await
        }
    };
    let rows: Vec<MetricBudgetRow> = match page_res {
        Ok(rows) => rows,
        Err(e) => {
            tracing::error!(error = %e, "listing budgets failed");
            return Err((
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(json!({"error": "could not list budgets"})),
            ));
        }
    };
    // Sibling COUNT with the IDENTICAL WHERE/binds (minus LIMIT/OFFSET), so the
    // reported total is the full filtered set regardless of the page bounds.
    let total_res: Result<i64, sqlx::Error> = match (&site_vals, &env_vals) {
        (None, None) => {
            sqlx::query_scalar("SELECT COUNT(*) FROM metric_budgets")
                .fetch_one(pool)
                .await
        }
        (Some(sites), None) => {
            sqlx::query_scalar(
                "SELECT COUNT(*) FROM metric_budgets WHERE (site IS NULL OR site = ANY($1))",
            )
            .bind(sites)
            .fetch_one(pool)
            .await
        }
        (None, Some(envs)) => {
            sqlx::query_scalar(
                "SELECT COUNT(*) FROM metric_budgets \
                 WHERE (environment IS NULL OR environment = ANY($1))",
            )
            .bind(envs)
            .fetch_one(pool)
            .await
        }
        (Some(sites), Some(envs)) => {
            sqlx::query_scalar(
                "SELECT COUNT(*) FROM metric_budgets \
                 WHERE (site IS NULL OR site = ANY($1)) \
                   AND (environment IS NULL OR environment = ANY($2))",
            )
            .bind(sites)
            .bind(envs)
            .fetch_one(pool)
            .await
        }
    };
    let total: i64 = match total_res {
        Ok(total) => total,
        Err(e) => {
            tracing::error!(error = %e, "counting budgets failed");
            return Err((
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(json!({"error": "could not list budgets"})),
            ));
        }
    };
    let budgets: Vec<Value> = rows
        .iter()
        .map(|b| {
            json!({
                "id": b.id,
                "metric_key": b.metric_key,
                "site": b.site,
                "environment": b.environment,
                "threshold": b.threshold,
                "comparison": b.comparison,
                "enabled": b.enabled,
            })
        })
        .collect();
    Ok(Json(json!({
        "budgets": budgets,
        "durable": true,
        "total": total,
        "limit": limit,
        "offset": offset,
    })))
}

/// GET /api/metrics/budgets/status — evaluate every ENABLED budget against its
/// metric series, reporting current and projected breaches. Request-tier read.
/// 503 when no database is configured.
async fn metrics_budget_status(AuthExtractor(session): AuthExtractor) -> ApiResult {
    if !check_permission(&session, "request") {
        return Err((
            StatusCode::FORBIDDEN,
            Json(json!({"error": "authentication is required to read budget status"})),
        ));
    }
    let pool = get_db().ok_or_else(status_503_no_db)?;
    // Push both authorization axes into SQL and fetch at most cap+1 rows. Scope
    // filtering after a global fetch would still let foreign definitions consume
    // the work budget before visible rows are reached.
    let site_vals = nullable_axis_scope_values(&session.site_scope);
    let env_vals = nullable_axis_scope_values(&session.environment_scope);
    if !status_scope_work_is_bounded(site_vals.as_deref(), env_vals.as_deref()) {
        return Err((
            StatusCode::SERVICE_UNAVAILABLE,
            Json(json!({
                "error": "budget status scope exceeds the bounded definition-query capacity",
                "maximum_scope_values_per_axis": MAX_STATUS_SCOPE_VALUES_PER_AXIS,
                "maximum_scope_combinations": MAX_STATUS_SCOPE_COMBINATIONS,
            })),
        ));
    }
    let query_result =
        fetch_budget_status_definitions(pool, site_vals.as_deref(), env_vals.as_deref()).await;
    // Do NOT swallow a failure of the budget query into "no budgets" — for an
    // alerting surface that would silently hide every budget. Fail loud.
    let budgets = match query_result {
        Ok(rows) => rows,
        Err(e) => {
            tracing::error!(error = %e, "listing budgets for status failed");
            return Err((
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(json!({"error": "could not evaluate budget status"})),
            ));
        }
    };
    if status_definition_overflow(budgets.len()) {
        return Err((
            StatusCode::SERVICE_UNAVAILABLE,
            Json(json!({
                "error": "too many enabled budgets are visible to evaluate safely",
                "maximum": MAX_STATUS_DEFINITIONS,
            })),
        ));
    }

    let budget_series: Vec<BudgetSeriesKey> = budgets
        .iter()
        .map(|budget| {
            (
                budget.metric_key.clone(),
                budget.site.clone(),
                budget.environment.clone(),
            )
        })
        .collect();
    let analyses = match fetch_budget_status_analyses(pool, &budget_series).await {
        Ok(analyses) => analyses,
        Err(e) => {
            tracing::error!(error = %e, "batch-loading budget status series failed");
            return Err((
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(json!({"error": "could not evaluate budget status"})),
            ));
        }
    };
    let mut results: Vec<Value> = Vec::new();
    let mut breached_count = 0u64;
    let mut errored_count = 0u64;
    for b in &budgets {
        let comparison =
            ryuki_engine::metric_budget::BudgetComparison::from_str_or_above(&b.comparison);
        // All thresholds sharing one series reuse the same bounded fetch,
        // summary, and forecast. An absent key is the legitimate no-data case.
        let series_key = (b.metric_key.clone(), b.site.clone(), b.environment.clone());
        let Some(analysis) = analyses.get(&series_key) else {
            errored_count += 1;
            results.push(json!({
                "id": b.id,
                "metric_key": b.metric_key,
                "site": b.site,
                "environment": b.environment,
                "status": "insufficient-data",
                "coverage": {
                    "samples_used": 0,
                    "maximum_samples_per_series": BUDGET_STATUS_SAMPLES_PER_SERIES,
                    "truncated": false,
                },
            }));
            continue;
        };
        if analysis.truncated {
            errored_count += 1;
            results.push(json!({
                "id": b.id,
                "metric_key": b.metric_key,
                "site": b.site,
                "environment": b.environment,
                "status": "partial",
                "error": "the budget series exceeds the bounded sample capacity",
                "coverage": {
                    "samples_used": analysis.samples_used,
                    "maximum_samples_per_series": BUDGET_STATUS_SAMPLES_PER_SERIES,
                    "oldest_included_at": analysis.oldest_included_at,
                    "has_older_samples": true,
                    "truncated": true,
                },
            }));
            continue;
        }
        let summary = analysis.summary;
        let projected_extreme = match comparison {
            ryuki_engine::metric_budget::BudgetComparison::Below => analysis.projected_min,
            ryuki_engine::metric_budget::BudgetComparison::Above => analysis.projected_max,
        };
        let eval = ryuki_engine::metric_budget::evaluate_budget(
            b.threshold,
            comparison,
            summary.as_ref(),
            projected_extreme,
        );
        let breached = eval.breached_now || eval.breached_projected;
        if breached {
            breached_count += 1;
        }
        results.push(json!({
            "id": b.id,
            "metric_key": b.metric_key,
            "site": b.site,
            "environment": b.environment,
            "status": if breached { "breached" } else { "ok" },
            "evaluation": eval,
            "coverage": {
                "samples_used": analysis.samples_used,
                "maximum_samples_per_series": BUDGET_STATUS_SAMPLES_PER_SERIES,
                "oldest_included_at": analysis.oldest_included_at,
                "has_older_samples": false,
                "truncated": false,
            },
        }));
    }

    // `degraded` whenever any budget could not be evaluated — the caller must not
    // read a clean `breached_count` as "all budgets are healthy".
    // overall_status must reflect BREACHES, not just query/data errors — otherwise a
    // health gate reading `overall_status == "ok"` sees green while SLOs/budgets are
    // actively breached (breached_count > 0). errored (unevaluable) outranks breached.
    let overall_status = if errored_count > 0 {
        "degraded"
    } else if breached_count > 0 {
        "breached"
    } else {
        "ok"
    };
    Ok(Json(json!({
        "budgets": results,
        "breached_count": breached_count,
        "errored_count": errored_count,
        "overall_status": overall_status,
    })))
}

/// Query params for commitment/reserved-capacity modeling (#54).
#[derive(Debug, Deserialize, Default)]
struct MetricCommitmentParams {
    metric_key: Option<String>,
    site: Option<String>,
    environment: Option<String>,
    on_demand_rate: Option<f64>,
    commitment_rate: Option<f64>,
    committed_units: Option<f64>,
    /// Optional usage override; when absent, the series mean is used.
    usage: Option<f64>,
}

/// GET /api/metrics/commitment — model the cost of a reserved/committed capacity
/// level vs pure on-demand for a metric. `metric_key`, `on_demand_rate`,
/// `commitment_rate`, and `committed_units` are required; `usage` defaults to the
/// metric's mean. Request-tier read. 503 when no database is configured.
async fn metrics_commitment(
    AuthExtractor(session): AuthExtractor,
    Query(params): Query<MetricCommitmentParams>,
) -> ApiResult {
    if !check_permission(&session, "request") {
        return Err((
            StatusCode::FORBIDDEN,
            Json(json!({"error": "authentication is required to model commitments"})),
        ));
    }
    let Some(metric_key) = params
        .metric_key
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
    else {
        return Err((
            StatusCode::BAD_REQUEST,
            Json(json!({"error": "metric_key is required"})),
        ));
    };
    if let Some(msg) = metric_key_rejection(metric_key) {
        return Err((StatusCode::BAD_REQUEST, Json(json!({ "error": msg }))));
    }
    if metric_scope_too_long(&params.site) || metric_scope_too_long(&params.environment) {
        return Err((
            StatusCode::BAD_REQUEST,
            Json(json!({"error": "site/environment must be at most 200 characters"})),
        ));
    }
    let (Some(on_demand_rate), Some(commitment_rate), Some(committed_units)) = (
        params.on_demand_rate,
        params.commitment_rate,
        params.committed_units,
    ) else {
        return Err((
            StatusCode::BAD_REQUEST,
            Json(json!({
                "error": "on_demand_rate, commitment_rate, and committed_units are required"
            })),
        ));
    };
    for (name, val) in [
        ("on_demand_rate", Some(on_demand_rate)),
        ("commitment_rate", Some(commitment_rate)),
        ("committed_units", Some(committed_units)),
        ("usage", params.usage),
    ] {
        // Reject non-finite OR negative before any DB work — a cost rate, a
        // committed level, or a usage cannot be negative.
        if val.is_some_and(|v| !v.is_finite() || v < 0.0) {
            return Err((
                StatusCode::BAD_REQUEST,
                Json(json!({ "error": format!("{name} must be a finite, non-negative number") })),
            ));
        }
    }
    let norm = |o: &Option<String>| {
        o.as_deref()
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(str::to_string)
    };
    // #2: enforce the session's site/environment scopes before any DB access.
    let (f_site, f_env) =
        enforce_scope_filters(&session, norm(&params.site), norm(&params.environment))?;
    let pool = get_db().ok_or_else(status_503_no_db)?;
    // Usage = the explicit override (no DB needed), else the series mean. Only
    // query the series on the fallback path, so an explicit-usage model never
    // fails on an empty series or a DB outage.
    let usage = match params.usage {
        Some(u) => u,
        None => {
            let rows = match fetch_metric_series_rows(pool, metric_key, &f_site, &f_env).await {
                Ok(rows) => rows,
                Err(e) => {
                    tracing::error!(error = %e, "querying metric series for commitment failed");
                    return Err((
                        StatusCode::INTERNAL_SERVER_ERROR,
                        Json(json!({"error": "could not query metric series"})),
                    ));
                }
            };
            let points: Vec<ryuki_engine::metric_forecast::MetricPoint> = rows
                .iter()
                .map(|r| ryuki_engine::metric_forecast::MetricPoint {
                    t: r.observed_at.timestamp() as f64,
                    value: r.value,
                })
                .collect();
            match ryuki_engine::metric_forecast::summarize(&points) {
                Some(s) => s.mean,
                None => {
                    return Err((
                        StatusCode::BAD_REQUEST,
                        Json(json!({
                            "error": "no usage data for this metric; record samples or pass a usage override"
                        })),
                    ));
                }
            }
        }
    };
    let Some(model) = ryuki_engine::metric_commitment::model_commitment(
        usage,
        on_demand_rate,
        commitment_rate,
        committed_units,
    ) else {
        return Err((
            StatusCode::BAD_REQUEST,
            Json(json!({"error": "rates, committed_units, and usage must be non-negative"})),
        ));
    };

    Ok(Json(json!({
        "metric_key": metric_key,
        "site": f_site,
        "environment": f_env,
        "usage_source": if params.usage.is_some() { "override" } else { "series_mean" },
        "model": model,
    })))
}

// ─── SLO / error-budget tracking (#25) ───

const SLO_COLUMNS: &str =
    "id, name, target, window_days, good_metric_key, total_metric_key, site, environment, enabled";

/// One persisted slo_definitions row.
#[derive(sqlx::FromRow)]
struct SloDefRow {
    id: String,
    name: String,
    target: f64,
    window_days: i32,
    good_metric_key: String,
    total_metric_key: String,
    site: Option<String>,
    environment: Option<String>,
    enabled: bool,
}

#[derive(sqlx::FromRow)]
struct SloMetricSumsRow {
    id: String,
    good: f64,
    total: f64,
    truncated: bool,
    good_truncated: bool,
    total_truncated: bool,
    good_samples_used: i64,
    total_samples_used: i64,
    good_oldest_included_at: Option<chrono::DateTime<chrono::Utc>>,
    total_oldest_included_at: Option<chrono::DateTime<chrono::Utc>>,
}

#[derive(Clone)]
struct SloMetricTotals {
    good: f64,
    total: f64,
    truncated: bool,
    good_truncated: bool,
    total_truncated: bool,
    good_samples_used: i64,
    total_samples_used: i64,
    good_oldest_included_at: Option<chrono::DateTime<chrono::Utc>>,
    total_oldest_included_at: Option<chrono::DateTime<chrono::Utc>>,
}

struct SloMetricInput {
    id: String,
    window_days: i32,
    good_metric_key: String,
    total_metric_key: String,
    site: Option<String>,
    environment: Option<String>,
}

impl From<&SloDefRow> for SloMetricInput {
    fn from(value: &SloDefRow) -> Self {
        Self {
            id: value.id.clone(),
            window_days: value.window_days,
            good_metric_key: value.good_metric_key.clone(),
            total_metric_key: value.total_metric_key.clone(),
            site: value.site.clone(),
            environment: value.environment.clone(),
        }
    }
}

const SLO_STATUS_SAMPLES_PER_SERIES: i64 = 2_000;
const SLO_STATUS_MAX_DISTINCT_SERIES: usize = MAX_STATUS_DEFINITIONS * 2;
const SLO_STATUS_MAX_SAMPLE_ROWS: usize =
    SLO_STATUS_MAX_DISTINCT_SERIES * (SLO_STATUS_SAMPLES_PER_SERIES as usize + 1);

async fn fetch_slo_status_definitions(
    pool: &sqlx::PgPool,
    sites: Option<&[String]>,
    environments: Option<&[String]>,
) -> Result<Vec<SloDefRow>, sqlx::Error> {
    let limit = status_definition_query_limit();
    match (sites, environments) {
        (None, None) => {
            sqlx::query_as(&format!(
                "SELECT {SLO_COLUMNS} FROM slo_definitions WHERE enabled \
                 ORDER BY created_at DESC, id DESC LIMIT $1"
            ))
            .bind(limit)
            .fetch_all(pool)
            .await
        }
        (Some(sites), None) => {
            sqlx::query_as(&format!(
                "WITH site_scope(site, site_present) AS ( \
                     SELECT site, TRUE FROM unnest($1::text[]) AS input(site) \
                     UNION ALL SELECT ''::text, FALSE \
                 ), candidates AS ( \
                     SELECT definition.* FROM site_scope \
                     CROSS JOIN LATERAL ( \
                         SELECT {SLO_COLUMNS}, created_at FROM slo_definitions \
                         WHERE enabled \
                           AND (slo_definitions.site IS NOT NULL) = site_scope.site_present \
                           AND COALESCE(slo_definitions.site, '') = site_scope.site \
                         ORDER BY created_at DESC, id DESC LIMIT $2 \
                     ) AS definition \
                 ) \
                 SELECT {SLO_COLUMNS} FROM candidates \
                 ORDER BY created_at DESC, id DESC LIMIT $2"
            ))
            .bind(sites)
            .bind(limit)
            .fetch_all(pool)
            .await
        }
        (None, Some(environments)) => {
            sqlx::query_as(&format!(
                "WITH environment_scope(environment, environment_present) AS ( \
                     SELECT environment, TRUE \
                     FROM unnest($1::text[]) AS input(environment) \
                     UNION ALL SELECT ''::text, FALSE \
                 ), candidates AS ( \
                     SELECT definition.* FROM environment_scope \
                     CROSS JOIN LATERAL ( \
                         SELECT {SLO_COLUMNS}, created_at FROM slo_definitions \
                         WHERE enabled \
                           AND (slo_definitions.environment IS NOT NULL) = \
                               environment_scope.environment_present \
                           AND COALESCE(slo_definitions.environment, '') = \
                               environment_scope.environment \
                         ORDER BY created_at DESC, id DESC LIMIT $2 \
                     ) AS definition \
                 ) \
                 SELECT {SLO_COLUMNS} FROM candidates \
                 ORDER BY created_at DESC, id DESC LIMIT $2"
            ))
            .bind(environments)
            .bind(limit)
            .fetch_all(pool)
            .await
        }
        (Some(sites), Some(environments)) => {
            sqlx::query_as(&format!(
                "WITH site_scope(site, site_present) AS ( \
                     SELECT site, TRUE FROM unnest($1::text[]) AS input(site) \
                     UNION ALL SELECT ''::text, FALSE \
                 ), environment_scope(environment, environment_present) AS ( \
                     SELECT environment, TRUE \
                     FROM unnest($2::text[]) AS input(environment) \
                     UNION ALL SELECT ''::text, FALSE \
                 ), authorized_scope AS ( \
                     SELECT site, site_present, environment, environment_present \
                     FROM site_scope CROSS JOIN environment_scope \
                 ), candidates AS ( \
                     SELECT definition.* FROM authorized_scope \
                     CROSS JOIN LATERAL ( \
                         SELECT {SLO_COLUMNS}, created_at FROM slo_definitions \
                         WHERE enabled \
                           AND (slo_definitions.site IS NOT NULL) = \
                               authorized_scope.site_present \
                           AND COALESCE(slo_definitions.site, '') = authorized_scope.site \
                           AND (slo_definitions.environment IS NOT NULL) = \
                               authorized_scope.environment_present \
                           AND COALESCE(slo_definitions.environment, '') = \
                               authorized_scope.environment \
                         ORDER BY created_at DESC, id DESC LIMIT $3 \
                     ) AS definition \
                 ) \
                 SELECT {SLO_COLUMNS} FROM candidates \
                 ORDER BY created_at DESC, id DESC LIMIT $3"
            ))
            .bind(sites)
            .bind(environments)
            .bind(limit)
            .fetch_all(pool)
            .await
        }
    }
}

/// Body for creating an SLO definition.
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct SloCreateRequest {
    name: String,
    target: f64,
    #[serde(default)]
    window_days: Option<i32>,
    good_metric_key: String,
    total_metric_key: String,
    #[serde(default)]
    site: Option<String>,
    #[serde(default)]
    environment: Option<String>,
}

/// PATCH-style update of an SLO's mutable fields (swarm #20). Every field is
/// optional; an omitted field is left unchanged. The metric keys and scope
/// (good/total_metric_key, site, environment) are NOT updatable here — recreate
/// to re-target or re-scope.
#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct SloUpdateRequest {
    #[serde(default)]
    name: Option<String>,
    #[serde(default)]
    target: Option<f64>,
    #[serde(default)]
    window_days: Option<i32>,
    #[serde(default)]
    enabled: Option<bool>,
}

/// Sum both counters from a server-built immutable definition snapshot. Each
/// distinct series/window performs an indexed newest-first read of at most
/// `SLO_STATUS_SAMPLES_PER_SERIES + 1` rows. The lookahead row makes truncation
/// explicit: callers must report `partial`, never a false compliant/breached
/// result. The closed upper bound excludes future-dated samples.
async fn sum_slo_metrics_in_batch(
    pool: &sqlx::PgPool,
    slos: &[SloMetricInput],
    until: chrono::DateTime<chrono::Utc>,
) -> Result<std::collections::HashMap<String, SloMetricTotals>, sqlx::Error> {
    let requested_sample_rows = slos
        .len()
        .checked_mul(2)
        .and_then(|series| series.checked_mul(SLO_STATUS_SAMPLES_PER_SERIES as usize + 1))
        .ok_or_else(|| sqlx::Error::Protocol("SLO status sample bound overflowed".to_string()))?;
    if slos.len() > MAX_STATUS_DEFINITIONS || requested_sample_rows > SLO_STATUS_MAX_SAMPLE_ROWS {
        return Err(sqlx::Error::Protocol(
            "SLO status sample bound exceeded".to_string(),
        ));
    }
    let ids: Vec<String> = slos.iter().map(|slo| slo.id.clone()).collect();
    let good_metric_keys: Vec<String> =
        slos.iter().map(|slo| slo.good_metric_key.clone()).collect();
    let total_metric_keys: Vec<String> = slos
        .iter()
        .map(|slo| slo.total_metric_key.clone())
        .collect();
    let sites: Vec<String> = slos
        .iter()
        .map(|slo| slo.site.clone().unwrap_or_default())
        .collect();
    let site_present: Vec<bool> = slos.iter().map(|slo| slo.site.is_some()).collect();
    let environments: Vec<String> = slos
        .iter()
        .map(|slo| slo.environment.clone().unwrap_or_default())
        .collect();
    let environment_present: Vec<bool> = slos.iter().map(|slo| slo.environment.is_some()).collect();
    let window_days: Vec<i32> = slos.iter().map(|slo| slo.window_days).collect();
    let rows: Vec<SloMetricSumsRow> = sqlx::query_as(
        "WITH definitions AS ( \
             SELECT id, good_metric_key, total_metric_key, window_days, \
                    site, site_present, environment, environment_present \
             FROM unnest( \
                 $1::text[], $2::text[], $3::text[], $4::text[], $5::bool[], \
                 $6::text[], $7::bool[], $8::int4[] \
             ) AS input( \
                 id, good_metric_key, total_metric_key, site, site_present, \
                 environment, environment_present, window_days \
             ) \
         ), series_keys AS ( \
             SELECT good_metric_key AS metric_key, site, site_present, environment, \
                    environment_present, window_days \
             FROM definitions \
             UNION \
             SELECT total_metric_key AS metric_key, site, site_present, environment, \
                    environment_present, window_days \
             FROM definitions \
         ), series_sums AS ( \
             SELECT series_key.metric_key, series_key.site, series_key.site_present, \
                    series_key.environment, series_key.environment_present, \
                    series_key.window_days, \
                    COALESCE(SUM(sample.value) FILTER ( \
                        WHERE sample.sample_rank <= $11 \
                    ), 0.0)::float8 AS value_sum, \
                    COALESCE(MAX(sample.sample_rank) > $11, FALSE) AS truncated, \
                    COUNT(sample.sample_rank) FILTER ( \
                        WHERE sample.sample_rank <= $11 \
                    )::bigint AS samples_used, \
                    MIN(sample.observed_at) FILTER ( \
                        WHERE sample.sample_rank <= $11 \
                    ) AS oldest_included_at \
             FROM series_keys AS series_key \
             LEFT JOIN LATERAL ( \
                 SELECT recent.value, recent.observed_at, \
                        ROW_NUMBER() OVER ( \
                            ORDER BY recent.observed_at DESC, recent.id DESC \
                        ) AS sample_rank \
                 FROM ( \
                     SELECT value, observed_at, id FROM metric_samples \
                     WHERE metric_key = series_key.metric_key \
                       AND (metric_samples.site IS NOT NULL) = series_key.site_present \
                       AND COALESCE(metric_samples.site, '') = series_key.site \
                       AND (metric_samples.environment IS NOT NULL) = \
                           series_key.environment_present \
                       AND COALESCE(metric_samples.environment, '') = \
                           series_key.environment \
                       AND observed_at >= $9 - series_key.window_days * INTERVAL '1 day' \
                       AND observed_at <= $9 \
                     ORDER BY observed_at DESC, id DESC LIMIT $10 \
                 ) AS recent \
             ) AS sample ON TRUE \
             GROUP BY series_key.metric_key, series_key.site, series_key.site_present, \
                      series_key.environment, series_key.environment_present, \
                      series_key.window_days \
         ) \
         SELECT definition.id, good.value_sum AS good, total.value_sum AS total, \
                (good.truncated OR total.truncated) AS truncated, \
                good.truncated AS good_truncated, \
                total.truncated AS total_truncated, \
                good.samples_used AS good_samples_used, \
                total.samples_used AS total_samples_used, \
                good.oldest_included_at AS good_oldest_included_at, \
                total.oldest_included_at AS total_oldest_included_at \
         FROM definitions AS definition \
         JOIN series_sums AS good \
           ON good.metric_key = definition.good_metric_key \
          AND good.site_present = definition.site_present \
          AND good.site = definition.site \
          AND good.environment_present = definition.environment_present \
          AND good.environment = definition.environment \
          AND good.window_days = definition.window_days \
         JOIN series_sums AS total \
           ON total.metric_key = definition.total_metric_key \
          AND total.site_present = definition.site_present \
          AND total.site = definition.site \
          AND total.environment_present = definition.environment_present \
          AND total.environment = definition.environment \
          AND total.window_days = definition.window_days",
    )
    .bind(&ids)
    .bind(&good_metric_keys)
    .bind(&total_metric_keys)
    .bind(&sites)
    .bind(&site_present)
    .bind(&environments)
    .bind(&environment_present)
    .bind(&window_days)
    .bind(until)
    .bind(SLO_STATUS_SAMPLES_PER_SERIES + 1)
    .bind(SLO_STATUS_SAMPLES_PER_SERIES)
    .fetch_all(pool)
    .await?;
    if rows.len() != slos.len() {
        return Err(sqlx::Error::Protocol(
            "SLO status snapshot aggregate returned an incomplete definition set".to_string(),
        ));
    }
    Ok(rows
        .into_iter()
        .map(|row| {
            (
                row.id,
                SloMetricTotals {
                    good: row.good,
                    total: row.total,
                    truncated: row.truncated,
                    good_truncated: row.good_truncated,
                    total_truncated: row.total_truncated,
                    good_samples_used: row.good_samples_used,
                    total_samples_used: row.total_samples_used,
                    good_oldest_included_at: row.good_oldest_included_at,
                    total_oldest_included_at: row.total_oldest_included_at,
                },
            )
        })
        .collect())
}

/// POST /api/metrics/slo — define an SLO. Execute-tier. 503 when no DB.
/// `good_metric_key`/`total_metric_key` MUST be COUNTER-style event-count
/// metrics — the status endpoint SUMs them over the window, which is only
/// meaningful for additive samples (a gauge would produce nonsense compliance).
async fn slo_create(
    AuthExtractor(session): AuthExtractor,
    Json(b): Json<SloCreateRequest>,
) -> ApiResult {
    if !check_permission(&session, "execute") {
        return Err((
            StatusCode::FORBIDDEN,
            Json(json!({"error": "Execute-tier access is required to define SLOs"})),
        ));
    }
    let name = b.name.trim();
    if name.is_empty() || name.len() > 200 {
        return Err(status_400("name must be 1..=200 characters"));
    }
    if !(b.target.is_finite() && b.target > 0.0 && b.target < 1.0) {
        return Err(status_400(
            "target must be a fraction in the open interval (0, 1)",
        ));
    }
    let window = b.window_days.unwrap_or(30);
    if !(1..=365).contains(&window) {
        return Err(status_400("window_days must be between 1 and 365"));
    }
    let good_key = b.good_metric_key.trim();
    let total_key = b.total_metric_key.trim();
    if let Some(msg) = metric_key_rejection(good_key).or_else(|| metric_key_rejection(total_key)) {
        return Err(status_400(msg));
    }
    if metric_scope_too_long(&b.site) || metric_scope_too_long(&b.environment) {
        return Err(status_400(
            "site/environment must be at most 200 characters",
        ));
    }
    let norm = |o: &Option<String>| {
        o.as_deref()
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(str::to_string)
    };
    // #2: enforce scope BEFORE any DB access; bind the EFFECTIVE (site,
    // environment) into the INSERT — NEVER the raw body — so a scoped principal
    // cannot define an SLO for another scope.
    let (f_site, f_env) = enforce_scope_filters(&session, norm(&b.site), norm(&b.environment))?;
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let id = uuid::Uuid::new_v4().to_string();
    // Persist + audit ATOMICALLY: an SLO definition never lands without its
    // durable audit_log row (#7).
    let mut tx = pool.begin().await.map_err(db_error)?;
    sqlx::query(
        "INSERT INTO slo_definitions \
         (id, name, target, window_days, good_metric_key, total_metric_key, site, environment) \
         VALUES ($1, $2, $3, $4, $5, $6, $7, $8)",
    )
    .bind(&id)
    .bind(name)
    .bind(b.target)
    .bind(window)
    .bind(good_key)
    .bind(total_key)
    .bind(&f_site)
    .bind(&f_env)
    .execute(&mut *tx)
    .await
    .map_err(db_error)?;
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "slo-create",
            None,
            "created",
            json!({
                "slo_id": &id,
                "name": name,
                "site": &f_site,
                "environment": &f_env,
            }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;
    Ok(Json(json!({ "id": id, "created": true })))
}

/// GET /api/metrics/slo — list SLO definitions. Request-tier read.
async fn slo_list(AuthExtractor(session): AuthExtractor) -> ApiResult {
    if !check_permission(&session, "request") {
        return Err((
            StatusCode::FORBIDDEN,
            Json(json!({"error": "authentication is required to read SLOs"})),
        ));
    }
    let Some(pool) = get_db() else {
        return Ok(Json(json!({"slos": [], "durable": false})));
    };
    let rows: Vec<SloDefRow> = match sqlx::query_as(&format!(
        "SELECT {SLO_COLUMNS} FROM slo_definitions ORDER BY created_at DESC LIMIT {MAX_LIST_ROWS}"
    ))
    .fetch_all(pool)
    .await
    {
        Ok(rows) => rows,
        Err(e) => {
            tracing::error!(error = %e, "listing SLOs failed");
            return Err((
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(json!({"error": "could not list SLOs"})),
            ));
        }
    };
    let slos: Vec<Value> = rows
        .iter()
        // #2: a scoped principal sees only in-scope (or platform-wide None) SLO
        // definitions — consistent with slo_status.
        .filter(|s| {
            ryuki_engine::auth::scope_permits(&session.site_scope, s.site.as_deref())
                && ryuki_engine::auth::scope_permits(
                    &session.environment_scope,
                    s.environment.as_deref(),
                )
        })
        .map(|s| {
            json!({
                "id": s.id, "name": s.name, "target": s.target,
                "window_days": s.window_days, "good_metric_key": s.good_metric_key,
                "total_metric_key": s.total_metric_key, "site": s.site,
                "environment": s.environment, "enabled": s.enabled,
            })
        })
        .collect();
    Ok(Json(json!({ "slos": slos, "durable": true })))
}

/// GET /api/metrics/slo/status — evaluate every enabled SLO over its window
/// (sum good/total from metric_samples, compute attainment + error-budget burn).
/// Request-tier. Alerting-safe: the one batch aggregate fails the request loud
/// (never a false `compliant`), and a window with no events is
/// `insufficient-data`.
async fn slo_status(AuthExtractor(session): AuthExtractor) -> ApiResult {
    if !check_permission(&session, "request") {
        return Err((
            StatusCode::FORBIDDEN,
            Json(json!({"error": "authentication is required to read SLO status"})),
        ));
    }
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let site_vals = nullable_axis_scope_values(&session.site_scope);
    let env_vals = nullable_axis_scope_values(&session.environment_scope);
    if !status_scope_work_is_bounded(site_vals.as_deref(), env_vals.as_deref()) {
        return Err((
            StatusCode::SERVICE_UNAVAILABLE,
            Json(json!({
                "error": "SLO status scope exceeds the bounded definition-query capacity",
                "maximum_scope_values_per_axis": MAX_STATUS_SCOPE_VALUES_PER_AXIS,
                "maximum_scope_combinations": MAX_STATUS_SCOPE_COMBINATIONS,
            })),
        ));
    }
    let query_result =
        fetch_slo_status_definitions(pool, site_vals.as_deref(), env_vals.as_deref()).await;
    let slos = match query_result {
        Ok(rows) => rows,
        Err(e) => {
            tracing::error!(error = %e, "listing SLOs for status failed");
            return Err((
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(json!({"error": "could not evaluate SLO status"})),
            ));
        }
    };
    if status_definition_overflow(slos.len()) {
        return Err((
            StatusCode::SERVICE_UNAVAILABLE,
            Json(json!({
                "error": "too many enabled SLO definitions are visible to evaluate safely",
                "maximum": MAX_STATUS_DEFINITIONS,
            })),
        ));
    }

    let now = chrono::Utc::now();
    let metric_inputs: Vec<SloMetricInput> = slos.iter().map(SloMetricInput::from).collect();
    let sums = match sum_slo_metrics_in_batch(pool, &metric_inputs, now).await {
        Ok(sums) => sums,
        Err(e) => {
            tracing::error!(error = %e, "batch-summing SLO metrics failed");
            return Err((
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(json!({"error": "could not evaluate SLO status"})),
            ));
        }
    };
    let mut results: Vec<Value> = Vec::new();
    let mut breached_count = 0u64;
    let mut errored_count = 0u64;
    for s in &slos {
        let totals = match sums.get(&s.id) {
            Some(values) => values,
            None => {
                errored_count += 1;
                results.push(json!({
                    "id": s.id, "name": s.name, "status": "error",
                    "error": "the SLO definition changed during evaluation",
                }));
                continue;
            }
        };
        if totals.truncated {
            errored_count += 1;
            results.push(json!({
                "id": s.id,
                "name": s.name,
                "window_days": s.window_days,
                "status": "partial",
                "error": "the SLO window exceeds the bounded raw-sample capacity",
                "good_partial": totals.good,
                "total_partial": totals.total,
                "coverage": {
                    "maximum_samples_per_metric_series": SLO_STATUS_SAMPLES_PER_SERIES,
                    "good_samples_used": totals.good_samples_used,
                    "total_samples_used": totals.total_samples_used,
                    "good_oldest_included_at": totals.good_oldest_included_at,
                    "total_oldest_included_at": totals.total_oldest_included_at,
                    "good_has_older_window_samples": totals.good_truncated,
                    "total_has_older_window_samples": totals.total_truncated,
                    "truncated": true,
                },
            }));
            continue;
        }
        let good = totals.good;
        let total = totals.total;
        // No events yet (total 0) is benign — not a breach, not an error.
        if total <= 0.0 {
            results.push(json!({
                "id": s.id, "name": s.name, "status": "insufficient-data",
                "good": good, "total": total,
                "coverage": {
                    "maximum_samples_per_metric_series": SLO_STATUS_SAMPLES_PER_SERIES,
                    "good_samples_used": totals.good_samples_used,
                    "total_samples_used": totals.total_samples_used,
                    "good_oldest_included_at": totals.good_oldest_included_at,
                    "total_oldest_included_at": totals.total_oldest_included_at,
                    "good_has_older_window_samples": false,
                    "total_has_older_window_samples": false,
                    "truncated": false,
                },
            }));
            continue;
        }
        match ryuki_engine::slo::compute_slo(good, total, s.target) {
            Some(status) => {
                if !status.compliant {
                    breached_count += 1;
                }
                results.push(json!({
                    "id": s.id,
                    "name": s.name,
                    "window_days": s.window_days,
                    "status": if status.compliant { "compliant" } else { "breached" },
                    "slo": status,
                    "coverage": {
                        "maximum_samples_per_metric_series": SLO_STATUS_SAMPLES_PER_SERIES,
                        "good_samples_used": totals.good_samples_used,
                        "total_samples_used": totals.total_samples_used,
                        "good_oldest_included_at": totals.good_oldest_included_at,
                        "total_oldest_included_at": totals.total_oldest_included_at,
                        "good_has_older_window_samples": false,
                        "total_has_older_window_samples": false,
                        "truncated": false,
                    },
                }));
            }
            // total > 0 but the SLO is still unevaluable (good > total, or a
            // negative sum) — a DATA inconsistency, NOT "no data". Flag it as
            // errored so a clean breached_count is never mistaken for healthy.
            None => {
                errored_count += 1;
                results.push(json!({
                    "id": s.id, "name": s.name, "status": "invalid-data",
                    "good": good, "total": total,
                    "coverage": {
                        "maximum_samples_per_metric_series": SLO_STATUS_SAMPLES_PER_SERIES,
                        "good_samples_used": totals.good_samples_used,
                        "total_samples_used": totals.total_samples_used,
                        "good_oldest_included_at": totals.good_oldest_included_at,
                        "total_oldest_included_at": totals.total_oldest_included_at,
                        "good_has_older_window_samples": false,
                        "total_has_older_window_samples": false,
                        "truncated": false,
                    },
                }));
            }
        }
    }

    // overall_status must reflect BREACHES, not just query/data errors — otherwise a
    // health gate reading `overall_status == "ok"` sees green while SLOs/budgets are
    // actively breached (breached_count > 0). errored (unevaluable) outranks breached.
    let overall_status = if errored_count > 0 {
        "degraded"
    } else if breached_count > 0 {
        "breached"
    } else {
        "ok"
    };
    Ok(Json(json!({
        "slos": results,
        "breached_count": breached_count,
        "errored_count": errored_count,
        "overall_status": overall_status,
    })))
}

/// One row for the SLO-breach scan (#11 slice 2b).
#[derive(sqlx::FromRow)]
struct SloScanRow {
    id: String,
    name: String,
    target: f64,
    window_days: i32,
    good_metric_key: String,
    total_metric_key: String,
    site: Option<String>,
    environment: Option<String>,
    breaching: bool,
}

/// One SLO-breach scan pass (#11 slice 2b): evaluate every enabled SLO and, on a
/// DEFINITIVE compliant/breached result, emit a `slo.breach` / `slo.recovered`
/// domain event ONLY when the SLO TRANSITIONS — deduped via the `breaching` flag,
/// flipped atomically with the emit. Partial, insufficient, and invalid data
/// leave the flag unchanged; a batch-query failure aborts the pass before any
/// transition is inferred.
/// Returns the number of transition events emitted.
pub(crate) async fn slo_breach_scan_once(pool: &sqlx::PgPool) -> Result<u64, sqlx::Error> {
    let slos: Vec<SloScanRow> = sqlx::query_as(
        "SELECT id, name, target, window_days, good_metric_key, total_metric_key, \
                site, environment, breaching \
         FROM slo_definitions WHERE enabled \
         ORDER BY created_at DESC, id DESC LIMIT $1",
    )
    .bind(status_definition_query_limit())
    .fetch_all(pool)
    .await?;
    if status_definition_overflow(slos.len()) {
        return Err(sqlx::Error::Protocol(
            "SLO breach scan definition bound exceeded".to_string(),
        ));
    }
    let now = chrono::Utc::now();
    let metric_inputs: Vec<SloMetricInput> = slos
        .iter()
        .map(|slo| SloMetricInput {
            id: slo.id.clone(),
            window_days: slo.window_days,
            good_metric_key: slo.good_metric_key.clone(),
            total_metric_key: slo.total_metric_key.clone(),
            site: slo.site.clone(),
            environment: slo.environment.clone(),
        })
        .collect();
    let sums = sum_slo_metrics_in_batch(pool, &metric_inputs, now).await?;
    let mut emitted = 0u64;
    for s in &slos {
        let Some(totals) = sums.get(&s.id) else {
            continue;
        };
        // A truncated window is deliberately non-definitive; never emit a
        // transition from a partial aggregate.
        if totals.truncated {
            continue;
        }
        let good = totals.good;
        let total = totals.total;
        // Insufficient data (no events) is not a definitive state.
        if total <= 0.0 {
            continue;
        }
        // Invalid data (good > total, etc.) is not a definitive state.
        let Some(status) = ryuki_engine::slo::compute_slo(good, total, s.target) else {
            continue;
        };
        let now_breaching = !status.compliant;
        if now_breaching == s.breaching {
            continue; // no transition — already in this state.
        }
        // Transition: emit the event + flip the flag atomically.
        let mut tx = pool.begin().await?;
        crate::repos::domain_events::insert(
            &mut *tx,
            crate::repos::domain_events::NewEvent {
                event_type: if now_breaching {
                    "slo.breach"
                } else {
                    "slo.recovered"
                },
                aggregate_type: "slo",
                aggregate_id: &s.id,
                site: s.site.as_deref(),
                environment: s.environment.as_deref(),
                actor: "system",
                payload: json!({
                    "to_status": if now_breaching { "breached" } else { "recovered" },
                    "slo_name": &s.name,
                    "attainment": status.attainment,
                    "target": s.target,
                    "window_days": s.window_days,
                }),
            },
        )
        .await?;
        // #11 slice 2f/2g: push a portal notification to the monitoring role in
        // the SAME tx (atomic with the event + flag) — Critical on breach, Success
        // on recovery, so operators get both the alert and the all-clear.
        {
            let (event_type, severity) = if now_breaching {
                (
                    "slo.breach",
                    ryuki_engine::notifications::Severity::Critical,
                )
            } else {
                (
                    "slo.recovered",
                    ryuki_engine::notifications::Severity::Success,
                )
            };
            let draft = ryuki_engine::notifications::draft_for_alert(event_type, &s.id, severity);
            crate::repos::notifications::insert_draft_tx(&mut tx, &draft, None).await?;
        }
        sqlx::query("UPDATE slo_definitions SET breaching = $1, updated_at = NOW() WHERE id = $2")
            .bind(now_breaching)
            .bind(&s.id)
            .execute(&mut *tx)
            .await?;
        tx.commit().await?;
        emitted += 1;
    }
    Ok(emitted)
}

/// Spawn the background SLO-breach scan (#11 slice 2b). Write-capable and
/// SEPARATE from the read-only scheduler (which may not emit). Runs on a fixed
/// interval with #31-style exponential backoff on consecutive failures so a
/// persistent outage does not hammer the DB. Call once at startup.
/// Heartbeat registry name for the SLO-breach scan loop.
const SLO_BREACH_SCAN_NAME: &str = "slo_breach_scan";

pub fn spawn_slo_breach_scan(pool: sqlx::PgPool, interval_secs: u64) {
    tokio::spawn(async move {
        crate::background::register_loop(SLO_BREACH_SCAN_NAME, interval_secs);
        let mut ticker = tokio::time::interval(std::time::Duration::from_secs(interval_secs));
        ticker.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
        ticker.tick().await; // skip the immediate first tick
        let timeout = crate::background::iteration_timeout(interval_secs);
        let mut consecutive_failures: u32 = 0;
        loop {
            ticker.tick().await;
            match crate::background::run_bounded(timeout, slo_breach_scan_once(&pool)).await {
                Ok(emitted) => {
                    consecutive_failures = 0;
                    crate::background::record_loop_success(SLO_BREACH_SCAN_NAME);
                    if emitted > 0 {
                        tracing::info!(emitted, "slo-breach scan emitted transition events");
                    }
                }
                Err(err) => {
                    let backoff = crate::background::note_failure(&mut consecutive_failures);
                    match err {
                        crate::background::IterError::Failed(e) => tracing::error!(
                            error = %e,
                            consecutive_failures,
                            backoff_intervals = backoff,
                            "slo-breach scan failed; backing off"
                        ),
                        crate::background::IterError::TimedOut => tracing::error!(
                            timeout_secs = timeout.as_secs(),
                            consecutive_failures,
                            backoff_intervals = backoff,
                            "slo-breach scan exceeded its iteration timeout; backing off"
                        ),
                    }
                    tokio::time::sleep(std::time::Duration::from_secs(
                        interval_secs.saturating_mul(backoff),
                    ))
                    .await;
                }
            }
        }
    });
}

/// One row for the budget-breach scan (#11 slice 2c).
#[derive(sqlx::FromRow)]
struct BudgetScanRow {
    id: String,
    metric_key: String,
    site: Option<String>,
    environment: Option<String>,
    threshold: f64,
    comparison: String,
    breaching: bool,
}

/// Definitive breach state for one budget, or `None` when there is no data yet
/// (empty series / no summary) — the same "skip transient" posture as the SLO
/// scan. Reuses the exact evaluation `metrics_budget_status` performs: load the
/// series, summarize, project the forecast extreme for the comparison direction,
/// and evaluate (breach = breached_now OR breached_projected).
fn budget_breach_state(b: &BudgetScanRow, analysis: BudgetSeriesAnalysis) -> Option<bool> {
    let summary = analysis.summary.as_ref()?;
    let comparison =
        ryuki_engine::metric_budget::BudgetComparison::from_str_or_above(&b.comparison);
    let projected_extreme = match comparison {
        ryuki_engine::metric_budget::BudgetComparison::Below => analysis.projected_min,
        ryuki_engine::metric_budget::BudgetComparison::Above => analysis.projected_max,
    };
    let eval = ryuki_engine::metric_budget::evaluate_budget(
        b.threshold,
        comparison,
        Some(summary),
        projected_extreme,
    );
    Some(eval.breached_now || eval.breached_projected)
}

/// One budget-breach scan pass (#11 slice 2c): evaluate every enabled budget and,
/// on a DEFINITIVE breach state, emit a `budget.breach` / `budget.recovered`
/// domain event ONLY when the budget TRANSITIONS — deduped via the `breaching`
/// flag, flipped atomically with the emit. No-data and truncated series leave
/// the flag unchanged; a batch-query failure aborts the pass before any
/// transition is inferred. Returns the number of transition events emitted.
pub(crate) async fn budget_breach_scan_once(pool: &sqlx::PgPool) -> Result<u64, sqlx::Error> {
    let budgets: Vec<BudgetScanRow> = sqlx::query_as(
        "SELECT id, metric_key, site, environment, threshold, comparison, breaching \
         FROM metric_budgets WHERE enabled \
         ORDER BY created_at DESC, id DESC LIMIT $1",
    )
    .bind(status_definition_query_limit())
    .fetch_all(pool)
    .await?;
    if status_definition_overflow(budgets.len()) {
        return Err(sqlx::Error::Protocol(
            "budget breach scan definition bound exceeded".to_string(),
        ));
    }
    let budget_series: Vec<BudgetSeriesKey> = budgets
        .iter()
        .map(|budget| {
            (
                budget.metric_key.clone(),
                budget.site.clone(),
                budget.environment.clone(),
            )
        })
        .collect();
    let analyses = fetch_budget_status_analyses(pool, &budget_series).await?;
    let mut emitted = 0u64;
    for b in &budgets {
        let key = (b.metric_key.clone(), b.site.clone(), b.environment.clone());
        let Some(analysis) = analyses.get(&key).cloned() else {
            continue;
        };
        // A lookahead row proves the forecast only covers a suffix. Preserve
        // the previously persisted breach state until a complete bounded
        // evaluation is available.
        if analysis.truncated {
            continue;
        }
        let Some(now_breaching) = budget_breach_state(b, analysis) else {
            continue;
        };
        if now_breaching == b.breaching {
            continue; // no transition
        }
        let mut tx = pool.begin().await?;
        crate::repos::domain_events::insert(
            &mut *tx,
            crate::repos::domain_events::NewEvent {
                event_type: if now_breaching {
                    "budget.breach"
                } else {
                    "budget.recovered"
                },
                aggregate_type: "budget",
                aggregate_id: &b.id,
                site: b.site.as_deref(),
                environment: b.environment.as_deref(),
                actor: "system",
                payload: json!({
                    "to_status": if now_breaching { "breached" } else { "recovered" },
                    "metric_key": &b.metric_key,
                    "threshold": b.threshold,
                    "comparison": &b.comparison,
                }),
            },
        )
        .await?;
        // #11 slice 2f/2g: notify the monitoring role on both directions —
        // Warning on breach, Success on recovery.
        {
            let (event_type, severity) = if now_breaching {
                (
                    "budget.breach",
                    ryuki_engine::notifications::Severity::Warning,
                )
            } else {
                (
                    "budget.recovered",
                    ryuki_engine::notifications::Severity::Success,
                )
            };
            let draft = ryuki_engine::notifications::draft_for_alert(event_type, &b.id, severity);
            crate::repos::notifications::insert_draft_tx(&mut tx, &draft, None).await?;
        }
        sqlx::query("UPDATE metric_budgets SET breaching = $1, updated_at = NOW() WHERE id = $2")
            .bind(now_breaching)
            .bind(&b.id)
            .execute(&mut *tx)
            .await?;
        tx.commit().await?;
        emitted += 1;
    }
    Ok(emitted)
}

/// Spawn the background budget-breach scan (#11 slice 2c). Write-capable, so
/// separate from the read-only scheduler; #31-style backoff on consecutive
/// failures. Call once at startup.
/// Heartbeat registry name for the budget-breach scan loop.
const BUDGET_BREACH_SCAN_NAME: &str = "budget_breach_scan";

pub fn spawn_budget_breach_scan(pool: sqlx::PgPool, interval_secs: u64) {
    tokio::spawn(async move {
        crate::background::register_loop(BUDGET_BREACH_SCAN_NAME, interval_secs);
        let mut ticker = tokio::time::interval(std::time::Duration::from_secs(interval_secs));
        ticker.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
        ticker.tick().await; // skip the immediate first tick
        let timeout = crate::background::iteration_timeout(interval_secs);
        let mut consecutive_failures: u32 = 0;
        loop {
            ticker.tick().await;
            match crate::background::run_bounded(timeout, budget_breach_scan_once(&pool)).await {
                Ok(emitted) => {
                    consecutive_failures = 0;
                    crate::background::record_loop_success(BUDGET_BREACH_SCAN_NAME);
                    if emitted > 0 {
                        tracing::info!(emitted, "budget-breach scan emitted transition events");
                    }
                }
                Err(err) => {
                    let backoff = crate::background::note_failure(&mut consecutive_failures);
                    match err {
                        crate::background::IterError::Failed(e) => tracing::error!(
                            error = %e,
                            consecutive_failures,
                            backoff_intervals = backoff,
                            "budget-breach scan failed; backing off"
                        ),
                        crate::background::IterError::TimedOut => tracing::error!(
                            timeout_secs = timeout.as_secs(),
                            consecutive_failures,
                            backoff_intervals = backoff,
                            "budget-breach scan exceeded its iteration timeout; backing off"
                        ),
                    }
                    tokio::time::sleep(std::time::Duration::from_secs(
                        interval_secs.saturating_mul(backoff),
                    ))
                    .await;
                }
            }
        }
    });
}

// ── Portal-notifications retention sweep ──────────────────────────────────────
//
// portal_notifications (mig 083) grows without bound — every request-lifecycle
// transition and operational alert appends rows and nothing deletes them. This
// sweep enforces the retention policy below via `repos::notifications::
// prune_expired` (bounded oldest-first batches; receipts + dispatch-outbox rows
// cascade via the mig 083/128 FKs; index: mig 156).
//
// The windows and cap are CONSTS, not env/platform-config knobs: every
// background-loop cadence and retention parameter in this binary is a hardcoded
// constant at its spawn/call site (the 300s scan intervals in main.rs, the
// idempotency sweep's RETENTION_TTL_SECS, the scheduler prunes' KEEP/MAX
// consts) — there is no config precedent for scan knobs, so these follow suit.

/// Standard retention: a READ (any receipt) or non-Critical notification is
/// pruned this many days after creation. Matches the shift_queue prune's 90-day
/// resolved-history window; the feed reads at most 200 recent rows, so nothing
/// user-visible depends on older history.
const NOTIFICATIONS_RETENTION_DAYS: i64 = 90;
/// Hard cap for the unread-Critical carve-out: an UNREAD Critical notification
/// outlives the standard window (it may still need acting on) but is pruned
/// unconditionally after this many days, so the table stays bounded even when
/// nobody ever acknowledges.
const NOTIFICATIONS_CRITICAL_UNREAD_RETENTION_DAYS: i64 = 365;
/// Per-run delete cap (the established prune batch bound): the first sweep of a
/// years-old backlog drains over a few ticks instead of one giant DELETE.
const NOTIFICATIONS_PRUNE_MAX_PER_RUN: i64 = 20_000;
/// Heartbeat registry name for the notifications retention sweep loop.
const NOTIFICATIONS_RETENTION_SWEEP_NAME: &str = "notifications_retention_sweep";

/// One retention pass — retry-idempotent (an expired-row DELETE re-run next
/// tick deletes nothing extra), so `run_bounded` cancellation is safe.
async fn notifications_retention_sweep_once(pool: &sqlx::PgPool) -> Result<u64, sqlx::Error> {
    crate::repos::notifications::prune_expired(
        pool,
        NOTIFICATIONS_RETENTION_DAYS,
        NOTIFICATIONS_CRITICAL_UNREAD_RETENTION_DAYS,
        NOTIFICATIONS_PRUNE_MAX_PER_RUN,
    )
    .await
}

/// Spawn the portal-notifications retention sweep. Fail-open: an error (or
/// iteration timeout) logs, backs off, and skips to a later tick — it never
/// crashes the API. Call once at startup.
pub fn spawn_notifications_retention_sweep(pool: sqlx::PgPool, interval_secs: u64) {
    tokio::spawn(async move {
        crate::background::register_loop(NOTIFICATIONS_RETENTION_SWEEP_NAME, interval_secs);
        let mut ticker = tokio::time::interval(std::time::Duration::from_secs(interval_secs));
        ticker.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
        ticker.tick().await; // skip the immediate first tick
        let timeout = crate::background::iteration_timeout(interval_secs);
        let mut consecutive_failures: u32 = 0;
        loop {
            ticker.tick().await;
            match crate::background::run_bounded(timeout, notifications_retention_sweep_once(&pool))
                .await
            {
                Ok(pruned) => {
                    consecutive_failures = 0;
                    crate::background::record_loop_success(NOTIFICATIONS_RETENTION_SWEEP_NAME);
                    if pruned > 0 {
                        tracing::info!(
                            pruned,
                            "notifications retention sweep pruned expired notifications"
                        );
                    }
                }
                Err(err) => {
                    let backoff = crate::background::note_failure(&mut consecutive_failures);
                    match err {
                        crate::background::IterError::Failed(e) => tracing::error!(
                            error = %e,
                            consecutive_failures,
                            backoff_intervals = backoff,
                            "notifications retention sweep failed; backing off"
                        ),
                        crate::background::IterError::TimedOut => tracing::error!(
                            timeout_secs = timeout.as_secs(),
                            consecutive_failures,
                            backoff_intervals = backoff,
                            "notifications retention sweep exceeded its iteration timeout; backing off"
                        ),
                    }
                    tokio::time::sleep(std::time::Duration::from_secs(
                        interval_secs.saturating_mul(backoff),
                    ))
                    .await;
                }
            }
        }
    });
}

/// PUT /api/metrics/budgets/{id} — update a budget's mutable fields (threshold,
/// comparison, enabled); omitted fields are left unchanged (PATCH semantics,
/// swarm #19). Execute-tier (same as create/delete). 404 if absent; 503 no DB.
/// The identity/scope fields are immutable here — recreate to re-scope.
async fn metrics_budget_update(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
    Json(body): Json<MetricBudgetUpdateRequest>,
) -> ApiResult {
    if !check_permission(&session, "execute") {
        return Err((
            StatusCode::FORBIDDEN,
            Json(json!({"error": "Execute-tier access is required to update budgets"})),
        ));
    }
    if let Some(t) = body.threshold {
        if !t.is_finite() {
            return Err((
                StatusCode::BAD_REQUEST,
                Json(json!({"error": "threshold must be a finite number"})),
            ));
        }
    }
    let comparison = match body.comparison.as_deref() {
        None => None,
        Some("above") => Some("above"),
        Some("below") => Some("below"),
        Some(_) => {
            return Err((
                StatusCode::BAD_REQUEST,
                Json(json!({"error": "comparison must be 'above' or 'below'"})),
            ));
        }
    };
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let mut tx = pool.begin().await.map_err(db_error)?;
    // #2: metric_budgets is dual-axis (site + environment, both nullable; NULL =
    // platform-wide). A scoped principal may only modify a budget fully contained
    // in its scope — a platform-wide or out-of-scope budget is reported as a missing
    // one (404). Pre-loaded inside the tx so a concurrent change can't slip in.
    if is_scoped(&session) {
        let row: Option<(Option<String>, Option<String>)> =
            sqlx::query_as("SELECT site, environment FROM metric_budgets WHERE id = $1")
                .bind(&id)
                .fetch_optional(&mut *tx)
                .await
                .map_err(db_error)?;
        let permitted = match row {
            Some((site, env)) => multi_scope_permits(
                &session,
                &site.into_iter().collect::<Vec<_>>(),
                &env.into_iter().collect::<Vec<_>>(),
            ),
            None => false,
        };
        if !permitted {
            return Err(status_404(&id));
        }
    }
    // COALESCE keeps any omitted field at its current value (PATCH semantics).
    let updated: Option<(String,)> = sqlx::query_as(
        "UPDATE metric_budgets SET \
           threshold = COALESCE($2, threshold), \
           comparison = COALESCE($3, comparison), \
           enabled = COALESCE($4, enabled), \
           updated_at = NOW() \
         WHERE id = $1 RETURNING id",
    )
    .bind(&id)
    .bind(body.threshold)
    .bind(comparison)
    .bind(body.enabled)
    .fetch_optional(&mut *tx)
    .await
    .map_err(db_error)?;
    match updated {
        Some((updated_id,)) => {
            audit::record_audit_tx(
                &mut tx,
                &session,
                &audit::security_audit(
                    "metric-budget-update",
                    Some("active"),
                    "updated",
                    json!({ "budget_id": &updated_id }),
                ),
            )
            .await
            .map_err(db_error)?;
            tx.commit().await.map_err(db_error)?;
            Ok(Json(json!({"updated": updated_id})))
        }
        None => Err(status_404(&id)),
    }
}

