// ─── Backup Coverage & Restore handlers ───

async fn backup_coverage_report(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<CoverageReportRequest>,
) -> ApiResult {
    // #2: a coverage report spans the caller-supplied site/environment vectors. A
    // scoped principal may only request a report whose footprint is contained in
    // its authority on BOTH axes (subset containment) — an empty (all-sites or
    // all-envs) request from a scoped principal is denied. Body-supplied → 403.
    if is_scoped(&session) {
        if !within_multi_scope(&session.site_scope, &body.site_scope) {
            return Err(status_403_out_of_scope("site"));
        }
        if !within_multi_scope(&session.environment_scope, &body.environment_scope) {
            return Err(status_403_out_of_scope("environment"));
        }
    }
    let pool = get_db().ok_or_else(status_503_no_db)?;

    let mut report =
        backup_engine::generate_backup_coverage_report(&body.site_scope, &body.environment_scope)
            .map_err(|e| status_400(&e))?;

    // The engine mints a non-UUID id (e.g. "bcr-abc12345") suitable for
    // in-memory use but not for the UUID primary key column. Replace it with a
    // proper UUID so the repo can bind it correctly.
    report.id = Uuid::new_v4().to_string();

    let persisted = crate::repos::backup_coverage_reports::insert(pool, &report)
        .await
        .map_err(db_error)?;

    Ok(Json(serde_json::to_value(&persisted).unwrap_or_default()))
}

async fn backup_restore_plan(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<RestorePlanRequest>,
) -> ApiResult {
    let actor_principal = authenticated_principal_id(&session)?.to_string();
    // #2 dual-axis WRITE: a scoped principal may only plan a restore whose target
    // site AND environment are both within its scope (body-supplied → 403, no
    // existence oracle).
    guard_body_scope_dual(&session, &body.target_site, &body.target_environment)?;
    let pool = get_db().ok_or_else(status_503_no_db)?;

    let restore_type = match body.restore_type.as_str() {
        "full-vm" => ryuki_engine::models::RestoreType::FullVm,
        "file-level" => ryuki_engine::models::RestoreType::FileLevel,
        "application-item" => ryuki_engine::models::RestoreType::ApplicationItem,
        "instant-vm-recovery" => ryuki_engine::models::RestoreType::InstantVmRecovery,
        _ => return Err(status_400("Invalid restore type")),
    };

    let mut restore = backup_engine::plan_restore(
        &body.source_ci_key,
        restore_type,
        &body.restore_point,
        &body.target_site,
        &body.target_environment,
        &body.owner,
        &actor_principal,
    )
    .map_err(|e| status_400(&e))?;

    // The engine mints a non-UUID id (e.g. "rest-abc12345") suitable for
    // in-memory use but not for the UUID primary key column. Replace it with a
    // proper UUID so the repo can bind it correctly.
    restore.id = Uuid::new_v4().to_string();

    // The process-local engine registry is only an early validation cache. Lock
    // the durable active-site row in the same transaction as creation so a
    // concurrent deactivation cannot race a newly verified authority tuple.
    let mut tx = pool.begin().await.map_err(db_error)?;
    if !crate::repos::site_registry::lock_active(&mut tx, &restore.target_site)
        .await
        .map_err(db_error)?
    {
        return Err(status_400("Unknown or inactive target site"));
    }
    let persisted = crate::repos::restore_requests::insert(&mut *tx, &restore)
        .await
        .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;

    Ok(Json(serde_json::to_value(&persisted).unwrap_or_default()))
}

/// Validate a persisted restore request (read-only — no state transition).
async fn backup_restore_validate(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<RestoreActionRequest>,
) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;

    let r = crate::repos::restore_requests::get(pool, &body.restore_id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&body.restore_id))?;

    // #2 dual-axis by-id read: out-of-scope 404s like a missing one (no oracle).
    scope_guard_or_404(
        &session,
        &r.target_site,
        &r.target_environment,
        &body.restore_id,
    )?;

    let result = backup_engine::validate_restore_request(&r).map_err(|e| status_400(&e))?;

    Ok(Json(serde_json::to_value(&result).unwrap_or_default()))
}

async fn backup_restore_approve(
    Extension(session): Extension<AuthSession>,
    Json(body): Json<RestoreActionRequest>,
) -> ApiResult {
    let actor_principal = authenticated_principal_id(&session)?.to_string();
    let pool = get_db().ok_or_else(status_503_no_db)?;

    let r = crate::repos::restore_requests::get(pool, &body.restore_id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&body.restore_id))?;

    // #2 dual-axis by-id guard BEFORE the engine 409 — out-of-scope 404s like a
    // missing one, never leaking status via approve_restore's state check.
    scope_guard_or_404(
        &session,
        &r.target_site,
        &r.target_environment,
        &body.restore_id,
    )?;

    let planned_by = r
        .metadata
        .get("planned_by")
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| status_409("restore has no trusted planner; replan before approval"))?;
    if planned_by == &actor_principal {
        return Err(status_403());
    }

    let before = crate::repos::restore_requests::status_str(&r.status);
    // Approver = authenticated caller (from request extensions), never a
    // client-supplied body field — the audit trail must name the real principal.
    let approver = actor_principal.as_str();

    let approved = backup_engine::approve_restore(&r, approver).map_err(|e| status_409(&e))?;

    let mut tx = pool.begin().await.map_err(db_error)?;
    let persisted = crate::repos::restore_requests::transition(&mut *tx, before, &approved, None)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_409("state changed concurrently; reload and retry"))?;
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "backup-restore-approve",
            Some(before),
            "approved",
            json!({
                "restore_id": r.id,
                "source_ci_key": r.source_ci_key,
                "target_site": r.target_site,
            }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;

    Ok(Json(serde_json::to_value(&persisted).unwrap_or_default()))
}

/// Execute a persisted restore request (must be Approved) and record the
/// execution by transitioning Approved -> Executed. The response is the evidence
/// the engine produced. The CAS transition also makes execute non-idempotent in
/// the safe direction: a second call finds the request Executed (not Approved),
/// so the engine's Approved precondition rejects it (409) — a restore cannot be
/// silently run twice, and list/get reflect that it ran.
async fn backup_restore_execute(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<RestoreActionRequest>,
) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;

    let r = crate::repos::restore_requests::get(pool, &body.restore_id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&body.restore_id))?;

    // #2 dual-axis by-id guard BEFORE the engine 409 — out-of-scope 404s like a miss.
    scope_guard_or_404(
        &session,
        &r.target_site,
        &r.target_environment,
        &body.restore_id,
    )?;

    let before = crate::repos::restore_requests::status_str(&r.status);

    // Engine requires Approved; produces evidence without changing status.
    let evidence = backup_engine::execute_restore(&r).map_err(|e| status_409(&e))?;

    // Record the execution durably: Approved -> Executed.
    let mut executed = r.clone();
    executed.status = ryuki_engine::models::RestoreStatus::Executed;
    executed.metadata.insert(
        "execution_evidence_count".into(),
        evidence.len().to_string(),
    );

    let mut tx = pool.begin().await.map_err(db_error)?;
    crate::repos::restore_requests::transition(&mut *tx, before, &executed, None)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_409("state changed concurrently; reload and retry"))?;
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "backup-restore-execute",
            Some(before),
            "executed",
            json!({
                "restore_id": r.id,
                "source_ci_key": r.source_ci_key,
                "target_site": r.target_site,
            }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;

    Ok(Json(serde_json::to_value(&evidence).unwrap_or_default()))
}

/// Dedicated pagination query for GET /api/protect/backup/restores (#14) —
/// endpoint-local rather than a shared struct, so another handler's params can
/// never bleed into this list's contract (the 400-regression class).
#[derive(Debug, Deserialize)]
struct BackupRestoreListQuery {
    limit: Option<i64>,
    offset: Option<i64>,
}

/// GET /api/protect/backup/restores — list persisted restore requests, paged
/// (#14). Returns an empty array when no DB is available rather than an error.
/// The body stays a BARE array (backward-compatible); the scope-filtered total
/// rides the `X-Total-Count` header.
async fn backup_restores_list(
    AuthExtractor(session): AuthExtractor,
    Query(q): Query<BackupRestoreListQuery>,
) -> Result<(HeaderMap, Json<Value>), (StatusCode, Json<Value>)> {
    // #14: bound the page (generous default keeps seed-scale callers unaffected).
    let limit = q.limit.unwrap_or(500).clamp(1, 1000);
    let offset = q.offset.unwrap_or(0).max(0);
    let Some(pool) = get_db() else {
        return Ok((
            total_count_headers(0),
            Json(serde_json::Value::Array(vec![])),
        ));
    };
    // #2 dual-axis list filter: keep only rows whose (target_site, target_environment)
    // are both within the principal's scope. An unrestricted principal keeps all
    // (scope_permits is unrestricted only for a LITERALLY empty axis); a principal
    // scoped on one axis keeps rows matching that axis and unrestricted on the
    // other — the old in-memory `row_scope_permits` retain, pushed INTO SQL (#14)
    // so a LIMIT/OFFSET page and the total both reflect the scope-filtered set.
    let sites = scope_axis_sql_filter(&session.site_scope);
    let envs = scope_axis_sql_filter(&session.environment_scope);
    let records = crate::repos::restore_requests::list_page(
        pool,
        sites.as_deref(),
        envs.as_deref(),
        limit,
        offset,
    )
    .await
    .map_err(db_error)?;
    let total = crate::repos::restore_requests::count(pool, sites.as_deref(), envs.as_deref())
        .await
        .map_err(db_error)?;
    Ok((
        total_count_headers(total),
        Json(serde_json::to_value(&records).unwrap_or_default()),
    ))
}

/// GET /api/protect/backup/restores/{id} — fetch a single restore request by id.
/// Returns 404 when absent or when no DB is configured.
async fn backup_restore_get(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> ApiResult {
    let pool = get_db().ok_or_else(|| status_404(&id))?;
    let record = crate::repos::restore_requests::get(pool, &id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&id))?;
    // #2 dual-axis by-id read: out-of-scope 404s like a missing one (no oracle).
    scope_guard_or_404(
        &session,
        &record.target_site,
        &record.target_environment,
        &id,
    )?;
    Ok(Json(serde_json::to_value(&record).unwrap_or_default()))
}

/// Query for GET /api/protect/backup/restore-tests/recency.
#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct RestoreTestRecencyQuery {
    overdue_after_days: Option<i64>,
}

/// GET /api/protect/backup/restore-tests/recency?overdue_after_days=N — restore
/// test recency (#47). A backup is only proven by a successful restore test;
/// this reports, per `source_ci_key` THAT HAS RESTORE-REQUEST HISTORY, the last
/// successful test (status Verified/Completed) and classifies it
/// `current`/`overdue`/`never_tested` against the policy window (default 90
/// days, bounded). Systems with no restore request at all are out of scope (a
/// coverage question — see coverage reports); the response carries a `scope` +
/// `note` saying so. Read-only; empty + `durable:false` when no DB.
async fn backup_restore_test_recency(
    AuthExtractor(session): AuthExtractor,
    Query(q): Query<RestoreTestRecencyQuery>,
) -> ApiResult {
    use ryuki_engine::backup_recency::{classify_restore_recency, RestoreTestRecency};

    let overdue_after_days = q.overdue_after_days.unwrap_or(90);
    if !(1..=3650).contains(&overdue_after_days) {
        return Err(status_400("overdue_after_days must be between 1 and 3650"));
    }
    // #2: narrow the cross-site aggregate to the principal's scope (restore_requests
    // are dual-axis, NOT NULL). A scoped principal that holds several distinct
    // scopes with no way to disambiguate is 403'd (enforce_scope_filters contract).
    let (f_site, f_env) = enforce_scope_filters(&session, None, None)?;

    // The report covers systems that HAVE restore-request history; a system that
    // never had a restore request at all is a backup-coverage gap, not a recency
    // one, so `never_tested` here means "requested but never proven".
    let scope = "systems-with-restore-requests";
    let note = "Covers systems with restore-request history only; \
                'never_tested' = requested but never reached Verified/Completed. \
                Systems with no restore request at all are a coverage concern \
                (see backup coverage reports), not surfaced here. \
                'last_successful_test' is the request's last-transition time, used \
                as an advisory success time.";

    let Some(pool) = get_db() else {
        return Ok(Json(json!({
            "overdue_after_days": overdue_after_days,
            "systems": [],
            "summary": {"total_systems": 0, "current": 0, "overdue": 0, "never_tested": 0},
            "scope": scope,
            "note": note,
            "durable": false,
        })));
    };

    let rows = crate::repos::restore_requests::restore_test_recency(
        pool,
        f_site.as_deref(),
        f_env.as_deref(),
    )
    .await
    .map_err(db_error)?;

    let now_unix = chrono::Utc::now().timestamp();
    let overdue_after_secs = overdue_after_days * 86_400;
    let (mut current, mut overdue, mut never) = (0_i64, 0_i64, 0_i64);
    let systems: Vec<Value> = rows
        .iter()
        .map(|r| {
            let last_unix = r.last_successful_test.map(|d| d.timestamp());
            let recency = classify_restore_recency(last_unix, now_unix, overdue_after_secs);
            match recency {
                RestoreTestRecency::Current => current += 1,
                RestoreTestRecency::Overdue => overdue += 1,
                RestoreTestRecency::NeverTested => never += 1,
            }
            json!({
                "source_ci_key": r.source_ci_key,
                "last_successful_test": r.last_successful_test.map(|d| d.to_rfc3339()),
                "successful_test_count": r.successful_test_count,
                "total_requests": r.total_requests,
                "recency": recency.as_str(),
                "at_risk": recency.is_at_risk(),
            })
        })
        .collect();

    Ok(Json(json!({
        "overdue_after_days": overdue_after_days,
        "systems": systems,
        "summary": {
            "total_systems": systems.len(),
            "current": current,
            "overdue": overdue,
            "never_tested": never,
        },
        "scope": scope,
        "note": note,
        // Uniform with the no-DB path's `durable:false`, so a client can always
        // tell a persisted result from a graceful no-DB degradation.
        "durable": true,
    })))
}

/// Dedicated pagination query for GET /api/protect/backup/coverage-reports
/// (#14) — endpoint-local rather than a shared struct, so another handler's
/// params can never bleed into this list's contract (the 400-regression class).
#[derive(Debug, Deserialize)]
struct BackupCoverageReportListQuery {
    limit: Option<i64>,
    offset: Option<i64>,
}

/// GET /api/protect/backup/coverage-reports — list persisted coverage reports,
/// paged (#14). Returns an empty array when no DB is available rather than an
/// error. The body stays a BARE array (backward-compatible); the
/// scope-filtered total rides the `X-Total-Count` header.
async fn backup_coverage_reports_list(
    AuthExtractor(session): AuthExtractor,
    Query(q): Query<BackupCoverageReportListQuery>,
) -> Result<(HeaderMap, Json<Value>), (StatusCode, Json<Value>)> {
    // #14: bound the page (generous default keeps seed-scale callers unaffected).
    let limit = q.limit.unwrap_or(500).clamp(1, 1000);
    let offset = q.offset.unwrap_or(0).max(0);
    let Some(pool) = get_db() else {
        return Ok((
            total_count_headers(0),
            Json(serde_json::Value::Array(vec![])),
        ));
    };
    // #2: keep only reports whose (site_scope, environment_scope) footprint is
    // contained in the principal's authority — an unrestricted principal keeps
    // all; a scoped principal drops all-sites/all-envs and out-of-scope reports.
    // The old in-memory `multi_scope_permits` retain, pushed INTO SQL (#14) so a
    // LIMIT/OFFSET page and the total both reflect the scope-filtered set.
    let sites = multi_scope_axis_sql_filter(&session.site_scope);
    let envs = multi_scope_axis_sql_filter(&session.environment_scope);
    let records = crate::repos::backup_coverage_reports::list_page(
        pool,
        sites.as_deref(),
        envs.as_deref(),
        limit,
        offset,
    )
    .await
    .map_err(db_error)?;
    let total =
        crate::repos::backup_coverage_reports::count(pool, sites.as_deref(), envs.as_deref())
            .await
            .map_err(db_error)?;
    Ok((
        total_count_headers(total),
        Json(serde_json::to_value(&records).unwrap_or_default()),
    ))
}

/// GET /api/protect/backup/coverage-reports/{id} — fetch a single coverage report by id.
/// Returns 404 when absent or when no DB is configured.
async fn backup_coverage_report_get(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> ApiResult {
    let pool = get_db().ok_or_else(|| status_404(&id))?;
    let record = crate::repos::backup_coverage_reports::get(pool, &id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&id))?;
    // #2: a report whose footprint is not contained in the principal's scope 404s
    // exactly like a missing one (no cross-scope existence oracle).
    if !multi_scope_permits(&session, &record.site_scope, &record.environment_scope) {
        return Err(status_404(&id));
    }
    Ok(Json(serde_json::to_value(&record).unwrap_or_default()))
}

async fn backup_coverage_contract() -> Json<Value> {
    Json(json!({
        "source": "static-seed",
        "coverageMode": "dry-run-report",
        "dryRunRequired": true,
        "providerCallsEnabled": false,
        "liveBackupQueryAllowed": false,
        "supportedWorkflows": ["backup-coverage-report","restore-plan","restore-validation","restore-approval","restore-execution"],
        "requiredInputs": ["siteScope","environmentScope","sourceCiKey","restoreType","restorePoint","targetSite","targetEnvironment","owner"],
        "requiredGuards": ["backup-state-known","restore-point-verified","target-capacity-reviewed","network-isolation-reviewed","approval-route-assigned","evidence-redacted"],
        "blockedReasons": ["provider-calls-disabled","live-backup-query-disabled","backup-state-unknown","restore-point-not-verified","target-capacity-not-reviewed"],
        "requiredEvidence": ["Coverage report summary","Restore dry-run plan","Backup integrity check","Restore execution log","Post-restore verification","Evidence references"]
    }))
}

