async fn decommission_approve(
    Path(id): Path<String>,
    Extension(session): Extension<AuthSession>,
) -> ApiResult {
    let actor_principal = authenticated_principal_id(&session)?.to_string();
    let pool = get_db().ok_or_else(status_503_no_db)?;

    let req = crate::repos::decommissions::get(pool, &id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&id))?;

    // Scope guard BEFORE the engine state transition so an out-of-scope request
    // 404s exactly like a missing one — never a 409 oracle leaking its status (#2).
    site_scope_guard_or_404(&session, &req.site, &id)?;

    let before = crate::repos::decommissions::status_str(&req.status);

    // Approver = authenticated caller (from request extensions), never a
    // client-supplied body field — the audit trail must name the real principal.
    let approved = server_decommission::approve_decommission(&req, &actor_principal)
        .map_err(|e| status_409(&e))?;

    let mut tx = pool.begin().await.map_err(db_error)?;
    let ok = crate::repos::decommissions::transition(&mut tx, before, &approved, None)
        .await
        .map_err(db_error)?;
    if !ok {
        return Err(status_409("state changed concurrently; reload and retry"));
    }
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "decommission-approve",
            Some(before),
            "approved",
            json!({
                "decommission_id": approved.id,
                "server_name": approved.server_name,
                "site": approved.site,
            }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;

    Ok(Json(serde_json::to_value(&approved).unwrap_or_default()))
}

async fn decommission_quarantine(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> ApiResult {
    let actor_principal = authenticated_principal_id(&session)?.to_string();
    let pool = get_db().ok_or_else(status_503_no_db)?;

    let req = crate::repos::decommissions::get(pool, &id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&id))?;

    // Scope guard BEFORE the engine transition: out-of-scope 404s like a miss (#2).
    site_scope_guard_or_404(&session, &req.site, &id)?;

    let before = crate::repos::decommissions::status_str(&req.status);

    let quarantined = server_decommission::quarantine_server(&req).map_err(|e| status_409(&e))?;

    let mut tx = pool.begin().await.map_err(db_error)?;
    let ok =
        crate::repos::decommissions::transition(&mut tx, before, &quarantined, Some("quarantine"))
            .await
            .map_err(db_error)?;
    if !ok {
        return Err(status_409("state changed concurrently; reload and retry"));
    }
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "decommission-quarantine",
            Some(before),
            "quarantined",
            json!({
                "decommission_id": quarantined.id,
                "server_name": quarantined.server_name,
                "site": quarantined.site,
            }),
        ),
    )
    .await
    .map_err(db_error)?;
    // #11/#2: emit the operational domain event in the SAME tx as the audit row, so
    // the destructive decommission lifecycle is queryable in /api/events. A
    // decommission is SITE-ONLY — environment is NULL — and domain_events::list
    // keeps such site-only events out of an environment-scoped principal's feed, in
    // lock-step with site_scope_guard_or_404 above. `to_status` ("Quarantined") is
    // NOT in event_alerts::alert_worthy_statuses(), so this is a non-alerting event.
    crate::repos::domain_events::insert(
        &mut *tx,
        crate::repos::domain_events::NewEvent {
            event_type: "decommission.quarantined",
            aggregate_type: "decommission",
            aggregate_id: &quarantined.id,
            site: Some(&req.site),
            environment: None,
            actor: &actor_principal,
            payload: json!({
                "from_status": before,
                "to_status": crate::repos::decommissions::status_str(&quarantined.status),
                "server_name": &quarantined.server_name,
                "site": &req.site,
            }),
        },
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;

    Ok(Json(serde_json::to_value(&quarantined).unwrap_or_default()))
}

