async fn certificates_renew(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
    Json(body): Json<CertificateRenewRequest>,
) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;

    let cert = crate::repos::certificates::get(pool, &id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&id))?;
    // #2: certificates are site-only — guard on the loaded row's site.
    scope_guard_or_404(&session, &cert.site, "", &id)?;

    // A revoked certificate is a state conflict (409), not malformed input (400).
    if cert.status == certificate_lifecycle::CertificateStatus::Revoked {
        return Err(status_409("Cannot renew a revoked certificate"));
    }

    let before = crate::repos::certificates::status_str(&cert.status);

    // renew is a same-status transition (Active -> Active); the CAS guards on the
    // prior valid_to so two concurrent renews cannot both win.
    let renewed = certificate_lifecycle::renew_certificate(&cert, body.validity_days)
        .map_err(|e| status_400(&e))?;

    let mut tx = pool.begin().await.map_err(db_error)?;
    let persisted =
        crate::repos::certificates::transition(&mut *tx, before, &cert.valid_to, &renewed, None)
            .await
            .map_err(db_error)?
            .ok_or_else(|| status_409("state changed concurrently; reload and retry"))?;
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "certificate-renew",
            Some(before),
            "renewed",
            json!({
                "cert_id": cert.id,
                "common_name": cert.common_name,
                "site": cert.site,
            }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;

    Ok(Json(serde_json::to_value(&persisted).unwrap_or_default()))
}

async fn certificates_revoke(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;

    let cert = crate::repos::certificates::get(pool, &id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&id))?;
    // #2: certificates are site-only — guard on the loaded row's site.
    scope_guard_or_404(&session, &cert.site, "", &id)?;

    let before = crate::repos::certificates::status_str(&cert.status);

    // Engine guard: returns Err if already revoked → 409.
    let revoked = certificate_lifecycle::revoke_certificate(&cert).map_err(|e| status_409(&e))?;

    let mut tx = pool.begin().await.map_err(db_error)?;
    let persisted =
        crate::repos::certificates::transition(&mut *tx, before, &cert.valid_to, &revoked, None)
            .await
            .map_err(db_error)?
            .ok_or_else(|| status_409("state changed concurrently; reload and retry"))?;
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "certificate-revoke",
            Some(before),
            "revoked",
            json!({
                "cert_id": cert.id,
                "common_name": cert.common_name,
                "site": cert.site,
            }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;

    Ok(Json(serde_json::to_value(&persisted).unwrap_or_default()))
}

const DEFAULT_CERTIFICATE_EXPIRY_PAGE_ROWS: usize = 100;
const MAX_CERTIFICATE_EXPIRY_PAGE_ROWS: usize = 200;
const MAX_CERTIFICATE_CURSOR_BYTES: usize = 768;
const MAX_CERTIFICATE_CURSOR_DECODED_BYTES: usize = 512;
const CERTIFICATE_EXPIRY_CURSOR_KIND: &[u8] = b"expiry-v1";
const CERTIFICATE_INVENTORY_CURSOR_KIND: &[u8] = b"inventory-v1";

fn certificate_site_within_query_bounds(site: &str) -> bool {
    (1..=crate::repos::certificates::MAX_CERTIFICATE_SITE_QUERY_BYTES).contains(&site.len())
}

static DRY_RUN_CERTIFICATE_CURSOR_KEY: OnceLock<[u8; 32]> = OnceLock::new();

fn dry_run_certificate_cursor_key() -> &'static [u8; 32] {
    DRY_RUN_CERTIFICATE_CURSOR_KEY.get_or_init(|| {
        use rand::RngCore;
        let mut key = [0_u8; 32];
        rand::rngs::OsRng.fill_bytes(&mut key);
        key
    })
}

/// Select the purpose-specific configured key in every mode when valid.
/// Credential-free, loopback-only dry-run modes receive one process-ephemeral CSPRNG key so a
/// continuation remains usable for this process lifetime without introducing
/// a checked-in/default secret. Persisted authentication modes and generic
/// OIDC still fail closed if startup/config validation did not provide the
/// required key. The session verifier key is deliberately never a substitute.
fn certificate_cursor_hmac_key_for_config(
    config: &ryuki_core::config::RyukiConfig,
) -> Result<&[u8], &'static str> {
    let configured = &config.security.certificate_cursor_hmac_key;
    let key = configured.as_bytes();
    if !configured.is_empty() {
        if key.len() >= 32
            && !key.iter().any(u8::is_ascii_control)
            && configured.trim() == configured.as_str()
            && key != config.session.credential_hmac_key.as_bytes()
        {
            return Ok(key);
        }
        return Err("certificate cursor signing key is unavailable");
    }
    if config.auth_mode.is_credential_free() && !config.oidc.enabled {
        return Ok(dry_run_certificate_cursor_key());
    }
    Err("certificate cursor signing key is unavailable")
}

#[cfg(test)]
fn certificate_cursor_hmac_key() -> Result<&'static [u8], &'static str> {
    Ok(b"ryuki-test-certificate-cursor-key-v1") // secret-scan-allow: test-only fixture
}

#[cfg(not(test))]
fn certificate_cursor_hmac_key() -> Result<&'static [u8], &'static str> {
    certificate_cursor_hmac_key_for_config(crate::config_store::get_app_config())
}

fn certificate_cursor_signature(kind: &[u8], payload: &[u8]) -> Result<String, &'static str> {
    let mut mac = hmac::Hmac::<Sha256>::new_from_slice(certificate_cursor_hmac_key()?)
        .map_err(|_| "certificate cursor signing key is unavailable")?;
    mac.update(b"ryuki/certificate-cursor/v1\0");
    mac.update(&(kind.len() as u64).to_be_bytes());
    mac.update(kind);
    mac.update(&(payload.len() as u64).to_be_bytes());
    mac.update(payload);
    Ok(base64::Engine::encode(
        &base64::engine::general_purpose::URL_SAFE_NO_PAD,
        mac.finalize().into_bytes(),
    ))
}

fn certificate_cursor_signature_valid(kind: &[u8], payload: &[u8], encoded: &str) -> bool {
    let Ok(signature) =
        base64::Engine::decode(&base64::engine::general_purpose::URL_SAFE_NO_PAD, encoded)
    else {
        return false;
    };
    let Ok(key) = certificate_cursor_hmac_key() else {
        return false;
    };
    let Ok(mut mac) = hmac::Hmac::<Sha256>::new_from_slice(key) else {
        return false;
    };
    mac.update(b"ryuki/certificate-cursor/v1\0");
    mac.update(&(kind.len() as u64).to_be_bytes());
    mac.update(kind);
    mac.update(&(payload.len() as u64).to_be_bytes());
    mac.update(payload);
    mac.verify_slice(&signature).is_ok()
}

#[derive(Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
struct CertificateExpiryCursorClaims {
    version: u8,
    site: String,
    days: i64,
    expires_before: String,
    valid_to: String,
    id: String,
}

#[derive(Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
struct CertificateExpiryCursorEnvelope {
    claims: CertificateExpiryCursorClaims,
    signature: String,
}

struct CertificateExpiryCursor {
    expires_before: chrono::DateTime<chrono::Utc>,
    valid_to: chrono::DateTime<chrono::Utc>,
    id: Uuid,
}

fn certificate_expiry_page_size(limit: Option<usize>) -> usize {
    limit
        .unwrap_or(DEFAULT_CERTIFICATE_EXPIRY_PAGE_ROWS)
        .clamp(1, MAX_CERTIFICATE_EXPIRY_PAGE_ROWS)
}

fn encode_certificate_expiry_cursor(
    site: &str,
    days: i64,
    expires_before: chrono::DateTime<chrono::Utc>,
    valid_to: &str,
    id: &str,
) -> Result<String, &'static str> {
    let valid_to = chrono::DateTime::parse_from_rfc3339(valid_to)
        .map_err(|_| "invalid certificate expiry cursor state")?
        .with_timezone(&chrono::Utc);
    Uuid::parse_str(id).map_err(|_| "invalid certificate expiry cursor state")?;
    let claims = CertificateExpiryCursorClaims {
        version: 1,
        site: site.to_string(),
        days,
        expires_before: expires_before.to_rfc3339(),
        valid_to: valid_to.to_rfc3339(),
        id: id.to_string(),
    };
    let claims_bytes =
        serde_json::to_vec(&claims).map_err(|_| "invalid certificate expiry cursor state")?;
    let envelope = CertificateExpiryCursorEnvelope {
        signature: certificate_cursor_signature(CERTIFICATE_EXPIRY_CURSOR_KIND, &claims_bytes)?,
        claims,
    };
    let bytes =
        serde_json::to_vec(&envelope).map_err(|_| "invalid certificate expiry cursor state")?;
    if bytes.len() > MAX_CERTIFICATE_CURSOR_DECODED_BYTES {
        return Err("invalid certificate expiry cursor state");
    }
    let encoded = base64::Engine::encode(&base64::engine::general_purpose::URL_SAFE_NO_PAD, bytes);
    if encoded.len() > MAX_CERTIFICATE_CURSOR_BYTES {
        return Err("invalid certificate expiry cursor state");
    }
    Ok(encoded)
}

fn decode_certificate_expiry_cursor(
    raw: &str,
    expected_site: &str,
    expected_days: i64,
) -> Result<CertificateExpiryCursor, &'static str> {
    const INVALID: &str = "invalid or stale certificate expiry cursor";
    if raw.is_empty() || raw.len() > MAX_CERTIFICATE_CURSOR_BYTES {
        return Err(INVALID);
    }
    let bytes = base64::Engine::decode(&base64::engine::general_purpose::URL_SAFE_NO_PAD, raw)
        .map_err(|_| INVALID)?;
    if bytes.len() > MAX_CERTIFICATE_CURSOR_DECODED_BYTES {
        return Err(INVALID);
    }
    let envelope: CertificateExpiryCursorEnvelope =
        serde_json::from_slice(&bytes).map_err(|_| INVALID)?;
    let claims_bytes = serde_json::to_vec(&envelope.claims).map_err(|_| INVALID)?;
    if !certificate_cursor_signature_valid(
        CERTIFICATE_EXPIRY_CURSOR_KIND,
        &claims_bytes,
        &envelope.signature,
    ) {
        return Err(INVALID);
    }
    let payload = envelope.claims;
    if payload.version != 1 || payload.site != expected_site || payload.days != expected_days {
        return Err(INVALID);
    }
    let expires_before = chrono::DateTime::parse_from_rfc3339(&payload.expires_before)
        .map_err(|_| INVALID)?
        .with_timezone(&chrono::Utc);
    let valid_to = chrono::DateTime::parse_from_rfc3339(&payload.valid_to)
        .map_err(|_| INVALID)?
        .with_timezone(&chrono::Utc);
    if valid_to > expires_before {
        return Err(INVALID);
    }
    let id = Uuid::parse_str(&payload.id).map_err(|_| INVALID)?;
    Ok(CertificateExpiryCursor {
        expires_before,
        valid_to,
        id,
    })
}

async fn certificates_expiring(
    AuthExtractor(session): AuthExtractor,
    Query(query): Query<CertificateExpiringQuery>,
) -> Result<(HeaderMap, Json<Value>), (StatusCode, Json<Value>)> {
    // #2: scoped-site read ("" = all sites for an unrestricted caller).
    let site_scoped = enforce_site_scope(&session, query.site.as_deref(), "")?;
    if !site_scoped.is_empty() && !certificate_site_within_query_bounds(&site_scoped) {
        return Err(status_400(
            "certificate site must contain 1-32 UTF-8 octets",
        ));
    }
    let days = query.days.unwrap_or(90);
    const MAX_EXPIRY_WINDOW_DAYS: i64 = 36_500;
    if !(-MAX_EXPIRY_WINDOW_DAYS..=MAX_EXPIRY_WINDOW_DAYS).contains(&days) {
        return Err(status_400(
            "days is outside the supported certificate-expiry window",
        ));
    }
    if query.offset.unwrap_or(0) != 0 {
        return Err(status_400(
            "certificate-expiry offset pagination is no longer supported; use cursor",
        ));
    }
    let limit = certificate_expiry_page_size(query.limit);
    let cursor = query
        .cursor
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|raw| decode_certificate_expiry_cursor(raw, &site_scoped, days))
        .transpose()
        .map_err(status_400)?;
    let expires_before = match &cursor {
        Some(cursor) => cursor.expires_before,
        None => chrono::Utc::now()
            .checked_add_signed(chrono::Duration::days(days))
            .ok_or_else(|| status_400("days produces an invalid certificate-expiry timestamp"))?,
    };

    let Some(pool) = get_db() else {
        return Ok((HeaderMap::new(), Json(serde_json::Value::Array(vec![]))));
    };
    let site = (!site_scoped.is_empty()).then_some(site_scoped.as_str());
    let after = cursor.as_ref().map(|cursor| (&cursor.valid_to, &cursor.id));
    let mut results = crate::repos::certificates::list_expiring_page(
        pool,
        site,
        &expires_before,
        after,
        (limit + 1) as i64,
    )
    .await
    .map_err(db_error)?;
    let has_more = results.len() > limit;
    if has_more {
        results.truncate(limit);
    }
    let next_cursor = if has_more {
        results
            .last()
            .map(|certificate| {
                encode_certificate_expiry_cursor(
                    &site_scoped,
                    days,
                    expires_before,
                    &certificate.valid_to,
                    &certificate.id,
                )
            })
            .transpose()
            .map_err(|error| {
                (
                    StatusCode::INTERNAL_SERVER_ERROR,
                    Json(json!({"error": error})),
                )
            })?
    } else {
        None
    };
    let mut headers = HeaderMap::new();
    if let Some(cursor) = next_cursor {
        if let Ok(value) = axum::http::HeaderValue::from_str(&cursor) {
            headers.insert("x-next-cursor", value);
        }
    }
    Ok((
        headers,
        Json(serde_json::to_value(results).unwrap_or_default()),
    ))
}

/// Bounded certificate inventory traversal.  Legacy fields remain deserializable
/// only so the endpoint can return a clear migration error; the accepted query
/// contract is fixed descending `(created_at,id)` keyset order.
#[derive(Debug, Deserialize, Default)]
struct CertListParams {
    limit: Option<usize>,
    offset: Option<usize>,
    include_total: Option<bool>,
    cursor: Option<String>,
    status: Option<String>,
    hostname: Option<String>,
    q: Option<String>,
    sort: Option<String>,
    direction: Option<String>,
}

const DEFAULT_CERTIFICATE_PAGE_ROWS: usize = 50;
const MAX_CERTIFICATE_PAGE_ROWS: usize = 100;
const MAX_CERTIFICATE_SCOPE_SITES: usize = 64;

fn certificate_page_size(limit: Option<usize>) -> usize {
    limit
        .unwrap_or(DEFAULT_CERTIFICATE_PAGE_ROWS)
        .clamp(1, MAX_CERTIFICATE_PAGE_ROWS)
}

#[derive(Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
struct CertificateInventoryCursorClaims {
    version: u8,
    scope: String,
    created_at: String,
    id: String,
}

#[derive(Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
struct CertificateInventoryCursorEnvelope {
    claims: CertificateInventoryCursorClaims,
    signature: String,
}

fn certificate_inventory_scope(sites: Option<&[String]>) -> String {
    let mut hasher = Sha256::new();
    hasher.update(b"ryuki/certificate-inventory-scope/v1\0");
    match sites {
        None => hasher.update([0_u8]),
        Some(sites) => {
            hasher.update([1_u8]);
            for site in sites {
                hasher.update((site.len() as u64).to_be_bytes());
                hasher.update(site.as_bytes());
            }
        }
    }
    format!("{:x}", hasher.finalize())
}

fn encode_certificate_inventory_cursor(
    scope: &str,
    created_at: &str,
    id: &str,
) -> Result<String, &'static str> {
    let created_at = chrono::DateTime::parse_from_rfc3339(created_at)
        .map_err(|_| "invalid certificate inventory cursor state")?
        .with_timezone(&chrono::Utc);
    let id = Uuid::parse_str(id).map_err(|_| "invalid certificate inventory cursor state")?;
    let claims = CertificateInventoryCursorClaims {
        version: 1,
        scope: scope.to_string(),
        created_at: created_at.to_rfc3339(),
        id: id.to_string(),
    };
    let claims_bytes =
        serde_json::to_vec(&claims).map_err(|_| "invalid certificate inventory cursor state")?;
    let envelope = CertificateInventoryCursorEnvelope {
        signature: certificate_cursor_signature(CERTIFICATE_INVENTORY_CURSOR_KIND, &claims_bytes)?,
        claims,
    };
    let bytes =
        serde_json::to_vec(&envelope).map_err(|_| "invalid certificate inventory cursor state")?;
    if bytes.len() > MAX_CERTIFICATE_CURSOR_DECODED_BYTES {
        return Err("invalid certificate inventory cursor state");
    }
    let encoded = base64::Engine::encode(&base64::engine::general_purpose::URL_SAFE_NO_PAD, bytes);
    if encoded.len() > MAX_CERTIFICATE_CURSOR_BYTES {
        return Err("invalid certificate inventory cursor state");
    }
    Ok(encoded)
}

fn decode_certificate_inventory_cursor(
    raw: &str,
    expected_scope: &str,
) -> Result<(chrono::DateTime<chrono::Utc>, Uuid), &'static str> {
    const INVALID: &str = "invalid or stale certificate inventory cursor";
    if raw.is_empty() || raw.len() > MAX_CERTIFICATE_CURSOR_BYTES {
        return Err(INVALID);
    }
    let bytes = base64::Engine::decode(&base64::engine::general_purpose::URL_SAFE_NO_PAD, raw)
        .map_err(|_| INVALID)?;
    if bytes.len() > MAX_CERTIFICATE_CURSOR_DECODED_BYTES {
        return Err(INVALID);
    }
    let envelope: CertificateInventoryCursorEnvelope =
        serde_json::from_slice(&bytes).map_err(|_| INVALID)?;
    let claims_bytes = serde_json::to_vec(&envelope.claims).map_err(|_| INVALID)?;
    if !certificate_cursor_signature_valid(
        CERTIFICATE_INVENTORY_CURSOR_KIND,
        &claims_bytes,
        &envelope.signature,
    ) || envelope.claims.version != 1
        || envelope.claims.scope != expected_scope
    {
        return Err(INVALID);
    }
    let created_at = chrono::DateTime::parse_from_rfc3339(&envelope.claims.created_at)
        .map_err(|_| INVALID)?
        .with_timezone(&chrono::Utc);
    let id = Uuid::parse_str(&envelope.claims.id).map_err(|_| INVALID)?;
    Ok((created_at, id))
}

async fn certificates_inventory(
    AuthExtractor(session): AuthExtractor,
    Query(params): Query<CertListParams>,
) -> Result<(HeaderMap, Json<Value>), (StatusCode, Json<Value>)> {
    let nonblank = |value: &Option<String>| {
        value
            .as_deref()
            .map(str::trim)
            .is_some_and(|value| !value.is_empty())
    };
    if params.offset.unwrap_or(0) != 0
        || params.include_total.unwrap_or(false)
        || nonblank(&params.status)
        || nonblank(&params.hostname)
        || nonblank(&params.q)
        || params
            .sort
            .as_deref()
            .map(str::trim)
            .is_some_and(|sort| !sort.is_empty() && sort != "created_at")
        || params
            .direction
            .as_deref()
            .map(str::trim)
            .is_some_and(|direction| {
                !direction.is_empty() && !direction.eq_ignore_ascii_case("desc")
            })
    {
        return Err(status_400(
            "certificate inventory supports only descending created_at cursor pagination; filters, offsets, alternate sorts, and exact totals are unavailable",
        ));
    }
    let limit = certificate_page_size(params.limit);
    let sites = match list_site_scope(&session) {
        ListSiteScope::Empty => {
            return Ok((HeaderMap::new(), Json(serde_json::Value::Array(vec![]))));
        }
        ListSiteScope::All => None,
        ListSiteScope::Sites(mut sites) => {
            sites.sort();
            sites.dedup();
            if sites.len() > MAX_CERTIFICATE_SCOPE_SITES {
                return Err((
                    StatusCode::SERVICE_UNAVAILABLE,
                    Json(json!({
                        "error": "certificate inventory scope exceeds the bounded site-merge capacity",
                        "maximum_sites": MAX_CERTIFICATE_SCOPE_SITES,
                    })),
                ));
            }
            if sites
                .iter()
                .any(|site| !certificate_site_within_query_bounds(site))
            {
                return Err((
                    StatusCode::SERVICE_UNAVAILABLE,
                    Json(json!({
                        "error": "certificate inventory scope contains an out-of-bounds site authority",
                        "maximum_site_bytes": crate::repos::certificates::MAX_CERTIFICATE_SITE_QUERY_BYTES,
                    })),
                ));
            }
            Some(sites)
        }
    };
    let cursor_scope = certificate_inventory_scope(sites.as_deref());
    let after = params
        .cursor
        .as_deref()
        .map(str::trim)
        .filter(|cursor| !cursor.is_empty())
        .map(|cursor| decode_certificate_inventory_cursor(cursor, &cursor_scope))
        .transpose()
        .map_err(status_400)?;
    let Some(pool) = get_db() else {
        return Ok((HeaderMap::new(), Json(serde_json::Value::Array(vec![]))));
    };
    let query = crate::repos::certificates::CertificateListQuery {
        sites,
        after,
        limit: (limit + 1) as i64,
    };
    let mut page = crate::repos::certificates::list_page(pool, &query)
        .await
        .map_err(db_error)?;
    let has_more = page.len() > limit;
    if has_more {
        page.truncate(limit);
    }
    let next_cursor = if has_more {
        page.last()
            .map(|certificate| {
                encode_certificate_inventory_cursor(
                    &cursor_scope,
                    &certificate.created_at,
                    &certificate.id,
                )
            })
            .transpose()
            .map_err(|error| {
                (
                    StatusCode::INTERNAL_SERVER_ERROR,
                    Json(json!({"error": error})),
                )
            })?
    } else {
        None
    };
    let mut headers = HeaderMap::new();
    if let Some(cursor) = next_cursor {
        let value = axum::http::HeaderValue::from_str(&cursor).map_err(|_| {
            (
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(json!({"error": "could not encode certificate inventory cursor"})),
            )
        })?;
        headers.insert("x-next-cursor", value);
    }

    Ok((
        headers,
        Json(serde_json::to_value(&page).unwrap_or_default()),
    ))
}

async fn certificates_get(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> ApiResult {
    let Some(pool) = get_db() else {
        return Err(status_404(&id));
    };
    let record = crate::repos::certificates::get(pool, &id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&id))?;
    scope_guard_or_404(&session, &record.site, "", &id)?;
    Ok(Json(serde_json::to_value(&record).unwrap_or_default()))
}

/// DELETE /api/maintain/certificates/{id} — operational cleanup of a TERMINAL
/// certificate. Only an `Expired`/`Revoked` cert is deletable: an `Active`/`Expiring`
/// cert is LIVE, and removing its record from the `execute` tier would lose tracking of
/// an in-use certificate (the patch-wave delete lesson). Certificates are a leaf table
/// (no FK references them) — no cascade. Site-scoped (out-of-scope → 404, no oracle).
async fn certificates_delete(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let cert = crate::repos::certificates::get(pool, &id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&id))?;
    // #2: site-only — an out-of-scope cert 404s exactly like a missing one.
    scope_guard_or_404(&session, &cert.site, "", &id)?;
    if !crate::repos::certificates::certificate_status_deletable(&cert.status) {
        return Err(status_409(
            "only an Expired or Revoked certificate can be deleted (an Active/Expiring certificate is in use)",
        ));
    }
    let before = crate::repos::certificates::status_str(&cert.status);
    let mut tx = pool.begin().await.map_err(db_error)?;
    match crate::repos::certificates::delete(&mut tx, &id, &cert.status, &cert.site)
        .await
        .map_err(db_error)?
    {
        crate::repos::certificates::DeleteOutcome::Deleted => {
            // Tombstone audit: the row is gone, so capture the cert's identity + scope
            // for the durable trail. The table stores NO key material / CSR — these are
            // the same identity fields the cert read endpoints already expose.
            audit::record_audit_tx(
                &mut tx,
                &session,
                &audit::security_audit(
                    "certificate-delete",
                    Some(before),
                    "deleted",
                    json!({
                        "certificate_id": &id,
                        "common_name": &cert.common_name,
                        "hostname": &cert.hostname,
                        "site": &cert.site,
                    }),
                ),
            )
            .await
            .map_err(db_error)?;
            tx.commit().await.map_err(db_error)?;
            Ok(Json(json!({ "deleted": id })))
        }
        crate::repos::certificates::DeleteOutcome::BlockedStatus => {
            tx.rollback().await.ok();
            Err(status_409("certificate status does not permit deletion"))
        }
        crate::repos::certificates::DeleteOutcome::StaleStatus => {
            tx.rollback().await.ok();
            Err(status_409(
                "certificate changed concurrently; reload and retry",
            ))
        }
        crate::repos::certificates::DeleteOutcome::NotFound => {
            tx.rollback().await.ok();
            Err(status_404(&id))
        }
    }
}

async fn certificate_lifecycle_contract() -> Json<Value> {
    Json(json!({
        "source": "static-seed",
        "providerCallsEnabled": false,
        "liveExecutionAllowed": false,
        "dryRunRequired": true,
        "supportedWorkflows": ["certificate-request","certificate-validate","certificate-approve","certificate-install","certificate-verify","certificate-renew","certificate-revoke","certificate-expiry-check","certificate-inventory"],
        "validStatuses": ["Active","Expiring","Expired","Revoked"],
        "validServiceTypes": ["IIS","VMware","ESXi","RDP","SQL Server","Apache","Nginx","LDAP","SMTP","Custom"],
        "requiredInputs": ["commonName","subject","serviceType","hostname","site","validityDays"],
        "requiredGuards": ["common-name-known","subject-known","service-type-known","hostname-known","site-known","validity-days-valid","evidence-redacted"],
        "blockedReasons": ["provider-calls-disabled","live-execution-disabled","unknown-certificate","invalid-validity-days","missing-common-name","missing-service-type","missing-hostname","missing-site","evidence-not-redacted"],
        "requiredEvidence": ["Certificate request summary","Validation result","Approval decision","Install evidence","Post-install verification","Expiry report","Inventory summary","Evidence references"],
        "rules": [
            {"id":"no-live-certificate-action","decision":"block","requirement":"Certificate lifecycle returns dry-run decisions only and never calls a live CA, mutates certificate stores, or deploys certificates to endpoints.","evidence":"Certificate request summary"},
            {"id":"validation-before-approval-required","decision":"block","requirement":"Every certificate request must pass field validation before approval readiness can be represented.","evidence":"Validation result"},
            {"id":"post-install-verification-required","decision":"block","requirement":"Certificate install must be followed by a verify step before the lifecycle can move to maintain.","evidence":"Post-install verification"},
            {"id":"expiry-monitoring-required","decision":"block","requirement":"Expiring and expired certificates must be surfaced through the expiry check endpoint with site and days-window filtering.","evidence":"Expiry report"},
            {"id":"raw-certificate-data-not-exposed","decision":"block","requirement":"Certificate lifecycle evidence must use safe summaries only and must not expose private keys, certificate signing requests, CA endpoints, raw certificate blobs, or provider payloads.","evidence":"Evidence references"}
        ]
    }))
}

// ─── Alert routing handlers ───

const ALERT_ROUTE_SCOPE_CLASSIFICATION: &str = "site_environment";

/// Canonicalize and validate the required dual-axis classification for a new
/// route or a route-resolution query.  Existing rows without this provenance
/// are quarantined by migration 175 and never reach an API projection.
fn canonical_alert_route_scope(
    site: &str,
    environment: &str,
) -> Result<(String, String), (StatusCode, Json<Value>)> {
    let site =
        site_registry::normalize_site_code_for_lookup(site).map_err(|error| status_400(&error))?;
    if !site_registry::is_valid_site(&site) {
        return Err(status_400(
            "alert route site must be an active canonical site",
        ));
    }

    reject_control_chars("environment", environment)?;
    let environment = environment.trim();
    if environment.is_empty() {
        return Err(status_400("alert route environment is required"));
    }
    if environment.chars().count() > 64 {
        return Err(status_400(
            "alert route environment must be at most 64 characters",
        ));
    }
    Ok((site, environment.to_string()))
}

/// One verified dual-axis `alert_routes` row (migration 175).  Every query that
/// constructs this type includes the classification + scope predicate before
/// projection, so nullable legacy rows cannot be decoded or exposed.
#[derive(sqlx::FromRow)]
struct AlertRouteRow {
    id: uuid::Uuid,
    site: String,
    environment: String,
    trigger_name: String,
    severity: String,
    host_group: String,
    support_group: String,
    priority: String,
    enabled: bool,
    created_at: chrono::DateTime<chrono::Utc>,
    updated_at: chrono::DateTime<chrono::Utc>,
}

impl AlertRouteRow {
    fn to_json(&self) -> Value {
        json!({
            "id": self.id.to_string(),
            "site": self.site,
            "environment": self.environment,
            "trigger_name": self.trigger_name,
            "severity": self.severity,
            "host_group": self.host_group,
            "support_group": self.support_group,
            "priority": self.priority,
            "enabled": self.enabled,
            "created_at": self.created_at.to_rfc3339(),
            "updated_at": self.updated_at.to_rfc3339(),
        })
    }
}

const ALERT_ROUTE_COLUMNS: &str = "id, site, environment, trigger_name, severity, host_group, \
     support_group, priority, enabled, created_at, updated_at";

async fn alert_routes_create(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<AlertRouteCreateRequest>,
) -> ApiResult {
    operation_capability_guard(&session, OperationCapability::MonitoringAlertRoutingManage)?;
    let (site, environment) = canonical_alert_route_scope(&body.site, &body.environment)?;
    guard_body_scope_dual(&session, &site, &environment)?;
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let site_is_active: bool = sqlx::query_scalar(
        "SELECT EXISTS(SELECT 1 FROM site_registry WHERE unlocode = $1 AND active = TRUE)",
    )
    .bind(&site)
    .fetch_one(pool)
    .await
    .map_err(db_error)?;
    if !site_is_active {
        return Err(status_400("alert route site must be currently active"));
    }

    // Pure validation/construction: durable creation must not mutate the
    // legacy in-memory route store before the database + audit transaction.
    let route = alert_routing_engine::prepare_alert_route(
        &body.trigger_name,
        &body.severity,
        &body.host_group,
        &body.support_group,
        &body.priority,
    )
    .map_err(|e| status_400(&e))?;

    // Persist + audit ATOMICALLY.  Scope comes only from the canonical,
    // server-validated values above; legacy/unclassified is never an API option.
    let uid = uuid::Uuid::parse_str(&route.id).map_err(|e| status_400(&e.to_string()))?;
    let mut tx = pool.begin().await.map_err(db_error)?;
    let row: Option<AlertRouteRow> = sqlx::query_as(&format!(
        "INSERT INTO alert_routes \
            (id, site, environment, scope_classification, trigger_name, severity, \
             host_group, support_group, priority, enabled) \
         SELECT $1, registry.unlocode, $3, $4, $5, $6, $7, $8, $9, $10 \
         FROM site_registry AS registry \
         WHERE registry.unlocode = $2 AND registry.active = TRUE \
         RETURNING {ALERT_ROUTE_COLUMNS}"
    ))
    .bind(uid)
    .bind(&site)
    .bind(&environment)
    .bind(ALERT_ROUTE_SCOPE_CLASSIFICATION)
    .bind(&route.trigger_name)
    .bind(&route.severity)
    .bind(&route.host_group)
    .bind(&route.support_group)
    .bind(&route.priority)
    .bind(route.enabled)
    .fetch_optional(&mut *tx)
    .await
    .map_err(db_error)?;
    let Some(row) = row else {
        tx.rollback().await.ok();
        return Err(status_400("alert route site must be currently active"));
    };
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "alert-route-create",
            None,
            "created",
            json!({
                "route_id": row.id.to_string(),
                "site": &row.site,
                "environment": &row.environment,
                "trigger_name": &row.trigger_name,
            }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;
    Ok(Json(row.to_json()))
}

async fn alert_routes_list(AuthExtractor(session): AuthExtractor) -> ApiResult {
    let Some(pool) = get_db() else {
        // The in-memory seeds have no verified scope provenance.  Fail closed
        // to an empty collection rather than reclassify or expose them.
        return Ok(Json(json!([])));
    };
    let rows: Vec<AlertRouteRow> = sqlx::query_as(&format!(
        "SELECT {ALERT_ROUTE_COLUMNS} \
         FROM alert_routes AS route \
         JOIN site_registry AS registry \
           ON registry.unlocode = route.site AND registry.active = TRUE \
         WHERE route.scope_classification = 'site_environment' \
           AND (cardinality($1::text[]) = 0 OR route.site = ANY($1)) \
           AND (cardinality($2::text[]) = 0 OR route.environment = ANY($2)) \
         ORDER BY route.created_at, route.id \
         LIMIT {MAX_LIST_ROWS}"
    ))
    .bind(&session.site_scope)
    .bind(&session.environment_scope)
    .fetch_all(pool)
    .await
    .map_err(db_error)?;
    let routes: Vec<Value> = rows.iter().map(AlertRouteRow::to_json).collect();
    Ok(Json(json!(routes)))
}

async fn alert_routes_get(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> ApiResult {
    let Some(pool) = get_db() else {
        return Err(status_404(&id));
    };
    let Ok(uid) = uuid::Uuid::parse_str(&id) else {
        return Err(status_404(&id));
    };
    let row: Option<AlertRouteRow> = sqlx::query_as(&format!(
        "SELECT {ALERT_ROUTE_COLUMNS} \
         FROM alert_routes AS route \
         JOIN site_registry AS registry \
           ON registry.unlocode = route.site AND registry.active = TRUE \
         WHERE route.id = $1 \
           AND route.scope_classification = 'site_environment' \
           AND (cardinality($2::text[]) = 0 OR route.site = ANY($2)) \
           AND (cardinality($3::text[]) = 0 OR route.environment = ANY($3))"
    ))
    .bind(uid)
    .bind(&session.site_scope)
    .bind(&session.environment_scope)
    .fetch_optional(pool)
    .await
    .map_err(db_error)?;
    match row {
        Some(route) => Ok(Json(route.to_json())),
        None => Err(status_404(&id)),
    }
}

async fn alert_routes_update(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
    Json(body): Json<AlertRouteUpdateRequest>,
) -> ApiResult {
    operation_capability_guard(&session, OperationCapability::MonitoringAlertRoutingManage)?;
    let pool = get_db().ok_or_else(status_503_no_db)?;

    // DB path: validate severity/priority vocab inline (no ROUTE_STORE mutation),
    // then UPDATE only a classified row inside both authorized axes.
    const VALID_SEVERITIES: &[&str] = &["info", "warning", "average", "high", "disaster"];
    const VALID_PRIORITIES: &[&str] = &["P1", "P2", "P3", "P4"];

    if let Some(ref sev) = body.severity {
        if !VALID_SEVERITIES.contains(&sev.as_str()) {
            return Err(status_400(&format!(
                "Invalid severity '{}'. Must be one of: {:?}",
                sev, VALID_SEVERITIES
            )));
        }
    }
    if let Some(ref pri) = body.priority {
        if !VALID_PRIORITIES.contains(&pri.as_str()) {
            return Err(status_400(&format!(
                "Invalid priority '{}'. Must be one of: {:?}",
                pri, VALID_PRIORITIES
            )));
        }
    }
    // A provided text field must not be blank (parity with engine validation).
    for (field, val) in [
        ("triggerName", &body.trigger_name),
        ("hostGroup", &body.host_group),
        ("supportGroup", &body.support_group),
    ] {
        if let Some(v) = val {
            if v.trim().is_empty() {
                return Err(status_400(&format!(
                    "{field} must not be empty when provided"
                )));
            }
        }
    }

    let Ok(uid) = uuid::Uuid::parse_str(&id) else {
        return Err(status_404(&id));
    };
    // Persist + audit atomically.  The classification and scope predicates are
    // part of the UPDATE itself, so a concurrent/out-of-scope row cannot pass a
    // prior check and then be mutated.  Missing, legacy, and denied all 404.
    let mut tx = pool.begin().await.map_err(db_error)?;
    let row: Option<AlertRouteRow> = sqlx::query_as(&format!(
        "UPDATE alert_routes \
         SET trigger_name  = COALESCE($2, trigger_name), \
             severity      = COALESCE($3, severity), \
             host_group    = COALESCE($4, host_group), \
             support_group = COALESCE($5, support_group), \
             priority      = COALESCE($6, priority), \
             enabled       = COALESCE($7, enabled), \
             updated_at    = NOW() \
         WHERE id = $1 \
           AND scope_classification = 'site_environment' \
           AND EXISTS ( \
               SELECT 1 FROM site_registry AS registry \
               WHERE registry.unlocode = alert_routes.site \
                 AND registry.active = TRUE \
           ) \
           AND (cardinality($8::text[]) = 0 OR site = ANY($8)) \
           AND (cardinality($9::text[]) = 0 OR environment = ANY($9)) \
         RETURNING {ALERT_ROUTE_COLUMNS}"
    ))
    .bind(uid)
    .bind(body.trigger_name.as_deref())
    .bind(body.severity.as_deref())
    .bind(body.host_group.as_deref())
    .bind(body.support_group.as_deref())
    .bind(body.priority.as_deref())
    .bind(body.enabled)
    .bind(&session.site_scope)
    .bind(&session.environment_scope)
    .fetch_optional(&mut *tx)
    .await
    .map_err(db_error)?;
    let Some(updated) = row else {
        tx.rollback().await.ok();
        return Err(status_404(&id));
    };
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "alert-route-update",
            None,
            "updated",
            json!({
                "route_id": updated.id.to_string(),
                "site": &updated.site,
                "environment": &updated.environment,
            }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;
    Ok(Json(updated.to_json()))
}

async fn alert_routes_delete(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> ApiResult {
    operation_capability_guard(&session, OperationCapability::MonitoringAlertRoutingManage)?;
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let Ok(uid) = uuid::Uuid::parse_str(&id) else {
        return Err(status_404(&id));
    };
    let mut tx = pool.begin().await.map_err(db_error)?;
    let deleted: Option<(uuid::Uuid, String, String)> = sqlx::query_as(
        "DELETE FROM alert_routes \
         WHERE id = $1 \
           AND scope_classification = 'site_environment' \
           AND EXISTS ( \
               SELECT 1 FROM site_registry AS registry \
               WHERE registry.unlocode = alert_routes.site \
                 AND registry.active = TRUE \
           ) \
           AND (cardinality($2::text[]) = 0 OR site = ANY($2)) \
           AND (cardinality($3::text[]) = 0 OR environment = ANY($3)) \
         RETURNING id, site, environment",
    )
    .bind(uid)
    .bind(&session.site_scope)
    .bind(&session.environment_scope)
    .fetch_optional(&mut *tx)
    .await
    .map_err(db_error)?;
    let Some((_, site, environment)) = deleted else {
        tx.rollback().await.ok();
        return Err(status_404(&id));
    };
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "alert-route-delete",
            Some("active"),
            "deleted",
            json!({
                "route_id": &id,
                "site": site,
                "environment": environment,
            }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;
    Ok(Json(serde_json::json!({"deleted": true, "id": id})))
}

async fn alert_resolve(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<AlertResolveRequest>,
) -> ApiResult {
    let (site, environment) = canonical_alert_route_scope(&body.site, &body.environment)?;
    guard_body_scope_dual(&session, &site, &environment)?;
    let pool = get_db().ok_or_else(status_503_no_db)?;

    // Resolution is itself a scoped read.  Legacy rows remain quarantined and
    // the exact dual-axis predicate runs before route fields are projected.
    let row: Option<AlertRouteRow> = sqlx::query_as(&format!(
        "SELECT {ALERT_ROUTE_COLUMNS} \
         FROM alert_routes AS route \
         JOIN site_registry AS registry \
           ON registry.unlocode = route.site AND registry.active = TRUE \
         WHERE route.scope_classification = 'site_environment' \
           AND route.site = $1 \
           AND route.environment = $2 \
           AND route.enabled = true \
           AND route.trigger_name = $3 \
           AND route.severity     = $4 \
           AND route.host_group   = $5 \
         ORDER BY route.created_at, route.id \
         LIMIT 1"
    ))
    .bind(&site)
    .bind(&environment)
    .bind(&body.trigger_name)
    .bind(&body.severity)
    .bind(&body.host_group)
    .fetch_optional(pool)
    .await
    .map_err(db_error)?;

    let alert_id = format!(
        "alert-{}",
        uuid::Uuid::new_v4()
            .to_string()
            .split('-')
            .next()
            .unwrap_or("unknown")
    );
    let now = chrono::Utc::now().to_rfc3339();

    let decision = match row {
        Some(route) => json!({
            "alert_id": alert_id,
            "route_id": route.id.to_string(),
            "support_group": route.support_group,
            "escalated": route.severity == "disaster",
            "timestamp": now,
            "evidence": format!(
                "DRY-RUN: Alert '{}' (severity={}, host_group={}, site={}, environment={}) matched route {} -> support group '{}' (priority={}). No live Zabbix or ServiceNow calls.",
                body.trigger_name, body.severity, body.host_group, site, environment,
                route.id, route.support_group, route.priority
            ),
        }),
        None => json!({
            "alert_id": alert_id,
            "route_id": null,
            "support_group": "Unrouted",
            "escalated": body.severity == "disaster",
            "timestamp": now,
            "evidence": format!(
                "DRY-RUN: No matching route found for alert '{}' (severity={}, host_group={}, site={}, environment={}). Alert is unrouted. Configure a scoped route or review coverage.",
                body.trigger_name, body.severity, body.host_group, site, environment
            ),
        }),
    };
    Ok(Json(decision))
}

