// ─── Network Port & VLAN Readiness handlers ───

/// Defense in depth for the four persisted network-read data surfaces. The
/// central safe-method gate classifies the same exact paths as `admin`; keeping
/// this check at the handler boundary prevents direct invocation or future
/// route remounting from downgrading the authorization requirement.
fn require_network_inventory_read(session: &AuthSession) -> Result<(), (StatusCode, Json<Value>)> {
    if check_permission(session, "admin") {
        Ok(())
    } else {
        Err((
            StatusCode::FORBIDDEN,
            Json(json!({"error": "Admin permission required for network readiness data"})),
        ))
    }
}

fn network_inventory_unavailable() -> (StatusCode, Json<Value>) {
    (
        StatusCode::NOT_FOUND,
        Json(json!({"error": "Network readiness data unavailable"})),
    )
}

async fn network_readiness_check(
    AuthExtractor(session): AuthExtractor,
    Query(query): Query<NetworkReadinessQuery>,
) -> ApiResult {
    require_network_inventory_read(&session)?;
    // #2: narrow the site to the principal's scope (env-scoped -> 403).
    let site = enforce_site_scope(&session, query.site.as_deref(), "DEFRA")?;
    let port_count = query.ports.unwrap_or(1);
    let vlan = query.vlan;
    let ip_count = query.ips.unwrap_or(1);

    let ports = match get_db() {
        Some(pool) => crate::repos::network_readiness::list_ports(pool, &site)
            .await
            .map_err(db_error)?,
        None => Vec::new(),
    };
    let vlans = match get_db() {
        Some(pool) => crate::repos::network_readiness::list_vlans(pool, &site)
            .await
            .map_err(db_error)?,
        None => Vec::new(),
    };

    let projection = network_readiness::build_network_readiness(
        &site, port_count, vlan, ip_count, &ports, &vlans,
    );
    Ok(Json(serde_json::to_value(projection).unwrap_or_default()))
}

async fn network_reserve_ports(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<NetworkReservePortsRequest>,
) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;
    // #2: scoped principals may only reserve ports in their own site.
    guard_body_site_scope(&session, &body.site)?;
    match crate::repos::network_readiness::reserve_ports(
        pool,
        &body.site,
        body.count,
        &body.purpose,
    )
    .await
    {
        Ok(resv) => Ok(Json(serde_json::to_value(resv).unwrap_or_default())),
        Err(crate::repos::network_readiness::ReserveError::Invalid(msg)) => Err(status_400(&msg)),
        Err(crate::repos::network_readiness::ReserveError::Insufficient { needed, available }) => {
            Err(status_409(&format!(
                "insufficient port capacity at site {}: needed {needed}, available {available}",
                body.site
            )))
        }
        Err(crate::repos::network_readiness::ReserveError::NotFound) => Err(status_404(&body.site)),
        Err(crate::repos::network_readiness::ReserveError::Db(e)) => Err(db_error(e)),
    }
}

