#[cfg(test)]
mod image_factory_audit_db_tests {
    use super::*;
    use crate::database::DB_TEST_SERIAL;
    use sqlx::PgPool;

    async fn global_pool() -> Option<&'static PgPool> {
        let url = std::env::var("RYUKI_DATABASE_URL").ok()?;
        crate::database::try_connect_with_url(&url, 5, 1, 300, 30, 1800).await;
        let pool = crate::database::get_db()?;
        crate::database::run_migrations(pool).await.ok()?;
        Some(pool)
    }

    async fn seed_image(pool: &PgPool, id: Uuid, site: &str, status: &str, suffix: &str) {
        sqlx::query(
            "INSERT INTO golden_images \
             (id, image_name, os_family, os_version, distro, status, site_scope, build_log) \
             VALUES ($1, $2, 'Linux', '24.04', 'Ubuntu 24.04 LTS', $3, $4, $5)",
        )
        .bind(id)
        .bind(format!("db-image-{suffix}-{id}"))
        .bind(status)
        .bind(site)
        .bind(format!("fixture-{suffix}"))
        .execute(pool)
        .await
        .expect("seed golden image");
    }

    async fn cleanup(pool: &PgPool, ids: &[Uuid]) {
        sqlx::query("DELETE FROM golden_images WHERE id = ANY($1)")
            .bind(ids)
            .execute(pool)
            .await
            .ok();
    }

    fn actor_session(actor: &str) -> AuthSession {
        let mut session = AuthSession::static_dry_run();
        bind_test_principal(&mut session, actor);
        session.display_name = format!("{actor} (test)");
        session.token_valid = true;
        session.actor_class = ryuki_engine::auth::ActorClass::VerifiedHuman;
        session.provider_mode = "test-verified-human".into();
        session
    }

    #[tokio::test]
    async fn execute_only_image_operator_is_denied_before_storage_lookup() {
        let mut session = actor_session("image-execute-only");
        session.roles = vec![ryuki_engine::auth::APP_ROLE_VMWARE_OPERATOR.to_string()];

        let result =
            image_factory_promote(AuthExtractor(session), Path(Uuid::new_v4().to_string())).await;

        assert!(matches!(result, Err((StatusCode::FORBIDDEN, _))));
    }

    #[tokio::test]
    async fn image_approver_reaches_the_resource_boundary() {
        let mut session = actor_session("image-designated-approver");
        session.roles = vec![ryuki_engine::auth::APP_ROLE_DATACENTER_APPROVER.to_string()];

        let result =
            image_factory_promote(AuthExtractor(session), Path(Uuid::new_v4().to_string())).await;

        assert!(
            !matches!(result, Err((StatusCode::FORBIDDEN, _))),
            "an approval-capable principal must pass the local capability guard"
        );
    }

    async fn install_audit_failure_trigger(pool: &PgPool) {
        sqlx::query("DROP TRIGGER IF EXISTS zz_ryuki_test_reject_image_audit ON audit_log")
            .execute(pool)
            .await
            .expect("drop stale image audit trigger");
        sqlx::query("DROP FUNCTION IF EXISTS ryuki_test_reject_image_audit()")
            .execute(pool)
            .await
            .expect("drop stale image audit function");
        sqlx::query(
            "CREATE FUNCTION ryuki_test_reject_image_audit() RETURNS trigger \
             LANGUAGE plpgsql AS $$ \
             BEGIN \
               IF NEW.actor_principal LIKE 'dbtest-image-audit-failure-%' THEN \
                 RAISE EXCEPTION 'injected image audit failure' USING ERRCODE = '23514'; \
               END IF; \
               RETURN NEW; \
             END $$",
        )
        .execute(pool)
        .await
        .expect("create image audit function");
        sqlx::query(
            "CREATE TRIGGER zz_ryuki_test_reject_image_audit \
             BEFORE INSERT ON audit_log FOR EACH ROW \
             EXECUTE FUNCTION ryuki_test_reject_image_audit()",
        )
        .execute(pool)
        .await
        .expect("create image audit trigger");
    }

    async fn remove_audit_failure_trigger(pool: &PgPool) {
        sqlx::query("DROP TRIGGER IF EXISTS zz_ryuki_test_reject_image_audit ON audit_log")
            .execute(pool)
            .await
            .expect("drop image audit trigger");
        sqlx::query("DROP FUNCTION IF EXISTS ryuki_test_reject_image_audit()")
            .execute(pool)
            .await
            .expect("drop image audit function");
    }

    #[tokio::test]
    async fn promotion_and_peer_supersession_commit_with_one_audit() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let target = Uuid::new_v4();
        let peer = Uuid::new_v4();
        let site = format!("DBIMG-{}", Uuid::new_v4().simple());
        let actor = "dbtest-image-promoter";
        let session = actor_session(actor);
        seed_image(pool, target, &site, "testing", "target").await;
        seed_image(pool, peer, &site, "promoted", "peer").await;

        let result =
            image_factory_promote(AuthExtractor(session.clone()), Path(target.to_string())).await;
        assert!(result.is_ok(), "promotion must succeed: {result:?}");
        let retry =
            image_factory_promote(AuthExtractor(session.clone()), Path(target.to_string())).await;
        assert!(retry.is_err(), "already-promoted target must be a no-op");

        let image_ids = vec![target, peer];
        let statuses: Vec<(Uuid, String)> =
            sqlx::query_as("SELECT id, status FROM golden_images WHERE id = ANY($1) ORDER BY id")
                .bind(&image_ids)
                .fetch_all(pool)
                .await
                .expect("read image statuses");
        assert!(statuses.contains(&(target, "promoted".to_string())));
        assert!(statuses.contains(&(peer, "superseded".to_string())));

        type GoldenImagePromotionAuditRow = (
            String,
            String,
            Vec<String>,
            String,
            Option<String>,
            String,
            serde_json::Value,
            String,
            Option<String>,
            Option<String>,
        );
        let audits: Vec<GoldenImagePromotionAuditRow> = sqlx::query_as(
            "SELECT actor_principal, actor_display, actor_roles, provider_mode, \
             from_status, to_status, detail, outcome, prev_hash, entry_hash FROM audit_log \
             WHERE action = 'golden-image-promote' AND detail->>'image_id' = $1 \
             ORDER BY id",
        )
        .bind(target.to_string())
        .fetch_all(pool)
        .await
        .expect("read promotion audit");
        assert_eq!(audits.len(), 1, "retry must not duplicate promotion audit");
        let (
            audit_actor,
            actor_display,
            actor_roles,
            provider_mode,
            from_status,
            to_status,
            detail,
            outcome,
            prev_hash,
            entry_hash,
        ) = &audits[0];
        assert_eq!(audit_actor, actor);
        assert_eq!(actor_display, &session.display_name);
        assert_eq!(actor_roles, &session.roles);
        assert_eq!(provider_mode, &session.provider_mode);
        assert_eq!(from_status.as_deref(), Some("testing"));
        assert_eq!(to_status, "promoted");
        assert_eq!(detail["image_id"], target.to_string());
        assert_eq!(detail["site"], site);
        assert_eq!(detail["os_family"], "Linux");
        assert_eq!(detail["superseded_image_ids"], json!([peer.to_string()]));
        assert!(detail.get("image_name").is_none());
        assert!(detail.get("build_log").is_none());
        assert_eq!(outcome, "success");
        assert!(prev_hash.as_deref().is_some_and(|h| !h.is_empty()));
        assert!(entry_hash.as_deref().is_some_and(|h| !h.is_empty()));
        let chain = crate::audit::verify_audit_chain(pool)
            .await
            .expect("verify golden-image promotion audit chain");
        assert!(chain.verified, "promotion must preserve the audit chain");
        cleanup(pool, &[target, peer]).await;
    }

    #[tokio::test]
    async fn audit_failure_rolls_back_target_and_all_peers() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let target = Uuid::new_v4();
        let peer = Uuid::new_v4();
        let site = format!("DBIMG-{}", Uuid::new_v4().simple());
        let actor = format!("dbtest-image-audit-failure-{}", Uuid::new_v4());
        seed_image(pool, target, &site, "testing", "rollback-target").await;
        seed_image(pool, peer, &site, "promoted", "rollback-peer").await;

        install_audit_failure_trigger(pool).await;
        let result = image_factory_promote(
            AuthExtractor(actor_session(&actor)),
            Path(target.to_string()),
        )
        .await;
        remove_audit_failure_trigger(pool).await;

        assert!(matches!(
            result,
            Err((StatusCode::INTERNAL_SERVER_ERROR, _))
        ));
        let (target_status, target_build_log): (String, String) =
            sqlx::query_as("SELECT status, build_log FROM golden_images WHERE id = $1")
                .bind(target)
                .fetch_one(pool)
                .await
                .expect("target state");
        let (peer_status, peer_build_log): (String, String) =
            sqlx::query_as("SELECT status, build_log FROM golden_images WHERE id = $1")
                .bind(peer)
                .fetch_one(pool)
                .await
                .expect("peer state");
        assert_eq!(target_status, "testing", "target promotion must roll back");
        assert_eq!(peer_status, "promoted", "peer supersession must roll back");
        assert_eq!(target_build_log, "fixture-rollback-target");
        assert_eq!(peer_build_log, "fixture-rollback-peer");
        let audit_count: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM audit_log WHERE actor_principal = $1 \
             AND action = 'golden-image-promote'",
        )
        .bind(&actor)
        .fetch_one(pool)
        .await
        .expect("count rejected image audits");
        assert_eq!(audit_count, 0);
        cleanup(pool, &[target, peer]).await;
    }
}

