async fn cmdb_import_records(
    Json(body): Json<CmdbImportRequest>,
) -> Result<Json<Vec<ryuki_engine::models::CmdbRecord>>, (StatusCode, Json<Value>)> {
    cmdb_engine::import_cmdb_records(&body.source)
        .map(Json)
        .map_err(|e| (StatusCode::BAD_REQUEST, Json(json!({"error": e}))))
}

async fn cmdb_run_reconciliation() -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let inventory = inventory_sync::sync_inventory_sources()
        .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(json!({"error": e}))))?;
    let cmdb_records = cmdb_engine::import_cmdb_records("cmdb-excel-export")
        .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(json!({"error": e}))))?;
    let results = cmdb_engine::reconcile_cmdb(&inventory, &cmdb_records)
        .map_err(|e| (StatusCode::BAD_REQUEST, Json(json!({"error": e}))))?;
    // #27 "+ drift": presence reconciliation (results, above) never checks whether a
    // CI present in BOTH sources actually AGREES — surface attribute-level divergence
    // (owner/site/environment/criticality) for matched CIs alongside the presence gaps.
    let attribute_drift = cmdb_engine::detect_attribute_drift(&inventory, &cmdb_records);
    Ok(Json(json!({
        "source": "dry-run",
        "reconciliation_results": results,
        "attribute_drift": attribute_drift,
    })))
}

async fn cmdb_export_records(
    Query(params): Query<CmdbExportQuery>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let records = cmdb_engine::import_cmdb_records("cmdb-excel-export")
        .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(json!({"error": e}))))?;
    let format_str = params.format.as_deref().unwrap_or("json");
    cmdb_engine::export_cmdb(&records, format_str)
        .map(|s| Json(json!({"source": "dry-run", "format": format_str, "data": s})))
        .map_err(|e| (StatusCode::BAD_REQUEST, Json(json!({"error": e}))))
}

/// GET /api/cmdb/cis/{ci_name} — read one configuration item from the REAL
/// `configuration_items` table by its unique `ci_name` (#18). The FIRST authenticated,
/// DB-backed CMDB read — the impact/export endpoints serve an in-memory mock. AUDIT-tier
/// (an explicit check, NOT the central gate's looser `audit OR request`): CI criticality
/// and owner are inventory signals, kept audit-grade. Site/environment scope is applied in
/// SQL through the exact active site-registry relation (out-of-scope → 404, no oracle).
/// 503 with no DB (the table is the only CI source).
/// NOTE: a `ci_name` containing `/` will not route as one path segment (404) — a by-UUID
/// variant (the response carries `id`) is the follow-up for such names.
async fn cmdb_ci_get(
    AuthExtractor(session): AuthExtractor,
    Path(ci_name): Path<String>,
) -> ApiResult {
    if !check_permission(&session, "audit") {
        return Err((
            StatusCode::FORBIDDEN,
            Json(
                json!({"error": "Audit-tier access is required to read CMDB configuration items"}),
            ),
        ));
    }
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let ci = crate::repos::configuration_items::get_authorized_by_name(
        pool,
        &ci_name,
        &session.site_scope,
        &session.environment_scope,
    )
    .await
    .map_err(db_error)?
    .ok_or_else(|| status_404(&ci_name))?;
    Ok(Json(serde_json::to_value(&ci).unwrap_or_default()))
}

