async fn firmware_request_exception(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<FirmwareExceptionRequest>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let Some(principal_id) = session.principal_id else {
        return Err(status_403());
    };
    let actor = principal_id.to_string();
    // requested_by is the authenticated maker, never client payload data.
    firmware_lifecycle::validate_exception_request(&body.reason, &actor, body.expiry_days)
        .map_err(|e| status_400(&e))?;
    let expiry_days = i32::try_from(body.expiry_days)
        .map_err(|_| status_400("expiryDays is outside the supported range"))?;
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let mut tx = pool.begin().await.map_err(db_error)?;
    let device = crate::repos::firmware_lifecycle::get_device_for_update(&mut tx, &body.device_id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&body.device_id))?;
    scope_guard_or_404(&session, &device.site, "", &body.device_id)?;
    let outcome = crate::repos::firmware_lifecycle::request_exception(
        &mut tx,
        &body.device_id,
        &body.reason,
        &actor,
        expiry_days,
    )
    .await
    .map_err(db_error)?;
    let exception = match outcome {
        crate::repos::firmware_lifecycle::RequestExceptionOutcome::Created(exception) => exception,
        crate::repos::firmware_lifecycle::RequestExceptionOutcome::MissingDevice => {
            return Err(status_404(&body.device_id));
        }
        crate::repos::firmware_lifecycle::RequestExceptionOutcome::Conflict => {
            return Err(status_409(
                "an unresolved firmware exception already exists",
            ));
        }
    };
    let effective_device =
        crate::repos::firmware_lifecycle::recalculate_compliance(&mut tx, &body.device_id)
            .await
            .map_err(db_error)?
            .ok_or_else(|| status_404(&body.device_id))?;
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "firmware-exception-request",
            None,
            "pending",
            json!({
                "exception_id": &exception.id,
                "device_id": &exception.device_id,
                "site": &device.site,
                "version": exception.version,
                "expiry_date": &exception.expiry_date,
            }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;
    Ok(Json(json!({
        "source": "live",
        "exception": exception,
        "device_status": effective_device.compliance_status.to_string()
    })))
}

async fn firmware_approve_exception(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
    Json(body): Json<FirmwareExceptionApprovalRequest>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    // The route is approve-tier in the central manifest; repeat the guard here
    // so direct handler calls and future router composition cannot bypass it.
    if !check_permission(&session, "approve") {
        return Err(status_403());
    }
    let Some(principal_id) = session.principal_id else {
        return Err(status_403());
    };
    let actor = principal_id.to_string();
    if body.expected_version <= 0 {
        return Err(status_400("expectedVersion must be greater than zero"));
    }
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let device_id = crate::repos::firmware_lifecycle::exception_device_id(pool, &id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&id))?;
    let mut tx = pool.begin().await.map_err(db_error)?;
    let device = crate::repos::firmware_lifecycle::get_device_for_update(&mut tx, &device_id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&id))?;
    scope_guard_or_404(&session, &device.site, "", &id)?;
    let outcome = crate::repos::firmware_lifecycle::approve_exception(
        &mut tx,
        &id,
        body.expected_version,
        &actor,
    )
    .await
    .map_err(db_error)?;
    let exception = match outcome {
        crate::repos::firmware_lifecycle::ApproveExceptionOutcome::Approved(exception) => exception,
        crate::repos::firmware_lifecycle::ApproveExceptionOutcome::NotFound => {
            return Err(status_404(&id));
        }
        crate::repos::firmware_lifecycle::ApproveExceptionOutcome::SelfApproval => {
            return Err(status_403());
        }
        crate::repos::firmware_lifecycle::ApproveExceptionOutcome::Conflict => {
            return Err(status_409(
                "firmware exception approval is stale, expired, or already decided",
            ));
        }
    };
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "firmware-exception-approve",
            Some("pending"),
            "approved",
            json!({
                "exception_id": &exception.id,
                "device_id": &exception.device_id,
                "site": &device.site,
                "version": exception.version,
                "expiry_date": &exception.expiry_date,
            }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;
    Ok(Json(json!({
        "source": "live",
        "exception": exception,
        "device_status": firmware_lifecycle::ComplianceStatus::Exception.to_string(),
    })))
}

