async fn firmware_compliance_report(
    AuthExtractor(session): AuthExtractor,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    match get_db() {
        Some(pool) => {
            let devices = crate::repos::firmware_lifecycle::list_all_for_report(pool)
                .await
                .map_err(db_error)?;
            // #2: a scoped principal's report counts only its own site's devices.
            let devices = retain_site_scoped(&session, devices, |d| d.site.as_str());
            let total = devices.len();
            let compliant = devices
                .iter()
                .filter(|d| d.compliance_status == firmware_lifecycle::ComplianceStatus::Compliant)
                .count();
            let noncompliant = devices
                .iter()
                .filter(|d| {
                    d.compliance_status == firmware_lifecycle::ComplianceStatus::NonCompliant
                })
                .count();
            let eol = devices
                .iter()
                .filter(|d| d.compliance_status == firmware_lifecycle::ComplianceStatus::EOL)
                .count();
            let exception = devices
                .iter()
                .filter(|d| d.compliance_status == firmware_lifecycle::ComplianceStatus::Exception)
                .count();
            Ok(Json(json!({
                "source": "live",
                "total": total,
                "compliant": compliant,
                "noncompliant": noncompliant,
                "eol": eol,
                "exception": exception,
            })))
        }
        None => Ok(Json(json!({
            "source": "dry-run",
            "total": 0,
            "compliant": 0,
            "noncompliant": 0,
            "eol": 0,
            "exception": 0,
            "dry_run": true
        }))),
    }
}

async fn firmware_vendor_summary(
    AuthExtractor(session): AuthExtractor,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    match get_db() {
        Some(pool) => {
            let devices = crate::repos::firmware_lifecycle::list_all_for_report(pool)
                .await
                .map_err(db_error)?;
            // #2: a scoped principal's vendor summary covers only its own site's devices.
            let devices = retain_site_scoped(&session, devices, |d| d.site.as_str());
            let mut vendors: std::collections::BTreeMap<
                String,
                (usize, usize, usize, usize, usize),
            > = std::collections::BTreeMap::new();
            for device in &devices {
                let entry = vendors
                    .entry(device.vendor.clone())
                    .or_insert((0, 0, 0, 0, 0));
                entry.0 += 1;
                match device.compliance_status {
                    firmware_lifecycle::ComplianceStatus::Compliant => entry.1 += 1,
                    firmware_lifecycle::ComplianceStatus::NonCompliant => entry.2 += 1,
                    firmware_lifecycle::ComplianceStatus::EOL => entry.3 += 1,
                    firmware_lifecycle::ComplianceStatus::Exception => entry.4 += 1,
                }
            }
            let summary: Vec<Value> = vendors
                .into_iter()
                .map(
                    |(vendor, (total, compliant, noncompliant, eol, exception))| {
                        let pct = if total == 0 {
                            0.0
                        } else {
                            (compliant as f64 / total as f64) * 100.0
                        };
                        json!({
                            "vendor": vendor,
                            "total": total,
                            "compliant": compliant,
                            "noncompliant": noncompliant,
                            "eol": eol,
                            "exception": exception,
                            "compliance_percentage": pct
                        })
                    },
                )
                .collect();
            Ok(Json(json!({ "source": "live", "vendors": summary })))
        }
        None => Ok(Json(json!({ "source": "dry-run", "vendors": [] }))),
    }
}

