/// List active incident contexts, newest first. Capped at the latest
/// `MAX_LIST_ROWS` (1000) rows — a defense-in-depth bound against a
/// sustained-incident burst, not full pagination.
async fn incident_active(AuthExtractor(session): AuthExtractor) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let incidents = match list_site_scope(&session) {
        ListSiteScope::Empty => Vec::new(),
        ListSiteScope::All => crate::repos::incident_contexts::list_active(pool, MAX_LIST_ROWS)
            .await
            .map_err(db_error)?,
        ListSiteScope::Sites(sites) => {
            crate::repos::incident_contexts::list_active_for_sites(pool, &sites, MAX_LIST_ROWS)
                .await
                .map_err(db_error)?
        }
    };
    Ok(Json(serde_json::to_value(&incidents).unwrap_or_default()))
}

