async fn dr_plans_list(
    AuthExtractor(session): AuthExtractor,
    Query(q): Query<DrPlanListQuery>,
) -> Result<(HeaderMap, Json<Value>), (StatusCode, Json<Value>)> {
    let pool = get_db().ok_or_else(status_503_no_db)?;
    // #2: scoped-site list ("" = all sites for an unrestricted caller).
    let site_scoped = enforce_site_scope(&session, q.site.as_deref(), "")?;
    let site = site_scoped.as_str();
    // #14: bound the page; bare-array body + X-Total-Count (the total).
    let limit = q.limit.unwrap_or(500).clamp(1, 1000);
    let offset = q.offset.unwrap_or(0).max(0);
    let plans = crate::repos::dr_plans::list_page(pool, site, limit, offset)
        .await
        .map_err(db_error)?;
    let total = crate::repos::dr_plans::count(pool, site)
        .await
        .map_err(db_error)?;
    Ok((
        total_count_headers(total),
        Json(serde_json::to_value(plans).unwrap_or_default()),
    ))
}
async fn dr_plan_create(
    AuthExtractor(session): AuthExtractor,
    Json(b): Json<DrPlanCreateRequest>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    // #2: a scoped principal may only create a DR plan OWNED by its own site.
    // `target_site` (the failover destination) is plan content, not an action on
    // that site, so DR plans may still target a cross-site destination.
    guard_body_site_scope(&session, &b.site)?;
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let plan = dr_testing::build_dr_plan(&b.name, &b.site, &b.target_site, b.systems, b.rpo, b.rto)
        .map_err(|e| status_400(&e))?;
    let mut tx = pool.begin().await.map_err(db_error)?;
    crate::repos::dr_plans::insert(&mut *tx, &plan)
        .await
        .map_err(db_error)?;
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "dr-plan-create",
            None,
            "created",
            json!({"plan_id": &plan.id, "site": &plan.site}),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;
    // Write-through: keep the in-memory store consistent so test-run creation
    // (start_test resolves the plan from the static store) sees this new plan.
    dr_testing::upsert_plan(&plan);
    Ok(Json(serde_json::to_value(&plan).unwrap_or_default()))
}
