async fn dr_plan_delete(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let (plan, version) = crate::repos::dr_plans::get(pool, &id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&id))?;
    // #2: a scoped principal may only delete a plan in its own site. The site is
    // checked on the loaded row; the xmin CAS in the delete fails the write if the
    // row changed concurrently, so there is no TOCTOU window.
    guard_body_site_scope(&session, &plan.site)?;
    let mut tx = pool.begin().await.map_err(db_error)?;
    let outcome = crate::repos::dr_plans::delete(&mut tx, &id, &version)
        .await
        .map_err(db_error)?;
    match outcome {
        crate::repos::dr_plans::DeleteOutcome::Deleted => {
            audit::record_audit_tx(
                &mut tx,
                &session,
                &audit::security_audit(
                    "dr-plan-delete",
                    None,
                    "deleted",
                    json!({"plan_id": &id, "site": &plan.site}),
                ),
            )
            .await
            .map_err(db_error)?;
            tx.commit().await.map_err(db_error)?;
            // Write-through: drop the plan from the in-memory store so test-run
            // creation (start_test resolves from the static store) refuses it
            // immediately, without waiting for a restart.
            dr_testing::remove_plan(&id);
            Ok(Json(json!({"deleted": &id})))
        }
        crate::repos::dr_plans::DeleteOutcome::HasHistory => {
            tx.rollback().await.ok();
            Err(status_409(
                "plan has test-run history; cannot delete (retire it instead)",
            ))
        }
        crate::repos::dr_plans::DeleteOutcome::StaleVersion => {
            tx.rollback().await.ok();
            Err(status_409(
                "plan was modified concurrently; reload and retry",
            ))
        }
        crate::repos::dr_plans::DeleteOutcome::NotFound => {
            tx.rollback().await.ok();
            Err(status_404(&id))
        }
    }
}
async fn dr_test_start(
    AuthExtractor(session): AuthExtractor,
    Json(b): Json<DrTestStartRequest>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    // Plan resolved from static store (DB-consistent via slice-1 write-through)
    let plan = dr_testing::get_plan_from_store(&b.plan_id).ok_or_else(|| {
        (
            StatusCode::NOT_FOUND,
            Json(json!({"error": format!("DR plan '{}' not found", b.plan_id)})),
        )
    })?;
    // #2: a scoped principal may only start a DR test for a plan in its own site
    // — checked before touching the DB.
    guard_body_site_scope(&session, &plan.site)?;
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let run = dr_testing::build_test_run(&plan, &b.scenario_type, &b.tester)
        .map_err(|e| status_400(&e))?;
    let mut tx = pool.begin().await.map_err(db_error)?;
    crate::repos::dr_test_runs::insert(&mut *tx, &run)
        .await
        .map_err(|e| {
            // The plan may have been DELETEd concurrently (the store still resolved
            // it, but the DB row is gone). Its run INSERT then fails the ON DELETE
            // RESTRICT FK (migration 124) with 23503 — map that to 409 ("reload")
            // instead of leaking a generic 500.
            if e.as_database_error()
                .and_then(|d| d.code())
                .map(|c| c == "23503")
                .unwrap_or(false)
            {
                status_409("DR plan was deleted concurrently; reload and retry")
            } else {
                db_error(e)
            }
        })?;
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "dr-test-start",
            None,
            "started",
            json!({"test_id": &run.id, "plan_id": &run.plan_id, "site": &run.site}),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;
    Ok(Json(serde_json::to_value(&run).unwrap_or_default()))
}
async fn dr_test_complete(
    AuthExtractor(session): AuthExtractor,
    Json(b): Json<DrTestCompleteRequest>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let (run, run_version) = crate::repos::dr_test_runs::get(pool, &b.test_id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&b.test_id))?;
    // #2: load the plan and enforce scope BEFORE any run-state validation, so an
    // out-of-scope test_id cannot leak run state (e.g. a 409 "already completed")
    // ahead of the 403 scope decision. A scoped principal may only complete a DR
    // test for a plan in its own site; the per-row version CAS in the write tx
    // below fails if either row changed concurrently, so there is no TOCTOU gap.
    let (plan, plan_version) = crate::repos::dr_plans::get(pool, &run.plan_id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&run.plan_id))?;
    guard_body_site_scope(&session, &plan.site)?;
    let completed_run = dr_testing::complete_test_run_pure(&run, &b.result, b.systems_failed)
        .map_err(|e| status_409(&e))?;
    let completed_at = completed_run.completed_at.clone().unwrap_or_default();
    let updated_plan = dr_testing::mark_plan_tested_pure(&plan, &completed_at);
    let run_json = serde_json::to_value(&completed_run)
        .map_err(|e| db_error(sqlx::Error::Decode(format!("serialize run: {e}").into())))?;
    let plan_json = serde_json::to_value(&updated_plan)
        .map_err(|e| db_error(sqlx::Error::Decode(format!("serialize plan: {e}").into())))?;
    let mut tx = pool.begin().await.map_err(db_error)?;
    let run_res = sqlx::query(
        "UPDATE dr_test_runs SET completed = $2, run_json = $3, updated_at = NOW() \
         WHERE id = $1 AND xmin = $4::xid",
    )
    .bind(&completed_run.id)
    .bind(true)
    .bind(&run_json)
    .bind(&run_version)
    .execute(&mut *tx)
    .await;
    let run_res = match run_res {
        Ok(r) => r,
        Err(e) => {
            tx.rollback().await.ok();
            return Err(db_error(e));
        }
    };
    if run_res.rows_affected() == 0 {
        tx.rollback().await.ok();
        return Err(status_409(
            "test run was modified concurrently; reload and retry",
        ));
    }
    let plan_res = sqlx::query(
        "UPDATE dr_plans SET plan_json = $2, updated_at = NOW() \
         WHERE id = $1 AND xmin = $3::xid",
    )
    .bind(&updated_plan.id)
    .bind(&plan_json)
    .bind(&plan_version)
    .execute(&mut *tx)
    .await;
    let plan_res = match plan_res {
        Ok(r) => r,
        Err(e) => {
            tx.rollback().await.ok();
            return Err(db_error(e));
        }
    };
    if plan_res.rows_affected() == 0 {
        tx.rollback().await.ok();
        return Err(status_409(
            "DR plan was modified concurrently; reload and retry",
        ));
    }
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "dr-test-complete",
            None,
            "completed",
            json!({"test_id": &completed_run.id, "plan_id": &completed_run.plan_id, "site": &completed_run.site}),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;
    dr_testing::upsert_plan(&updated_plan);
    Ok(Json(
        serde_json::to_value(&completed_run).unwrap_or_default(),
    ))
}
async fn dr_test_results(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let pool = get_db().ok_or_else(status_503_no_db)?;
    // Verify plan exists first (matches engine behavior returning error if plan missing)
    let (plan, _version) = crate::repos::dr_plans::get(pool, &id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&id))?;
    // #2: a scoped principal may only read a plan's test results in its own site.
    guard_body_site_scope(&session, &plan.site)?;
    let runs = crate::repos::dr_test_runs::list_by_plan(pool, &id)
        .await
        .map_err(db_error)?;
    Ok(Json(json!({
        "plan_id": id,
        "count": runs.len(),
        "test_results": runs
    })))
}
async fn dr_tests_due(
    AuthExtractor(session): AuthExtractor,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    // DR plans are site-only. An environment-restricted principal cannot have
    // that axis represented by this resource, so fail closed before touching
    // the shared store. The engine applies the persisted site scope inside the
    // locked iteration, before any plan is cloned into the response.
    if session
        .environment_scope
        .iter()
        .any(|scope| !scope.trim().is_empty())
    {
        return Err(status_403_out_of_scope("environment"));
    }
    dr_testing::list_due_tests(&session.site_scope)
        .map(Json)
        .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(json!({"error": e}))))
}
