// ─── Load Balancer handlers ───

#[derive(Debug, Deserialize)]
#[allow(dead_code)]
struct LbSiteQuery {
    site: Option<String>,
}

/// #14: the LIST endpoint's query — site + pagination. Kept SEPARATE from the
/// site-only `LbSiteQuery` so `lb_status` doesn't start rejecting a malformed
/// `?limit=` it never used.
#[derive(Debug, Deserialize)]
#[allow(dead_code)]
struct LbListQuery {
    site: Option<String>,
    limit: Option<i64>,
    offset: Option<i64>,
}
#[derive(Debug, Deserialize)]
#[allow(dead_code)]
struct LbProvisionRequest {
    name: String,
    vip: String,
    port: u16,
    protocol: String,
    site: String,
    members: Vec<String>,
    algorithm: String,
}
#[derive(Debug, Deserialize)]
#[allow(dead_code)]
struct LbMemberRequest {
    hostname: String,
    ip: String,
    port: u16,
}

#[derive(Debug, Deserialize)]
#[allow(dead_code)]
struct LbValidateVipRequest {
    vip: String,
    site: String,
}

async fn lb_vs_list(
    AuthExtractor(session): AuthExtractor,
    Query(q): Query<LbListQuery>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    // #2: scoped-site list ("" = all sites for an unrestricted caller).
    let site_scoped = enforce_site_scope(&session, q.site.as_deref(), "")?;
    let site = site_scoped.as_str();
    // #14: bound the page (generous default keeps seed-scale callers unaffected).
    let limit = q.limit.unwrap_or(500).clamp(1, 1000);
    let offset = q.offset.unwrap_or(0).max(0);
    let (vss, total) = match get_db() {
        Some(pool) => (
            crate::repos::load_balancer::list_virtual_servers(pool, site, limit, offset)
                .await
                .map_err(db_error)?,
            crate::repos::load_balancer::count_virtual_servers(pool, site)
                .await
                .map_err(db_error)?,
        ),
        None => (vec![], 0),
    };
    let mut resp = load_balancer::list_virtual_servers(site, &vss)
        .map_err(|e| (StatusCode::BAD_REQUEST, Json(json!({"error": e}))))?;
    add_page_meta(&mut resp, total, limit, offset);
    Ok(Json(resp))
}
async fn lb_provision(
    AuthExtractor(session): AuthExtractor,
    Json(b): Json<LbProvisionRequest>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let (pool_entity, vs, request) = load_balancer::build_provision(
        &b.name,
        &b.vip,
        b.port,
        &b.protocol,
        &b.site,
        b.members,
        &b.algorithm,
    )
    .map_err(|e| (StatusCode::BAD_REQUEST, Json(json!({"error": e}))))?;

    // #2: body-create site scope — scoped principals may only provision in their
    // own site; env-scoped principals are rejected (lb resources are site-only).
    guard_body_site_scope(&session, &vs.site)?;

    let db = get_db().ok_or_else(status_503_no_db)?;

    // Check VIP uniqueness before inserting
    if let Some(conflict) = crate::repos::load_balancer::find_vip_conflict(db, &vs.vip, &vs.site)
        .await
        .map_err(db_error)?
    {
        return Err(status_409(&format!(
            "VIP '{}' is already in use at site '{}'",
            conflict.vip, conflict.site
        )));
    }

    crate::repos::load_balancer::provision_lb(db, &vs, &pool_entity, &request)
        .await
        .map_err(|e| {
            // The find_vip_conflict pre-check above is advisory; the UNIQUE(vip,
            // site) index is the real guard. A concurrent provision that loses the
            // race (or any duplicate id) hits a unique-violation here — return 409,
            // not the blanket 500 from db_error.
            if let Some(d) = e.as_database_error() {
                if d.is_unique_violation() {
                    return status_409(&format!(
                        "VIP '{}' is already in use at site '{}'",
                        vs.vip, vs.site
                    ));
                }
            }
            db_error(e)
        })?;

    Ok(Json(json!({
        "source": "db",
        "action": "provision-lb",
        "providerCallsEnabled": false,
        "virtual_server": vs,
        "pool": pool_entity,
        "request": request
    })))
}
async fn lb_vs_get(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let Some(db) = get_db() else {
        return Err(status_404(&id));
    };
    // #2: load only the VS first and guard on its site BEFORE any further work,
    // so an out-of-scope caller always gets a clean 404 — never a 500 from a
    // pool/member decode error that would betray the VS's existence.
    let vs = crate::repos::load_balancer::get_virtual_server(db, &id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&id))?;
    scope_guard_or_404(&session, &vs.site, "", &id)?;
    let pool = crate::repos::load_balancer::load_pool_with_members_pub(db, &vs.pool_id)
        .await
        .map_err(db_error)?;
    match pool {
        Some(p) => Ok(Json(load_balancer::get_virtual_server(&vs, &p))),
        None => Ok(Json(json!({ "source": "db", "virtual_server": vs }))),
    }
}

/// Mutable structural fields of a virtual server. Identity (vip/site/name/pool)
/// and live status are NOT here — status has its own drain/enable/disable
/// endpoints. `deny_unknown_fields` so a PUT carrying an immutable field is a
/// hard 422. `ssl_profile`: omitted keeps the current value, empty clears it.
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct LbVsUpdateRequest {
    port: Option<u16>,
    protocol: Option<String>,
    persistence_method: Option<String>,
    ssl_profile: Option<String>,
}

/// PUT /api/network/loadbalancer/vs/{id} — update a VS's structural fields
/// (validated through the pure engine parsers). 404 when unknown; 503 when no DB.
async fn lb_vs_update(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
    Json(b): Json<LbVsUpdateRequest>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let db = get_db().ok_or_else(status_503_no_db)?;
    // #2: by-id site scope — pre-load and guard before mutating.
    let existing = crate::repos::load_balancer::get_virtual_server(db, &id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&id))?;
    scope_guard_or_404(&session, &existing.site, "", &id)?;
    // Validate ONLY the provided fields and pass them through as Options — the
    // repo UPDATE is partial (COALESCE), so there is no read-modify-write that a
    // concurrent partial update could clobber.
    let port = match b.port {
        Some(0) => return Err(status_400("port must be greater than zero")),
        other => other,
    };
    let protocol = match b.protocol.as_deref() {
        Some(s) => Some(load_balancer::parse_protocol(s).map_err(|e| status_400(&e))?),
        None => None,
    };
    let persistence = match b.persistence_method.as_deref() {
        Some(s) => Some(load_balancer::parse_persistence(s).map_err(|e| status_400(&e))?),
        None => None,
    };
    // ssl_profile three-state: omitted = keep; empty = clear (NULL); value = set.
    let (update_ssl, ssl_value): (bool, Option<String>) = match b.ssl_profile {
        None => (false, None),
        Some(ref s) if s.trim().is_empty() => (true, None),
        Some(s) => (true, Some(s)),
    };

    let mut tx = db.begin().await.map_err(db_error)?;
    let updated = crate::repos::load_balancer::update_virtual_server(
        &mut *tx,
        &id,
        port,
        protocol.as_ref(),
        persistence.as_ref(),
        update_ssl,
        ssl_value.as_deref(),
    )
    .await
    .map_err(db_error)?
    .ok_or_else(|| status_404(&id))?;
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit("lb-vs-update", None, "updated", json!({ "vs_id": &id })),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;

    let pool = crate::repos::load_balancer::load_pool_with_members_pub(db, &updated.pool_id)
        .await
        .map_err(db_error)?;
    match pool {
        Some(p) => Ok(Json(load_balancer::get_virtual_server(&updated, &p))),
        None => Ok(Json(json!({ "source": "db", "virtual_server": updated }))),
    }
}

/// DELETE /api/network/loadbalancer/vs/{id} — decommission a VS (and orphan-clean
/// its backing pool). 404 when unknown; 503 when no DB.
async fn lb_vs_delete(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let db = get_db().ok_or_else(status_503_no_db)?;
    // #2: by-id site scope — pre-load and guard before mutating.
    let existing = crate::repos::load_balancer::get_virtual_server(db, &id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&id))?;
    scope_guard_or_404(&session, &existing.site, "", &id)?;
    let mut tx = db.begin().await.map_err(db_error)?;
    let deleted = crate::repos::load_balancer::delete_virtual_server(&mut tx, &id)
        .await
        .map_err(db_error)?;
    if !deleted {
        return Err(status_404(&id));
    }
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "lb-vs-delete",
            Some("active"),
            "deleted",
            json!({ "vs_id": &id }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;
    Ok(Json(json!({
        "source": "db",
        "deleted": true,
        "virtual_server_id": id,
    })))
}
async fn lb_pool_member_add(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
    Json(b): Json<LbMemberRequest>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    if b.hostname.trim().is_empty() {
        return Err(status_400("hostname cannot be empty"));
    }
    if b.ip.trim().is_empty() {
        return Err(status_400("ip cannot be empty"));
    }
    if b.port == 0 {
        return Err(status_400("port must be greater than zero"));
    }

    let db = get_db().ok_or_else(status_503_no_db)?;

    // Resolve VS → pool_id (read before mutation tx)
    let vs = crate::repos::load_balancer::get_virtual_server(db, &id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&id))?;
    // #2: by-id site scope — guard the resolved VS before mutating its pool.
    scope_guard_or_404(&session, &vs.site, "", &id)?;
    let pool_id = vs.pool_id.clone();

    let member = ryuki_engine::load_balancer::PoolMember {
        hostname: b.hostname.clone(),
        ip: b.ip.clone(),
        port: b.port,
        weight: 1,
        status: ryuki_engine::load_balancer::PoolMemberStatus::Up,
    };

    let mut tx = db.begin().await.map_err(db_error)?;
    crate::repos::load_balancer::add_pool_member(&mut *tx, &pool_id, &member)
        .await
        .map_err(|e| {
            if e.as_database_error()
                .map(|de| de.is_unique_violation())
                .unwrap_or(false)
            {
                status_409(&format!(
                    "Pool member '{}' already exists on virtual server '{}'",
                    b.hostname, id
                ))
            } else {
                db_error(e)
            }
        })?;
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "lb-pool-member-add",
            None,
            "added",
            json!({ "vs_id": &id, "hostname": &member.hostname }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;

    // Return updated member count (post-commit read)
    let pool = crate::repos::load_balancer::load_pool_with_members_pub(db, &pool_id)
        .await
        .map_err(db_error)?;
    let member_count = pool.as_ref().map(|p| p.members.len()).unwrap_or(0);

    Ok(Json(json!({
        "source": "db",
        "action": "add-pool-member",
        "virtual_server_id": id,
        "pool_id": pool_id,
        "member": member,
        "member_count": member_count
    })))
}
async fn lb_pool_member_remove(
    AuthExtractor(session): AuthExtractor,
    Path((id, hostname)): Path<(String, String)>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let db = get_db().ok_or_else(status_503_no_db)?;

    // Resolve VS → pool_id (read before mutation tx)
    let vs = crate::repos::load_balancer::get_virtual_server(db, &id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&id))?;
    // #2: by-id site scope — guard the resolved VS before mutating its pool.
    scope_guard_or_404(&session, &vs.site, "", &id)?;
    let pool_id = vs.pool_id.clone();

    let mut tx = db.begin().await.map_err(db_error)?;
    let removed = crate::repos::load_balancer::remove_pool_member(&mut *tx, &pool_id, &hostname)
        .await
        .map_err(db_error)?;

    if !removed {
        return Err(status_404(&format!(
            "Pool member '{}' not found on virtual server '{}'",
            hostname, id
        )));
    }
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "lb-pool-member-remove",
            None,
            "removed",
            json!({ "vs_id": &id, "hostname": &hostname }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;

    // Return updated member count (post-commit read)
    let pool = crate::repos::load_balancer::load_pool_with_members_pub(db, &pool_id)
        .await
        .map_err(db_error)?;
    let member_count = pool.as_ref().map(|p| p.members.len()).unwrap_or(0);

    Ok(Json(json!({
        "source": "db",
        "action": "remove-pool-member",
        "virtual_server_id": id,
        "pool_id": pool_id,
        "removed_hostname": hostname,
        "member_count": member_count
    })))
}
