    /// B4: auth_logout no longer accepts a client-supplied body session id, so
    /// there is no INVALID_SESSION_ID/MISSING_SESSION_ID branch to validate. A
    /// logout with no resolvable credentials is idempotent: 200 + logged_out,
    /// no DB error, nothing deleted.
    #[tokio::test]
    async fn test_auth_logout_idempotent_no_session() {
        crate::config_store::init_with_config(
            "logout-unit-test-config.json",
            &ryuki_core::config::RyukiConfig::default(),
        );
        let headers = HeaderMap::new();
        let response = auth_logout(headers).await;
        assert_eq!(response.status(), StatusCode::OK);
        let set_cookie_fields = response
            .headers()
            .get_all(SET_COOKIE)
            .iter()
            .map(|value| value.to_str().unwrap())
            .collect::<Vec<_>>();
        assert_eq!(
            set_cookie_fields,
            vec![
                "__Host-ryuki_session=; Path=/; HttpOnly; Max-Age=0; SameSite=Lax; Secure",
                "ryuki_session=; Path=/; HttpOnly; Max-Age=0; SameSite=Lax; Secure",
            ]
        );
        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .unwrap();
        let body: Value = serde_json::from_slice(&bytes).unwrap();
        assert_eq!(body, json!({"status": "logged_out"}));
    }

    #[tokio::test]
    async fn test_auth_logout_revocation_failure_clears_cookie_without_claiming_success() {
        crate::config_store::init_with_config(
            "logout-failure-unit-test-config.json",
            &ryuki_core::config::RyukiConfig::default(),
        );
        let response = logout_http_response(Err(LogoutFailure::DatabaseUnavailable));
        assert_eq!(response.status(), StatusCode::SERVICE_UNAVAILABLE);
        let set_cookie_fields = response
            .headers()
            .get_all(SET_COOKIE)
            .iter()
            .map(|value| value.to_str().unwrap())
            .collect::<Vec<_>>();
        assert_eq!(
            set_cookie_fields,
            vec![
                "__Host-ryuki_session=; Path=/; HttpOnly; Max-Age=0; SameSite=Lax; Secure",
                "ryuki_session=; Path=/; HttpOnly; Max-Age=0; SameSite=Lax; Secure",
            ]
        );
        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .unwrap();
        let body: Value = serde_json::from_slice(&bytes).unwrap();
        assert_eq!(body["error"], "SESSION_REVOCATION_FAILED");
        assert_ne!(body["status"], "logged_out");
    }

