    #[test]
    fn login_prequeue_selector_covers_every_state_allocating_method() {
        fn request(method: axum::http::Method, path: &str) -> Request {
            Request::builder()
                .method(method)
                .uri(path)
                .body(axum::body::Body::empty())
                .expect("selector test request")
        }

        let mut cfg = ryuki_core::config::RyukiConfig::default();
        cfg.oidc.enabled = true;
        assert!(request_requires_login_initiation_admission(
            &request(axum::http::Method::GET, "/api/auth/oidc/login"),
            &cfg,
        ));
        assert!(request_requires_login_initiation_admission(
            &request(axum::http::Method::HEAD, "/api/auth/oidc/login"),
            &cfg,
        ));
        assert!(!request_requires_login_initiation_admission(
            &request(axum::http::Method::POST, "/api/auth/oidc/login"),
            &cfg,
        ));
        assert!(!request_requires_login_initiation_admission(
            &request(axum::http::Method::GET, "/api/auth/oidc/callback"),
            &cfg,
        ));

        cfg.auth_mode = AuthMode::EntraId;
        cfg.entra_tenant_id = "test-tenant".to_string();
        cfg.entra_client_id = "test-client".to_string();
        cfg.entra_redirect_uri = "https://portal.example.test/api/auth/entra/callback".to_string();
        assert!(request_requires_login_initiation_admission(
            &request(axum::http::Method::GET, "/api/auth/entra/authorize-url",),
            &cfg,
        ));
        assert!(request_requires_login_initiation_admission(
            &request(axum::http::Method::HEAD, "/api/auth/entra/authorize-url",),
            &cfg,
        ));
    }

