    // ─── Local login brute-force throttle ───

    fn admitted_local_login_attempt<'a>(
        throttle: &'a LocalLoginThrottle,
        local_auth: &ryuki_core::config::LocalAuthConfig,
        username: &str,
        now: std::time::Instant,
    ) -> LocalLoginAttempt<'a> {
        let test_credential = random_test_password();
        match throttle.begin_attempt_at(local_auth, username, &test_credential, now) {
            LocalLoginAttemptAdmission::Verify(attempt) => attempt,
            LocalLoginAttemptAdmission::Dummy => {
                panic!("configured, unlocked account should receive a verification reservation")
            }
        }
    }

    fn record_local_login_failure(
        throttle: &LocalLoginThrottle,
        local_auth: &ryuki_core::config::LocalAuthConfig,
        username: &str,
        now: std::time::Instant,
    ) {
        admitted_local_login_attempt(throttle, local_auth, username, now).record_failure_at(now);
    }

    #[test]
    fn test_local_login_guard_normalizes_and_bounds_before_state_insertion() {
        let max = "a".repeat(LOCAL_AUTH_MAX_FIELD_BYTES);
        let over = "a".repeat(LOCAL_AUTH_MAX_FIELD_BYTES + 1);

        assert_eq!(
            normalize_local_login_username("Alice-1.test"),
            Some("Alice-1.test")
        );
        assert_eq!(normalize_local_login_username(&max), Some(max.as_str()));
        assert_eq!(normalize_local_login_username(""), None);
        assert_eq!(normalize_local_login_username(" Alice"), None);
        assert_eq!(normalize_local_login_username("alice@example"), None);
        assert_eq!(normalize_local_login_username("álice"), None);
        assert_eq!(normalize_local_login_username(&over), None);

        let local_auth = test_local_auth_config("admin:placeholder-pass-1:PlatformAdmin");
        let throttle = LocalLoginThrottle::default();
        let now = std::time::Instant::now();
        let oversized_credential = random_test_password().repeat(LOCAL_AUTH_MAX_FIELD_BYTES + 1);
        let test_credential = random_test_password();

        assert!(matches!(
            throttle.begin_attempt_at(&local_auth, &over, &test_credential, now),
            LocalLoginAttemptAdmission::Dummy
        ));
        assert!(matches!(
            throttle.begin_attempt_at(&local_auth, "admin", &oversized_credential, now),
            LocalLoginAttemptAdmission::Dummy
        ));
        assert!(matches!(
            throttle.begin_attempt_at(&local_auth, "admin@example", &test_credential, now),
            LocalLoginAttemptAdmission::Dummy
        ));
        assert!(
            throttle.entries.lock().unwrap().is_empty(),
            "malformed and oversized fields must never enter retained state"
        );
    }

    #[test]
    fn test_local_login_guard_lock_deadline_is_fixed_and_success_resets() {
        let local_auth = test_local_auth_config(
            "admin:placeholder-pass-1:PlatformAdmin,operator:placeholder-pass-2:Operator",
        );
        let throttle = LocalLoginThrottle::default();
        let now = std::time::Instant::now();
        let test_credential = random_test_password();

        for _ in 0..LOCAL_LOGIN_LOCKOUT_THRESHOLD {
            record_local_login_failure(&throttle, &local_auth, "admin", now);
        }

        let original_lock_until = throttle
            .entries
            .lock()
            .unwrap()
            .get("admin")
            .and_then(|entry| entry.lock_until)
            .expect("threshold failure must establish a lock deadline");
        assert_eq!(original_lock_until, now + LOCAL_LOGIN_LOCKOUT_DURATION);

        // A request while locked performs dummy work but cannot refresh the
        // deadline (the original vulnerable path did refresh it here).
        assert!(matches!(
            throttle.begin_attempt_at(
                &local_auth,
                "admin",
                &test_credential,
                original_lock_until - std::time::Duration::from_secs(1),
            ),
            LocalLoginAttemptAdmission::Dummy
        ));
        assert_eq!(
            throttle
                .entries
                .lock()
                .unwrap()
                .get("admin")
                .and_then(|entry| entry.lock_until),
            Some(original_lock_until)
        );

        // Exact expiry re-admits the account. A successful verification then
        // clears all prior failure state.
        admitted_local_login_attempt(&throttle, &local_auth, "admin", original_lock_until)
            .record_success();
        assert!(!throttle.entries.lock().unwrap().contains_key("admin"));
    }

    #[test]
    fn test_local_login_guard_partial_failure_window_expires_without_extension() {
        let local_auth = test_local_auth_config("admin:placeholder-pass-1:PlatformAdmin");
        let throttle = LocalLoginThrottle::default();
        let now = std::time::Instant::now();

        for offset in 0..LOCAL_LOGIN_LOCKOUT_THRESHOLD - 1 {
            record_local_login_failure(
                &throttle,
                &local_auth,
                "admin",
                now + std::time::Duration::from_secs(u64::from(offset)),
            );
        }

        let fixed_window = throttle
            .entries
            .lock()
            .unwrap()
            .get("admin")
            .expect("partial failure state")
            .failure_window_until;
        assert_eq!(fixed_window, now + LOCAL_LOGIN_FAILURE_WINDOW);

        // Later failures did not slide the first-failure window. At its exact
        // deadline the next attempt starts a fresh count of one.
        record_local_login_failure(&throttle, &local_auth, "admin", fixed_window);
        let entries = throttle.entries.lock().unwrap();
        let entry = entries.get("admin").unwrap();
        assert_eq!(entry.consecutive_failures, 1);
        assert_eq!(
            entry.failure_window_until,
            fixed_window + LOCAL_LOGIN_FAILURE_WINDOW
        );
        assert_eq!(entry.lock_until, None);
    }

    #[test]
    fn test_random_unknown_names_cannot_allocate_or_evict_active_account_locks() {
        let local_auth = test_local_auth_config(
            "admin:placeholder-pass-1:PlatformAdmin,operator:placeholder-pass-2:Operator",
        );
        let throttle = LocalLoginThrottle::default();
        let now = std::time::Instant::now();
        let test_credential = random_test_password();

        for _ in 0..LOCAL_LOGIN_LOCKOUT_THRESHOLD {
            record_local_login_failure(&throttle, &local_auth, "admin", now);
        }

        for index in 0..10_000 {
            assert!(matches!(
                throttle.begin_attempt_at(
                    &local_auth,
                    &format!("unknown-{index}"),
                    &test_credential,
                    now,
                ),
                LocalLoginAttemptAdmission::Dummy
            ));
        }

        {
            let entries = throttle.entries.lock().unwrap();
            assert_eq!(entries.len(), 1, "unknown names retain no state");
            assert!(entries.get("admin").unwrap().lock_until.is_some());
        }

        // A different configured account has a reserved state domain and is
        // still admitted; unknown-name floods cannot create a fail-closed cap
        // that denies previously unseen configured accounts.
        admitted_local_login_attempt(&throttle, &local_auth, "operator", now).record_success();
        let entries = throttle.entries.lock().unwrap();
        assert_eq!(entries.len(), 1);
        assert!(entries.get("admin").unwrap().lock_until.is_some());
    }

    #[test]
    fn test_local_login_guard_serializes_concurrent_verification_at_threshold() {
        use std::sync::atomic::{AtomicUsize, Ordering};

        const BURST: usize = 16;
        let local_auth = test_local_auth_config("admin:placeholder-pass-1:PlatformAdmin");
        let throttle = LocalLoginThrottle::default();
        let verifier_calls = AtomicUsize::new(0);
        let now = std::time::Instant::now();
        let test_credential = random_test_password();

        // In each concurrent wave every thread reaches admission before the
        // single reservation can complete. Exactly one verifier reservation
        // is issued per wave, and after five completions the sixth wave gets
        // none. The vulnerable split check/record protocol issued the whole
        // burst before any failure was recorded.
        for _ in 0..=LOCAL_LOGIN_LOCKOUT_THRESHOLD {
            let start = std::sync::Barrier::new(BURST + 1);
            let all_decided = std::sync::Barrier::new(BURST + 1);
            std::thread::scope(|scope| {
                for _ in 0..BURST {
                    let start = &start;
                    let all_decided = &all_decided;
                    let local_auth = &local_auth;
                    let throttle = &throttle;
                    let verifier_calls = &verifier_calls;
                    let test_credential = &test_credential;
                    scope.spawn(move || {
                        start.wait();
                        let admission =
                            throttle.begin_attempt_at(local_auth, "admin", test_credential, now);
                        all_decided.wait();
                        if let LocalLoginAttemptAdmission::Verify(attempt) = admission {
                            verifier_calls.fetch_add(1, Ordering::SeqCst);
                            attempt.record_failure_at(now);
                        }
                    });
                }
                start.wait();
                all_decided.wait();
            });
        }

        assert_eq!(
            verifier_calls.load(Ordering::SeqCst),
            LOCAL_LOGIN_LOCKOUT_THRESHOLD as usize,
            "no concurrent burst may evaluate more than the configured threshold"
        );
        assert!(throttle
            .entries
            .lock()
            .unwrap()
            .get("admin")
            .unwrap()
            .lock_until
            .is_some());
    }

    #[test]
    fn test_stale_attempt_completion_cannot_overwrite_new_generation() {
        let local_auth = test_local_auth_config("admin:placeholder-pass-1:PlatformAdmin");
        let throttle = LocalLoginThrottle::default();
        let now = std::time::Instant::now();

        let stale = admitted_local_login_attempt(&throttle, &local_auth, "admin", now);
        let later = now + LOCAL_LOGIN_FAILURE_WINDOW;
        let current = admitted_local_login_attempt(&throttle, &local_auth, "admin", later);
        current.record_failure_at(later);
        stale.record_failure_at(later);

        let entries = throttle.entries.lock().unwrap();
        let entry = entries.get("admin").unwrap();
        assert_eq!(entry.consecutive_failures, 1);
        assert!(entry.in_flight_generation.is_none());
    }

