    #[test]
    fn test_local_login_throttle_recovers_from_poisoned_mutex() {
        // A panic while holding the throttle lock poisons the mutex. The
        // throttle must keep working (recover via into_inner) rather than
        // turning every subsequent login into a panic — an auth-path DoS.
        let local_auth = test_local_auth_config(
            "admin:placeholder-pass-1:PlatformAdmin,operator:placeholder-pass-2:Operator",
        );
        let throttle = std::sync::Arc::new(LocalLoginThrottle::default());
        let now = std::time::Instant::now();
        record_local_login_failure(&throttle, &local_auth, "admin", now);

        let poisoner = std::sync::Arc::clone(&throttle);
        let handle = std::thread::spawn(move || {
            let _guard = poisoner.entries.lock().unwrap();
            panic!("intentional panic while holding the throttle lock");
        });
        assert!(handle.join().is_err(), "poisoning thread must panic");

        // Neither admission nor completion may panic on the poisoned mutex.
        admitted_local_login_attempt(&throttle, &local_auth, "operator", now).record_success();
        admitted_local_login_attempt(&throttle, &local_auth, "admin", now).record_success();
        let entries = match throttle.entries.lock() {
            Ok(_) => panic!("intentional poisoning should remain observable"),
            Err(poisoned) => poisoned.into_inner(),
        };
        assert!(entries.is_empty());
    }

