    #[test]
    fn request_sort_is_allowlisted_and_injection_safe() {
        // Known columns map through; everything unknown (incl. an injection
        // attempt) falls back to created_at — never interpolated raw.
        assert_eq!(request_sort_column(Some("name")), "name");
        assert_eq!(request_sort_column(Some("updated_at")), "updated_at");
        assert_eq!(request_sort_column(None), "created_at");
        assert_eq!(
            request_sort_column(Some("created_at; DROP TABLE requests--")),
            "created_at"
        );
        // Direction is ASC only on an explicit case-insensitive "asc"; else DESC.
        assert_eq!(request_sort_direction(Some("asc")), "ASC");
        assert_eq!(request_sort_direction(Some("ASC")), "ASC");
        assert_eq!(request_sort_direction(Some("desc")), "DESC");
        assert_eq!(request_sort_direction(Some("garbage")), "DESC");
        assert_eq!(request_sort_direction(None), "DESC");
    }

    /// #9: the X-Total-Count header reports the FILTERED total (before
    /// limit/offset), not the page size — so a paginating client knows the page
    /// count. The body stays a bare array (backward-compatible).
    #[tokio::test]
    async fn requests_list_total_count_header_reflects_filtered_total() {
        let site = "RLTOTAL-z9"; // unique site so other tests' rows don't match
        for i in 0..3 {
            let mut r = test_request(&format!("rl-total-{i}"));
            r.site = site.into();
            request_store().lock().await.push(r);
        }
        let (headers, Json(body)) = requests_list(
            AuthExtractor(AuthSession::static_dry_run()),
            Query(RequestListParams {
                limit: Some(2),
                offset: Some(0),
                include_total: Some(true),
                site: Some(site.into()),
                ..Default::default()
            }),
        )
        .await
        .expect("list");
        assert_eq!(
            body.as_array().unwrap().len(),
            2,
            "the page body is capped at limit=2"
        );
        let total = headers
            .get("x-total-count")
            .expect("X-Total-Count header present")
            .to_str()
            .unwrap();
        assert_eq!(
            total, "3",
            "X-Total-Count must be the filtered total (3), not the page size (2)"
        );
    }

