    #[tokio::test]
    async fn requests_list_filters_in_memory_by_status_site_and_q() {
        let mut a = test_request("rl-filter-a");
        a.site = "DEFRA".into();
        a.requester = "alice-deploy".into();
        let mut b = test_request("rl-filter-b");
        b.site = "GBLON".into();
        b.requester = "bob-deploy".into();
        {
            let mut store = request_store().lock().await;
            store.push(a);
            store.push(b);
        }

        let ids = |body: &Value| -> Vec<String> {
            body.as_array()
                .unwrap()
                .iter()
                .map(|i| i["request_id"].as_str().unwrap_or_default().to_string())
                .collect()
        };

        // Filter by site → only the DEFRA row.
        let (_, Json(by_site)) = requests_list(
            AuthExtractor(AuthSession::static_dry_run()),
            Query(RequestListParams {
                site: Some("DEFRA".into()),
                ..Default::default()
            }),
        )
        .await
        .expect("an unrestricted session lists requests");
        let site_ids = ids(&by_site);
        assert!(site_ids.contains(&"rl-filter-a".to_string()));
        assert!(!site_ids.contains(&"rl-filter-b".to_string()));

        // Case-insensitive substring on the (requester) name.
        let (_, Json(by_q)) = requests_list(
            AuthExtractor(AuthSession::static_dry_run()),
            Query(RequestListParams {
                q: Some("BOB".into()),
                ..Default::default()
            }),
        )
        .await
        .expect("an unrestricted session lists requests");
        let q_ids = ids(&by_q);
        assert!(q_ids.contains(&"rl-filter-b".to_string()));
        assert!(!q_ids.contains(&"rl-filter-a".to_string()));

        // A blank filter is ignored (both rows listed).
        let (_, Json(blank)) = requests_list(
            AuthExtractor(AuthSession::static_dry_run()),
            Query(RequestListParams {
                site: Some("   ".into()),
                ..Default::default()
            }),
        )
        .await
        .expect("an unrestricted session lists requests");
        let blank_ids = ids(&blank);
        assert!(blank_ids.contains(&"rl-filter-a".to_string()));
        assert!(blank_ids.contains(&"rl-filter-b".to_string()));
    }

    /// C015: request-only visibility is an object-ownership boundary on both
    /// list and detail reads. A client-supplied foreign creator filter cannot
    /// replace that mandatory boundary, while audit-capable identities retain
    /// their operational cross-owner read.
    #[tokio::test]
    async fn request_only_principal_lists_and_reads_only_own_requests() {
        let suffix = Uuid::new_v4().simple().to_string();
        let site = format!("OWNERSHIP-{}", &suffix[..8]);
        let alice = format!("alice-{suffix}");
        let bob = format!("bob-{suffix}");
        let own_id = format!("request-own-{suffix}");
        let foreign_id = format!("request-foreign-{suffix}");
        let alice_principal = test_principal_id(&alice).to_string();
        let bob_principal = test_principal_id(&bob).to_string();

        let mut own = test_request(&own_id);
        own.site = site.clone();
        own.requester = alice_principal.clone();
        own.owner = alice_principal;
        let mut foreign = test_request(&foreign_id);
        foreign.site = site.clone();
        foreign.requester = bob_principal.clone();
        foreign.owner = bob_principal.clone();
        request_store().lock().await.extend([own, foreign]);

        let requester = single_role_session(&alice, ryuki_engine::auth::APP_ROLE_REQUESTER);
        let (visible_headers, Json(visible)) = requests_list(
            AuthExtractor(requester.clone()),
            Query(RequestListParams {
                site: Some(site.clone()),
                limit: Some(100),
                include_total: Some(true),
                ..Default::default()
            }),
        )
        .await
        .expect("a requester may list its own requests");
        assert_eq!(
            visible_headers
                .get("x-total-count")
                .and_then(|value| value.to_str().ok()),
            Some("1")
        );
        let ids: Vec<&str> = visible
            .as_array()
            .expect("list response is an array")
            .iter()
            .filter_map(|item| item["request_id"].as_str())
            .collect();
        assert_eq!(ids, vec![own_id.as_str()]);

        let (foreign_headers, Json(foreign_filter)) = requests_list(
            AuthExtractor(requester.clone()),
            Query(RequestListParams {
                site: Some(site.clone()),
                created_by: Some(bob_principal),
                limit: Some(100),
                include_total: Some(true),
                ..Default::default()
            }),
        )
        .await
        .expect("a foreign filter is safely intersected with ownership");
        assert_eq!(
            foreign_headers
                .get("x-total-count")
                .and_then(|value| value.to_str().ok()),
            Some("0")
        );
        assert!(
            foreign_filter.as_array().is_some_and(Vec::is_empty),
            "a foreign created_by filter must never widen requester visibility"
        );

        let Json(own_detail) =
            requests_get_for_test(AuthExtractor(requester.clone()), Path(own_id.clone()))
                .await
                .expect("a requester may read its own request");
        assert_eq!(own_detail["id"], own_id);

        let foreign_err = requests_get_for_test(AuthExtractor(requester), Path(foreign_id.clone()))
            .await
            .expect_err("a foreign request must be hidden from a request-only principal");
        assert_eq!(foreign_err.0, StatusCode::NOT_FOUND);

        let auditor = single_role_session("auditor", ryuki_engine::auth::APP_ROLE_AUDITOR);
        let (_, Json(audited_list)) = requests_list(
            AuthExtractor(auditor.clone()),
            Query(RequestListParams {
                site: Some(site),
                limit: Some(100),
                ..Default::default()
            }),
        )
        .await
        .expect("an auditor retains cross-owner list visibility");
        let audited_ids: std::collections::HashSet<&str> = audited_list
            .as_array()
            .expect("list response is an array")
            .iter()
            .filter_map(|item| item["request_id"].as_str())
            .collect();
        assert_eq!(
            audited_ids,
            std::collections::HashSet::from([own_id.as_str(), foreign_id.as_str()])
        );

        let Json(foreign_detail) =
            requests_get_for_test(AuthExtractor(auditor), Path(foreign_id.clone()))
                .await
                .expect("an auditor retains cross-owner detail visibility");
        assert_eq!(foreign_detail["id"], foreign_id);
    }

    /// C016: policy evaluation follows the same request-owner boundary as the
    /// request detail. Alice may evaluate her own request, Bob's request is a
    /// 404, and an audit-capable reader retains the operational view.
    #[tokio::test]
    async fn request_policy_eval_is_limited_to_owner_or_auditor() {
        let suffix = Uuid::new_v4().simple().to_string();
        let alice = format!("policy-alice-{suffix}");
        let bob = format!("policy-bob-{suffix}");
        let own_id = format!("policy-own-{suffix}");
        let foreign_id = format!("policy-foreign-{suffix}");
        let alice_principal = test_principal_id(&alice).to_string();
        let bob_principal = test_principal_id(&bob).to_string();

        let mut own = test_request(&own_id);
        own.requester = alice_principal.clone();
        own.owner = alice_principal;
        let mut foreign = test_request(&foreign_id);
        foreign.requester = bob_principal;
        foreign.owner = foreign.requester.clone();
        request_store().lock().await.extend([own, foreign]);

        let requester = single_role_session(&alice, ryuki_engine::auth::APP_ROLE_REQUESTER);
        let Json(own_eval) =
            requests_policy_eval(AuthExtractor(requester.clone()), Path(own_id.clone()))
                .await
                .expect("a requester may inspect policy readiness for its own request");
        assert_eq!(own_eval["request_id"], own_id);

        let foreign = requests_policy_eval(AuthExtractor(requester), Path(foreign_id.clone()))
            .await
            .expect_err("a requester must not inspect a foreign policy evaluation");
        assert_eq!(foreign.0, StatusCode::NOT_FOUND);

        let auditor = single_role_session(
            &format!("policy-auditor-{suffix}"),
            ryuki_engine::auth::APP_ROLE_AUDITOR,
        );
        let Json(audit_eval) =
            requests_policy_eval(AuthExtractor(auditor), Path(foreign_id.clone()))
                .await
                .expect("an auditor retains cross-owner policy visibility");
        assert_eq!(audit_eval["request_id"], foreign_id);
    }

    #[test]
    fn request_ownership_prefers_requester_then_legacy_created_by() {
        assert!(request_is_owned_by("alice", Some("alice"), Some("bob")));
        assert!(request_is_owned_by("alice", None, Some("alice")));
        assert!(request_is_owned_by("alice", Some("  "), Some("alice")));
        assert!(
            !request_is_owned_by("alice", Some("bob"), Some("alice")),
            "a populated authoritative requester must not be overridden by legacy created_by"
        );
        assert!(!request_is_owned_by("alice", None, None));
    }

    // ─── API token & session administration ───

    #[test]
    fn test_generate_api_token_format() {
        let token = generate_api_token();
        // ryk_ prefix + 43 base64url-no-pad chars (32 bytes) = 47 total.
        assert!(token.starts_with(crate::API_TOKEN_PREFIX));
        assert_eq!(token.len(), 47);
        let suffix = token.strip_prefix(crate::API_TOKEN_PREFIX).unwrap();
        assert_eq!(suffix.len(), 43);
        assert!(suffix
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_'));
    }

    #[test]
    fn test_generate_api_token_is_unique_per_call() {
        // CSPRNG: two mints are (astronomically certainly) distinct, and their
        // hashes differ — so neither the token nor its hash is ever a literal.
        let a = generate_api_token();
        let b = generate_api_token();
        assert_ne!(a, b);
        assert_ne!(crate::sha256_hex(&a), crate::sha256_hex(&b));
    }

