    #[test]
    fn credential_administration_requires_global_verified_human() {
        let global_human = AuthSession {
            display_user_id: "global-admin".into(),
            principal_id: Some(test_principal_id("global-admin")),
            display_name: "Global admin".into(),
            roles: vec![ryuki_engine::auth::APP_ROLE_PLATFORM_ADMIN.to_string()],
            token_valid: true,
            actor_class: ryuki_engine::auth::ActorClass::VerifiedHuman,
            provider_mode: "persisted-session".into(),
            site_scope: vec![],
            environment_scope: vec![],
        };
        assert!(require_global_verified_human_admin_permission(&global_human).is_ok());

        let workload = AuthSession {
            actor_class: ryuki_engine::auth::ActorClass::Workload,
            provider_mode: "api-token".into(),
            ..global_human.clone()
        };
        let Err((status, Json(error))) = require_global_verified_human_admin_permission(&workload)
        else {
            panic!("an admin API token must not administer credential inventory");
        };
        assert_eq!(status, StatusCode::FORBIDDEN);
        assert_eq!(error.error, "GLOBAL_VERIFIED_HUMAN_REQUIRED");

        for scoped in [
            AuthSession {
                site_scope: vec!["BRU".into()],
                ..global_human.clone()
            },
            AuthSession {
                environment_scope: vec!["production".into()],
                ..global_human.clone()
            },
        ] {
            assert!(require_global_verified_human_admin_permission(&scoped).is_err());
        }

        let simulated = AuthSession {
            actor_class: ryuki_engine::auth::ActorClass::Simulated,
            ..global_human
        };
        assert!(require_global_verified_human_admin_permission(&simulated).is_err());
    }

    #[test]
    fn derived_token_authority_is_an_exact_subset_of_human_context() {
        let principal_id = test_principal_id("derived-token-issuer");
        let principal_binding = crate::principal_registry::PrincipalBinding {
            principal_id,
            principal_lifecycle_version: 7,
            principal_authority_version: 11,
            principal_key_id: Uuid::new_v4(),
            principal_key_version: 13,
            principal_link_id: Uuid::new_v4(),
            principal_link_version: 17,
        };
        let session = AuthSession {
            display_user_id: principal_id.to_string(),
            principal_id: Some(principal_id),
            display_name: "Issuer".into(),
            roles: vec!["Auditor".into(), "PlatformAdmin".into()],
            token_valid: true,
            actor_class: ryuki_engine::auth::ActorClass::VerifiedHuman,
            provider_mode: "persisted-session".into(),
            site_scope: vec!["SITE-A".into(), "SITE-B".into()],
            environment_scope: vec!["prod".into()],
        };
        let authority = crate::human_authority::InteractiveHumanAuthorityContext {
            principal_binding,
            provider: "entra-id".into(),
            issuer: "https://issuer.example/tenant/v2.0".into(),
            subject: "issuer-subject".into(),
            identity_epoch: 7,
            assignment_version: 11,
            roles: session.roles.clone(),
            site_mode: crate::human_authority::HumanAuthorityMode::Scoped,
            site_scope: session.site_scope.clone(),
            environment_mode: crate::human_authority::HumanAuthorityMode::Scoped,
            environment_scope: session.environment_scope.clone(),
        };
        assert!(token_authority_is_bounded_by_issuer(
            &session,
            &authority,
            &["Auditor".into()],
            &["SITE-A".into()],
            &["prod".into()],
        ));
        assert!(!token_authority_is_bounded_by_issuer(
            &session,
            &authority,
            &["Auditor".into()],
            &[],
            &["prod".into()],
        ));
        assert!(!token_authority_is_bounded_by_issuer(
            &session,
            &authority,
            &["Auditor".into()],
            &["SITE-C".into()],
            &["prod".into()],
        ));
        assert!(!token_authority_is_bounded_by_issuer(
            &session,
            &authority,
            &["AgentOperator".into()],
            &["SITE-A".into()],
            &["prod".into()],
        ));

        let wrong_subject = crate::human_authority::InteractiveHumanAuthorityContext {
            subject: "same-display-different-subject".into(),
            ..authority.clone()
        };
        assert!(token_authority_is_bounded_by_issuer(
            &session,
            &wrong_subject,
            &["Auditor".into()],
            &["SITE-A".into()],
            &["prod".into()],
        ));
        let wrong_principal = crate::human_authority::InteractiveHumanAuthorityContext {
            principal_binding: crate::principal_registry::PrincipalBinding {
                principal_id: test_principal_id("different-token-issuer"),
                ..principal_binding
            },
            ..authority.clone()
        };
        assert!(!token_authority_is_bounded_by_issuer(
            &session,
            &wrong_principal,
            &["Auditor".into()],
            &["SITE-A".into()],
            &["prod".into()],
        ));
        let workload = AuthSession {
            actor_class: ryuki_engine::auth::ActorClass::Workload,
            ..session
        };
        assert!(!token_authority_is_bounded_by_issuer(
            &workload,
            &authority,
            &["Auditor".into()],
            &["SITE-A".into()],
            &["prod".into()],
        ));
    }

