    /// Build an in-memory request advanced to Planned (the decision point).
    async fn seed_planned_request(id: &str, requester: &str) {
        let mut request = test_request(id);
        request.requester = test_principal_id(requester).to_string();
        request.owner = request.requester.clone();
        request.approval_route.push("Datacenter Approver".into());
        request_store().lock().await.push(request);

        let operator = static_admin_operator_session();
        let _ = requests_validate(Path(id.to_string()), AuthExtractor(operator.clone()))
            .await
            .expect("validate");
        let _ = requests_plan(Path(id.to_string()), AuthExtractor(operator))
            .await
            .expect("plan");
    }

    /// #2 RBAC: the NO-DB (in-memory) branches of requests_verify / requests_protect
    /// are site/environment-scoped — a scoped principal verifying/protecting an
    /// out-of-scope request gets a 404 (not a cross-scope transition or oracle),
    /// while an in-scope principal passes the scope gate. (The DB branches are
    /// covered by lifecycle_transition_is_site_scoped + the chokepoint.)
    #[tokio::test]
    async fn verify_protect_no_db_are_site_scoped() {
        let id = format!("req-scope-{}", Uuid::new_v4());
        // Seeds a DEFRA/production request into the in-memory store (no-DB path).
        seed_planned_request(&id, "alice").await;

        // Out-of-scope (GBLON) → 404 from the no-DB scope guard.
        let mut gblon = static_admin_operator_session();
        gblon.site_scope = vec!["GBLON".into()];
        let v = requests_verify(Path(id.clone()), AuthExtractor(gblon.clone())).await;
        assert!(
            matches!(v, Err((StatusCode::NOT_FOUND, _))),
            "out-of-scope verify must 404: {v:?}"
        );
        let p = requests_protect(Path(id.clone()), AuthExtractor(gblon)).await;
        assert!(
            matches!(p, Err((StatusCode::NOT_FOUND, _))),
            "out-of-scope protect must 404: {p:?}"
        );

        // In-scope (DEFRA/production) passes the scope gate (the engine then
        // rejects the wrong-state transition, but it is never the scope 404).
        let mut defra = static_admin_operator_session();
        defra.site_scope = vec!["DEFRA".into()];
        defra.environment_scope = vec!["production".into()];
        let v2 = requests_verify(Path(id.clone()), AuthExtractor(defra)).await;
        assert!(
            !matches!(v2, Err((StatusCode::NOT_FOUND, _))),
            "in-scope verify must pass the scope gate: {v2:?}"
        );
    }

    #[test]
    fn sod_decision_blocks_self_approval_only_under_live_identity() {
        let alice = single_role_session("alice", ryuki_engine::auth::APP_ROLE_DATACENTER_APPROVER);
        let alice_principal = alice
            .principal_id
            .expect("alice test principal")
            .to_string();
        // A different creator (or unknown creator) is never a self-approval.
        assert_eq!(
            sod_decision(&alice, Some("bob"), &AuthMode::EntraId),
            SodDecision::Allow
        );
        assert_eq!(
            sod_decision(&alice, None, &AuthMode::Local),
            SodDecision::Allow
        );
        // Self-approval under live identity → hard block.
        assert_eq!(
            sod_decision(&alice, Some(&alice_principal), &AuthMode::EntraId),
            SodDecision::Block
        );
        assert_eq!(
            sod_decision(&alice, Some(&alice_principal), &AuthMode::Local),
            SodDecision::Block
        );
        // Self-approval in dry-run → warn-only (every caller is `static-user`).
        assert_eq!(
            sod_decision(&alice, Some(&alice_principal), &AuthMode::MockDryRun),
            SodDecision::Warn
        );
        assert_eq!(
            sod_decision(&alice, Some(&alice_principal), &AuthMode::StaticDryRun),
            SodDecision::Warn
        );
    }

