    /// #17 (slice 2, no-DB scope hardening): the in-memory reject path now applies
    /// the SAME by-id scope guard as the DB path and as cancel_one. A scoped
    /// principal rejecting an out-of-scope in-memory request gets a 404 — both via
    /// the SINGLE handler and INSIDE a batch (where it surfaces as a per-id 404).
    /// This proves reject_one closed the lone no-DB scope gap.
    #[tokio::test]
    async fn requests_reject_no_db_is_site_scoped_single_and_batch() {
        // seed_planned_request creates a DEFRA/production in-memory request.
        let id = format!("req-scope-{}", Uuid::new_v4());
        seed_planned_request(&id, "requester-1").await;

        // A GBLON-scoped approver is OUT of scope for the DEFRA request.
        let mut gblon = single_role_session(
            "approver-gblon",
            ryuki_engine::auth::APP_ROLE_DATACENTER_APPROVER,
        );
        gblon.site_scope = vec!["GBLON".into()];

        // Single handler → 404 (scope guard), not a cross-scope reject.
        let single = requests_reject(
            Path(id.clone()),
            AuthExtractor(gblon.clone()),
            reviewed_request_reject_body(&id, "out of scope").await,
        )
        .await;
        assert!(
            matches!(single, Err((StatusCode::NOT_FOUND, _))),
            "out-of-scope single reject must 404: {single:?}"
        );

        // Batch handler → HTTP 200 with a per-id 404 result (no oracle), 0 succeeded.
        let Json(out) = requests_batch_reject(
            AuthExtractor(gblon),
            Json(BatchRejectRequest {
                items: vec![reviewed_batch_reject_item(&id).await],
                reason: "out of scope".into(),
            }),
        )
        .await
        .expect("batch reject returns 200 even when every item fails");
        assert_eq!(out["succeeded"], 0);
        assert_eq!(out["failed"], 1);
        let item = &out["results"].as_array().unwrap()[0];
        assert_eq!(item["ok"], false);
        assert_eq!(item["status"], 404);

        // The request was never rejected — still planned in the store.
        let store = request_store().lock().await;
        let stored = store.iter().find(|r| r.id == id).unwrap();
        assert_eq!(stored.status, ryuki_engine::models::RequestStatus::Planned);
    }

    /// run-5: the 6 request-lifecycle mutations whose NO-DB branch was missing the
    /// scope guard (validate / plan / lock / execute / publish / retire) now 404 for an
    /// out-of-scope scoped principal BEFORE any transition — never a cross-scope
    /// mutation. (approve / verify / protect / reject / fail / cancel were already
    /// guarded.) Runs meaningfully only in a no-DB process.
    #[tokio::test]
    async fn requests_lifecycle_mutations_no_db_are_site_scoped() {
        // FAIL-CLOSED: get_db() reads the process-global pool, NOT the env var. If a
        // prior DB test initialized it, these handlers take the DB branch and 404 as
        // not-found — a false green. Only run (meaningfully) in a no-DB process.
        if get_db().is_some() {
            eprintln!("SKIP: no-DB scope test requires no-DB mode (run via `make test`)");
            return;
        }
        let id = format!("req-scope-lifecycle-{}", Uuid::new_v4());
        // Seeds a DEFRA/production Planned in-memory request.
        seed_planned_request(&id, "requester-1").await;

        // execute-tier (all 6 gate `execute`) GBLON-scoped principal — OUT of scope for
        // the DEFRA request (VMwareOperator grants execute; site_scope makes it scoped).
        let scoped = || {
            let mut s = AuthSession::static_dry_run();
            s.roles
                .push(ryuki_engine::auth::APP_ROLE_VMWARE_OPERATOR.to_string());
            s.site_scope = vec!["GBLON".into()];
            s
        };

        macro_rules! assert_scoped_404 {
            ($call:expr, $name:expr) => {{
                let r = $call.await;
                assert!(
                    matches!(r, Err((StatusCode::NOT_FOUND, _))),
                    "{} out-of-scope must 404 (no-DB scope guard): {:?}",
                    $name,
                    r
                );
            }};
        }
        assert_scoped_404!(
            requests_validate(Path(id.clone()), AuthExtractor(scoped())),
            "validate"
        );
        assert_scoped_404!(
            requests_plan(Path(id.clone()), AuthExtractor(scoped())),
            "plan"
        );
        assert_scoped_404!(
            requests_lock(Path(id.clone()), AuthExtractor(scoped())),
            "lock"
        );
        assert_scoped_404!(
            requests_execute(
                Path(id.clone()),
                Query(ExecuteParams::default()),
                AuthExtractor(scoped())
            ),
            "execute"
        );
        assert_scoped_404!(
            requests_publish(Path(id.clone()), AuthExtractor(scoped())),
            "publish"
        );
        assert_scoped_404!(
            requests_retire(Path(id.clone()), AuthExtractor(scoped())),
            "retire"
        );

        // The request was never mutated — still Planned in the store.
        let store = request_store().lock().await;
        let stored = store.iter().find(|r| r.id == id).unwrap();
        assert_eq!(
            stored.status,
            ryuki_engine::models::RequestStatus::Planned,
            "no cross-scope mutation occurred"
        );
    }

    /// run-5: a usize pagination offset above i64::MAX must clamp so the `as i64`
    /// SQL bind never wraps negative (which Postgres rejects → 500). Guards the
    /// requests_list / activity_audit_feed / settings-history offset binds.
    #[test]
    fn clamp_offset_usize_never_casts_negative() {
        assert_eq!(clamp_offset_usize(0), 0);
        assert_eq!(clamp_offset_usize(100), 100);
        let max = i64::MAX as usize;
        assert_eq!(
            clamp_offset_usize(max),
            max,
            "exactly i64::MAX is preserved"
        );
        // usize::MAX (and anything above i64::MAX) clamps to i64::MAX.
        assert_eq!(clamp_offset_usize(usize::MAX), max);
        assert!(
            clamp_offset_usize(usize::MAX) as i64 >= 0,
            "the clamped offset never casts to a negative i64"
        );
        // `max + 1` only exists on platforms where usize is wider than i64 (64-bit);
        // guard with checked_add so the test itself is width-clean (codex).
        if let Some(over) = max.checked_add(1) {
            assert!(clamp_offset_usize(over) as i64 >= 0);
        }
    }

