    #[test]
    fn request_list_cursor_is_bounded_scope_bound_and_deterministic() {
        let created_at = chrono::DateTime::parse_from_rfc3339("2026-07-15T12:00:00Z")
            .unwrap()
            .with_timezone(&chrono::Utc);
        let scope = request_list_cursor_scope(&[
            Some("alice"),
            Some("alice"),
            Some("planned"),
            Some("DEFRA"),
            Some("production"),
            None,
            None,
            None,
        ]);
        let encoded = encode_request_list_cursor(
            created_at,
            "5b1413dd-3ea2-459b-a7af-0f8d40c1c32b",
            "DESC",
            &scope,
        )
        .expect("valid cursor state encodes");
        assert!(encoded.len() <= MAX_REQUEST_LIST_CURSOR_BYTES);
        assert_eq!(
            decode_request_list_cursor(&encoded, "DESC", &scope),
            Ok(RequestListCursor {
                created_at,
                id: "5b1413dd-3ea2-459b-a7af-0f8d40c1c32b".into(),
            })
        );
        assert!(decode_request_list_cursor(&encoded, "ASC", &scope).is_err());
        let other_scope = request_list_cursor_scope(&[
            Some("bob"),
            Some("bob"),
            Some("planned"),
            Some("DEFRA"),
            Some("production"),
            None,
            None,
            None,
        ]);
        assert!(decode_request_list_cursor(&encoded, "DESC", &other_scope).is_err());
        assert!(decode_request_list_cursor(
            &"x".repeat(MAX_REQUEST_LIST_CURSOR_BYTES + 1),
            "DESC",
            &scope,
        )
        .is_err());
        assert_eq!(
            request_list_cursor_predicate(7, 8, "DESC"),
            "(created_at, id) < ($7::timestamptz, $8::uuid)"
        );
        assert_eq!(
            request_list_cursor_predicate(7, 8, "ASC"),
            "(created_at, id) > ($7::timestamptz, $8::uuid)"
        );
        let headers = request_list_headers(Some(3), Some(&encoded), false);
        assert_eq!(
            headers
                .get("x-next-cursor")
                .and_then(|value| value.to_str().ok()),
            Some(encoded.as_str())
        );
        let unavailable = request_list_headers(None, None, true);
        assert!(unavailable.get("x-total-count").is_none());
        assert_eq!(
            unavailable
                .get("x-total-count-unavailable")
                .and_then(|value| value.to_str().ok()),
            Some("true")
        );
    }

