    #[test]
    fn bounded_store_rejects_capacity_without_evicting_lifecycle_state() {
        let first = test_request("local-capacity-first");
        let second = test_request("local-capacity-second");
        let third = test_request("local-capacity-third");
        let record_bytes = retained_request_bytes(&first);

        let mut count_limited = Vec::new();
        retain_request_in_memory_with_limits(
            &mut count_limited,
            first.clone(),
            2,
            usize::MAX,
            usize::MAX,
        )
        .expect("first record fits");
        retain_request_in_memory_with_limits(
            &mut count_limited,
            second.clone(),
            2,
            usize::MAX,
            usize::MAX,
        )
        .expect("second record fits");
        assert_eq!(
            retain_request_in_memory_with_limits(
                &mut count_limited,
                third,
                2,
                usize::MAX,
                usize::MAX,
            ),
            Err(InMemoryRequestStoreError::RecordLimit)
        );
        assert_eq!(count_limited.len(), 2);
        assert_eq!(count_limited[0].id, "local-capacity-first");

        let mut byte_limited = Vec::new();
        retain_request_in_memory_with_limits(
            &mut byte_limited,
            first.clone(),
            10,
            record_bytes * 2 - 1,
            record_bytes,
        )
        .expect("first record fits byte budget");
        assert_eq!(
            retain_request_in_memory_with_limits(
                &mut byte_limited,
                second,
                10,
                record_bytes * 2 - 1,
                usize::MAX,
            ),
            Err(InMemoryRequestStoreError::ByteLimit)
        );
        assert_eq!(byte_limited.len(), 1);
        assert_eq!(
            retain_request_in_memory_with_limits(
                &mut Vec::new(),
                first,
                10,
                usize::MAX,
                record_bytes - 1,
            ),
            Err(InMemoryRequestStoreError::RecordTooLarge)
        );

        let now = chrono::Utc::now();
        let mut expired = test_request("expired-terminal");
        expired.status = ryuki_engine::models::RequestStatus::Failed;
        expired.updated_at =
            (now - chrono::Duration::seconds(LOCAL_REQUEST_TERMINAL_TTL_SECS + 1)).to_rfc3339();
        let mut active = test_request("active-record");
        active.updated_at = expired.updated_at.clone();
        let mut terminal_records = vec![expired, active];
        prune_expired_local_terminal_requests(&mut terminal_records, now);
        assert_eq!(terminal_records.len(), 1);
        assert_eq!(terminal_records[0].id, "active-record");
    }

