    /// The evidence pack is tamper-evident: it carries a `sha256:` digest over
    /// stable content, and re-exporting an UNCHANGED request reproduces the same
    /// digest (the volatile `generated_at` is excluded from the digest).
    #[tokio::test]
    async fn request_evidence_pack_is_digest_sealed_and_reproducible() {
        let id = format!("req-evidence-{}", Uuid::new_v4());
        request_store().lock().await.push(test_request(&id));
        let admin = AuthSession::static_dry_run();

        let Ok(Json(first)) =
            request_evidence_pack(AuthExtractor(admin.clone()), Path(id.clone())).await
        else {
            panic!("admin must export the evidence pack");
        };
        let digest = first["digest"].as_str().expect("digest present");
        assert!(
            digest.starts_with("sha256:"),
            "digest must be sha256-tagged"
        );
        assert_eq!(first["algorithm"], "sha256");
        assert_eq!(first["request_id"], id);
        assert!(first["content"]["pack"].is_object());
        assert!(first["content"]["audit_trail"].is_array());

        let Ok(Json(second)) = request_evidence_pack(AuthExtractor(admin), Path(id.clone())).await
        else {
            panic!("second export must succeed");
        };
        assert_eq!(
            first["digest"], second["digest"],
            "an unchanged request must reproduce the same digest"
        );
    }

    /// Conflicting credential evidence is rejected before any resolver can
    /// fall through from one identity to another.
    #[test]
    fn test_session_header_conflicts_with_api_token_bearer() {
        let session_token = crate::session_credentials::generate_session_bearer();
        let mut headers = HeaderMap::new();
        headers.insert(
            "X-Ryuki-Session-Id",
            axum::http::HeaderValue::from_str(session_token.as_str()).unwrap(),
        );
        let cookie_runtime = crate::cookie_runtime::ApiCookieRuntime::from_admitted_config(
            &ryuki_core::config::RyukiConfig::default(),
            false,
        )
        .unwrap();
        let session_parser = cookie_runtime.session_auth_parser();
        let (parsed, source) = crate::session_credential_from_headers(
            &headers,
            Some("Bearer ryk_bogustoken"),
            &session_parser,
        )
        .expect("session header must be resolvable");
        assert_eq!(parsed, Err(()));
        assert_eq!(source, crate::SessionIdSource::Header);
    }

    /// B8: the no-DB audit path must capture the prior status/stage instead of
    /// recording NULL. Drive a fresh (Intake) request through validate and
    /// assert the local audit entry carries from_status="intake" /
    /// from_stage="intake".
    #[tokio::test]
    async fn test_local_audit_captures_from_status() {
        let id = format!("req-test-{}", Uuid::new_v4());
        let mut request = test_request(&id);
        request.approval_route.push("Datacenter Approver".into());
        request_store().lock().await.push(request);

        let operator = static_admin_operator_session();
        let _ = requests_validate(Path(id.clone()), AuthExtractor(operator))
            .await
            .expect("validate from intake");

        let Json(trail) = requests_audit(
            AuthExtractor(AuthSession::static_dry_run()),
            Path(id.clone()),
        )
        .await
        .expect("audit read");
        let entries = trail["entries"].as_array().unwrap();
        let validate = entries
            .iter()
            .find(|e| e["action"] == "request.validate")
            .expect("validate audit entry present");
        // B8: prior status/stage are no longer null.
        assert_eq!(validate["from_status"], "intake");
        assert_eq!(validate["from_stage"], "intake");
        assert_eq!(validate["to_status"], "validated");
        assert_eq!(validate["to_stage"], "validate");
    }

