    /// T2 (RED→GREEN): A DatacenterApprover calling `approvals_pending` in
    /// no-DB mode must receive an empty array — must NOT error.
    /// (No-DB mode has no decision-ledger; per the design, we return `[]`.)
    #[tokio::test]
    async fn approvals_pending_empty_in_no_db_mode() {
        let approver = single_role_session(
            "appr-pending-1",
            ryuki_engine::auth::APP_ROLE_DATACENTER_APPROVER,
        );
        let result = approvals_pending(AuthExtractor(approver)).await;
        let Ok(Json(body)) = result else {
            panic!("approver must receive Ok in no-DB mode, not an error");
        };
        // Must be a JSON array (possibly empty).
        assert!(
            body.as_array().is_some(),
            "response body must be a JSON array; got: {body}"
        );
        // The no-DB path returns [] unconditionally: the in-memory store has no
        // decision-ledger, so the `NOT EXISTS (decision)` predicate cannot be
        // evaluated and the handler returns an empty array by design. Asserting
        // is_array() is the real behavioral assertion: the function ran and
        // produced an array.
    }

    #[test]
    fn ordinary_approval_role_never_falls_back_to_emergency_principal() {
        let break_glass = single_role_session(
            "emergency-admin-a",
            ryuki_engine::auth::APP_ROLE_BREAK_GLASS_ADMIN,
        );
        assert!(
            check_permission(&break_glass, "approve"),
            "the coarse admin capability remains unchanged"
        );
        assert_eq!(
            approval_role_for(&break_glass),
            None,
            "a break-glass principal must not become a synthetic approval role"
        );

        let second_break_glass = single_role_session(
            "emergency-admin-b",
            ryuki_engine::auth::APP_ROLE_BREAK_GLASS_ADMIN,
        );
        assert_eq!(approval_role_for(&second_break_glass), None);

        let mut explicitly_ordinary = break_glass;
        explicitly_ordinary
            .roles
            .push(ryuki_engine::auth::APP_ROLE_DATACENTER_APPROVER.to_string());
        assert_eq!(
            approval_role_for(&explicitly_ordinary).as_deref(),
            Some(ryuki_engine::auth::APP_ROLE_DATACENTER_APPROVER),
            "an independently assigned ordinary role remains usable"
        );
    }

