    // ── metric aggregation (#10) — validation (no global pool: 400s precede the DB) ──

    #[tokio::test]
    async fn metric_aggregated_validation_400() {
        let s = || AuthExtractor(AuthSession::static_dry_run());
        let p = |metric_key: Option<&str>, granularity: Option<&str>| MetricAggregatedParams {
            metric_key: metric_key.map(str::to_string),
            granularity: granularity.map(str::to_string),
            ..Default::default()
        };
        // metric_key required.
        let r = metrics_series_aggregated(s(), Query(p(None, Some("daily")))).await;
        assert!(
            matches!(r, Err((StatusCode::BAD_REQUEST, _))),
            "missing metric_key: {r:?}"
        );
        // granularity required.
        let r = metrics_series_aggregated(s(), Query(p(Some("cost.x"), None))).await;
        assert!(
            matches!(r, Err((StatusCode::BAD_REQUEST, _))),
            "missing granularity: {r:?}"
        );
        // unknown granularity → 400.
        let r = metrics_series_aggregated(s(), Query(p(Some("cost.x"), Some("fortnightly")))).await;
        assert!(
            matches!(r, Err((StatusCode::BAD_REQUEST, _))),
            "bad granularity: {r:?}"
        );
        // malformed metric_key (illegal char) → 400.
        let r = metrics_series_aggregated(s(), Query(p(Some("bad key!"), Some("daily")))).await;
        assert!(
            matches!(r, Err((StatusCode::BAD_REQUEST, _))),
            "bad metric_key: {r:?}"
        );
    }

    /// C151: live operational-alert disclosure is not implied by `request`,
    /// `audit`, or unrelated `execute` authority. Every ungranted published role
    /// is rejected before the no-DB/feed branch.
    #[tokio::test]
    async fn events_alert_read_requires_dedicated_monitoring_capability() {
        for role in [
            ryuki_engine::auth::APP_ROLE_REQUESTER,
            ryuki_engine::auth::APP_ROLE_SERVICE_DESK,
            ryuki_engine::auth::APP_ROLE_AUDITOR,
            ryuki_engine::auth::APP_ROLE_BACKUP_OPERATOR,
        ] {
            let denied = events_alerts(
                AuthExtractor(single_role_session("alert-read-denied", role)),
                Query(EventsQuery::default()),
            )
            .await;
            let Err((status, Json(body))) = denied else {
                panic!("role {role} must not inherit live alert read authority");
            };
            assert_eq!(status, StatusCode::FORBIDDEN, "role {role}");
            assert_eq!(
                body["required"],
                OperationCapability::MonitoringAlertRead.as_str(),
                "role {role}"
            );
        }

        operation_capability_guard(
            &single_role_session(
                "alert-read-monitor",
                ryuki_engine::auth::APP_ROLE_MONITORING_OPERATOR,
            ),
            OperationCapability::MonitoringAlertRead,
        )
        .expect("the monitoring role owns the dedicated alert-read capability");
    }

    /// C152: single and batch acknowledgement require their own monitoring
    /// triage capability. Request, audit, and unrelated execute roles are
    /// rejected before note validation or database access; the monitoring role
    /// reaches the unchanged validation boundary.
    #[tokio::test]
    async fn events_alert_ack_requires_dedicated_capability_and_batch_validates() {
        for role in [
            ryuki_engine::auth::APP_ROLE_REQUESTER,
            ryuki_engine::auth::APP_ROLE_SERVICE_DESK,
            ryuki_engine::auth::APP_ROLE_AUDITOR,
            ryuki_engine::auth::APP_ROLE_BACKUP_OPERATOR,
        ] {
            let denied = single_role_session("alert-ack-denied", role);
            let Err((single_status, Json(single_body))) = events_alert_ack(
                AuthExtractor(denied.clone()),
                Path(1),
                Json(AlertAckBody {
                    note: Some("bad\nnote".into()),
                }),
            )
            .await
            else {
                panic!("role {role} must not acknowledge one alert");
            };
            assert_eq!(single_status, StatusCode::FORBIDDEN, "role {role}");
            assert_eq!(
                single_body["required"],
                OperationCapability::MonitoringAlertAcknowledge.as_str(),
                "role {role}"
            );

            let Err((status, Json(body))) = events_alert_batch_ack(
                AuthExtractor(denied),
                Json(BatchAlertAckBody {
                    event_ids: vec![1, 2],
                    note: None,
                }),
            )
            .await
            else {
                panic!("role {role} must not acknowledge an alert batch");
            };
            assert_eq!(status, StatusCode::FORBIDDEN, "role {role}");
            assert_eq!(
                body["required"],
                OperationCapability::MonitoringAlertAcknowledge.as_str(),
                "role {role}"
            );
        }

        let operator = single_role_session(
            "alert-operator",
            ryuki_engine::auth::APP_ROLE_MONITORING_OPERATOR,
        );
        let invalid_single = events_alert_ack(
            AuthExtractor(operator.clone()),
            Path(1),
            Json(AlertAckBody {
                note: Some("bad\nnote".into()),
            }),
        )
        .await;
        assert!(
            matches!(invalid_single, Err((StatusCode::BAD_REQUEST, _))),
            "the monitoring triage role must reach single-ack validation: {invalid_single:?}"
        );

        // Empty ids → 400.
        let empty = events_alert_batch_ack(
            AuthExtractor(operator.clone()),
            Json(BatchAlertAckBody {
                event_ids: vec![],
                note: None,
            }),
        )
        .await;
        assert!(
            matches!(empty, Err((StatusCode::BAD_REQUEST, _))),
            "empty: {empty:?}"
        );
        // > 100 ids → 400.
        let too_many = events_alert_batch_ack(
            AuthExtractor(operator.clone()),
            Json(BatchAlertAckBody {
                event_ids: (0..101).collect(),
                note: None,
            }),
        )
        .await;
        assert!(
            matches!(too_many, Err((StatusCode::BAD_REQUEST, _))),
            "cap: {too_many:?}"
        );
        // An EMBEDDED control char in the note → 400 (trim doesn't strip an interior \n).
        let bad_note = events_alert_batch_ack(
            AuthExtractor(operator),
            Json(BatchAlertAckBody {
                event_ids: vec![1],
                note: Some("bad\nnote".into()),
            }),
        )
        .await;
        assert!(
            matches!(bad_note, Err((StatusCode::BAD_REQUEST, _))),
            "control-char note: {bad_note:?}"
        );
    }

    /// #18: CMDB CI GET is AUDIT-only — a `request`-only principal is 403'd BEFORE any DB
    /// access (codex MAJOR); an audit principal with no DB gets 503 (the table is the only
    /// CI source). Both resolve without a global pool.
    #[tokio::test]
    async fn cmdb_ci_get_rbac_403_and_no_db_503() {
        // A request-only Requester (no audit, not a superuser) → 403.
        let requester = AuthSession {
            display_user_id: "req-user".into(),
            principal_id: Some(test_principal_id("cmdb-requester")),
            display_name: "R".into(),
            roles: vec![ryuki_engine::auth::APP_ROLE_REQUESTER.to_string()],
            token_valid: true,
            provider_mode: "local".into(),
            ..Default::default()
        };
        let denied = cmdb_ci_get(AuthExtractor(requester), Path("any-ci".into())).await;
        assert!(
            matches!(denied, Err((StatusCode::FORBIDDEN, _))),
            "a request-only principal must 403 (audit-only): {denied:?}"
        );
        // An audit-holder with no DB → 503 (the permission check precedes get_db).
        let no_db = cmdb_ci_get(
            AuthExtractor(AuthSession::static_dry_run()),
            Path("any-ci".into()),
        )
        .await;
        assert!(
            matches!(no_db, Err((StatusCode::SERVICE_UNAVAILABLE, _))),
            "no DB must 503: {no_db:?}"
        );
    }

