    #[test]
    fn metering_usage_window_enforces_registered_boundaries() {
        let now = chrono::DateTime::parse_from_rfc3339("2026-07-15T12:00:00Z")
            .unwrap()
            .with_timezone(&chrono::Utc);
        let earliest = now - chrono::Duration::days(MAX_METERING_USAGE_LOOKBACK_DAYS);

        assert_eq!(
            bounded_metering_usage_window(now, None, None),
            Ok((earliest, now)),
            "the omitted window is exactly the registered lookback"
        );
        assert_eq!(
            bounded_metering_usage_window(
                now,
                Some(&earliest.to_rfc3339()),
                Some(&now.to_rfc3339()),
            ),
            Ok((earliest, now)),
            "both exact boundaries are admitted"
        );
        assert_eq!(
            bounded_metering_usage_window(now, None, Some(&earliest.to_rfc3339()),),
            Ok((earliest, earliest)),
            "an explicit until at the oldest admitted instant is valid"
        );
        assert_eq!(
            bounded_metering_usage_window(
                now,
                Some(&(earliest - chrono::Duration::seconds(1)).to_rfc3339()),
                None,
            ),
            Err("metering window exceeds the maximum 90-day lookback")
        );
        assert_eq!(
            bounded_metering_usage_window(
                now,
                None,
                Some(&(earliest - chrono::Duration::seconds(1)).to_rfc3339()),
            ),
            Err("metering window exceeds the maximum 90-day lookback")
        );
        assert_eq!(
            bounded_metering_usage_window(
                now,
                Some(&(now + chrono::Duration::seconds(1)).to_rfc3339()),
                None,
            ),
            Err("metering window timestamps must not be in the future")
        );
        assert_eq!(
            bounded_metering_usage_window(
                now,
                None,
                Some(&(now + chrono::Duration::seconds(1)).to_rfc3339()),
            ),
            Err("metering window timestamps must not be in the future")
        );
        assert_eq!(
            bounded_metering_usage_window(
                now,
                Some(&now.to_rfc3339()),
                Some(&(now - chrono::Duration::seconds(1)).to_rfc3339()),
            ),
            Err("since must be less than or equal to until")
        );
        assert_eq!(
            bounded_metering_usage_window(now, Some("not-a-timestamp"), None),
            Err("since must be an RFC3339 timestamp")
        );
        assert_eq!(
            bounded_metering_usage_window(now, None, Some("not-a-timestamp")),
            Err("until must be an RFC3339 timestamp")
        );
    }

    #[test]
    fn metering_usage_query_shape_is_sargable_and_scope_specific() {
        let global = metering_usage_sql(false);
        let scoped = metering_usage_sql(true);
        assert_eq!(METERING_USAGE_STATEMENT_TIMEOUT, "2s");
        for sql in [global, scoped] {
            assert!(sql.contains("created_at >= $1 AND created_at <= $2"));
            assert!(!sql.contains("IS NULL"));
            assert!(!sql.contains(" OR "));
        }
        assert!(!global.contains("site = $3"));
        assert!(scoped.contains("site = $3"));
    }

