    #[tokio::test]
    async fn k8s_provision_enforces_both_axes_and_maintenance_site() {
        // k8s_namespace_provision is DUAL-axis (site + environment). Out-of-scope
        // SITE is a 403...
        let err = k8s_namespace_provision(
            AuthExtractor(scoped_session(&["GBLON"], &[])),
            Json(K8sProvisionRequest {
                name: "ns1".into(),
                cluster: "c1".into(),
                site: "DEFRA".into(),
                cpu: 1,
                memory: 1,
                storage: 1,
                environment: "production".into(),
            }),
        )
        .await
        .expect_err("out-of-scope site must be 403");
        assert_eq!(err.0, StatusCode::FORBIDDEN);

        // ...and an in-scope SITE but out-of-scope ENVIRONMENT is also a 403
        // (the second axis is enforced independently — k8s HAS an env axis, so an
        // environment-scoped principal is constrained, not blanket-denied).
        let err = k8s_namespace_provision(
            AuthExtractor(scoped_session(&["GBLON"], &["production"])),
            Json(K8sProvisionRequest {
                name: "ns1".into(),
                cluster: "c1".into(),
                site: "GBLON".into(),
                cpu: 1,
                memory: 1,
                storage: 1,
                environment: "dev".into(),
            }),
        )
        .await
        .expect_err("in-scope site + out-of-scope environment must be 403");
        assert_eq!(err.0, StatusCode::FORBIDDEN);

        // A valid in-scope body must not fall back to an in-memory/static
        // cluster mapping when the authoritative database is unavailable.
        if get_db().is_none() {
            let err = k8s_namespace_provision(
                AuthExtractor(scoped_session(&["GBLON"], &["Prod"])),
                Json(K8sProvisionRequest {
                    name: "no-db-ns".into(),
                    cluster: "gblon-k8s-01".into(),
                    site: "GBLON".into(),
                    cpu: 1,
                    memory: 1,
                    storage: 1,
                    environment: "Prod".into(),
                }),
            )
            .await
            .expect_err("namespace provisioning without cluster authority DB must fail closed");
            assert_eq!(err.0, StatusCode::SERVICE_UNAVAILABLE);
        }

        // maintenance_calendar_schedule receives its session via Extension and is
        // site-only: an out-of-scope site is a 403 before any DB access.
        let err = maintenance_calendar_schedule(
            Extension(scoped_session(&["GBLON"], &[])),
            Json(MaintenanceCalendarScheduleRequest {
                site: "DEFRA".into(),
                start_time: "2026-07-01T02:00:00Z".into(),
                end_time: "2026-07-01T04:00:00Z".into(),
                reason: "patch".into(),
                affected_cis: vec![],
            }),
        )
        .await
        .expect_err("scheduling maintenance for an out-of-scope site must be 403");
        assert_eq!(err.0, StatusCode::FORBIDDEN);
    }

    #[test]
    fn k8s_read_filters_preserve_site_and_environment_scope() {
        let session = scoped_session(&["DEFRA", "GBLON"], &["Dev"]);
        let (sites, environments) =
            k8s_read_scope_filters(&session, None).expect("held scope must resolve");
        assert_eq!(sites, vec!["DEFRA".to_string(), "GBLON".to_string()]);
        assert_eq!(environments, vec!["Dev".to_string()]);

        let explicit = k8s_read_scope_filters(&session, Some("GBLON"))
            .expect("held explicit site must resolve");
        assert_eq!(explicit.0, vec!["GBLON".to_string()]);
        assert_eq!(explicit.1, vec!["Dev".to_string()]);

        let denied = k8s_read_scope_filters(&session, Some("FRPAR"))
            .expect_err("foreign explicit site must be rejected before SQL");
        assert_eq!(denied.0, StatusCode::FORBIDDEN);

        let blank_scoped = scoped_session(&["   "], &["   "]);
        let (blank_sites, blank_environments) =
            k8s_read_scope_filters(&blank_scoped, None).expect("blank scope is representable");
        assert_eq!(blank_sites, vec![String::new()]);
        assert_eq!(blank_environments, vec![String::new()]);
    }

