    /// #2 RBAC: EVERY request lifecycle transition funnels through
    /// apply_transition_audited, which now scope-guards on the loaded request's
    /// site/environment. A principal scoped to another site gets a 404 (not a
    /// cross-scope write); an in-scope principal passes the gate. One test covers
    /// all transition handlers via the chokepoint.
    #[tokio::test]
    async fn lifecycle_transition_is_site_scoped() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        // seed_request creates a DEFRA/production request. 'validated' is plannable.
        let id = seed_request(pool, "validated", "validate").await;
        let id_s = id.to_string();

        // Out-of-scope (GBLON) → 404 from the after-load scope guard, BEFORE any
        // engine logic (so it is not a state oracle either).
        let mut gblon = AuthSession::static_dry_run();
        bind_test_principal(&mut gblon, "op-gblon");
        gblon.site_scope = vec!["GBLON".into()];
        let denied = requests_plan(Path(id_s.clone()), AuthExtractor(gblon)).await;
        assert!(
            matches!(denied, Err((StatusCode::NOT_FOUND, _))),
            "an out-of-scope transition must 404 at the scope guard: {denied:?}"
        );

        // In-scope (DEFRA/production) → passes the gate and the transition runs.
        let mut defra = AuthSession::static_dry_run();
        bind_test_principal(&mut defra, "op-defra");
        defra.site_scope = vec!["DEFRA".into()];
        defra.environment_scope = vec!["production".into()];
        let allowed = requests_plan(Path(id_s.clone()), AuthExtractor(defra)).await;
        assert!(
            allowed.is_ok(),
            "an in-scope transition must pass the scope gate: {allowed:?}"
        );

        cleanup_request(pool, id).await;
    }

    /// C015: the database page/count predicates and by-id handler enforce the
    /// same owner boundary as the no-database path. The current requester field
    /// is authoritative, legacy created_by remains readable only as a fallback,
    /// a caller-supplied foreign created_by filter cannot widen the result, and
    /// audit-capable readers retain the intended cross-owner operational view.
    #[tokio::test]
    async fn request_database_reads_are_limited_to_owner_or_auditor() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let suffix = Uuid::new_v4().simple().to_string();
        let alice = format!("owner-alice-{suffix}");
        let bob = format!("owner-bob-{suffix}");
        let own_id = Uuid::new_v4();
        let legacy_id = Uuid::new_v4();
        let foreign_id = Uuid::new_v4();

        for (id, created_by, requester, name) in [
            (
                own_id,
                "legacy-other",
                Some(alice.as_str()),
                "owner-current",
            ),
            (legacy_id, alice.as_str(), None, "owner-legacy"),
            (
                foreign_id,
                alice.as_str(),
                Some(bob.as_str()),
                "owner-foreign",
            ),
        ] {
            sqlx::query(
                "INSERT INTO requests (id, request_type, status, stage, site, environment, \
                 name, cpu, memory_gb, created_by, requester) \
                 VALUES ($1, 'server-deployment', 'draft', 'request', 'DEFRA', \
                 'production', $2, 2, 4, $3, $4)",
            )
            .bind(id)
            .bind(name)
            .bind(created_by)
            .bind(requester)
            .execute(pool)
            .await
            .expect("seed owner-bound request");
        }

        let requester = request_read_session(&alice, ryuki_engine::auth::APP_ROLE_REQUESTER);
        let (visible_headers, Json(visible)) = requests_list(
            AuthExtractor(requester.clone()),
            Query(RequestListParams {
                site: Some("DEFRA".into()),
                environment: Some("production".into()),
                limit: Some(100),
                include_total: Some(true),
                ..Default::default()
            }),
        )
        .await
        .expect("request owner may list its current and legacy rows");
        assert_eq!(
            visible_headers
                .get("x-total-count")
                .and_then(|value| value.to_str().ok()),
            Some("2")
        );
        let visible_ids: std::collections::HashSet<&str> = visible
            .as_array()
            .expect("list response is an array")
            .iter()
            .filter_map(|item| item["request_id"].as_str())
            .collect();
        assert!(visible_ids.contains(own_id.to_string().as_str()));
        assert!(visible_ids.contains(legacy_id.to_string().as_str()));
        assert!(!visible_ids.contains(foreign_id.to_string().as_str()));

        let (filtered_headers, Json(filtered)) = requests_list(
            AuthExtractor(requester.clone()),
            Query(RequestListParams {
                site: Some("DEFRA".into()),
                environment: Some("production".into()),
                created_by: Some(alice.clone()),
                limit: Some(100),
                include_total: Some(true),
                ..Default::default()
            }),
        )
        .await
        .expect("a foreign created_by filter remains owner-constrained");
        assert_eq!(
            filtered_headers
                .get("x-total-count")
                .and_then(|value| value.to_str().ok()),
            Some("1")
        );
        let filtered_ids: std::collections::HashSet<&str> = filtered
            .as_array()
            .expect("filtered list response is an array")
            .iter()
            .filter_map(|item| item["request_id"].as_str())
            .collect();
        assert!(filtered_ids.contains(legacy_id.to_string().as_str()));
        assert!(
            !filtered_ids.contains(foreign_id.to_string().as_str()),
            "caller filters must not replace the mandatory owner predicate"
        );

        assert!(
            requests_get_for_test(AuthExtractor(requester.clone()), Path(own_id.to_string()))
                .await
                .is_ok(),
            "the current requester may read its own request"
        );
        assert!(
            requests_get_for_test(
                AuthExtractor(requester.clone()),
                Path(legacy_id.to_string())
            )
            .await
            .is_ok(),
            "created_by remains the fallback for a legacy row"
        );
        let foreign = requests_get_for_test(AuthExtractor(requester), Path(foreign_id.to_string()))
            .await
            .expect_err("a foreign request must be hidden from a request-only principal");
        assert_eq!(foreign.0, StatusCode::NOT_FOUND);

        let auditor = request_read_session(
            &format!("owner-auditor-{suffix}"),
            ryuki_engine::auth::APP_ROLE_AUDITOR,
        );
        assert!(
            requests_get_for_test(AuthExtractor(auditor), Path(foreign_id.to_string()))
                .await
                .is_ok(),
            "an auditor retains cross-owner detail visibility"
        );

        for id in [own_id, legacy_id, foreign_id] {
            cleanup_request(pool, id).await;
        }
    }

    /// C016/C017: both policy readiness and execution-job metadata inherit the
    /// parent request's owner boundary. The seed intentionally has only the
    /// legacy created_by identity, proving that fallback as well as the current
    /// requester field. The same-scope foreign Requester receives 404; owner and
    /// Auditor controls remain readable.
    #[tokio::test]
    async fn request_child_reads_are_limited_to_parent_owner_or_auditor() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let id = seed_request(pool, "executing", "execute").await;
        let spec = ryuki_protocol::JobSpec {
            request_id: id,
            request_resource_version: ryuki_protocol::RequestResourceVersion::new(1)
                .expect("positive request resource version"),
            offering_id: Uuid::new_v4(),
            iac_ref: "linux-server-deployment@v1".into(),
            iac_digest: "0".repeat(64),
            vars: std::collections::BTreeMap::new(),
            state_key: Some(request_state_key(id)),
            mode: ryuki_protocol::JobMode::OfflineDryRun,
        };
        let job_id: Uuid = sqlx::query_scalar(
            "INSERT INTO agent_jobs (request_id, platform, spec, mode, status) \
             VALUES ($1, 'DEFRA', $2, 'OfflineDryRun', 'Pending') RETURNING id",
        )
        .bind(id)
        .bind(serde_json::to_value(spec).expect("serialize job spec"))
        .fetch_one(pool)
        .await
        .expect("seed execution job");

        let owner = request_read_session("requester-db", ryuki_engine::auth::APP_ROLE_REQUESTER);
        let foreign = request_read_session(
            "foreign-requester-db",
            ryuki_engine::auth::APP_ROLE_REQUESTER,
        );
        let auditor = request_read_session("auditor-db", ryuki_engine::auth::APP_ROLE_AUDITOR);
        let path = || Path(id.to_string());

        assert!(
            requests_policy_eval(AuthExtractor(owner.clone()), path())
                .await
                .is_ok(),
            "the parent owner may read policy readiness"
        );
        let policy_foreign = requests_policy_eval(AuthExtractor(foreign.clone()), path())
            .await
            .expect_err("a foreign requester must not read policy readiness");
        assert_eq!(policy_foreign.0, StatusCode::NOT_FOUND);
        assert!(
            requests_policy_eval(AuthExtractor(auditor.clone()), path())
                .await
                .is_ok(),
            "an auditor retains policy readiness access"
        );

        assert!(
            requests_execution_job(AuthExtractor(owner), path())
                .await
                .is_ok(),
            "the parent owner may read execution-job metadata"
        );
        let job_foreign = requests_execution_job(AuthExtractor(foreign), path())
            .await
            .expect_err("a foreign requester must not read execution-job metadata");
        assert_eq!(job_foreign.0, StatusCode::NOT_FOUND);
        assert!(
            requests_execution_job(AuthExtractor(auditor), path())
                .await
                .is_ok(),
            "an auditor retains execution-job access"
        );

        sqlx::query("DELETE FROM agent_jobs WHERE id = $1")
            .bind(job_id)
            .execute(pool)
            .await
            .ok();
        cleanup_request(pool, id).await;
    }

    /// #2 RBAC (certificates, site-only): a by-id cert read is 404 for an
    /// out-of-scope principal and succeeds for one scoped to the cert's own site.
    #[tokio::test]
    async fn certificates_by_id_is_site_scoped() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let (id, site): (String, String) =
            sqlx::query_as("SELECT id::text, site FROM certificates LIMIT 1")
                .fetch_one(pool)
                .await
                .expect("a seeded certificate");
        let other = if site == "GBLON" { "DEFRA" } else { "GBLON" };

        let mut out = AuthSession::static_dry_run();
        out.site_scope = vec![other.to_string()];
        let denied = certificates_get(AuthExtractor(out), Path(id.clone())).await;
        assert!(
            matches!(denied, Err((StatusCode::NOT_FOUND, _))),
            "out-of-scope cert get must 404: {denied:?}"
        );

        let mut ins = AuthSession::static_dry_run();
        ins.site_scope = vec![site.clone()];
        let ok = certificates_get(AuthExtractor(ins), Path(id.clone())).await;
        assert!(ok.is_ok(), "in-scope cert get must succeed: {ok:?}");
    }

    /// #8 cert inventory: seed a cert with the given common_name/status/hostname at
    /// the given site and return its id. valid_from/valid_to are well-formed UTC.
    async fn seed_cert(
        pool: &PgPool,
        common_name: &str,
        status: &str,
        hostname: &str,
        site: &str,
    ) -> String {
        sqlx::query_scalar(
            "INSERT INTO certificates \
             (common_name, subject, valid_from, valid_to, service_type, hostname, site, status) \
             VALUES ($1, $2, NOW() - INTERVAL '10 days', NOW() + INTERVAL '90 days', \
                     'Custom', $3, $4, $5) RETURNING id::text",
        )
        .bind(common_name)
        .bind(format!("CN={common_name}"))
        .bind(hostname)
        .bind(site)
        .bind(status)
        .fetch_one(pool)
        .await
        .expect("seed certificate")
    }

    async fn cleanup_cert(pool: &PgPool, id: &str) {
        sqlx::query("DELETE FROM certificates WHERE id = $1::uuid")
            .bind(id)
            .execute(pool)
            .await
            .ok();
    }

    /// Migration 185 makes the durable registry row the certificate site's
    /// authority. Tests using generated site codes must therefore seed that
    /// authority in PostgreSQL rather than only in the process-local cache.
    async fn seed_active_certificate_site(pool: &PgPool, site: &str) {
        sqlx::query(
            "INSERT INTO site_registry \
             (unlocode, code_system, name, country, country_code, timezone, active) \
             VALUES ($1, 'custom', $2, 'Test country', 'ZZ', 'UTC', true)",
        )
        .bind(site)
        .bind(format!("Certificate test site {site}"))
        .execute(pool)
        .await
        .expect("seed active canonical certificate site");
    }

    async fn cleanup_certificate_site(pool: &PgPool, site: &str) {
        sqlx::query("DELETE FROM site_registry WHERE unlocode = $1")
            .bind(site)
            .execute(pool)
            .await
            .expect("clean active canonical certificate site");
    }

    /// C279: inventory is a fixed newest-first keyset.  Equal timestamps use
    /// UUID as the deterministic tie-break, and legacy scan-amplifying query
    /// options fail explicitly instead of silently falling back to a full scan.
    #[tokio::test]
    async fn cert_inventory_keyset_and_legacy_options() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let suffix = Uuid::new_v4();
        let prefix = format!("clp-{suffix}");
        let site = format!("CERT{}", &suffix.simple().to_string()[..8]);
        seed_active_certificate_site(pool, &site).await;
        let id_a = seed_cert(
            pool,
            &format!("{prefix}-alpha"),
            "Active",
            "host-a.test",
            &site,
        )
        .await;
        let id_b = seed_cert(
            pool,
            &format!("{prefix}-bravo"),
            "Expiring",
            "host-b.test",
            &site,
        )
        .await;
        let id_c = seed_cert(
            pool,
            &format!("{prefix}-charlie"),
            "Active",
            "other.test",
            &site,
        )
        .await;
        sqlx::query(
            "UPDATE certificates SET created_at = '2026-01-01T00:00:00Z' \
             WHERE id = ANY($1::uuid[])",
        )
        .bind(vec![
            Uuid::parse_str(&id_a).unwrap(),
            Uuid::parse_str(&id_b).unwrap(),
            Uuid::parse_str(&id_c).unwrap(),
        ])
        .execute(pool)
        .await
        .expect("tie certificate creation timestamps");

        let mut session = AuthSession::static_dry_run();
        session.site_scope = vec![site.clone()];
        let list = |params: CertListParams| {
            let s = session.clone();
            async move { certificates_inventory(AuthExtractor(s), Query(params)).await }
        };
        let (first_headers, Json(first)) = list(CertListParams {
            limit: Some(2),
            ..Default::default()
        })
        .await
        .unwrap();
        assert_eq!(first.as_array().unwrap().len(), 2);
        assert!(first_headers.get("x-total-count").is_none());
        let cursor = first_headers
            .get("x-next-cursor")
            .unwrap()
            .to_str()
            .unwrap()
            .to_string();
        let (_, Json(second)) = list(CertListParams {
            limit: Some(2),
            cursor: Some(cursor),
            ..Default::default()
        })
        .await
        .unwrap();
        assert_eq!(second.as_array().unwrap().len(), 1);
        let ids: std::collections::HashSet<&str> = first
            .as_array()
            .unwrap()
            .iter()
            .chain(second.as_array().unwrap())
            .filter_map(|row| row["id"].as_str())
            .collect();
        assert_eq!(ids.len(), 3);

        for params in [
            CertListParams {
                q: Some(prefix.clone()),
                ..Default::default()
            },
            CertListParams {
                status: Some("active".into()),
                ..Default::default()
            },
            CertListParams {
                sort: Some("common_name".into()),
                ..Default::default()
            },
            CertListParams {
                direction: Some("asc".into()),
                ..Default::default()
            },
            CertListParams {
                offset: Some(1),
                ..Default::default()
            },
            CertListParams {
                include_total: Some(true),
                ..Default::default()
            },
        ] {
            assert!(matches!(
                list(params).await,
                Err((StatusCode::BAD_REQUEST, _))
            ));
        }

        for id in [&id_a, &id_b, &id_c] {
            cleanup_cert(pool, id).await;
        }
        cleanup_certificate_site(pool, &site).await;
    }

    /// C279: the scoped repository performs a bounded per-site top-N merge.
    /// Walking the signed cursor across two sparse authorized sites must match
    /// the database's single global `(created_at,id)` order exactly.
    #[tokio::test]
    async fn cert_inventory_multi_site_merge_preserves_global_keyset_order() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let tag = Uuid::new_v4().simple().to_string();
        let site_a = format!("CMA{}", tag[..8].to_ascii_uppercase());
        let site_b = format!("CMB{}", tag[..8].to_ascii_uppercase());
        seed_active_certificate_site(pool, &site_a).await;
        seed_active_certificate_site(pool, &site_b).await;
        let mut ids = Vec::new();
        for (index, site) in [&site_a, &site_b, &site_a, &site_b, &site_a, &site_b]
            .into_iter()
            .enumerate()
        {
            let id = seed_cert(
                pool,
                &format!("cert-merge-{tag}-{index}"),
                "Active",
                &format!("merge-{index}.test"),
                site,
            )
            .await;
            sqlx::query(
                "UPDATE certificates \
                 SET created_at = '2026-07-15T12:00:00Z'::timestamptz \
                                  - $2 * INTERVAL '1 second' \
                 WHERE id = $1::uuid",
            )
            .bind(&id)
            .bind(index as i64)
            .execute(pool)
            .await
            .expect("interleave certificate creation order");
            ids.push(id);
        }

        let expected: Vec<String> = sqlx::query_scalar(
            "SELECT id::text FROM certificates WHERE site = ANY($1::text[]) \
             ORDER BY created_at DESC, id DESC",
        )
        .bind(vec![site_a.clone(), site_b.clone()])
        .fetch_all(pool)
        .await
        .expect("read expected multi-site certificate order");
        assert_eq!(expected.len(), 6);

        let mut session = AuthSession::static_dry_run();
        session.site_scope = vec![site_b.clone(), site_a.clone()];
        let mut cursor = None;
        let mut actual = Vec::new();
        loop {
            let (headers, Json(page)) = certificates_inventory(
                AuthExtractor(session.clone()),
                Query(CertListParams {
                    limit: Some(2),
                    cursor,
                    ..Default::default()
                }),
            )
            .await
            .expect("walk bounded multi-site certificate page");
            actual.extend(
                page.as_array()
                    .expect("certificate page array")
                    .iter()
                    .filter_map(|row| row["id"].as_str().map(str::to_string)),
            );
            cursor = headers
                .get("x-next-cursor")
                .and_then(|value| value.to_str().ok())
                .map(str::to_string);
            if cursor.is_none() {
                break;
            }
            assert!(
                actual.len() <= 6,
                "cursor traversal must make bounded progress"
            );
        }
        assert_eq!(actual, expected);

        for id in &ids {
            cleanup_cert(pool, id).await;
        }
        cleanup_certificate_site(pool, &site_a).await;
        cleanup_certificate_site(pool, &site_b).await;
    }

    /// C278/C279: omission/exaggeration of a limit is capped, inventory and
    /// expiry both walk authenticated keysets, and neither emits an exact count.
    #[tokio::test]
    async fn certificate_queries_filter_before_hard_bounded_pages() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let tag = Uuid::new_v4().simple().to_string();
        let bulk_prefix = format!("cert-bound-{tag}-");
        let inventory_site = format!("CI{}", tag[..10].to_ascii_uppercase());
        seed_active_certificate_site(pool, &inventory_site).await;
        sqlx::query(
            "INSERT INTO certificates \
             (common_name, subject, valid_from, valid_to, service_type, hostname, site, status) \
             SELECT $1 || n::text, 'CN=' || $1 || n::text, NOW() - INTERVAL '1 day', \
                    NOW() + INTERVAL '30 days', 'Custom', 'bounded-' || n::text, \
                    $2, 'Active' \
             FROM generate_series(1, $3::bigint) AS n",
        )
        .bind(&bulk_prefix)
        .bind(&inventory_site)
        .bind((MAX_CERTIFICATE_PAGE_ROWS + 5) as i64)
        .execute(pool)
        .await
        .expect("seed bounded inventory");

        let mut inventory_session = AuthSession::static_dry_run();
        inventory_session.site_scope = vec![inventory_site.clone()];
        let (first_headers, Json(first_page)) = certificates_inventory(
            AuthExtractor(inventory_session.clone()),
            Query(CertListParams {
                limit: Some(usize::MAX),
                ..Default::default()
            }),
        )
        .await
        .expect("first bounded inventory page");
        assert_eq!(
            first_page.as_array().expect("array").len(),
            MAX_CERTIFICATE_PAGE_ROWS
        );
        assert!(first_headers.get("x-total-count").is_none());
        let inventory_cursor = first_headers
            .get("x-next-cursor")
            .and_then(|value| value.to_str().ok())
            .expect("bounded inventory page emits a continuation")
            .to_string();

        let (_, Json(second_page)) = certificates_inventory(
            AuthExtractor(inventory_session),
            Query(CertListParams {
                limit: Some(usize::MAX),
                cursor: Some(inventory_cursor),
                ..Default::default()
            }),
        )
        .await
        .expect("second bounded inventory page");
        assert_eq!(second_page.as_array().expect("array").len(), 5);

        let expiry_site = format!("CQP{}", tag[..8].to_ascii_uppercase());
        seed_active_certificate_site(pool, &expiry_site).await;
        let expiry_prefix = format!("cert-expiry-{tag}-");
        sqlx::query(
            "INSERT INTO certificates \
             (common_name, subject, valid_from, valid_to, service_type, hostname, site, status) \
             SELECT $1 || n::text, 'expiry', NOW() - INTERVAL '1 day', \
                    NOW() + (n % 30) * INTERVAL '1 day', 'Custom', \
                    'expiry-' || n::text, $2, 'Active' \
             FROM generate_series(1, $3::bigint) AS n",
        )
        .bind(&expiry_prefix)
        .bind(&expiry_site)
        .bind((2 * DEFAULT_CERTIFICATE_EXPIRY_PAGE_ROWS + 1) as i64)
        .execute(pool)
        .await
        .expect("seed expiry inventory");
        let foreign_expiry_site = format!("CQF{}", tag[..8].to_ascii_uppercase());
        seed_active_certificate_site(pool, &foreign_expiry_site).await;
        sqlx::query(
            "INSERT INTO certificates \
             (common_name, subject, valid_from, valid_to, service_type, hostname, site, status) \
             SELECT $1 || 'foreign-' || n::text, 'expiry', NOW() - INTERVAL '1 day', \
                    NOW() + (n % 30) * INTERVAL '1 day', 'Custom', \
                    'foreign-expiry-' || n::text, $2, 'Active' \
             FROM generate_series(1, 150) AS n \
             UNION ALL \
             SELECT $1 || 'outside-' || n::text, 'expiry', NOW() - INTERVAL '1 day', \
                    NOW() + INTERVAL '200 days', 'Custom', \
                    'outside-expiry-' || n::text, $3, 'Active' \
             FROM generate_series(1, 25) AS n",
        )
        .bind(&expiry_prefix)
        .bind(&foreign_expiry_site)
        .bind(&expiry_site)
        .execute(pool)
        .await
        .expect("seed foreign and out-of-window expiry population");

        let mut expiry_cursor = None;
        let mut expiry_page_sizes = Vec::new();
        let mut expiry_ids = std::collections::HashSet::new();
        loop {
            let (headers, Json(page)) = certificates_expiring(
                AuthExtractor(AuthSession::static_dry_run()),
                Query(CertificateExpiringQuery {
                    site: Some(expiry_site.clone()),
                    days: Some(90),
                    limit: None,
                    cursor: expiry_cursor,
                    offset: None,
                }),
            )
            .await
            .expect("walk bounded expiry keyset page");
            assert!(headers.get("x-total-count").is_none());
            let rows = page.as_array().expect("expiry array");
            expiry_page_sizes.push(rows.len());
            for id in rows
                .iter()
                .filter_map(|certificate| certificate["id"].as_str())
            {
                assert!(
                    expiry_ids.insert(id.to_string()),
                    "unchanged expiry traversal must not repeat a certificate"
                );
            }
            expiry_cursor = headers
                .get("x-next-cursor")
                .and_then(|value| value.to_str().ok())
                .map(str::to_string);
            if expiry_cursor.is_none() {
                break;
            }
            assert!(
                expiry_page_sizes.len() <= 3,
                "expiry cursor must make progress"
            );
        }
        assert_eq!(
            expiry_page_sizes,
            vec![
                DEFAULT_CERTIFICATE_EXPIRY_PAGE_ROWS,
                DEFAULT_CERTIFICATE_EXPIRY_PAGE_ROWS,
                1,
            ]
        );
        assert_eq!(
            expiry_ids.len(),
            2 * DEFAULT_CERTIFICATE_EXPIRY_PAGE_ROWS + 1
        );

        let indexes: Vec<String> = sqlx::query_scalar(
            "SELECT indexname FROM pg_indexes \
             WHERE schemaname = current_schema() AND tablename = 'certificates'",
        )
        .fetch_all(pool)
        .await
        .expect("read certificate indexes");
        for required in [
            "idx_certificates_inventory_page",
            "idx_certificates_site_inventory_page",
            "idx_certificates_expiry_page",
            "idx_certificates_site_expiry_page",
        ] {
            assert!(
                indexes.iter().any(|index| index == required),
                "missing {required}"
            );
        }

        sqlx::query("ANALYZE certificates")
            .execute(pool)
            .await
            .expect("analyze certificate query fixtures");
        let mut plan_tx = pool
            .begin()
            .await
            .expect("begin certificate plan transaction");
        sqlx::query("SET LOCAL enable_seqscan = off")
            .execute(&mut *plan_tx)
            .await
            .expect("disable certificate sequential scans");
        sqlx::query("SET LOCAL enable_bitmapscan = off")
            .execute(&mut *plan_tx)
            .await
            .expect("disable certificate bitmap scans");
        let scoped_inventory_plan: Value = sqlx::query_scalar(
            "EXPLAIN (FORMAT JSON) \
             SELECT id, common_name, created_at FROM certificates \
             WHERE octet_length(site) BETWEEN 1 AND 32 AND site = $1 \
             ORDER BY created_at DESC, id DESC LIMIT 101",
        )
        .bind(&inventory_site)
        .fetch_one(&mut *plan_tx)
        .await
        .expect("explain scoped certificate inventory");
        assert!(
            scoped_inventory_plan
                .to_string()
                .contains("idx_certificates_site_inventory_page"),
            "scoped inventory must use its ordered keyset index: {scoped_inventory_plan}"
        );
        let global_inventory_plan: Value = sqlx::query_scalar(
            "EXPLAIN (FORMAT JSON) \
             SELECT id, common_name, created_at FROM certificates \
             WHERE octet_length(site) BETWEEN 1 AND 32 \
             ORDER BY created_at DESC, id DESC LIMIT 101",
        )
        .fetch_one(&mut *plan_tx)
        .await
        .expect("explain global certificate inventory");
        assert!(
            global_inventory_plan
                .to_string()
                .contains("idx_certificates_inventory_page"),
            "global inventory must use its ordered keyset index: {global_inventory_plan}"
        );
        let scoped_expiry_plan: Value = sqlx::query_scalar(
            "EXPLAIN (FORMAT JSON) \
             SELECT id, common_name, valid_to FROM certificates \
             WHERE octet_length(site) BETWEEN 1 AND 32 \
               AND site = $1 AND valid_to <= $2 \
             ORDER BY valid_to ASC, id ASC LIMIT 201",
        )
        .bind(&expiry_site)
        .bind(chrono::Utc::now() + chrono::Duration::days(90))
        .fetch_one(&mut *plan_tx)
        .await
        .expect("explain scoped certificate expiry");
        assert!(
            scoped_expiry_plan
                .to_string()
                .contains("idx_certificates_site_expiry_page"),
            "scoped expiry must use its ordered keyset index: {scoped_expiry_plan}"
        );
        // On the deliberately small fixture, PostgreSQL may validly prefer a
        // differently ordered covering index plus an in-memory sort. Isolate
        // the global-expiry index in a savepoint so this probe verifies that
        // its predicate and key order satisfy the query, independent of cost
        // estimates; rolling back restores every competing index.
        sqlx::query("SAVEPOINT certificate_global_expiry_plan")
            .execute(&mut *plan_tx)
            .await
            .expect("savepoint global certificate expiry plan");
        sqlx::query(
            "DROP INDEX idx_certificates_inventory_page, \
             idx_certificates_site_inventory_page, idx_certificates_site_expiry_page",
        )
        .execute(&mut *plan_tx)
        .await
        .expect("isolate global certificate expiry index");
        let global_expiry_plan: Value = sqlx::query_scalar(
            "EXPLAIN (FORMAT JSON) \
             SELECT id, common_name, valid_to FROM certificates \
             WHERE octet_length(site) BETWEEN 1 AND 32 AND valid_to <= $1 \
             ORDER BY valid_to ASC, id ASC LIMIT 201",
        )
        .bind(chrono::Utc::now() + chrono::Duration::days(90))
        .fetch_one(&mut *plan_tx)
        .await
        .expect("explain unrestricted certificate expiry");
        assert!(
            global_expiry_plan
                .to_string()
                .contains("idx_certificates_expiry_page"),
            "unrestricted expiry must use its ordered keyset index: {global_expiry_plan}"
        );
        sqlx::query("ROLLBACK TO SAVEPOINT certificate_global_expiry_plan")
            .execute(&mut *plan_tx)
            .await
            .expect("restore certificate plan indexes");
        let scoped_merge_plan: Value = sqlx::query_scalar(
            "EXPLAIN (FORMAT JSON) \
             WITH site_candidates AS ( \
                 SELECT candidate.id, candidate.created_at \
                 FROM (SELECT DISTINCT site FROM unnest($1::text[]) AS scoped(site)) authorized \
                 CROSS JOIN LATERAL ( \
                     SELECT candidate.id, candidate.created_at \
                     FROM certificates candidate \
                     WHERE octet_length(candidate.site) BETWEEN 1 AND 32 \
                       AND candidate.site = authorized.site \
                       AND (candidate.created_at, candidate.id) < ($2, $3) \
                     ORDER BY candidate.created_at DESC, candidate.id DESC LIMIT 101 \
                 ) candidate \
             ) \
             SELECT id FROM site_candidates \
             ORDER BY created_at DESC, id DESC LIMIT 101",
        )
        .bind(vec![inventory_site.clone(), expiry_site.clone()])
        .bind(chrono::Utc::now() + chrono::Duration::days(1))
        .bind(
            Uuid::parse_str("ffffffff-ffff-ffff-ffff-ffffffffffff").expect("maximum UUID fixture"),
        )
        .fetch_one(&mut *plan_tx)
        .await
        .expect("explain scoped per-site certificate merge");
        assert!(
            scoped_merge_plan
                .to_string()
                .contains("idx_certificates_site_inventory_page"),
            "each scoped merge probe must use the partial site keyset index: {scoped_merge_plan}"
        );

        let site_constraint: (bool, String) = sqlx::query_as(
            "SELECT convalidated, pg_get_constraintdef(pg_constraint.oid) \
             FROM pg_constraint \
             WHERE conrelid = 'certificates'::regclass \
               AND conname = 'certificates_site_query_bounds' \
               AND contype = 'c'",
        )
        .fetch_one(&mut *plan_tx)
        .await
        .expect("read certificate site query-bound constraint");
        assert!(
            site_constraint.0,
            "migration 185 validates the bounds after quarantining legacy rows"
        );
        assert!(
            site_constraint.1.contains("octet_length(site) >= 1")
                && site_constraint.1.contains("octet_length(site) <= 32"),
            "certificate site constraint must retain the reviewed octet envelope: {}",
            site_constraint.1
        );
        plan_tx
            .rollback()
            .await
            .expect("rollback certificate plan transaction");

        sqlx::query("DELETE FROM certificates WHERE common_name LIKE $1 || '%'")
            .bind(&bulk_prefix)
            .execute(pool)
            .await
            .expect("clean bounded inventory");
        sqlx::query("DELETE FROM certificates WHERE common_name LIKE $1 || '%'")
            .bind(&expiry_prefix)
            .execute(pool)
            .await
            .expect("clean expiry inventory");
        cleanup_certificate_site(pool, &inventory_site).await;
        cleanup_certificate_site(pool, &expiry_site).await;
        cleanup_certificate_site(pool, &foreign_expiry_site).await;
    }

    /// C278/C279: migration 172 must be deployable over a schema-valid legacy
    /// site wider than a btree tuple. The row remains untouched for explicit
    /// reconciliation, but every partial index and list predicate quarantines
    /// it; the NOT VALID check rejects all new out-of-bounds direct writes.
    /// Migration 185 later validates that check and adds canonical-site
    /// authority; this simulation removes those later controls only inside a
    /// rolled-back transaction and verifies they remain installed afterwards.
    #[tokio::test]
    async fn certificate_site_bound_rollout_quarantines_oversized_legacy_rows() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(test_db) = test_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let pool = &test_db;
        let direct_error = sqlx::query(
            "INSERT INTO certificates \
             (common_name, subject, valid_from, valid_to, service_type, hostname, site, status) \
             VALUES ('direct-site-bound', 'CN=direct-site-bound', NOW(), \
                     NOW() + INTERVAL '1 day', 'Custom', 'direct.test', $1, 'Active')",
        )
        .bind("é".repeat(17))
        .execute(pool)
        .await
        .expect_err("a 34-octet direct-write site must be rejected");
        let direct_database_error = direct_error
            .as_database_error()
            .expect("site-bound rejection is a PostgreSQL error");
        assert_eq!(direct_database_error.code().as_deref(), Some("23514"));
        assert!(
            direct_database_error
                .message()
                .contains("certificate site must reference an active canonical site"),
            "migration 185 active-site trigger must reject the direct write: {direct_database_error}"
        );

        let index_names = vec![
            "idx_certificates_inventory_page".to_string(),
            "idx_certificates_site_inventory_page".to_string(),
            "idx_certificates_expiry_page".to_string(),
            "idx_certificates_site_expiry_page".to_string(),
        ];
        let indexes_before: Vec<(String, String)> = sqlx::query_as(
            "SELECT indexname, indexdef FROM pg_indexes \
             WHERE schemaname = current_schema() \
               AND indexname = ANY($1::text[]) ORDER BY indexname",
        )
        .bind(&index_names)
        .fetch_all(pool)
        .await
        .expect("snapshot migration 172 indexes");
        assert_eq!(indexes_before.len(), 4);
        let constraint_before: (bool, String) = sqlx::query_as(
            "SELECT convalidated, pg_get_constraintdef(pg_constraint.oid) \
             FROM pg_constraint \
             WHERE conrelid = 'certificates'::regclass \
               AND conname = 'certificates_site_query_bounds' AND contype = 'c'",
        )
        .fetch_one(pool)
        .await
        .expect("snapshot migration 185-validated bounds constraint");
        assert!(constraint_before.0);
        let site_fk_before: bool = sqlx::query_scalar(
            "SELECT convalidated FROM pg_constraint \
             WHERE conrelid = 'certificates'::regclass \
               AND conname = 'certificates_site_registry_fk' AND contype = 'f'",
        )
        .fetch_one(pool)
        .await
        .expect("snapshot migration 185 certificate site foreign key");
        assert!(site_fk_before);
        let active_site_trigger_before: bool = sqlx::query_scalar(
            "SELECT EXISTS ( \
                 SELECT 1 FROM pg_trigger \
                 WHERE tgrelid = 'certificates'::regclass \
                   AND tgname = 'trg_certificates_active_site' \
                   AND NOT tgisinternal \
             )",
        )
        .fetch_one(pool)
        .await
        .expect("snapshot migration 185 active-site trigger");
        assert!(active_site_trigger_before);

        let legacy_id = Uuid::new_v4();
        let mut tx = pool
            .begin()
            .await
            .expect("begin certificate site-bound rollout test");
        sqlx::raw_sql(
            "DROP TRIGGER trg_certificates_active_site ON certificates;
             ALTER TABLE certificates DROP CONSTRAINT certificates_site_registry_fk;
             DROP INDEX idx_certificates_inventory_page;
             DROP INDEX idx_certificates_site_inventory_page;
             DROP INDEX idx_certificates_expiry_page;
             DROP INDEX idx_certificates_site_expiry_page;
             ALTER TABLE certificates DROP CONSTRAINT certificates_site_query_bounds;",
        )
        .execute(&mut *tx)
        .await
        .expect("restore reviewed pre-migration certificate schema");
        sqlx::query(
            "INSERT INTO certificates \
             (id, common_name, subject, valid_from, valid_to, service_type, hostname, site, status) \
             VALUES ($1, 'legacy-oversized-site', 'CN=legacy-oversized-site', NOW(), \
                     NOW() + INTERVAL '1 day', 'Custom', 'legacy.test', $2, 'Active')",
        )
        .bind(legacy_id)
        .bind("x".repeat(3_000))
        .execute(&mut *tx)
        .await
        .expect("seed schema-valid oversized legacy certificate");

        sqlx::raw_sql(include_str!(
            "../../../migrations/172_certificate_query_bounds.sql"
        ))
        .execute(&mut *tx)
        .await
        .expect("partial certificate indexes must tolerate oversized legacy sites");
        let rolled_indexes: Vec<(String, String)> = sqlx::query_as(
            "SELECT indexname, indexdef FROM pg_indexes \
             WHERE schemaname = current_schema() \
               AND indexname = ANY($1::text[]) ORDER BY indexname",
        )
        .bind(&index_names)
        .fetch_all(&mut *tx)
        .await
        .expect("read legacy-safe certificate indexes");
        assert_eq!(rolled_indexes.len(), 4);
        assert!(
            rolled_indexes
                .iter()
                .all(|(_, definition)| definition.contains("octet_length(site)")),
            "every certificate page index must exclude unreconciled legacy sites"
        );
        let legacy_visible: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM certificates \
             WHERE octet_length(site) BETWEEN 1 AND 32 AND id = $1",
        )
        .bind(legacy_id)
        .fetch_one(&mut *tx)
        .await
        .expect("probe quarantined legacy certificate");
        assert_eq!(legacy_visible, 0);
        let legacy_preserved: i64 =
            sqlx::query_scalar("SELECT COUNT(*) FROM certificates WHERE id = $1")
                .bind(legacy_id)
                .fetch_one(&mut *tx)
                .await
                .expect("verify migration did not rewrite legacy certificate");
        assert_eq!(legacy_preserved, 1);
        let rolled_constraint: (bool, String) = sqlx::query_as(
            "SELECT convalidated, pg_get_constraintdef(pg_constraint.oid) \
             FROM pg_constraint \
             WHERE conrelid = 'certificates'::regclass \
               AND conname = 'certificates_site_query_bounds' AND contype = 'c'",
        )
        .fetch_one(&mut *tx)
        .await
        .expect("read legacy-compatible site constraint");
        assert!(!rolled_constraint.0);
        let rollout_direct_error = sqlx::query(
            "INSERT INTO certificates \
             (common_name, subject, valid_from, valid_to, service_type, hostname, site, status) \
             VALUES ('rollout-direct-site-bound', 'CN=rollout-direct-site-bound', NOW(), \
                     NOW() + INTERVAL '1 day', 'Custom', 'rollout-direct.test', $1, 'Active')",
        )
        .bind("é".repeat(17))
        .execute(&mut *tx)
        .await
        .expect_err("migration 172 must reject new 34-octet direct-write sites");
        let rollout_direct_database_error = rollout_direct_error
            .as_database_error()
            .expect("migration 172 bounds rejection is a PostgreSQL error");
        assert_eq!(
            rollout_direct_database_error.code().as_deref(),
            Some("23514")
        );
        assert_eq!(
            rollout_direct_database_error.constraint(),
            Some("certificates_site_query_bounds")
        );
        tx.rollback()
            .await
            .expect("rollback certificate rollout simulation");

        let indexes_after: Vec<(String, String)> = sqlx::query_as(
            "SELECT indexname, indexdef FROM pg_indexes \
             WHERE schemaname = current_schema() \
               AND indexname = ANY($1::text[]) ORDER BY indexname",
        )
        .bind(&index_names)
        .fetch_all(pool)
        .await
        .expect("read certificate indexes after rollout rollback");
        let constraint_after: (bool, String) = sqlx::query_as(
            "SELECT convalidated, pg_get_constraintdef(pg_constraint.oid) \
             FROM pg_constraint \
             WHERE conrelid = 'certificates'::regclass \
               AND conname = 'certificates_site_query_bounds' AND contype = 'c'",
        )
        .fetch_one(pool)
        .await
        .expect("read certificate constraint after rollout rollback");
        let site_fk_after: bool = sqlx::query_scalar(
            "SELECT convalidated FROM pg_constraint \
             WHERE conrelid = 'certificates'::regclass \
               AND conname = 'certificates_site_registry_fk' AND contype = 'f'",
        )
        .fetch_one(pool)
        .await
        .expect("read migration 185 certificate site foreign key after rollback");
        let active_site_trigger_after: bool = sqlx::query_scalar(
            "SELECT EXISTS ( \
                 SELECT 1 FROM pg_trigger \
                 WHERE tgrelid = 'certificates'::regclass \
                   AND tgname = 'trg_certificates_active_site' \
                   AND NOT tgisinternal \
             )",
        )
        .fetch_one(pool)
        .await
        .expect("read migration 185 active-site trigger after rollback");
        assert_eq!(indexes_after, indexes_before);
        assert_eq!(constraint_after, constraint_before);
        assert_eq!(site_fk_after, site_fk_before);
        assert_eq!(active_site_trigger_after, active_site_trigger_before);
        let legacy_after: i64 =
            sqlx::query_scalar("SELECT COUNT(*) FROM certificates WHERE id = $1")
                .bind(legacy_id)
                .fetch_one(pool)
                .await
                .expect("verify legacy fixture rollback");
        assert_eq!(legacy_after, 0);
    }

    /// C278: expiry pagination is a bounded, at-least-once traversal rather
    /// than a cross-request MVCC snapshot. If renewal moves an already emitted
    /// `valid_to` beyond the cursor (but inside the fixed threshold), that id can
    /// appear again and callers must deduplicate it.
    #[tokio::test]
    async fn certificate_expiry_documents_mutable_key_at_least_once_semantics() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let tag = Uuid::new_v4().simple().to_string();
        let site = format!("CEM{}", tag[..8].to_ascii_uppercase());
        let prefix = format!("expiry-mutable-{tag}-");
        seed_active_certificate_site(pool, &site).await;
        sqlx::query(
            "INSERT INTO certificates \
             (common_name, subject, valid_from, valid_to, service_type, hostname, site, status) \
             SELECT $1 || n::text, 'mutable', NOW() - INTERVAL '1 day', \
                    NOW() + n * INTERVAL '1 day', 'Custom', \
                    'mutable-' || n::text, $2, 'Active' \
             FROM generate_series(1, 4) AS n",
        )
        .bind(&prefix)
        .bind(&site)
        .execute(pool)
        .await
        .expect("seed mutable expiry traversal");
        let (first_headers, Json(first_page)) = certificates_expiring(
            AuthExtractor(AuthSession::static_dry_run()),
            Query(CertificateExpiringQuery {
                site: Some(site.clone()),
                days: Some(90),
                limit: Some(2),
                cursor: None,
                offset: None,
            }),
        )
        .await
        .expect("read first mutable expiry page");
        let repeated_id = first_page[0]["id"]
            .as_str()
            .expect("first expiry id")
            .to_string();
        let cursor = first_headers
            .get("x-next-cursor")
            .and_then(|value| value.to_str().ok())
            .expect("mutable expiry page cursor")
            .to_string();
        sqlx::query(
            "UPDATE certificates SET valid_to = NOW() + INTERVAL '3 days 12 hours' \
             WHERE id = $1::uuid",
        )
        .bind(&repeated_id)
        .execute(pool)
        .await
        .expect("renew already-emitted certificate inside fixed expiry window");

        let (_, Json(second_page)) = certificates_expiring(
            AuthExtractor(AuthSession::static_dry_run()),
            Query(CertificateExpiringQuery {
                site: Some(site.clone()),
                days: Some(90),
                limit: Some(2),
                cursor: Some(cursor),
                offset: None,
            }),
        )
        .await
        .expect("read post-renewal expiry page");
        assert!(
            second_page
                .as_array()
                .expect("second expiry array")
                .iter()
                .any(|certificate| certificate["id"].as_str() == Some(repeated_id.as_str())),
            "a mutable key can reappear after it moves beyond the prior cursor"
        );

        sqlx::query("DELETE FROM certificates WHERE common_name LIKE $1 || '%'")
            .bind(&prefix)
            .execute(pool)
            .await
            .expect("clean mutable expiry traversal");
        cleanup_certificate_site(pool, &site).await;
    }

