    #[tokio::test]
    async fn certificate_pages_and_expiry_window_are_hard_bounded() {
        assert_eq!(
            crate::repos::certificates::MAX_CERTIFICATE_SITE_QUERY_BYTES,
            32
        );
        assert!(certificate_site_within_query_bounds("S"));
        assert!(certificate_site_within_query_bounds(&"S".repeat(32)));
        assert!(!certificate_site_within_query_bounds(""));
        assert!(!certificate_site_within_query_bounds(&"é".repeat(17)));
        assert_eq!(certificate_page_size(None), DEFAULT_CERTIFICATE_PAGE_ROWS);
        assert_eq!(
            certificate_page_size(Some(usize::MAX)),
            MAX_CERTIFICATE_PAGE_ROWS
        );
        assert_eq!(certificate_page_size(Some(0)), 1);
        assert_eq!(
            certificate_expiry_page_size(None),
            DEFAULT_CERTIFICATE_EXPIRY_PAGE_ROWS
        );
        assert_eq!(certificate_expiry_page_size(Some(0)), 1);
        assert_eq!(
            certificate_expiry_page_size(Some(usize::MAX)),
            MAX_CERTIFICATE_EXPIRY_PAGE_ROWS
        );
        let threshold = chrono::DateTime::parse_from_rfc3339("2026-12-01T00:00:00Z")
            .unwrap()
            .with_timezone(&chrono::Utc);
        let valid_to = "2026-11-01T00:00:00Z";
        let id = Uuid::new_v4().to_string();
        let cursor =
            encode_certificate_expiry_cursor("GBLON", 90, threshold, valid_to, &id).unwrap();
        assert!(cursor.len() <= MAX_CERTIFICATE_CURSOR_BYTES);
        let decoded = decode_certificate_expiry_cursor(&cursor, "GBLON", 90).unwrap();
        assert_eq!(decoded.id.to_string(), id);
        assert!(decode_certificate_expiry_cursor(&cursor, "DEFRA", 90).is_err());
        assert!(decode_certificate_expiry_cursor(&cursor, "GBLON", 30).is_err());
        assert!(decode_certificate_expiry_cursor("not-base64", "GBLON", 90).is_err());
        assert!(decode_certificate_expiry_cursor(
            &"A".repeat(MAX_CERTIFICATE_CURSOR_BYTES + 1),
            "GBLON",
            90,
        )
        .is_err());
        let expiry_bytes =
            base64::Engine::decode(&base64::engine::general_purpose::URL_SAFE_NO_PAD, &cursor)
                .unwrap();
        let mut expiry_envelope: Value = serde_json::from_slice(&expiry_bytes).unwrap();
        expiry_envelope["claims"]["id"] = json!(Uuid::new_v4().to_string());
        let tampered_expiry = base64::Engine::encode(
            &base64::engine::general_purpose::URL_SAFE_NO_PAD,
            serde_json::to_vec(&expiry_envelope).unwrap(),
        );
        assert!(decode_certificate_expiry_cursor(&tampered_expiry, "GBLON", 90).is_err());

        let inventory_scope =
            certificate_inventory_scope(Some(&["DEFRA".to_string(), "GBLON".to_string()]));
        let inventory_cursor =
            encode_certificate_inventory_cursor(&inventory_scope, "2026-07-15T10:00:00Z", &id)
                .unwrap();
        assert!(inventory_cursor.len() <= MAX_CERTIFICATE_CURSOR_BYTES);
        let (created_at, inventory_id) =
            decode_certificate_inventory_cursor(&inventory_cursor, &inventory_scope).unwrap();
        assert_eq!(created_at.to_rfc3339(), "2026-07-15T10:00:00+00:00");
        assert_eq!(inventory_id.to_string(), id);
        let foreign_scope = certificate_inventory_scope(Some(&["NLAMS".to_string()]));
        assert!(decode_certificate_inventory_cursor(&inventory_cursor, &foreign_scope).is_err());
        let inventory_bytes = base64::Engine::decode(
            &base64::engine::general_purpose::URL_SAFE_NO_PAD,
            &inventory_cursor,
        )
        .unwrap();
        let mut inventory_envelope: Value = serde_json::from_slice(&inventory_bytes).unwrap();
        inventory_envelope["claims"]["created_at"] = json!("2026-07-15T10:00:01+00:00");
        let tampered_inventory = base64::Engine::encode(
            &base64::engine::general_purpose::URL_SAFE_NO_PAD,
            serde_json::to_vec(&inventory_envelope).unwrap(),
        );
        assert!(
            decode_certificate_inventory_cursor(&tampered_inventory, &inventory_scope).is_err()
        );

        let dry_run = ryuki_core::config::RyukiConfig::default();
        let dry_run_key = certificate_cursor_hmac_key_for_config(&dry_run)
            .expect("default loopback dry-run mode receives an ephemeral cursor key");
        assert_eq!(dry_run_key.len(), 32);
        assert_eq!(
            dry_run_key,
            certificate_cursor_hmac_key_for_config(&dry_run).unwrap(),
            "the ephemeral cursor key must remain stable for the process lifetime"
        );
        let static_dry_run = ryuki_core::config::RyukiConfig {
            auth_mode: AuthMode::StaticDryRun,
            ..Default::default()
        };
        assert_eq!(
            certificate_cursor_hmac_key_for_config(&static_dry_run).unwrap(),
            dry_run_key,
            "both credential-free dry-run modes share the process-ephemeral key"
        );
        let malformed_dry_run = ryuki_core::config::RyukiConfig {
            security: ryuki_core::config::SecurityConfig {
                certificate_cursor_hmac_key: "short".into(),
                ..Default::default()
            },
            ..Default::default()
        };
        assert!(
            certificate_cursor_hmac_key_for_config(&malformed_dry_run).is_err(),
            "an explicit malformed key must not silently select the development fallback"
        );
        let mut persisted = ryuki_core::config::RyukiConfig {
            auth_mode: AuthMode::Local,
            ..Default::default()
        };
        assert!(certificate_cursor_hmac_key_for_config(&persisted).is_err());
        persisted.session.credential_hmac_key = "s".repeat(32);
        assert!(
            certificate_cursor_hmac_key_for_config(&persisted).is_err(),
            "the session credential key must never substitute for the cursor key"
        );
        persisted.security.certificate_cursor_hmac_key = "s".repeat(32);
        assert!(
            certificate_cursor_hmac_key_for_config(&persisted).is_err(),
            "one key value must not be shared across purposes"
        );
        persisted.security.certificate_cursor_hmac_key = "c".repeat(32);
        assert_eq!(
            certificate_cursor_hmac_key_for_config(&persisted).unwrap(),
            persisted.security.certificate_cursor_hmac_key.as_bytes()
        );

        let mut oidc_dry_run = ryuki_core::config::RyukiConfig::default();
        oidc_dry_run.oidc.enabled = true;
        assert!(
            certificate_cursor_hmac_key_for_config(&oidc_dry_run).is_err(),
            "enabled OIDC must not inherit the credential-free dry-run key"
        );

        let legacy_offset = certificates_expiring(
            AuthExtractor(AuthSession::static_dry_run()),
            Query(CertificateExpiringQuery {
                site: None,
                days: Some(90),
                limit: None,
                cursor: None,
                offset: Some(1),
            }),
        )
        .await;
        assert!(matches!(legacy_offset, Err((StatusCode::BAD_REQUEST, _))));

        let invalid_days = certificates_expiring(
            AuthExtractor(AuthSession::static_dry_run()),
            Query(CertificateExpiringQuery {
                site: None,
                days: Some(i64::MAX),
                limit: None,
                cursor: None,
                offset: None,
            }),
        )
        .await;
        assert!(matches!(invalid_days, Err((StatusCode::BAD_REQUEST, _))));

        let oversized_site = certificates_expiring(
            AuthExtractor(AuthSession::static_dry_run()),
            Query(CertificateExpiringQuery {
                site: Some("é".repeat(17)),
                days: Some(90),
                limit: None,
                cursor: None,
                offset: None,
            }),
        )
        .await;
        assert!(matches!(oversized_site, Err((StatusCode::BAD_REQUEST, _))));

        let mut sixty_five_sites = AuthSession::static_dry_run();
        sixty_five_sites.site_scope = (0..=MAX_CERTIFICATE_SCOPE_SITES)
            .map(|index| format!("CS{index:02}"))
            .collect();
        let scope_overflow = certificates_inventory(
            AuthExtractor(sixty_five_sites),
            Query(CertListParams::default()),
        )
        .await;
        assert!(matches!(
            scope_overflow,
            Err((StatusCode::SERVICE_UNAVAILABLE, _))
        ));

        let mut sixty_four_sites = AuthSession::static_dry_run();
        sixty_four_sites.site_scope = (0..MAX_CERTIFICATE_SCOPE_SITES)
            .map(|index| format!("CS{index:02}"))
            .collect();
        assert!(
            certificates_inventory(
                AuthExtractor(sixty_four_sites),
                Query(CertListParams::default()),
            )
            .await
            .is_ok(),
            "the exact 64-site merge boundary remains admitted"
        );

        let (headers, Json(page)) = certificates_inventory(
            AuthExtractor(AuthSession::static_dry_run()),
            Query(CertListParams::default()),
        )
        .await
        .expect("default certificate inventory page");
        assert!(headers.get("x-total-count").is_none());
        assert!(page
            .as_array()
            .is_some_and(|rows| rows.len() <= DEFAULT_CERTIFICATE_PAGE_ROWS));
    }

    /// #14 (pure): only a TERMINAL certificate (Expired|Revoked) is deletable; a live
    /// Active/Expiring cert is not. Single source of truth for the handler + repo guard.
    #[test]
    fn certificate_status_deletable_only_terminal() {
        use crate::repos::certificates::certificate_status_deletable as deletable;
        use ryuki_engine::certificate_lifecycle::CertificateStatus as S;
        assert!(deletable(&S::Expired));
        assert!(deletable(&S::Revoked));
        assert!(!deletable(&S::Active));
        assert!(!deletable(&S::Expiring));
    }

    /// #14: a terminal (Expired/Revoked) cert DELETEs (cascade-free) + a tombstone audit
    /// row is written; a subsequent GET 404s.
    #[tokio::test]
    async fn certificate_delete_happy_terminal_and_audits() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let suffix = Uuid::new_v4();
        for status in ["Expired", "Revoked"] {
            let id = seed_cert(
                pool,
                &format!("cdel-{status}-{suffix}"),
                status,
                "h.test",
                "GBLON",
            )
            .await;
            let Json(body) = certificates_delete(
                AuthExtractor(AuthSession::static_dry_run()),
                Path(id.clone()),
            )
            .await
            .unwrap_or_else(|e| panic!("delete of a {status} cert must succeed: {e:?}"));
            assert_eq!(body["deleted"], id);
            // Gone.
            let gone: i64 =
                sqlx::query_scalar("SELECT COUNT(*) FROM certificates WHERE id = $1::uuid")
                    .bind(&id)
                    .fetch_one(pool)
                    .await
                    .unwrap();
            assert_eq!(gone, 0, "the {status} cert row is deleted");
            // Audit row exists (the cert id is a fresh UUID, so EXISTS can't false-pass).
            let audited: bool = sqlx::query_scalar(
                "SELECT EXISTS(SELECT 1 FROM audit_log WHERE action = 'certificate-delete' \
                 AND detail->>'certificate_id' = $1)",
            )
            .bind(&id)
            .fetch_one(pool)
            .await
            .unwrap();
            assert!(
                audited,
                "a certificate-delete audit row must exist for {id}"
            );
        }
    }

