    #[tokio::test]
    async fn k8s_provision_audit_failure_rolls_namespace_and_request_back() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };

        let suffix = Uuid::new_v4().simple().to_string();
        let namespace_name = format!("audit-rollback-{}", &suffix[..8]);
        let actor_id = format!("k8s-audit-rollback-{}", &suffix[..8]);
        let mut actor = scoped_session(&["DEFRA"], &["Dev"]);
        bind_test_principal(&mut actor, &actor_id);
        actor.display_name = format!("Kubernetes rollback probe {actor_id}");
        let actor_principal = actor
            .principal_id
            .expect("Kubernetes rollback actor has an opaque principal")
            .to_string();

        let function_name = format!("reject_k8s_audit_{suffix}");
        let trigger_name = format!("reject_k8s_audit_trigger_{suffix}");
        sqlx::query(&format!(
            "CREATE FUNCTION {function_name}() RETURNS trigger LANGUAGE plpgsql AS $$ \
             BEGIN \
               IF NEW.action = 'k8s-namespace-provision' \
                  AND NEW.actor_principal = '{actor_principal}' THEN \
                 RAISE EXCEPTION 'injected namespace audit failure' \
                   USING ERRCODE = '23514'; \
               END IF; \
               RETURN NEW; \
             END $$"
        ))
        .execute(pool)
        .await
        .expect("create namespace audit failure function");
        sqlx::query(&format!(
            "CREATE TRIGGER {trigger_name} BEFORE INSERT ON audit_log \
             FOR EACH ROW EXECUTE FUNCTION {function_name}()"
        ))
        .execute(pool)
        .await
        .expect("create namespace audit failure trigger");

        let result = k8s_namespace_provision(
            AuthExtractor(actor.clone()),
            Json(K8sProvisionRequest {
                name: namespace_name.clone(),
                cluster: "defra-aks-01".into(),
                site: "DEFRA".into(),
                cpu: 1,
                memory: 2,
                storage: 10,
                environment: "Dev".into(),
            }),
        )
        .await;

        sqlx::query(&format!("DROP TRIGGER {trigger_name} ON audit_log"))
            .execute(pool)
            .await
            .expect("drop namespace audit failure trigger");
        sqlx::query(&format!("DROP FUNCTION {function_name}()"))
            .execute(pool)
            .await
            .expect("drop namespace audit failure function");

        assert!(
            matches!(result, Err((StatusCode::INTERNAL_SERVER_ERROR, _))),
            "an audit failure must fail namespace provisioning"
        );
        let namespace_count: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM k8s_namespaces WHERE cluster = $1 AND name = $2",
        )
        .bind("defra-aks-01")
        .bind(&namespace_name)
        .fetch_one(pool)
        .await
        .expect("count rolled-back namespaces");
        let request_count: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM container_requests WHERE cluster = $1 AND namespace_name = $2",
        )
        .bind("defra-aks-01")
        .bind(&namespace_name)
        .fetch_one(pool)
        .await
        .expect("count rolled-back container requests");
        let audit_count: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM audit_log \
             WHERE action = 'k8s-namespace-provision' AND actor_principal = $1",
        )
        .bind(&actor_principal)
        .fetch_one(pool)
        .await
        .expect("count rolled-back namespace audit rows");
        assert_eq!(namespace_count, 0);
        assert_eq!(request_count, 0);
        assert_eq!(audit_count, 0);
    }

