    /// C234/C235: status fan-out must fail before issuing any per-definition
    /// metric queries once the visible definition cardinality exceeds the hard
    /// bound. One set-based INSERT creates the overflow fixture; no metric rows
    /// are needed because the guard must run first.
    #[tokio::test]
    async fn metric_budget_and_slo_status_reject_overflow_before_fanout() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let tag = Uuid::new_v4().simple().to_string();
        let site = format!("STATUS-BOUND-{}", &tag[..8]);
        let budget_prefix = format!("status-bound-budget-{tag}-");
        let slo_prefix = format!("status-bound-slo-{tag}-");
        let overflow = status_definition_query_limit();

        sqlx::query(
            "INSERT INTO metric_budgets \
             (id, metric_key, site, threshold, comparison, enabled) \
             SELECT $1 || n::text, $2 || n::text, $3, 1.0, 'above', TRUE \
             FROM generate_series(1, $4::bigint) AS n",
        )
        .bind(&budget_prefix)
        .bind(format!("metric.{budget_prefix}"))
        .bind(&site)
        .bind(overflow)
        .execute(pool)
        .await
        .expect("seed budget overflow");

        let mut scoped = AuthSession::static_dry_run();
        scoped.site_scope = vec![site.clone()];
        let budget_result = metrics_budget_status(AuthExtractor(scoped.clone())).await;

        sqlx::query("DELETE FROM metric_budgets WHERE id LIKE $1 || '%'")
            .bind(&budget_prefix)
            .execute(pool)
            .await
            .expect("clean budget overflow");

        assert!(
            matches!(budget_result, Err((StatusCode::SERVICE_UNAVAILABLE, _))),
            "an overflow budget set must be rejected before series fan-out: {budget_result:?}"
        );

        sqlx::query(
            "INSERT INTO slo_definitions \
             (id, name, target, window_days, good_metric_key, total_metric_key, \
              site, enabled) \
             SELECT $1 || n::text, $2 || n::text, 0.99, 7, \
                    $3 || n::text, $4 || n::text, $5, TRUE \
             FROM generate_series(1, $6::bigint) AS n",
        )
        .bind(&slo_prefix)
        .bind(format!("SLO {tag} "))
        .bind(format!("metric.good.{tag}."))
        .bind(format!("metric.total.{tag}."))
        .bind(&site)
        .bind(overflow)
        .execute(pool)
        .await
        .expect("seed SLO overflow");

        let slo_result = slo_status(AuthExtractor(scoped)).await;

        sqlx::query("DELETE FROM slo_definitions WHERE id LIKE $1 || '%'")
            .bind(&slo_prefix)
            .execute(pool)
            .await
            .expect("clean SLO overflow");

        assert!(
            matches!(slo_result, Err((StatusCode::SERVICE_UNAVAILABLE, _))),
            "an overflow SLO set must be rejected before aggregate fan-out: {slo_result:?}"
        );
    }

    /// C234: exactly 250 newest samples are complete. A large foreign-scope
    /// population is invisible to the coherent-series probe, while the 251st
    /// same-scope sample flips coverage to partial without entering the
    /// forecast input.
    #[tokio::test]
    async fn budget_status_sample_cap_is_exact_and_scope_coherent() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let tag = Uuid::new_v4().simple().to_string();
        let key = format!("test.budget.bound.{tag}");
        let site = format!("BUD{}", tag[..8].to_ascii_uppercase());
        let foreign_site = format!("BFX{}", tag[..8].to_ascii_uppercase());
        let environment = "test".to_string();
        let prefix = format!("budget-bound-{tag}");
        sqlx::query(
            "INSERT INTO metric_samples \
             (id, metric_key, site, environment, value, observed_at) \
             SELECT $1 || '-target-' || n::text, $2, $3, $4, 1.0, \
                    NOW() - n * INTERVAL '1 second' \
             FROM generate_series(1, $5::bigint) AS n \
             UNION ALL \
             SELECT $1 || '-foreign-' || n::text, $2, $6, $4, 99.0, \
                    NOW() - n * INTERVAL '1 second' \
             FROM generate_series(1, 1000) AS n",
        )
        .bind(&prefix)
        .bind(&key)
        .bind(&site)
        .bind(&environment)
        .bind(BUDGET_STATUS_SAMPLES_PER_SERIES)
        .bind(&foreign_site)
        .execute(pool)
        .await
        .expect("seed exact budget sample cap and foreign population");

        let series = vec![(key.clone(), Some(site.clone()), Some(environment.clone()))];
        let exact = fetch_budget_status_analyses(pool, &series)
            .await
            .expect("evaluate exact budget cap");
        let exact = exact.get(&series[0]).expect("target analysis");
        assert_eq!(exact.samples_used, 250);
        assert!(!exact.truncated);
        assert_eq!(exact.summary.expect("summary").latest, 1.0);

        sqlx::query(
            "INSERT INTO metric_samples \
             (id, metric_key, site, environment, value, observed_at) \
             VALUES ($1, $2, $3, $4, 1.0, NOW() - INTERVAL '251 seconds')",
        )
        .bind(format!("{prefix}-target-lookahead"))
        .bind(&key)
        .bind(&site)
        .bind(&environment)
        .execute(pool)
        .await
        .expect("seed budget lookahead sample");

        let partial = fetch_budget_status_analyses(pool, &series)
            .await
            .expect("evaluate budget lookahead");
        let partial = partial.get(&series[0]).expect("target partial analysis");
        assert_eq!(partial.samples_used, 250);
        assert!(partial.truncated);

        let budget_id = format!("{prefix}-definition");
        sqlx::query(
            "INSERT INTO metric_budgets \
             (id, metric_key, site, environment, threshold, comparison, enabled) \
             VALUES ($1, $2, $3, $4, 10.0, 'above', TRUE)",
        )
        .bind(&budget_id)
        .bind(&key)
        .bind(&site)
        .bind(&environment)
        .execute(pool)
        .await
        .expect("seed partial budget definition");
        let mut scoped = AuthSession::static_dry_run();
        scoped.site_scope = vec![site.clone()];
        scoped.environment_scope = vec![environment.clone()];
        let Json(status) = metrics_budget_status(AuthExtractor(scoped))
            .await
            .expect("render partial budget status");
        let rendered = status["budgets"]
            .as_array()
            .expect("budget status array")
            .iter()
            .find(|budget| budget["id"] == budget_id)
            .expect("partial budget status row");
        assert_eq!(rendered["status"], "partial");
        assert!(rendered.get("evaluation").is_none());
        assert_eq!(rendered["coverage"]["samples_used"], 250);
        assert_eq!(status["overall_status"], "degraded");

        // A prior definitive breach must survive this indeterminate suffix.
        // The background scan may evaluate unrelated definitions too, so
        // assert the target's state/event stream instead of its global count.
        sqlx::query("UPDATE metric_budgets SET breaching = TRUE WHERE id = $1")
            .bind(&budget_id)
            .execute(pool)
            .await
            .expect("seed prior budget breach state");
        let recovered_before: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM domain_events \
             WHERE aggregate_id = $1 AND event_type = 'budget.recovered'",
        )
        .bind(&budget_id)
        .fetch_one(pool)
        .await
        .expect("count budget recoveries before partial scan");
        budget_breach_scan_once(pool)
            .await
            .expect("partial budget background scan");
        let still_breaching: bool =
            sqlx::query_scalar("SELECT breaching FROM metric_budgets WHERE id = $1")
                .bind(&budget_id)
                .fetch_one(pool)
                .await
                .expect("read budget state after partial scan");
        let recovered_after: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM domain_events \
             WHERE aggregate_id = $1 AND event_type = 'budget.recovered'",
        )
        .bind(&budget_id)
        .fetch_one(pool)
        .await
        .expect("count budget recoveries after partial scan");
        assert!(
            still_breaching,
            "partial data preserves the prior breach flag"
        );
        assert_eq!(
            recovered_after, recovered_before,
            "partial data must not claim a budget recovery"
        );

        sqlx::query("DELETE FROM metric_budgets WHERE id = $1")
            .bind(&budget_id)
            .execute(pool)
            .await
            .expect("clean partial budget definition");

        sqlx::query("DELETE FROM metric_samples WHERE metric_key = $1")
            .bind(&key)
            .execute(pool)
            .await
            .expect("clean budget bound samples");
    }

    /// C235: an out-of-window tail cannot consume the bounded sample budget.
    /// Exactly 2,000 in-window rows per counter are complete; the 2,001st
    /// in-window row is detected by lookahead and makes the result partial.
    #[tokio::test]
    async fn slo_status_sample_cap_and_closed_window_tail_are_exact() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let tag = Uuid::new_v4().simple().to_string();
        let good_key = format!("test.slo.bound.good.{tag}");
        let total_key = format!("test.slo.bound.total.{tag}");
        let site = format!("SLO{}", tag[..8].to_ascii_uppercase());
        let environment = "test".to_string();
        let prefix = format!("slo-bound-{tag}");
        let until = chrono::Utc::now();
        sqlx::query(
            "INSERT INTO metric_samples \
             (id, metric_key, site, environment, value, observed_at) \
             SELECT $1 || '-good-' || n::text, $2, $4, $5, 1.0, \
                    $6 - n * INTERVAL '1 second' \
             FROM generate_series(1, $7::bigint) AS n \
             UNION ALL \
             SELECT $1 || '-total-' || n::text, $3, $4, $5, 1.0, \
                    $6 - n * INTERVAL '1 second' \
             FROM generate_series(1, $7::bigint) AS n \
             UNION ALL \
             SELECT $1 || '-old-window-tail', $2, $4, $5, 99999.0, \
                    $6 - INTERVAL '2 days'",
        )
        .bind(&prefix)
        .bind(&good_key)
        .bind(&total_key)
        .bind(&site)
        .bind(&environment)
        .bind(until)
        .bind(SLO_STATUS_SAMPLES_PER_SERIES)
        .execute(pool)
        .await
        .expect("seed exact SLO cap and old-window tail");

        let inputs = vec![SloMetricInput {
            id: format!("slo-bound-definition-{tag}"),
            window_days: 1,
            good_metric_key: good_key.clone(),
            total_metric_key: total_key.clone(),
            site: Some(site.clone()),
            environment: Some(environment.clone()),
        }];
        let exact = sum_slo_metrics_in_batch(pool, &inputs, until)
            .await
            .expect("sum exact SLO cap");
        let exact = exact.get(&inputs[0].id).expect("exact SLO totals");
        assert!(!exact.truncated);
        assert_eq!(exact.good_samples_used, 2_000);
        assert_eq!(exact.total_samples_used, 2_000);
        assert_eq!(exact.good, 2_000.0);
        assert_eq!(exact.total, 2_000.0);

        sqlx::query(
            "INSERT INTO metric_samples \
             (id, metric_key, site, environment, value, observed_at) \
             VALUES ($1, $2, $3, $4, 1.0, $5 - INTERVAL '2001 seconds')",
        )
        .bind(format!("{prefix}-good-lookahead"))
        .bind(&good_key)
        .bind(&site)
        .bind(&environment)
        .bind(until)
        .execute(pool)
        .await
        .expect("seed in-window SLO lookahead");

        let partial = sum_slo_metrics_in_batch(pool, &inputs, until)
            .await
            .expect("sum partial SLO cap");
        let partial = partial.get(&inputs[0].id).expect("partial SLO totals");
        assert!(partial.truncated);
        assert!(partial.good_truncated);
        assert!(!partial.total_truncated);
        assert_eq!(partial.good_samples_used, 2_000);
        assert_eq!(partial.total_samples_used, 2_000);
        assert_eq!(partial.good, 2_000.0);
        assert_eq!(partial.total, 2_000.0);

        sqlx::query(
            "INSERT INTO slo_definitions \
             (id, name, target, window_days, good_metric_key, total_metric_key, \
              site, environment, enabled) \
             VALUES ($1, $2, 0.99, 1, $3, $4, $5, $6, TRUE)",
        )
        .bind(&inputs[0].id)
        .bind(format!("Partial SLO {tag}"))
        .bind(&good_key)
        .bind(&total_key)
        .bind(&site)
        .bind(&environment)
        .execute(pool)
        .await
        .expect("seed partial SLO definition");
        let mut scoped = AuthSession::static_dry_run();
        scoped.site_scope = vec![site.clone()];
        scoped.environment_scope = vec![environment.clone()];
        let Json(status) = slo_status(AuthExtractor(scoped))
            .await
            .expect("render partial SLO status");
        let rendered = status["slos"]
            .as_array()
            .expect("SLO status array")
            .iter()
            .find(|slo| slo["id"] == inputs[0].id)
            .expect("partial SLO status row");
        assert_eq!(rendered["status"], "partial");
        assert!(rendered.get("slo").is_none());
        assert_eq!(rendered["coverage"]["good_samples_used"], 2_000);
        assert_eq!(status["overall_status"], "degraded");

        // Preserve a prior definitive failure while the lookahead proves the
        // aggregate is partial; never emit a false compliant/recovered state.
        sqlx::query("UPDATE slo_definitions SET breaching = TRUE WHERE id = $1")
            .bind(&inputs[0].id)
            .execute(pool)
            .await
            .expect("seed prior SLO breach state");
        let recovered_before: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM domain_events \
             WHERE aggregate_id = $1 AND event_type = 'slo.recovered'",
        )
        .bind(&inputs[0].id)
        .fetch_one(pool)
        .await
        .expect("count SLO recoveries before partial scan");
        slo_breach_scan_once(pool)
            .await
            .expect("partial SLO background scan");
        let still_breaching: bool =
            sqlx::query_scalar("SELECT breaching FROM slo_definitions WHERE id = $1")
                .bind(&inputs[0].id)
                .fetch_one(pool)
                .await
                .expect("read SLO state after partial scan");
        let recovered_after: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM domain_events \
             WHERE aggregate_id = $1 AND event_type = 'slo.recovered'",
        )
        .bind(&inputs[0].id)
        .fetch_one(pool)
        .await
        .expect("count SLO recoveries after partial scan");
        assert!(
            still_breaching,
            "partial data preserves the prior SLO breach flag"
        );
        assert_eq!(
            recovered_after, recovered_before,
            "partial data must not claim an SLO recovery"
        );

        sqlx::query("DELETE FROM slo_definitions WHERE id = $1")
            .bind(&inputs[0].id)
            .execute(pool)
            .await
            .expect("clean partial SLO definition");

        sqlx::query("DELETE FROM metric_samples WHERE metric_key = ANY($1)")
            .bind(vec![good_key, total_key])
            .execute(pool)
            .await
            .expect("clean SLO bound samples");
    }

    /// C234/C235: representative leaf probes must retain the exact expression
    /// predicates and `(timestamp,id)` order matched by migration 183. Disabling
    /// sequential and bitmap scans makes an accidental loss of the ordered
    /// btree path visible in the JSON plan.
    #[tokio::test]
    async fn metric_status_query_plans_use_resource_bound_indexes() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(test_db) = test_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let pool = &test_db;
        let mut tx = pool.begin().await.expect("begin plan transaction");
        sqlx::query("SET LOCAL enable_seqscan = off")
            .execute(&mut *tx)
            .await
            .expect("disable sequential scans for plan assertion");
        sqlx::query("SET LOCAL enable_bitmapscan = off")
            .execute(&mut *tx)
            .await
            .expect("disable bitmap scans for plan assertion");

        let now = chrono::Utc::now();
        let sample_plan: Value = sqlx::query_scalar(
            "EXPLAIN (FORMAT JSON) \
             SELECT value FROM metric_samples \
             WHERE metric_key = $1 \
               AND (site IS NOT NULL) = TRUE AND COALESCE(site, '') = $2 \
               AND (environment IS NOT NULL) = TRUE \
               AND COALESCE(environment, '') = $3 \
               AND observed_at >= $4 - INTERVAL '1 day' AND observed_at <= $4 \
             ORDER BY observed_at DESC, id DESC LIMIT 2001",
        )
        .bind("plan.metric")
        .bind("PLAN-SITE")
        .bind("plan")
        .bind(now)
        .fetch_one(&mut *tx)
        .await
        .expect("explain metric sample probe");
        assert!(
            sample_plan
                .to_string()
                .contains("idx_metric_samples_status_series"),
            "sample plan must use the deterministic bounded-series index: {sample_plan}"
        );

        // Competing partial indexes are intentionally useful for other scope
        // shapes and can be cheaper on an empty test table. Temporarily remove
        // them so this probe tests the full dual-axis index contract itself,
        // not PostgreSQL's data-dependent cost choice.
        sqlx::query("SAVEPOINT metric_budget_dual_axis_plan")
            .execute(&mut *tx)
            .await
            .expect("savepoint metric budget plan");
        sqlx::query(
            "DROP INDEX idx_metric_budgets_status_global, \
             idx_metric_budgets_status_site, idx_metric_budgets_status_environment",
        )
        .execute(&mut *tx)
        .await
        .expect("isolate dual-axis metric budget index");
        let budget_plan: Value = sqlx::query_scalar(
            "EXPLAIN (FORMAT JSON) \
             SELECT id, metric_key, site, environment, threshold, comparison \
             FROM metric_budgets \
             WHERE enabled \
               AND (site IS NOT NULL) = TRUE AND COALESCE(site, '') = $1 \
               AND (environment IS NOT NULL) = TRUE \
               AND COALESCE(environment, '') = $2 \
             ORDER BY created_at DESC, id DESC LIMIT 101",
        )
        .bind("PLAN-SITE")
        .bind("plan")
        .fetch_one(&mut *tx)
        .await
        .expect("explain budget definition probe");
        assert!(
            budget_plan
                .to_string()
                .contains("idx_metric_budgets_status_site_environment"),
            "budget plan must use the scoped definition index: {budget_plan}"
        );
        sqlx::query("ROLLBACK TO SAVEPOINT metric_budget_dual_axis_plan")
            .execute(&mut *tx)
            .await
            .expect("restore metric budget indexes");

        sqlx::query("SAVEPOINT slo_dual_axis_plan")
            .execute(&mut *tx)
            .await
            .expect("savepoint SLO plan");
        sqlx::query(
            "DROP INDEX idx_slo_definitions_status_global, \
             idx_slo_definitions_status_site, idx_slo_definitions_status_environment",
        )
        .execute(&mut *tx)
        .await
        .expect("isolate dual-axis SLO index");
        let slo_plan: Value = sqlx::query_scalar(
            "EXPLAIN (FORMAT JSON) \
             SELECT id, name, target, window_days, good_metric_key, total_metric_key \
             FROM slo_definitions \
             WHERE enabled \
               AND (site IS NOT NULL) = TRUE AND COALESCE(site, '') = $1 \
               AND (environment IS NOT NULL) = TRUE \
               AND COALESCE(environment, '') = $2 \
             ORDER BY created_at DESC, id DESC LIMIT 101",
        )
        .bind("PLAN-SITE")
        .bind("plan")
        .fetch_one(&mut *tx)
        .await
        .expect("explain SLO definition probe");
        assert!(
            slo_plan
                .to_string()
                .contains("idx_slo_definitions_status_site_environment"),
            "SLO plan must use the scoped definition index: {slo_plan}"
        );
        sqlx::query("ROLLBACK TO SAVEPOINT slo_dual_axis_plan")
            .execute(&mut *tx)
            .await
            .expect("restore SLO indexes");

        let resource_indexes: Vec<String> = sqlx::query_scalar(
            "SELECT indexname FROM pg_indexes \
             WHERE schemaname = current_schema() \
               AND indexname = ANY($1::text[]) ORDER BY indexname",
        )
        .bind(vec![
            "idx_metric_samples_status_series".to_string(),
            "idx_metric_budgets_status_global".to_string(),
            "idx_metric_budgets_status_site".to_string(),
            "idx_metric_budgets_status_environment".to_string(),
            "idx_metric_budgets_status_site_environment".to_string(),
            "idx_slo_definitions_status_global".to_string(),
            "idx_slo_definitions_status_site".to_string(),
            "idx_slo_definitions_status_environment".to_string(),
            "idx_slo_definitions_status_site_environment".to_string(),
        ])
        .fetch_all(&mut *tx)
        .await
        .expect("read migration 183 indexes");
        assert_eq!(resource_indexes.len(), 9);

        let resource_constraints: Vec<(String, String, bool)> = sqlx::query_as(
            "SELECT pg_class.relname, conname, convalidated \
             FROM pg_constraint \
             JOIN pg_class ON pg_class.oid = conrelid \
             JOIN pg_namespace ON pg_namespace.oid = pg_class.relnamespace \
             JOIN (VALUES \
                    ('metric_samples', 'metric_samples_status_identity_bounds'), \
                    ('metric_budgets', 'metric_budgets_status_identity_bounds'), \
                    ('slo_definitions', 'slo_definitions_status_identity_bounds') \
             ) AS expected(table_name, constraint_name) \
               ON expected.table_name = pg_class.relname \
              AND expected.constraint_name = conname \
             WHERE pg_namespace.nspname = current_schema() \
               AND contype = 'c' \
             ORDER BY pg_class.relname, conname",
        )
        .fetch_all(&mut *tx)
        .await
        .expect("read migration 183 identity constraints");
        assert_eq!(
            resource_constraints,
            vec![
                (
                    "metric_budgets".to_string(),
                    "metric_budgets_status_identity_bounds".to_string(),
                    true,
                ),
                (
                    "metric_samples".to_string(),
                    "metric_samples_status_identity_bounds".to_string(),
                    true,
                ),
                (
                    "slo_definitions".to_string(),
                    "slo_definitions_status_identity_bounds".to_string(),
                    true,
                ),
            ],
            "every resource-bound constraint must be installed and validated"
        );
        tx.rollback().await.expect("rollback plan transaction");
    }

    /// C234/C235: migration 183's reviewed identity envelope is a durable
    /// writer boundary, not only an API convention. Direct writers cannot
    /// introduce a row that would make a future btree tuple unsafe.
    #[tokio::test]
    async fn metric_status_identity_constraints_reject_oversized_direct_writes() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(test_db) = test_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let pool = &test_db;
        let tag = Uuid::new_v4().simple().to_string();
        let oversized = "é".repeat(101);

        let sample_error =
            sqlx::query("INSERT INTO metric_samples (id, metric_key, value) VALUES ($1, $2, 1.0)")
                .bind(format!("resource-bound-sample-{tag}"))
                .bind(&oversized)
                .execute(pool)
                .await
                .expect_err("oversized metric sample identity must be rejected");
        assert_eq!(
            sample_error
                .as_database_error()
                .and_then(|error| error.code())
                .as_deref(),
            Some("23514")
        );
        assert_eq!(
            sample_error
                .as_database_error()
                .and_then(|error| error.constraint()),
            Some("metric_samples_status_identity_bounds")
        );

        let budget_error = sqlx::query(
            "INSERT INTO metric_budgets \
             (id, metric_key, site, threshold, comparison) \
             VALUES ($1, $2, $3, 1.0, 'above')",
        )
        .bind(format!("resource-bound-budget-{tag}"))
        .bind(format!("resource.bound.{tag}"))
        .bind(&oversized)
        .execute(pool)
        .await
        .expect_err("oversized metric budget scope must be rejected");
        assert_eq!(
            budget_error
                .as_database_error()
                .and_then(|error| error.code())
                .as_deref(),
            Some("23514")
        );
        assert_eq!(
            budget_error
                .as_database_error()
                .and_then(|error| error.constraint()),
            Some("metric_budgets_status_identity_bounds")
        );

        let slo_error = sqlx::query(
            "INSERT INTO slo_definitions \
             (id, name, target, window_days, good_metric_key, total_metric_key) \
             VALUES ($1, $2, 0.99, 7, $3, $4)",
        )
        .bind(format!("resource-bound-slo-{tag}"))
        .bind(&oversized)
        .bind(format!("resource.bound.good.{tag}"))
        .bind(format!("resource.bound.total.{tag}"))
        .execute(pool)
        .await
        .expect_err("oversized SLO identity must be rejected");
        assert_eq!(
            slo_error
                .as_database_error()
                .and_then(|error| error.code())
                .as_deref(),
            Some("23514")
        );
        assert_eq!(
            slo_error
                .as_database_error()
                .and_then(|error| error.constraint()),
            Some("slo_definitions_status_identity_bounds")
        );

        let empty_scope_error = sqlx::query(
            "INSERT INTO metric_samples \
             (id, metric_key, environment, value) VALUES ($1, $2, '', 1.0)",
        )
        .bind(format!("resource-bound-empty-scope-{tag}"))
        .bind(format!("resource.bound.empty.{tag}"))
        .execute(pool)
        .await
        .expect_err("a non-NULL empty metric scope must be rejected");
        assert_eq!(
            empty_scope_error
                .as_database_error()
                .and_then(|error| error.code())
                .as_deref(),
            Some("23514")
        );
        assert_eq!(
            empty_scope_error
                .as_database_error()
                .and_then(|error| error.constraint()),
            Some("metric_samples_status_identity_bounds")
        );
    }

    /// C234/C235: an oversized legacy row must stop migration 183 at its named
    /// preflight, before any index survives. The enclosing SQLx transaction
    /// restores the pre-cutover schema and data exactly after failure.
    #[tokio::test]
    async fn metric_status_migration_fails_cleanly_on_oversized_legacy_identity() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(test_db) = test_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let pool = &test_db;
        let index_names = vec![
            "idx_metric_samples_status_series".to_string(),
            "idx_metric_budgets_status_global".to_string(),
            "idx_metric_budgets_status_site".to_string(),
            "idx_metric_budgets_status_environment".to_string(),
            "idx_metric_budgets_status_site_environment".to_string(),
            "idx_slo_definitions_status_global".to_string(),
            "idx_slo_definitions_status_site".to_string(),
            "idx_slo_definitions_status_environment".to_string(),
            "idx_slo_definitions_status_site_environment".to_string(),
        ];
        let indexes_before: Vec<(String, String)> = sqlx::query_as(
            "SELECT indexname, indexdef FROM pg_indexes \
             WHERE schemaname = current_schema() \
               AND indexname = ANY($1::text[]) ORDER BY indexname",
        )
        .bind(&index_names)
        .fetch_all(pool)
        .await
        .expect("snapshot migration 183 indexes");
        assert_eq!(indexes_before.len(), 9);
        let constraints_before: Vec<(String, String, bool, String)> = sqlx::query_as(
            "SELECT pg_class.relname, conname, convalidated, \
                    pg_get_constraintdef(pg_constraint.oid) \
             FROM pg_constraint \
             JOIN pg_class ON pg_class.oid = conrelid \
             JOIN pg_namespace ON pg_namespace.oid = pg_class.relnamespace \
             JOIN (VALUES \
                    ('metric_samples', 'metric_samples_status_identity_bounds'), \
                    ('metric_budgets', 'metric_budgets_status_identity_bounds'), \
                    ('slo_definitions', 'slo_definitions_status_identity_bounds') \
             ) AS expected(table_name, constraint_name) \
               ON expected.table_name = pg_class.relname \
              AND expected.constraint_name = conname \
             WHERE pg_namespace.nspname = current_schema() \
               AND contype = 'c' ORDER BY pg_class.relname, conname",
        )
        .fetch_all(pool)
        .await
        .expect("snapshot migration 183 constraints");
        assert_eq!(constraints_before.len(), 3);
        assert!(constraints_before
            .iter()
            .all(|(_, _, validated, _)| *validated));

        let legacy_id = format!("resource-bound-legacy-{}", Uuid::new_v4().simple());
        let mut tx = pool
            .begin()
            .await
            .expect("begin resource-bound rollback test");
        sqlx::raw_sql(
            "DROP INDEX idx_metric_samples_status_series;
             DROP INDEX idx_metric_budgets_status_global;
             DROP INDEX idx_metric_budgets_status_site;
             DROP INDEX idx_metric_budgets_status_environment;
             DROP INDEX idx_metric_budgets_status_site_environment;
             DROP INDEX idx_slo_definitions_status_global;
             DROP INDEX idx_slo_definitions_status_site;
             DROP INDEX idx_slo_definitions_status_environment;
             DROP INDEX idx_slo_definitions_status_site_environment;
             ALTER TABLE metric_samples
                 DROP CONSTRAINT metric_samples_status_identity_bounds;
             ALTER TABLE metric_budgets
                 DROP CONSTRAINT metric_budgets_status_identity_bounds;
             ALTER TABLE slo_definitions
                 DROP CONSTRAINT slo_definitions_status_identity_bounds;",
        )
        .execute(&mut *tx)
        .await
        .expect("restore the reviewed pre-migration schema inside rollback test");
        sqlx::query(
            "INSERT INTO slo_definitions \
             (id, name, target, window_days, good_metric_key, total_metric_key) \
             VALUES ($1, $2, 0.99, 7, 'legacy.good', 'legacy.total')",
        )
        .bind(&legacy_id)
        .bind("x".repeat(3_000))
        .execute(&mut *tx)
        .await
        .expect("seed schema-valid oversized legacy SLO");

        let migration_error = sqlx::raw_sql(include_str!(
            "../../../migrations/183_resource_query_bounds.sql"
        ))
        .execute(&mut *tx)
        .await
        .expect_err("migration preflight must stop on the oversized legacy identity");
        let database_error = migration_error
            .as_database_error()
            .expect("preflight returns a PostgreSQL error");
        assert_eq!(database_error.code().as_deref(), Some("23514"));
        assert!(
            database_error
                .message()
                .contains("metric_samples=0, metric_budgets=0, slo_definitions=1"),
            "preflight must report the exact offending table count: {database_error}"
        );
        tx.rollback()
            .await
            .expect("rollback failed resource-bound cutover");

        let indexes_after: Vec<(String, String)> = sqlx::query_as(
            "SELECT indexname, indexdef FROM pg_indexes \
             WHERE schemaname = current_schema() \
               AND indexname = ANY($1::text[]) ORDER BY indexname",
        )
        .bind(&index_names)
        .fetch_all(pool)
        .await
        .expect("read indexes after failed migration rollback");
        let constraints_after: Vec<(String, String, bool, String)> = sqlx::query_as(
            "SELECT pg_class.relname, conname, convalidated, \
                    pg_get_constraintdef(pg_constraint.oid) \
             FROM pg_constraint \
             JOIN pg_class ON pg_class.oid = conrelid \
             JOIN pg_namespace ON pg_namespace.oid = pg_class.relnamespace \
             JOIN (VALUES \
                    ('metric_samples', 'metric_samples_status_identity_bounds'), \
                    ('metric_budgets', 'metric_budgets_status_identity_bounds'), \
                    ('slo_definitions', 'slo_definitions_status_identity_bounds') \
             ) AS expected(table_name, constraint_name) \
               ON expected.table_name = pg_class.relname \
              AND expected.constraint_name = conname \
             WHERE pg_namespace.nspname = current_schema() \
               AND contype = 'c' ORDER BY pg_class.relname, conname",
        )
        .fetch_all(pool)
        .await
        .expect("read constraints after failed migration rollback");
        assert_eq!(
            indexes_after, indexes_before,
            "no partial index DDL may survive"
        );
        assert_eq!(
            constraints_after, constraints_before,
            "failed preflight must restore the installed constraint catalog"
        );
        let legacy_rows: i64 =
            sqlx::query_scalar("SELECT COUNT(*) FROM slo_definitions WHERE id = $1")
                .bind(&legacy_id)
                .fetch_one(pool)
                .await
                .expect("verify oversized legacy fixture rollback");
        assert_eq!(legacy_rows, 0);
    }

    /// #54: commitment modeling derives usage from the series mean and reports a
    /// recommended commitment when it saves money.
    #[tokio::test]
    async fn test_metric_commitment_uses_series_mean_and_recommends() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let key = "test.metric.commit.6h2";
        sqlx::query("DELETE FROM metric_samples WHERE metric_key = $1")
            .bind(key)
            .execute(pool)
            .await
            .ok();

        let sess = || AuthExtractor(AuthSession::static_dry_run());
        // Mean of [80, 100, 120] = 100.
        for (i, v) in [(0i64, 80.0f64), (1, 100.0), (2, 120.0)] {
            let body = MetricSampleRequest {
                metric_key: key.to_string(),
                site: None,
                environment: None,
                value: v,
                observed_at: Some(format!("2026-06-01T0{i}:00:00+00:00")),
            };
            let _ = metrics_record_sample(sess(), Json(body))
                .await
                .expect("record sample");
        }

        // usage=100 (series mean), commit 100 units at 0.6 vs 1.0 on-demand →
        // 60 vs 100 → save 40, recommended.
        let params = MetricCommitmentParams {
            metric_key: Some(key.to_string()),
            site: None,
            environment: None,
            on_demand_rate: Some(1.0),
            commitment_rate: Some(0.6),
            committed_units: Some(100.0),
            usage: None,
        };
        let Json(out) = metrics_commitment(sess(), Query(params))
            .await
            .expect("commitment");
        assert_eq!(out["usage_source"], "series_mean");
        assert_eq!(out["model"]["recommended"], true);
        assert!((out["model"]["savings"].as_f64().unwrap() - 40.0).abs() < 1e-6);

        sqlx::query("DELETE FROM metric_samples WHERE metric_key = $1")
            .bind(key)
            .execute(pool)
            .await
            .ok();
    }

    /// #run8: the ipam_reserve_ip HANDLER reserves a DISTINCT IP each call and
    /// decrements the subnet counters atomically. Two sequential reserves must yield
    /// two different IPs and used/available moving by exactly 2 — the new in-tx,
    /// under-the-subnet-lock read+pick path (which closes the double-allocation race).
    #[tokio::test]
    async fn test_ipam_reserve_ip_handler_allocates_distinct_ips() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let Json(created) = ipam_subnet_create(
            AuthExtractor(AuthSession::static_dry_run()),
            Json(IpamSubnetCreateRequest {
                cidr: "10.77.0.0/24".to_string(),
                gateway: "10.77.0.1".to_string(),
                vlan_id: 777,
                site: "TESTSITE".to_string(),
            }),
        )
        .await
        .expect("create subnet");
        let id = created["subnet"]["id"].as_str().unwrap().to_string();

        let reserve = |hostname: &str| {
            let id = id.clone();
            let hostname = hostname.to_string();
            async move {
                ipam_reserve_ip(
                    Extension(AuthSession::static_dry_run()),
                    Json(IpamReserveRequest {
                        subnet_id: id,
                        hostname,
                        purpose: "test".to_string(),
                        ttl_days: 30,
                    }),
                )
                .await
            }
        };

        let Json(r1) = reserve("host-a").await.expect("reserve 1");
        let Json(r2) = reserve("host-b").await.expect("reserve 2");
        let ip1 = r1["reservation"]["ip_address"]
            .as_str()
            .unwrap()
            .to_string();
        let ip2 = r2["reservation"]["ip_address"]
            .as_str()
            .unwrap()
            .to_string();

        // Cleanup before asserting.
        sqlx::query("DELETE FROM ip_reservations WHERE subnet_id = $1")
            .bind(&id)
            .execute(pool)
            .await
            .ok();
        sqlx::query("DELETE FROM ipam_subnets WHERE id = $1")
            .bind(&id)
            .execute(pool)
            .await
            .ok();

        assert_ne!(ip1, ip2, "two reserves must hand out DISTINCT IPs");
        assert_eq!(r2["subnet"]["used_ips"], 2, "used_ips moved by exactly 2");
        assert_eq!(
            r2["subnet"]["available_ips"], 252,
            "available_ips decremented by exactly 2 (no stale-counter overwrite)"
        );
    }

    /// #P2-12: ipam_check_availability reads the AUTHORITATIVE `available_ips` column
    /// (maintained by ipam_reserve_ip / ipam_release_ip), NOT the in-memory engine
    /// seed — so after two reserves it reports the DECREMENTED count, and an unknown
    /// subnet id is a 404. Before this fix the handler read the engine store, which on
    /// a DB deployment returns a STALE seed-only count and never reflects reservations.
    #[tokio::test]
    async fn test_ipam_check_availability_reads_live_db_counter() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let Json(created) = ipam_subnet_create(
            AuthExtractor(AuthSession::static_dry_run()),
            Json(IpamSubnetCreateRequest {
                cidr: "10.78.0.0/24".to_string(),
                gateway: "10.78.0.1".to_string(),
                vlan_id: 778,
                site: "TESTSITE".to_string(),
            }),
        )
        .await
        .expect("create subnet");
        let id = created["subnet"]["id"].as_str().unwrap().to_string();

        let check = |count: u32| {
            let id = id.clone();
            async move {
                ipam_check_availability(
                    AuthExtractor(AuthSession::static_dry_run()),
                    Path(id),
                    Query(IpamAvailabilityQuery { count: Some(count) }),
                )
                .await
            }
        };

        // Fresh /24: 254 usable hosts, all available on the DB path.
        let Json(before) = check(254).await.expect("availability before");
        // Reserve two IPs, decrementing the authoritative counter to 252.
        for hostname in ["avail-a", "avail-b"] {
            let Json(_) = ipam_reserve_ip(
                Extension(AuthSession::static_dry_run()),
                Json(IpamReserveRequest {
                    subnet_id: id.clone(),
                    hostname: hostname.to_string(),
                    purpose: "test".to_string(),
                    ttl_days: 30,
                }),
            )
            .await
            .expect("reserve");
        }
        let Json(after) = check(252).await.expect("availability after");
        let Json(over) = check(253).await.expect("availability over");
        let missing = ipam_check_availability(
            AuthExtractor(AuthSession::static_dry_run()),
            Path("subnet-does-not-exist".to_string()),
            Query(IpamAvailabilityQuery { count: Some(1) }),
        )
        .await;

        // Cleanup BEFORE asserting (a failed assert must not leak the test subnet).
        sqlx::query("DELETE FROM ip_reservations WHERE subnet_id = $1")
            .bind(&id)
            .execute(pool)
            .await
            .ok();
        sqlx::query("DELETE FROM ipam_subnets WHERE id = $1")
            .bind(&id)
            .execute(pool)
            .await
            .ok();

        assert_eq!(
            before["source"], "database",
            "DB path, not the in-memory seed"
        );
        assert_eq!(before["available_ips"], 254);
        assert_eq!(before["can_allocate"], true);
        assert_eq!(
            after["available_ips"], 252,
            "availability tracks live DB reservations, not the stale seed"
        );
        assert_eq!(
            after["can_allocate"], true,
            "252 requested <= 252 available"
        );
        assert_eq!(
            over["can_allocate"], false,
            "253 requested > 252 available → cannot allocate"
        );
        assert!(
            matches!(missing, Err((StatusCode::NOT_FOUND, _))),
            "unknown subnet id is a 404 on the DB path"
        );
    }

    /// #run8: ipam_release_ip is AUTHORITATIVE — a double-release of the same
    /// reservation returns not-found on the second call and does NOT over-credit
    /// available_ips (the counter is credited only when the DELETE removes the row).
    #[tokio::test]
    async fn test_ipam_release_is_idempotent_no_over_credit() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let Json(created) = ipam_subnet_create(
            AuthExtractor(AuthSession::static_dry_run()),
            Json(IpamSubnetCreateRequest {
                cidr: "10.88.0.0/24".to_string(),
                gateway: "10.88.0.1".to_string(),
                vlan_id: 888,
                site: "TESTSITE".to_string(),
            }),
        )
        .await
        .expect("create subnet");
        let subnet_id = created["subnet"]["id"].as_str().unwrap().to_string();

        let Json(r) = ipam_reserve_ip(
            Extension(AuthSession::static_dry_run()),
            Json(IpamReserveRequest {
                subnet_id: subnet_id.clone(),
                hostname: "h".to_string(),
                purpose: "test".to_string(),
                ttl_days: 30,
            }),
        )
        .await
        .expect("reserve");
        let res_id = r["reservation"]["id"].as_str().unwrap().to_string();

        let Json(_) = ipam_release_ip(
            Extension(AuthSession::static_dry_run()),
            Path(res_id.clone()),
        )
        .await
        .expect("first release");
        let second = ipam_release_ip(Extension(AuthSession::static_dry_run()), Path(res_id)).await;

        let available: i32 =
            sqlx::query_scalar("SELECT available_ips FROM ipam_subnets WHERE id = $1")
                .bind(&subnet_id)
                .fetch_one(pool)
                .await
                .expect("read available");
        sqlx::query("DELETE FROM ipam_subnets WHERE id = $1")
            .bind(&subnet_id)
            .execute(pool)
            .await
            .ok();

        assert!(
            second.is_err(),
            "a second release of the same reservation must be not-found"
        );
        assert_eq!(
            available, 254,
            "available_ips restored to capacity, NOT over-credited to 255"
        );
    }

    /// #56: IPAM subnet CRUD — create (counters derived from the CIDR), update
    /// mutable fields (preserving counters), reject an invalid status, refuse a
    /// delete while reservations exist, then delete once released.
    #[tokio::test]
    async fn test_ipam_subnet_crud_lifecycle() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };

        // CREATE — a /24 yields 254 usable hosts.
        let Json(created) = ipam_subnet_create(
            AuthExtractor(AuthSession::static_dry_run()),
            Json(IpamSubnetCreateRequest {
                cidr: "10.99.0.0/24".to_string(),
                gateway: "10.99.0.1".to_string(),
                vlan_id: 999,
                site: "TESTSITE".to_string(),
            }),
        )
        .await
        .expect("create subnet");
        let id = created["subnet"]["id"].as_str().unwrap().to_string();
        assert_eq!(created["subnet"]["total_ips"], 254);
        assert_eq!(created["subnet"]["available_ips"], 254);

        // #7 audit: the create wrote a durable audit_log row.
        let create_audited: bool = sqlx::query_scalar(
            "SELECT EXISTS(SELECT 1 FROM audit_log \
             WHERE action = 'ipam-subnet-create' AND detail->>'subnet_id' = $1)",
        )
        .bind(&id)
        .fetch_one(pool)
        .await
        .expect("query create audit");
        assert!(create_audited, "subnet create must write an audit_log row");

        // UPDATE gateway + status; the reservation counters are preserved.
        let Json(updated) = ipam_subnet_update(
            AuthExtractor(AuthSession::static_dry_run()),
            Path(id.clone()),
            Json(IpamSubnetUpdateRequest {
                gateway: Some("10.99.0.254".to_string()),
                vlan_id: None,
                status: Some("Reserved".to_string()),
            }),
        )
        .await
        .expect("update subnet");
        assert_eq!(updated["subnet"]["gateway"], "10.99.0.254");
        assert_eq!(updated["subnet"]["status"], "Reserved");
        assert_eq!(updated["subnet"]["total_ips"], 254, "counters preserved");

        // An invalid status is a 400, never a silent coercion.
        assert!(
            ipam_subnet_update(
                AuthExtractor(AuthSession::static_dry_run()),
                Path(id.clone()),
                Json(IpamSubnetUpdateRequest {
                    gateway: None,
                    vlan_id: None,
                    status: Some("Bogus".to_string()),
                }),
            )
            .await
            .is_err(),
            "an invalid status is rejected"
        );

        // DELETE is refused (409) while a reservation exists.
        sqlx::query(
            "INSERT INTO ip_reservations \
             (id, ip_address, subnet_id, hostname, purpose, reserved_by, reserved_at, expiry) \
             VALUES ('res-test-ipam-1', '10.99.0.10', $1, 'h', 'p', 'u', '2026-01-01', '2027-01-01')",
        )
        .bind(&id)
        .execute(pool)
        .await
        .unwrap();
        match ipam_subnet_delete(
            AuthExtractor(AuthSession::static_dry_run()),
            Path(id.clone()),
        )
        .await
        {
            Err((status, _)) => assert_eq!(status, StatusCode::CONFLICT),
            Ok(_) => panic!("delete must be refused while reservations exist"),
        }

        // Release the reservation, then the delete succeeds.
        sqlx::query("DELETE FROM ip_reservations WHERE subnet_id = $1")
            .bind(&id)
            .execute(pool)
            .await
            .unwrap();
        let Json(deleted) = ipam_subnet_delete(
            AuthExtractor(AuthSession::static_dry_run()),
            Path(id.clone()),
        )
        .await
        .expect("delete subnet");
        assert_eq!(deleted["deleted"], true);

        // #7 audit: the delete wrote a durable audit_log row.
        let delete_audited: bool = sqlx::query_scalar(
            "SELECT EXISTS(SELECT 1 FROM audit_log \
             WHERE action = 'ipam-subnet-delete' AND detail->>'subnet_id' = $1)",
        )
        .bind(&id)
        .fetch_one(pool)
        .await
        .expect("query delete audit");
        assert!(delete_audited, "subnet delete must write an audit_log row");

        sqlx::query("DELETE FROM ipam_subnets WHERE id = $1")
            .bind(&id)
            .execute(pool)
            .await
            .ok();
    }

    /// #17: the batch-cancel handler rejects an empty batch, an empty reason,
