    /// R01-MB-C210: the UUID visible through admin session inventory is only a
    /// management handle. The unrelated rys_ bearer works through each single
    /// carrier until administrative revocation, and neither plaintext nor
    /// verifier appears in inventory/audit projections.
    #[tokio::test]
    async fn admin_session_id_cannot_be_replayed_as_bearer() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set");
            return;
        };
        let seeded = seed_session(pool, "session-boundary-user").await;
        let session_config = install_test_session_config();
        let resolution_config = ryuki_core::config::RyukiConfig {
            auth_mode: AuthMode::Local,
            session: session_config,
            ..Default::default()
        };
        let management_id = seeded.record_id.to_string();
        let admin_auth = admin_session("session-boundary-admin");

        let Json(list) = admin_sessions_list(
            AuthExtractor(admin_auth.clone()),
            Query(AdminListPage {
                limit: Some(1000),
                offset: Some(0),
            }),
        )
        .await
        .expect("admin list");
        let listed = list["sessions"]
            .as_array()
            .unwrap()
            .iter()
            .find(|row| row["id"] == json!(seeded.record_id))
            .expect("seeded management row is listed");
        assert!(listed.get("bearer_verifier").is_none());
        assert!(listed.get("session_token").is_none());

        let Json(got) =
            admin_sessions_get(AuthExtractor(admin_auth.clone()), Path(seeded.record_id))
                .await
                .expect("admin get");
        assert_eq!(got["id"], json!(seeded.record_id));
        assert!(got.get("bearer_verifier").is_none());
        assert!(got.get("session_token").is_none());

        let mut header_replay = HeaderMap::new();
        header_replay.insert("X-Ryuki-Session-Id", management_id.parse().unwrap());
        let replay =
            crate::auth_session_from_persisted_session(&header_replay, None, &resolution_config)
                .await
                .expect("explicit invalid header is classified");
        assert!(!replay.0.token_valid);

        let mut cookie_replay = HeaderMap::new();
        cookie_replay.insert(
            axum::http::header::COOKIE,
            format!("__Host-ryuki_session={management_id}")
                .parse()
                .unwrap(),
        );
        let replay =
            crate::auth_session_from_persisted_session(&cookie_replay, None, &resolution_config)
                .await
                .expect("explicit invalid cookie is classified");
        assert!(!replay.0.token_valid);

        let metadata_authorization = format!("Bearer {management_id}");
        assert!(
            crate::auth_session_from_persisted_session(
                &HeaderMap::new(),
                Some(&metadata_authorization),
                &resolution_config,
            )
            .await
            .is_none(),
            "management UUID must not claim any persisted credential class"
        );

        let mut session_header = HeaderMap::new();
        session_header.insert("X-Ryuki-Session-Id", seeded.session_token.parse().unwrap());
        let resolved =
            crate::auth_session_from_persisted_session(&session_header, None, &resolution_config)
                .await
                .expect("session header resolves");
        assert!(resolved.0.token_valid);

        let session_authorization = format!("Bearer {}", seeded.session_token);
        let resolved = crate::auth_session_from_persisted_session(
            &HeaderMap::new(),
            Some(&session_authorization),
            &resolution_config,
        )
        .await
        .expect("session Authorization resolves");
        assert!(resolved.0.token_valid);

        let mut session_cookie = HeaderMap::new();
        session_cookie.insert(
            axum::http::header::COOKIE,
            format!("__Host-ryuki_session={}", seeded.session_token)
                .parse()
                .unwrap(),
        );
        let resolved =
            crate::auth_session_from_persisted_session(&session_cookie, None, &resolution_config)
                .await
                .expect("session cookie resolves");
        assert!(resolved.0.token_valid);

        let _ = admin_sessions_revoke(AuthExtractor(admin_auth), Path(seeded.record_id))
            .await
            .expect("admin revoke");
        let revoked =
            crate::auth_session_from_persisted_session(&session_header, None, &resolution_config)
                .await
                .expect("revoked bearer is classified");
        assert!(!revoked.0.token_valid);

        let audit_detail: String = sqlx::query_scalar(
            "SELECT detail::text FROM audit_log \
             WHERE action = 'session-revoke' \
               AND detail->>'session_record_id' = $1 \
             ORDER BY id DESC LIMIT 1",
        )
        .bind(management_id)
        .fetch_one(pool)
        .await
        .expect("session revoke audit");
        assert!(!audit_detail.contains(&seeded.session_token));
        assert!(!audit_detail.contains("bearer_verifier"));
    }

    /// #5 audit-trail gap: minting and revoking an API token must each write a
    /// DURABLE audit_log row attributing the admin caller, with token metadata
    /// only — NEVER the plaintext or hash.
    #[tokio::test]
    async fn test_token_create_and_revoke_write_audit_log() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set");
            return;
        };
        crate::config_store::init_with_config(
            "/tmp/ryuki-test-token-audit-config.json",
            &ryuki_core::config::RyukiConfig {
                auth_mode: AuthMode::Local,
                ..Default::default()
            },
        );
        let mut admin = admin_session("dbtest-admin-tok-4d2");
        let subject = "dbtest-admin-tok-4d2";
        let (issuer, principal_binding) =
            seed_test_principal_binding(pool, "local", subject, &admin.roles).await;
        admin.principal_id = Some(principal_binding.principal_id);
        let issuing_authority = crate::human_authority::InteractiveHumanAuthorityContext {
            principal_binding,
            provider: "local".into(),
            issuer,
            subject: subject.into(),
            identity_epoch: principal_binding.principal_lifecycle_version,
            assignment_version: principal_binding.principal_authority_version,
            roles: canonical_token_roles(&admin.roles).unwrap(),
            site_mode: crate::human_authority::HumanAuthorityMode::Global,
            site_scope: vec![],
            environment_mode: crate::human_authority::HumanAuthorityMode::Global,
            environment_scope: vec![],
        };
        let created = admin_tokens_create(
            AuthExtractor(admin.clone()),
            InteractiveHumanAuthorityExtractor(Some(issuing_authority)),
            Json(CreateTokenRequest {
                name: "dbtest-audit-token".into(),
                roles: admin.roles.clone(),
                site_scope: None,
                environment_scope: None,
                expires_at: None,
            }),
        )
        .await;
        let (_status, _hdr, Json(body)) = created.expect("token create must succeed");
        assert_eq!(body["token_valid"], true);
        let created_at = chrono::DateTime::parse_from_rfc3339(
            body["created_at"].as_str().expect("created_at timestamp"),
        )
        .expect("parse token created_at");
        let expires_at = chrono::DateTime::parse_from_rfc3339(
            body["expires_at"].as_str().expect("expires_at timestamp"),
        )
        .expect("parse token expires_at");
        assert_eq!(
            expires_at - created_at,
            chrono::Duration::seconds(MAX_DERIVED_API_TOKEN_LIFETIME_SECS),
            "the default lifetime must use the database transaction clock exactly"
        );
        let token_id = body["id"].as_str().expect("token id").to_string();
        let token_uuid = Uuid::parse_str(&token_id).expect("uuid");

        let (c_action, c_actor, c_detail) = sqlx::query_as::<_, (String, String, String)>(
            "SELECT action, actor_principal, detail::text FROM audit_log \
             WHERE action = 'api-token-create' AND detail->>'token_id' = $1 \
             ORDER BY id DESC LIMIT 1",
        )
        .bind(&token_id)
        .fetch_optional(pool)
        .await
        .expect("query create audit")
        .expect("a durable create audit row must exist");
        assert_eq!(c_action, "api-token-create");
        assert_eq!(
            c_actor,
            principal_binding.principal_id.to_string(),
            "actor must be the opaque issuing principal"
        );
        assert!(c_detail.contains("dbtest-audit-token"), "names the token");
        assert!(
            !c_detail.contains("ryk_"),
            "detail must NEVER leak the plaintext token"
        );

        let revoked = admin_tokens_revoke(AuthExtractor(admin.clone()), Path(token_uuid)).await;
        assert!(revoked.is_ok(), "revoke must succeed: {revoked:?}");
        let revoke_audited: bool = sqlx::query_scalar(
            "SELECT EXISTS(SELECT 1 FROM audit_log \
             WHERE action = 'api-token-revoke' AND detail->>'token_id' = $1)",
        )
        .bind(&token_id)
        .fetch_one(pool)
        .await
        .expect("query revoke audit");

        assert!(
            revoke_audited,
            "revoke must write its own durable audit_log row"
        );
    }

