    fn scoped_admin_for_read_projection(site: &[&str], environment: &[&str]) -> AuthSession {
        let mut session = AuthSession::static_dry_run();
        session.site_scope = site.iter().map(|value| value.to_string()).collect();
        session.environment_scope = environment.iter().map(|value| value.to_string()).collect();
        session
    }

    #[tokio::test]
    async fn network_read_projections_apply_site_guard_before_data_access() {
        let gblon = scoped_admin_for_read_projection(&["GBLON"], &[]);

        let foreign_readiness = network_readiness_check(
            AuthExtractor(gblon.clone()),
            Query(NetworkReadinessQuery {
                site: Some("DEFRA".into()),
                ports: None,
                vlan: None,
                ips: None,
            }),
        )
        .await;
        assert!(matches!(foreign_readiness, Err((StatusCode::FORBIDDEN, _))));

        let foreign_capacity = network_capacity(
            AuthExtractor(gblon.clone()),
            Query(NetworkSiteQuery {
                site: Some("DEFRA".into()),
            }),
        )
        .await;
        assert!(matches!(foreign_capacity, Err((StatusCode::FORBIDDEN, _))));

        let foreign_vlans = network_vlans_inventory(
            AuthExtractor(gblon.clone()),
            Query(NetworkSiteQuery {
                site: Some("DEFRA".into()),
            }),
        )
        .await;
        assert!(matches!(foreign_vlans, Err((StatusCode::FORBIDDEN, _))));

        let own_readiness = network_readiness_check(
            AuthExtractor(gblon.clone()),
            Query(NetworkReadinessQuery {
                site: Some("GBLON".into()),
                ports: None,
                vlan: None,
                ips: None,
            }),
        )
        .await;
        assert!(
            !matches!(own_readiness, Err((StatusCode::FORBIDDEN, _))),
            "same-site readiness must pass the site guard: {own_readiness:?}"
        );

        let own_capacity = network_capacity(
            AuthExtractor(gblon.clone()),
            Query(NetworkSiteQuery {
                site: Some("GBLON".into()),
            }),
        )
        .await;
        assert!(
            !matches!(own_capacity, Err((StatusCode::FORBIDDEN, _))),
            "same-site capacity must pass the site guard: {own_capacity:?}"
        );

        let own_vlans = network_vlans_inventory(
            AuthExtractor(gblon),
            Query(NetworkSiteQuery {
                site: Some("GBLON".into()),
            }),
        )
        .await;
        assert!(
            !matches!(own_vlans, Err((StatusCode::FORBIDDEN, _))),
            "same-site VLAN projection must pass the site guard: {own_vlans:?}"
        );

        let environment_only = scoped_admin_for_read_projection(&[], &["production"]);
        let env_readiness = network_readiness_check(
            AuthExtractor(environment_only.clone()),
            Query(NetworkReadinessQuery {
                site: None,
                ports: None,
                vlan: None,
                ips: None,
            }),
        )
        .await;
        assert!(matches!(env_readiness, Err((StatusCode::FORBIDDEN, _))));

        let env_capacity = network_capacity(
            AuthExtractor(environment_only.clone()),
            Query(NetworkSiteQuery { site: None }),
        )
        .await;
        assert!(matches!(env_capacity, Err((StatusCode::FORBIDDEN, _))));

        let env_vlans = network_vlans_inventory(
            AuthExtractor(environment_only.clone()),
            Query(NetworkSiteQuery { site: None }),
        )
        .await;
        assert!(matches!(env_vlans, Err((StatusCode::FORBIDDEN, _))));

        let env_ports = network_ports_inventory(
            AuthExtractor(environment_only),
            Query(NetworkSwitchQuery {
                switch: Some("scope-canary".into()),
            }),
        )
        .await;
        let (status, body) = match env_ports {
            Err((status, Json(body))) => (status, body),
            other => panic!("environment-only port read must fail closed: {other:?}"),
        };
        assert_eq!(status, StatusCode::NOT_FOUND);
        assert!(
            !body.to_string().contains("scope-canary"),
            "generic denial must not echo the requested switch: {body}"
        );
    }

    #[tokio::test]
    async fn dr_due_tests_are_site_scoped_and_environment_scope_fails_closed() {
        let Json(defra) = dr_tests_due(AuthExtractor(scoped_admin_for_read_projection(
            &["DEFRA"],
            &[],
        )))
        .await
        .expect("single-site due-test listing must succeed");
        let defra_plans = defra["due_tests"].as_array().unwrap();
        assert!(!defra_plans.is_empty());
        assert!(defra_plans.iter().all(|plan| plan["site"] == "DEFRA"));

        let Json(union) = dr_tests_due(AuthExtractor(scoped_admin_for_read_projection(
            &["DEFRA", "FRPAR"],
            &[],
        )))
        .await
        .expect("multi-site due-test listing must return the held-site union");
        assert!(union["due_tests"]
            .as_array()
            .unwrap()
            .iter()
            .all(|plan| { matches!(plan["site"].as_str(), Some("DEFRA") | Some("FRPAR")) }));

        let Json(unrestricted) = dr_tests_due(AuthExtractor(AuthSession::static_dry_run()))
            .await
            .expect("unrestricted due-test listing remains compatible");
        assert!(unrestricted["count"].as_u64().unwrap() >= defra["count"].as_u64().unwrap());

        let environment_only = dr_tests_due(AuthExtractor(scoped_admin_for_read_projection(
            &[],
            &["production"],
        )))
        .await;
        assert!(matches!(environment_only, Err((StatusCode::FORBIDDEN, _))));
    }

