    #[tokio::test]
    async fn ad_quarantine_recovery_requires_maker_checker_and_audits_atomically() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };

        let sequence = 1000 + (Uuid::new_v4().as_u128() % 9000) as u16;
        let name = format!("DEFRA-DEV-{sequence:04}");
        let computer = ad_computer_lifecycle::prestage_computer(
            &name,
            "DEFRA",
            "OU=Development,OU=DEFRA,DC=corp,DC=local",
        )
        .expect("valid recovery fixture");
        let inserted = crate::repos::ad_computers::insert(pool, &computer)
            .await
            .expect("insert recovery fixture");
        let computer_id = Uuid::parse_str(&inserted.id).unwrap();
        sqlx::query(
            "UPDATE ad_computers \
             SET status = 'Quarantined', \
                 metadata = metadata || '{\"quarantine_reason\":\"synthetic investigation\"}'::jsonb, \
                 updated_at = NOW() \
             WHERE id = $1",
        )
        .bind(computer_id)
        .execute(pool)
        .await
        .expect("place fixture in quarantine");

        let mut maker = AuthSession::static_dry_run();
        bind_test_principal(&mut maker, "quarantine-recovery-maker");
        maker.token_valid = true;
        maker.actor_class = ryuki_engine::auth::ActorClass::VerifiedHuman;
        maker.provider_mode = "test-verified-human".into();
        let Json(requested) = ad_quarantine_recovery_review(
            AuthExtractor(maker.clone()),
            Path(name.clone()),
            Json(AdQuarantineRecoveryRequest {
                reason: "Independent review of synthetic quarantine evidence".into(),
            }),
        )
        .await
        .expect("maker may request reviewed recovery");
        let review_id = requested["reviewId"]
            .as_str()
            .expect("review id")
            .to_string();

        let forged_direct_approval = sqlx::query(
            "UPDATE ad_quarantine_recovery_reviews \
             SET state = 'Approved', approved_by = 'untrusted-direct-writer' \
             WHERE id = $1::uuid",
        )
        .bind(&review_id)
        .execute(pool)
        .await;
        assert!(
            forged_direct_approval.is_err(),
            "a direct writer without the versioned lifecycle contract must not forge approval"
        );

        let self_approval =
            ad_quarantine_recovery_approve(AuthExtractor(maker.clone()), Path(review_id.clone()))
                .await;
        assert!(
            matches!(self_approval, Err((StatusCode::CONFLICT, _))),
            "maker must not approve their own recovery review"
        );

        let mut checker = AuthSession::static_dry_run();
        bind_test_principal(&mut checker, "quarantine-recovery-checker");
        checker.token_valid = true;
        checker.actor_class = ryuki_engine::auth::ActorClass::VerifiedHuman;
        checker.provider_mode = "test-verified-human".into();
        let _ =
            ad_quarantine_recovery_approve(AuthExtractor(checker.clone()), Path(review_id.clone()))
                .await
                .expect("distinct admin checker approves");

        let mut tamper_tx = pool.begin().await.expect("begin checker tamper probe");
        sqlx::query(
            "SELECT set_config( \
                 'ryuki.ad_recovery_writer_contract', 'ad-recovery-v2', TRUE \
             )",
        )
        .execute(&mut *tamper_tx)
        .await
        .expect("install current writer contract in tamper probe");
        let checker_rewrite = sqlx::query(
            "UPDATE ad_quarantine_recovery_reviews \
             SET approved_by = 'replacement-checker' \
             WHERE id = $1::uuid",
        )
        .bind(&review_id)
        .execute(&mut *tamper_tx)
        .await;
        assert!(
            checker_rewrite.is_err(),
            "even a current writer must not rewrite durable checker evidence"
        );
        tamper_tx
            .rollback()
            .await
            .expect("rollback checker tamper probe");

        let self_apply =
            ad_quarantine_recovery_apply(AuthExtractor(maker), Path(review_id.clone())).await;
        assert!(
            matches!(self_apply, Err((StatusCode::CONFLICT, _))),
            "maker must not apply their own approved review"
        );

        let Json(applied) =
            ad_quarantine_recovery_apply(AuthExtractor(checker), Path(review_id.clone()))
                .await
                .expect("approved recovery applies atomically");
        assert_eq!(applied["status"], json!("Disabled"));

        let review_state: String = sqlx::query_scalar(
            "SELECT state FROM ad_quarantine_recovery_reviews WHERE id = $1::uuid",
        )
        .bind(&review_id)
        .fetch_one(pool)
        .await
        .expect("read applied review");
        assert_eq!(review_state, "Applied");

        let audit_actions: Vec<String> = sqlx::query_scalar(
            "SELECT action FROM audit_log \
             WHERE detail->>'review_id' = $1 \
             ORDER BY occurred_at, id",
        )
        .bind(&review_id)
        .fetch_all(pool)
        .await
        .expect("read quarantine recovery audit chain");
        assert_eq!(
            audit_actions,
            vec![
                "ad-quarantine-recovery-review-requested",
                "ad-quarantine-recovery-review-approved",
                "ad-quarantine-recovery-applied"
            ]
        );

        let hard_delete =
            sqlx::query("DELETE FROM ad_quarantine_recovery_reviews WHERE id = $1::uuid")
                .bind(&review_id)
                .execute(pool)
                .await;
        assert!(
            hard_delete.is_err(),
            "ordinary writers must not erase consumed maker/checker evidence"
        );

        sqlx::query("SELECT purge_ad_recovery_reviews_for_maintenance($1)")
            .bind(computer_id)
            .execute(pool)
            .await
            .expect("cleanup recovery review");
        sqlx::query("DELETE FROM ad_computers WHERE id = $1")
            .bind(computer_id)
            .execute(pool)
            .await
            .expect("cleanup recovery computer");
    }

