    /// #2 RBAC: slo_update / slo_delete enforce dual-axis subset containment.
    /// slo_definitions.site/environment are nullable (NULL = platform-wide on that
    /// axis). A scoped principal may only touch a row whose footprint is contained
    /// in its authority on both axes; an out-of-scope site, or platform-wide on an
    /// axis the principal is scoped to, collapses to a 404 (no existence oracle)
    /// BEFORE the mutation. The in-scope case still succeeds (not over-restrictive).
    #[tokio::test]
    async fn slo_update_delete_is_dual_axis_scoped() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };

        // Create three SLOs with distinct footprints (all via an unrestricted admin).
        let mut ids: Vec<(String, &str)> = Vec::new();
        for (site, name) in [
            (Some("DEFRA".to_string()), "scope-defra"),
            (None, "scope-global"),
            (Some("GBLON".to_string()), "scope-gblon"),
        ] {
            let created = slo_create(
                AuthExtractor(AuthSession::static_dry_run()),
                Json(SloCreateRequest {
                    name: name.to_string(),
                    target: 0.99,
                    window_days: Some(30),
                    good_metric_key: "slo.scope.good".into(),
                    total_metric_key: "slo.scope.total".into(),
                    site,
                    environment: None,
                }),
            )
            .await
            .expect("create slo");
            ids.push((created.0["id"].as_str().expect("slo id").to_string(), name));
        }
        let defra_id = ids[0].0.clone();
        let global_id = ids[1].0.clone();
        let gblon_id = ids[2].0.clone();

        // A GBLON-site-scoped principal (env-unrestricted).
        let scoped = || {
            let mut s = AuthSession::static_dry_run();
            s.site_scope = vec!["GBLON".into()];
            s
        };
        let hijack = || SloUpdateRequest {
            name: Some("hijacked".into()),
            target: None,
            window_days: None,
            enabled: Some(false),
        };

        // Out-of-scope site (DEFRA) → update 404.
        let r = slo_update(
            AuthExtractor(scoped()),
            Path(defra_id.clone()),
            Json(hijack()),
        )
        .await;
        assert!(
            matches!(r, Err((StatusCode::NOT_FOUND, _))),
            "out-of-scope DEFRA update must 404: {r:?}"
        );
        // Platform-wide (site NULL) → update 404 for a site-scoped principal.
        let r = slo_update(
            AuthExtractor(scoped()),
            Path(global_id.clone()),
            Json(hijack()),
        )
        .await;
        assert!(
            matches!(r, Err((StatusCode::NOT_FOUND, _))),
            "platform-wide update must 404 for a scoped principal: {r:?}"
        );
        // Out-of-scope delete → 404.
        let r = slo_delete(AuthExtractor(scoped()), Path(defra_id.clone())).await;
        assert!(
            matches!(r, Err((StatusCode::NOT_FOUND, _))),
            "out-of-scope DEFRA delete must 404: {r:?}"
        );

        // Neither denied row was mutated or removed.
        let (defra_name,): (String,) =
            sqlx::query_as("SELECT name FROM slo_definitions WHERE id = $1")
                .bind(&defra_id)
                .fetch_one(pool)
                .await
                .expect("DEFRA slo must still exist");
        assert_eq!(defra_name, "scope-defra", "DEFRA slo must be unmutated");
        let (global_name,): (String,) =
            sqlx::query_as("SELECT name FROM slo_definitions WHERE id = $1")
                .bind(&global_id)
                .fetch_one(pool)
                .await
                .expect("platform-wide slo must still exist");
        assert_eq!(
            global_name, "scope-global",
            "platform-wide slo must be unmutated"
        );

        // Positive: in-scope GBLON row updates fine for the scoped principal.
        let ok = slo_update(
            AuthExtractor(scoped()),
            Path(gblon_id.clone()),
            Json(SloUpdateRequest {
                name: Some("scope-gblon-renamed".into()),
                target: None,
                window_days: None,
                enabled: None,
            }),
        )
        .await
        .expect("in-scope GBLON update must succeed");
        assert_eq!(ok.0["updated"], json!(gblon_id));

        for (id, _) in &ids {
            sqlx::query("DELETE FROM slo_definitions WHERE id = $1")
                .bind(id)
                .execute(pool)
                .await
                .ok();
        }
    }

    /// #29: GET /api/observe/monitoring-review-queue reads the seeded
    /// `monitoring_review_queue` table (previously dead persistence) and applies
    /// site scope — a GBLON-scoped principal sees only GBLON rows.
    #[tokio::test]
    async fn monitoring_review_queue_list_reads_seeded_rows_site_scoped() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(_pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        // Unrestricted admin sees the seeded rows (mig 031 seeds DEFRA + GBLON).
        let all = monitoring_review_queue_list(
            AuthExtractor(AuthSession::static_dry_run()),
            Query(AdminListPage {
                limit: None,
                offset: None,
            }),
        )
        .await
        .expect("list must succeed");
        assert_eq!(all.0["durable"], json!(true));
        let items = all.0["items"].as_array().expect("items array");
        assert!(
            items.len() >= 3,
            "seeded monitoring-review rows must be returned, got {}",
            items.len()
        );
        // #14: total is the full (scope-filtered) count; the default page holds all.
        let total = all.0["total"].as_i64().expect("total is i64");
        assert_eq!(
            total,
            items.len() as i64,
            "#14: total equals the returned page at seed scale"
        );

        // #14: limit bounds the page but the total is unchanged by the limit.
        let page = monitoring_review_queue_list(
            AuthExtractor(AuthSession::static_dry_run()),
            Query(AdminListPage {
                limit: Some(1),
                offset: None,
            }),
        )
        .await
        .expect("limited list must succeed");
        assert_eq!(
            page.0["items"].as_array().expect("items array").len(),
            1,
            "limit=1 must bound the page to one row"
        );
        assert_eq!(
            page.0["total"].as_i64().expect("total is i64"),
            total,
            "#14: limit must NOT change the reported total"
        );

        // A GBLON-scoped principal sees only GBLON rows (SQL scope push-down).
        let mut gblon = AuthSession::static_dry_run();
        gblon.site_scope = vec!["GBLON".into()];
        let scoped = monitoring_review_queue_list(
            AuthExtractor(gblon),
            Query(AdminListPage {
                limit: None,
                offset: None,
            }),
        )
        .await
        .expect("scoped list must succeed");
        let scoped_items = scoped.0["items"].as_array().expect("scoped items array");
        // Non-empty guard (mig 031 seeds a GBLON row): without it, the two checks
        // below would false-green on an empty result (Codex).
        assert!(
            !scoped_items.is_empty(),
            "a GBLON-scoped principal must see the seeded GBLON row(s)"
        );
        assert!(
            scoped_items.iter().all(|i| i["site"] == json!("GBLON")),
            "a GBLON-scoped principal must see only GBLON rows: {scoped_items:?}"
        );
        // The scoped total must match the scoped page (count uses the SAME WHERE).
        assert_eq!(
            scoped.0["total"].as_i64().expect("scoped total is i64"),
            scoped_items.len() as i64,
            "#14: scoped total equals the scoped page (site = ANY WHERE)"
        );
    }

    /// #41: GET /api/operations/failure-patterns reads the seeded
    /// `failure_patterns` table (previously dead persistence), most-frequent
    /// first, and projects the non-body fields.
    #[tokio::test]
    async fn failure_patterns_list_reads_seeded_rows() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(_pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let resp = failure_patterns_list(
            AuthExtractor(AuthSession::static_dry_run()),
            Query(AdminListPage {
                limit: None,
                offset: None,
            }),
        )
        .await
        .expect("list must succeed");
        assert_eq!(resp.0["durable"], json!(true));
        let patterns = resp.0["patterns"].as_array().expect("patterns array");
        // #14: total matches the returned page (all seed rows fit the default page).
        assert_eq!(
            resp.0["total"].as_i64().expect("total is i64"),
            patterns.len() as i64,
            "#14: total equals the returned page length at seed scale"
        );
        assert!(
            !patterns.is_empty(),
            "seeded failure_patterns rows must be returned"
        );
        // Ordered by occurrence_count DESC.
        let counts: Vec<i64> = patterns
            .iter()
            .filter_map(|p| p["occurrence_count"].as_i64())
            .collect();
        assert!(
            counts.windows(2).all(|w| w[0] >= w[1]),
            "patterns must be ordered by occurrence_count DESC: {counts:?}"
        );
        // The (potentially long) article body is intentionally not in the list.
        assert!(
            patterns[0].get("suggested_article_body").is_none(),
            "the article body must be omitted from the list projection"
        );
    }

