    /// #4: approval quorum evaluates the real `request_approval_decisions` ledger —
    /// met with two distinct approving roles+actors, not met when short of the
    /// role threshold, and 404 for an unknown request.
    #[tokio::test]
    async fn approval_quorum_evaluates_real_decisions() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let id = seed_planned_empty_route(pool).await;

        sqlx::query(
            "INSERT INTO request_approval_decisions \
                 (request_id, approval_epoch, role, decision, actor) \
             SELECT r.id, r.approval_epoch, d.role, d.decision, d.actor \
             FROM requests AS r \
             CROSS JOIN (VALUES \
                 ('DatacenterApprover', 'approved', 'alice'), \
                 ('PlatformAdmin', 'approved', 'bob') \
             ) AS d(role, decision, actor) \
             WHERE r.id = $1",
        )
        .bind(id)
        .execute(pool)
        .await
        .expect("seed decisions");

        let session = AuthSession::static_dry_run();
        let q = |rr: usize, ra: usize| ApprovalQuorumQuery {
            required_roles: Some(rr),
            required_approvers: Some(ra),
        };
        let cleanup = |pool: &'static PgPool| async move {
            sqlx::query("SELECT purge_request_approval_decisions_for_maintenance($1)")
                .bind(id)
                .execute(pool)
                .await
                .ok();
            cleanup_request(pool, id).await;
        };

        // 2 roles / 2 approvers → met.
        let Ok(Json(body)) = requests_approval_quorum(
            AuthExtractor(session.clone()),
            Path(id.to_string()),
            Query(q(2, 2)),
        )
        .await
        else {
            cleanup(pool).await;
            panic!("quorum handler failed");
        };
        assert_eq!(body["quorum_met"], serde_json::json!(true));
        assert_eq!(body["approved_roles"], serde_json::json!(2));
        assert_eq!(body["distinct_approvers"], serde_json::json!(2));
        assert_eq!(body["durable"], serde_json::json!(true));
        assert_eq!(body["approval_epoch"], serde_json::json!(1));

        // Require 3 distinct roles → not met.
        let Ok(Json(body3)) = requests_approval_quorum(
            AuthExtractor(session.clone()),
            Path(id.to_string()),
            Query(q(3, 2)),
        )
        .await
        else {
            cleanup(pool).await;
            panic!("quorum handler failed");
        };
        assert_eq!(body3["quorum_met"], serde_json::json!(false));

        // Unknown request → 404.
        let err = requests_approval_quorum(
            AuthExtractor(session.clone()),
            Path(Uuid::new_v4().to_string()),
            Query(q(2, 2)),
        )
        .await
        .expect_err("unknown request must 404");
        assert_eq!(err.0, StatusCode::NOT_FOUND);

        cleanup(pool).await;
    }

    /// GET approval-decisions returns the full ledger (role/decision/actor/decided_at/
    /// reason) in DETERMINISTIC order — decided_at ASC, then BIGSERIAL id ASC as the
    /// tie-breaker for same-transaction timestamps (codex). reason is NULL for the
    /// approve and present for the reject; durable:true; unknown request → 404.
    #[tokio::test]
    async fn approval_decisions_returns_ledger_ordered_with_reasons() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let id = seed_planned_empty_route(pool).await;
        // Two decisions in ONE tx share decided_at (Postgres now() is tx-scoped), so
        // the id tie-breaker decides order: the approve (inserted first → lower id →
        // NULL reason) precedes the reject (present reason). This exercises exactly the
        // deterministic-ordering fix codex required.
        sqlx::query(
            "INSERT INTO request_approval_decisions \
                 (request_id, approval_epoch, role, decision, actor, reason) \
             SELECT r.id, r.approval_epoch, d.role, d.decision, d.actor, d.reason \
             FROM requests AS r \
             CROSS JOIN (VALUES \
                 ('DatacenterApprover', 'approved', 'alice', NULL::text), \
                 ('PlatformAdmin', 'rejected', 'bob', 'insufficient change window') \
             ) AS d(role, decision, actor, reason) \
             WHERE r.id = $1",
        )
        .bind(id)
        .execute(pool)
        .await
        .expect("seed decisions");

        let cleanup = |pool: &'static PgPool| async move {
            sqlx::query("SELECT purge_request_approval_decisions_for_maintenance($1)")
                .bind(id)
                .execute(pool)
                .await
                .ok();
            cleanup_request(pool, id).await;
        };

        let Ok(Json(body)) = requests_approval_decisions(
            AuthExtractor(dc_approver_session("alice")),
            Path(id.to_string()),
        )
        .await
        else {
            cleanup(pool).await;
            panic!("approval-decisions handler failed");
        };
        assert_eq!(body["durable"], serde_json::json!(true));
        assert_eq!(body["current_approval_epoch"], serde_json::json!(1));
        let decisions = body["decisions"].as_array().expect("decisions array");
        assert_eq!(decisions.len(), 2, "both decisions returned");
        assert!(decisions.iter().all(|d| d["approval_epoch"] == json!(1)));
        assert!(decisions.iter().all(|d| d["current"] == json!(true)));
        // Deterministic: the approve (lower id) is first, the reject second.
        assert_eq!(
            decisions[0]["role"],
            serde_json::json!("DatacenterApprover")
        );
        assert_eq!(decisions[0]["decision"], serde_json::json!("approved"));
        assert_eq!(decisions[0]["actor"], serde_json::json!("alice"));
        assert_eq!(
            decisions[0]["reason"],
            serde_json::Value::Null,
            "approve reason is null"
        );
        assert!(
            decisions[0]["decided_at"].as_str().is_some(),
            "decided_at present as rfc3339"
        );
        assert_eq!(decisions[1]["decision"], serde_json::json!("rejected"));
        assert_eq!(
            decisions[1]["reason"],
            serde_json::json!("insufficient change window")
        );
        // codex: make the tie-breaker premise EXPLICIT — both rows were inserted in
        // one tx so they share decided_at; the deterministic [approve, reject] order
        // therefore comes from the BIGSERIAL id ASC tie-breaker, not from timestamps.
        assert_eq!(
            decisions[0]["decided_at"], decisions[1]["decided_at"],
            "same-tx decisions share decided_at — id is the deciding tie-breaker"
        );

        // Unknown request → 404.
        let err = requests_approval_decisions(
            AuthExtractor(dc_approver_session("alice")),
            Path(Uuid::new_v4().to_string()),
        )
        .await
        .expect_err("unknown request must 404");
        assert_eq!(err.0, StatusCode::NOT_FOUND);

        cleanup(pool).await;
    }

    /// An existing, in-scope request with NO decisions → {decisions:[], durable:true}
