    /// An unrelated schema may legitimately reuse a constraint name. Migration
    /// installation guards must identify the target relation and namespace,
    /// otherwise a decoy constraint can suppress the real approval boundary.
    #[tokio::test]
    async fn migration_174_constraint_guards_ignore_cross_schema_name_collisions() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let sql = std::fs::read_to_string(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../migrations/174_request_approval_lifecycle_epoch.sql"
        ))
        .expect("read migration 174");
        let schema = format!("approval_epoch_decoy_{}", Uuid::new_v4().simple());
        let mut tx = pool.begin().await.expect("begin constraint-collision test");

        sqlx::raw_sql(&format!(
            "CREATE SCHEMA {schema};
             CREATE TABLE {schema}.requests (
                 approval_epoch BIGINT
                     CONSTRAINT requests_approval_epoch_positive CHECK (approval_epoch > 0)
             );
             CREATE TABLE {schema}.request_approval_decisions (
                 request_id UUID NOT NULL,
                 approval_epoch BIGINT
                     CONSTRAINT request_approval_decisions_epoch_positive
                     CHECK (approval_epoch > 0),
                 role TEXT NOT NULL,
                 CONSTRAINT uq_request_approval_epoch_role
                     UNIQUE (request_id, approval_epoch, role)
             );
             ALTER TABLE public.requests
                 DROP CONSTRAINT IF EXISTS requests_approval_epoch_positive;
             ALTER TABLE public.request_approval_decisions
                 DROP CONSTRAINT IF EXISTS request_approval_decisions_epoch_positive;
             ALTER TABLE public.request_approval_decisions
                 DROP CONSTRAINT IF EXISTS uq_request_approval_epoch_role;"
        ))
        .execute(&mut *tx)
        .await
        .expect("install cross-schema decoys and remove target constraints");

        sqlx::raw_sql(&sql)
            .execute(&mut *tx)
            .await
            .expect("migration must install target constraints despite decoys");

        let target_constraints: i64 = sqlx::query_scalar(
            "SELECT COUNT(*)
             FROM pg_constraint AS constraint_catalog
             WHERE constraint_catalog.connamespace = 'public'::regnamespace
               AND (
                    (constraint_catalog.conrelid = 'public.requests'::regclass
                     AND constraint_catalog.conname = 'requests_approval_epoch_positive')
                 OR (constraint_catalog.conrelid =
                         'public.request_approval_decisions'::regclass
                     AND constraint_catalog.conname IN (
                         'request_approval_decisions_epoch_positive',
                         'uq_request_approval_epoch_role'
                     ))
               )",
        )
        .fetch_one(&mut *tx)
        .await
        .expect("inspect target approval constraints");
        assert_eq!(target_constraints, 3);

        tx.rollback()
            .await
            .expect("roll back constraint-collision fixture");
    }

    #[tokio::test]
    async fn request_resource_version_is_database_owned_monotonic_and_fail_closed() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let mut tx = pool.begin().await.expect("begin resource-version test");
        sqlx::query("SET LOCAL ryuki.force_request_runtime_contract = 'runtime-v1'")
            .execute(&mut *tx)
            .await
            .expect("force the production request-resource branch");
        let id = Uuid::new_v4();

        let inserted_version: i64 = sqlx::query_scalar(
            "INSERT INTO requests \
                 (id, request_type, status, stage, site, environment, name, cpu, \
                  memory_gb, created_by, requester, owner, resource_version) \
             VALUES ($1, 'server-deployment', 'intake', 'intake', 'DEFRA', \
                     'production', 'resource-version-fixture', 2, 4, \
                     'version-maker', 'version-maker', 'version-maker', 99) \
             RETURNING resource_version",
        )
        .bind(id)
        .fetch_one(&mut *tx)
        .await
        .expect("database normalizes a caller-selected insert version");
        assert_eq!(inserted_version, 1);

        let advanced_version: i64 = sqlx::query_scalar(
            "UPDATE requests SET name = 'resource-version-advanced', updated_at = NOW() \
             WHERE id = $1 RETURNING resource_version",
        )
        .bind(id)
        .fetch_one(&mut *tx)
        .await
        .expect("meaningful request update advances the version");
        assert_eq!(advanced_version, 2);

        let timestamp_only_version: i64 = sqlx::query_scalar(
            "UPDATE requests SET updated_at = updated_at + INTERVAL '1 second' \
             WHERE id = $1 RETURNING resource_version",
        )
        .bind(id)
        .fetch_one(&mut *tx)
        .await
        .expect("bookkeeping-only update remains admissible");
        assert_eq!(timestamp_only_version, 2);

        sqlx::query("SAVEPOINT caller_version_reuse")
            .execute(&mut *tx)
            .await
            .expect("savepoint caller version reuse");
        let reuse =
            sqlx::query("UPDATE requests SET resource_version = resource_version WHERE id = $1")
                .bind(id)
                .execute(&mut *tx)
                .await
                .expect_err("even a same-value caller assignment must be rejected");
        assert!(reuse
            .to_string()
            .contains("request resource_version is database-managed"));
        sqlx::query("ROLLBACK TO SAVEPOINT caller_version_reuse")
            .execute(&mut *tx)
            .await
            .expect("recover caller version reuse");

        sqlx::query("SAVEPOINT caller_version_rollback")
            .execute(&mut *tx)
            .await
            .expect("savepoint caller version rollback");
        let rollback = sqlx::query("UPDATE requests SET resource_version = 1 WHERE id = $1")
            .bind(id)
            .execute(&mut *tx)
            .await
            .expect_err("a caller cannot roll the version back");
        assert!(rollback
            .to_string()
            .contains("request resource_version is database-managed"));
        sqlx::query("ROLLBACK TO SAVEPOINT caller_version_rollback")
            .execute(&mut *tx)
            .await
            .expect("recover caller version rollback");
        let guarded_version: i64 =
            sqlx::query_scalar("SELECT resource_version FROM requests WHERE id = $1")
                .bind(id)
                .fetch_one(&mut *tx)
                .await
                .expect("read caller-guarded version");
        assert_eq!(guarded_version, 2);

        sqlx::query("SAVEPOINT request_resource_delete")
            .execute(&mut *tx)
            .await
            .expect("savepoint request resource delete");
        let deletion = sqlx::query("DELETE FROM requests WHERE id = $1")
            .bind(id)
            .execute(&mut *tx)
            .await
            .expect_err("the runtime cannot delete and recreate a canonical request id");
        assert!(deletion
            .to_string()
            .contains("cannot be deleted or truncated by the runtime"));
        sqlx::query("ROLLBACK TO SAVEPOINT request_resource_delete")
            .execute(&mut *tx)
            .await
            .expect("recover request resource delete");

        // Exercise the installed trigger function against an isolated terminal
        // BIGINT fixture. The live requests row remains protected by its
        // database-owned trigger throughout the test.
        sqlx::raw_sql(
            "CREATE TEMPORARY TABLE request_resource_version_overflow_fixture (
                 name TEXT NOT NULL,
                 updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                 resource_version BIGINT NOT NULL CHECK (resource_version > 0)
             ) ON COMMIT DROP;
             INSERT INTO request_resource_version_overflow_fixture (name, resource_version)
             VALUES ('resource-version-advanced', 9223372036854775807);
             CREATE TRIGGER request_resource_version_overflow_fixture_advance
             BEFORE UPDATE ON request_resource_version_overflow_fixture
             FOR EACH ROW EXECUTE FUNCTION advance_request_resource_version();",
        )
        .execute(&mut *tx)
        .await
        .expect("install isolated overflow fixture");

        sqlx::query("SAVEPOINT resource_version_overflow")
            .execute(&mut *tx)
            .await
            .expect("savepoint resource version overflow");
        let overflow = sqlx::query(
            "UPDATE request_resource_version_overflow_fixture
             SET name = 'resource-version-must-not-wrap'",
        )
        .execute(&mut *tx)
        .await
        .expect_err("an exhausted version must fail the meaningful update");
        assert!(overflow
            .to_string()
            .contains("request resource_version exhausted"));
        sqlx::query("ROLLBACK TO SAVEPOINT resource_version_overflow")
            .execute(&mut *tx)
            .await
            .expect("recover resource version overflow");
        let preserved: (String, i64) = sqlx::query_as(
            "SELECT name, resource_version FROM request_resource_version_overflow_fixture",
        )
        .fetch_one(&mut *tx)
        .await
        .expect("read preserved overflow fixture");
        assert_eq!(
            preserved,
            ("resource-version-advanced".into(), i64::MAX),
            "overflow must preserve both state and the terminal version"
        );

        tx.rollback()
            .await
            .expect("roll back resource-version fixtures");
    }

    #[tokio::test]
    async fn approval_decision_identity_and_history_are_database_immutable() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let original_name = format!("immutable-original-{}", Uuid::new_v4());
        let other_name = format!("immutable-other-{}", Uuid::new_v4());
        let original_request = seed_planned(pool, &original_name).await;
        let other_request = seed_planned(pool, &other_name).await;

        sqlx::query(
            "INSERT INTO request_approval_decisions \
                 (request_id, approval_epoch, role, decision, actor, decided_at) \
             SELECT id, approval_epoch, 'DatacenterApprover', 'approved', 'immutable-test', \
                    TIMESTAMPTZ '2000-01-01 00:00:00+00' \
             FROM requests WHERE id = $1",
        )
        .bind(original_request)
        .execute(pool)
        .await
        .expect("seed immutable approval decision");

        let database_decided_at: chrono::DateTime<chrono::Utc> = sqlx::query_scalar(
            "SELECT decided_at FROM request_approval_decisions \
             WHERE request_id = $1 AND role = 'DatacenterApprover'",
        )
        .bind(original_request)
        .fetch_one(pool)
        .await
        .expect("read database-owned approval time");
        assert!(
            database_decided_at
                > chrono::DateTime::parse_from_rfc3339("2020-01-01T00:00:00Z")
                    .expect("static timestamp")
                    .with_timezone(&chrono::Utc),
            "the trigger must replace caller-supplied decision time"
        );

        let rekey = sqlx::query(
            "UPDATE request_approval_decisions SET request_id = $2 \
             WHERE request_id = $1 AND role = 'DatacenterApprover'",
        )
        .bind(original_request)
        .bind(other_request)
        .execute(pool)
        .await
        .expect_err("an approval decision cannot be retargeted to another request");
        assert!(rekey
            .to_string()
            .contains("approval decision identity is immutable"));

        let rewrite = sqlx::query(
            "UPDATE request_approval_decisions \
             SET decision = 'rejected', actor = 'replacement-actor', \
                 decided_at = TIMESTAMPTZ '2000-01-01 00:00:00+00', \
                 reason = 'rewritten evidence' \
             WHERE request_id = $1 AND role = 'DatacenterApprover'",
        )
        .bind(original_request)
        .execute(pool)
        .await
        .expect_err("decision, actor, time, and reason are immutable evidence");
        assert!(rewrite
            .to_string()
            .contains("approval decision evidence is immutable"));
        let preserved: (String, String, Option<String>) = sqlx::query_as(
            "SELECT decision, actor, reason FROM request_approval_decisions \
             WHERE request_id = $1 AND role = 'DatacenterApprover'",
        )
        .bind(original_request)
        .fetch_one(pool)
        .await
        .expect("read preserved approval evidence");
        assert_eq!(
            preserved,
            ("approved".into(), "immutable-test".into(), None)
        );

        let hard_delete =
            sqlx::query("DELETE FROM request_approval_decisions WHERE request_id = $1")
                .bind(original_request)
                .execute(pool)
                .await
                .expect_err("ordinary writers cannot delete approval history");
        assert!(hard_delete
            .to_string()
            .contains("approval decision history is append-only"));

        let truncate = sqlx::query("TRUNCATE TABLE request_approval_decisions")
            .execute(pool)
            .await
            .expect_err("ordinary writers cannot truncate approval history");
        assert!(truncate
            .to_string()
            .contains("approval decision history is append-only"));

        let removed: i64 =
            sqlx::query_scalar("SELECT purge_request_approval_decisions_for_maintenance($1)")
                .bind(original_request)
                .fetch_one(pool)
                .await
                .expect("schema-owner maintenance path removes the exact test row");
        assert_eq!(removed, 1);

        cleanup(pool, original_request).await;
        cleanup(pool, other_request).await;
    }

    #[tokio::test]
    async fn database_status_transition_requires_current_epoch_quorum() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let id = seed_planned_with_required_roles(pool, "database-quorum-guard", 2).await;

        let lowered_policy =
            sqlx::query("UPDATE requests SET required_approval_roles = 1 WHERE id = $1")
                .bind(id)
                .execute(pool)
                .await
                .expect_err("a Planned request cannot lower its quorum before the first decision");
        assert!(lowered_policy
            .to_string()
            .contains("reviewed request authority is immutable"));
        assert_eq!(read_row(pool, id).await.required_approval_roles, 2);

        let rewritten_maker = sqlx::query(
            "UPDATE requests SET created_by = 'replacement-maker', \
                                 requester = 'replacement-maker' \
             WHERE id = $1",
        )
        .bind(id)
        .execute(pool)
        .await
        .expect_err("request maker identity is immutable before and after review");
        assert!(rewritten_maker
            .to_string()
            .contains("request maker identity is immutable"));

        let invented_role = sqlx::query(
            "INSERT INTO request_approval_decisions \
                 (request_id, approval_epoch, role, decision, actor) \
             SELECT id, approval_epoch, 'InventedApprover', 'approved', 'invented-actor' \
             FROM requests WHERE id = $1",
        )
        .bind(id)
        .execute(pool)
        .await
        .expect_err("the durable ledger accepts only server-owned approval roles");
        assert!(invented_role
            .to_string()
            .contains("invalid canonical shape"));

        sqlx::query(
            "INSERT INTO request_approval_decisions \
                 (request_id, approval_epoch, role, decision, actor) \
             SELECT id, approval_epoch, 'DatacenterApprover', 'approved', \
                    'database-quorum-first-actor' \
             FROM requests WHERE id = $1",
        )
        .bind(id)
        .execute(pool)
        .await
        .expect("seed one canonical current-epoch decision");

        let bypass = sqlx::query(
            "UPDATE requests SET status = 'approved', updated_at = NOW() WHERE id = $1",
        )
        .bind(id)
        .execute(pool)
        .await
        .expect_err("direct Planned -> Approved must not bypass the required quorum");
        assert!(bypass
            .to_string()
            .contains("current-epoch role and actor quorum"));
        assert_eq!(read_row(pool, id).await.status, "planned");

        sqlx::query(
            "INSERT INTO request_approval_decisions \
                 (request_id, approval_epoch, role, decision, actor) \
             SELECT id, approval_epoch, 'PlatformAdmin', 'approved', \
                    'database-quorum-first-actor' \
             FROM requests WHERE id = $1",
        )
        .bind(id)
        .execute(pool)
        .await
        .expect("seed a second canonical role held by the same actor");

        let skipped_state =
            sqlx::query("UPDATE requests SET status = 'locked', updated_at = NOW() WHERE id = $1")
                .bind(id)
                .execute(pool)
                .await
                .expect_err("Planned -> Locked must not skip the approved predecessor");
        assert!(skipped_state
            .to_string()
            .contains("locked state may be entered only from approved"));

        let same_actor = sqlx::query(
            "UPDATE requests SET status = 'approved', updated_at = NOW() WHERE id = $1",
        )
        .bind(id)
        .execute(pool)
        .await
        .expect_err("two canonical roles held by one actor are not a two-party quorum");
        assert!(same_actor
            .to_string()
            .contains("current-epoch role and actor quorum"));
        assert_eq!(read_row(pool, id).await.status, "planned");

        cleanup(pool, id).await;
    }

