    // -------------------------------------------------------------------------
    // Async wrapper smoke tests (enrich_plan_stages_with_terraform /
    // enrich_verify_stages_with_ansible) — exercises the PRODUCTION path end-to-end.
    //
    // Uses `runner.available()` to branch deterministically: passes in CI
    // without the binaries AND locally with them.
    // -------------------------------------------------------------------------

    async fn wait_for_runner_flag(flag: &std::sync::atomic::AtomicBool, label: &str) {
        tokio::time::timeout(std::time::Duration::from_secs(2), async {
            while !flag.load(std::sync::atomic::Ordering::Acquire) {
                tokio::time::sleep(std::time::Duration::from_millis(5)).await;
            }
        })
        .await
        .unwrap_or_else(|_| panic!("timed out waiting for {label}"));
    }

    #[tokio::test]
    async fn terraform_enrichment_timeout_cancels_worker_and_retains_admission_until_cleanup() {
        use std::sync::{
            atomic::{AtomicBool, Ordering},
            Arc,
        };

        let admission = Arc::new(tokio::sync::Semaphore::new(1));
        let worker_admission = Arc::clone(&admission);
        let started = Arc::new(AtomicBool::new(false));
        let cancellation_seen = Arc::new(AtomicBool::new(false));
        let cleanup_done = Arc::new(AtomicBool::new(false));
        let worker_started = Arc::clone(&started);
        let worker_cancellation_seen = Arc::clone(&cancellation_seen);
        let worker_cleanup_done = Arc::clone(&cleanup_done);

        let timed_out = tokio::time::timeout(
            std::time::Duration::from_millis(100),
            run_cancellable_terraform_blocking(admission.clone(), move |cancellation| {
                worker_started.store(true, Ordering::Release);
                let deadline = std::time::Instant::now() + std::time::Duration::from_secs(2);
                while !cancellation.is_cancelled() {
                    assert!(
                        std::time::Instant::now() < deadline,
                        "timed-out request must signal its blocking worker"
                    );
                    std::thread::sleep(std::time::Duration::from_millis(5));
                }
                worker_cancellation_seen.store(true, Ordering::Release);

                // Model the runner supervisor's bounded kill/reap/drain tail.
                // The permit is owned by this closure and cannot be recycled
                // while that cleanup is still in progress.
                assert_eq!(worker_admission.available_permits(), 0);
                std::thread::sleep(std::time::Duration::from_millis(150));
                assert_eq!(worker_admission.available_permits(), 0);
                worker_cleanup_done.store(true, Ordering::Release);
            }),
        )
        .await;

        assert!(timed_out.is_err(), "synthetic HTTP deadline must elapse");
        wait_for_runner_flag(&started, "Terraform worker start").await;
        wait_for_runner_flag(&cancellation_seen, "Terraform worker cancellation").await;
        assert_eq!(
            admission.available_permits(),
            0,
            "request timeout must not release runner admission during cleanup"
        );
        wait_for_runner_flag(&cleanup_done, "Terraform worker cleanup").await;
        tokio::time::timeout(std::time::Duration::from_secs(2), async {
            while admission.available_permits() != 1 {
                tokio::time::sleep(std::time::Duration::from_millis(5)).await;
            }
        })
        .await
        .expect("runner admission must release after cleanup returns");
    }

    #[tokio::test]
    async fn dropping_terraform_enrichment_owner_uses_the_same_cancellation_path() {
        use std::sync::{
            atomic::{AtomicBool, Ordering},
            Arc,
        };

        let admission = Arc::new(tokio::sync::Semaphore::new(1));
        let started = Arc::new(AtomicBool::new(false));
        let cancellation_seen = Arc::new(AtomicBool::new(false));
        let worker_started = Arc::clone(&started);
        let worker_cancellation_seen = Arc::clone(&cancellation_seen);

        let owner = tokio::spawn(run_cancellable_terraform_blocking(
            Arc::clone(&admission),
            move |cancellation| {
                worker_started.store(true, Ordering::Release);
                let deadline = std::time::Instant::now() + std::time::Duration::from_secs(2);
                while !cancellation.is_cancelled() {
                    assert!(
                        std::time::Instant::now() < deadline,
                        "dropped request owner must signal its blocking worker"
                    );
                    std::thread::sleep(std::time::Duration::from_millis(5));
                }
                worker_cancellation_seen.store(true, Ordering::Release);
            },
        ));

        wait_for_runner_flag(&started, "Terraform worker start").await;
        owner.abort();
        assert!(
            owner
                .await
                .expect_err("owner task must be cancelled")
                .is_cancelled(),
            "task abort models a dropped handler/client disconnect"
        );
        wait_for_runner_flag(&cancellation_seen, "Terraform worker cancellation").await;
        tokio::time::timeout(std::time::Duration::from_secs(2), async {
            while admission.available_permits() != 1 {
                tokio::time::sleep(std::time::Duration::from_millis(5)).await;
            }
        })
        .await
        .expect("dropped-owner worker must release admission after returning");
    }

    #[tokio::test]
    async fn fast_terraform_enrichment_completes_without_spurious_cancellation() {
        let admission = std::sync::Arc::new(tokio::sync::Semaphore::new(1));
        let result =
            run_cancellable_terraform_blocking(std::sync::Arc::clone(&admission), |cancellation| {
                assert!(!cancellation.is_cancelled());
                42_u8
            })
            .await
            .expect("fast blocking worker must join successfully");

        assert_eq!(result, 42);
        assert_eq!(admission.available_permits(), 1);
    }

