    /// A legacy metadata-only row is quarantined and excluded from both the
    /// common NOT EXISTS predicate and the resource unique index. If a reviewer
    /// later maps that legacy row onto an already-open tuple, the release fails
    /// atomically and its review remains pending for collision resolution.
    #[tokio::test]
    async fn shift_legacy_quarantine_never_suppresses_verified_resource_work() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set");
            return;
        };
        let item_type = format!("legacy-suppression-test-{}", Uuid::new_v4());
        let source_ci_key = format!("source-{}", Uuid::new_v4());
        let legacy_id = Uuid::new_v4();
        let metadata = json!({
            "source_ci_key": &source_ci_key,
            "site": "DEFRA",
            "environment": "production",
        })
        .to_string();
        sqlx::query(
            "INSERT INTO shift_queue (id, item_type, title, description, priority, metadata) \
             VALUES ($1, $2, 'legacy', 'legacy metadata-only writer', 'P3', $3::jsonb)",
        )
        .bind(legacy_id)
        .bind(&item_type)
        .bind(&metadata)
        .execute(pool)
        .await
        .expect("seed quarantined legacy row");

        let inserted = crate::repos::shift_queue::enqueue_if_absent(
            pool,
            &item_type,
            &source_ci_key,
            crate::repos::shift_queue::ShiftQueueAuthority::Resource {
                site: "DEFRA",
                environment: Some("production"),
            },
            "verified resource",
            "verified resource",
            "P2",
            &metadata,
        )
        .await
        .expect("legacy quarantine must not suppress resource work");
        assert_eq!(inserted, 1);

        let visibilities: Vec<String> = sqlx::query_scalar(
            "SELECT visibility_kind FROM shift_queue WHERE item_type = $1 \
             ORDER BY visibility_kind",
        )
        .bind(&item_type)
        .fetch_all(pool)
        .await
        .expect("read legacy and verified rows");
        assert_eq!(
            visibilities,
            vec!["quarantined".to_string(), "resource".to_string()]
        );

        sqlx::query(
            "UPDATE shift_queue_scope_reconciliation_reviews \
             SET approved_visibility_kind = 'resource', approved_source_ci_key = $2, \
                 approved_site = 'DEFRA', approved_environment = 'production', \
                 reviewed_by = 'scope-reviewer', review_reason = 'verified source mapping', \
                 reviewed_at = clock_timestamp() \
             WHERE shift_queue_id = $1",
        )
        .bind(legacy_id)
        .bind(&source_ci_key)
        .execute(pool)
        .await
        .expect("record reviewed legacy mapping");
        let collision = sqlx::query(
            "UPDATE shift_queue \
             SET visibility_kind = 'resource', source_ci_key = $2, site = 'DEFRA', \
                 environment = 'production', scope_provenance = 'reviewed-reconciliation-v1' \
             WHERE id = $1",
        )
        .bind(legacy_id)
        .bind(&source_ci_key)
        .execute(pool)
        .await;
        let collision = collision.expect_err("reviewed duplicate authority must collide");
        assert_eq!(
            collision
                .as_database_error()
                .and_then(|error| error.code())
                .as_deref(),
            Some("23505")
        );
        let review_applied: Option<chrono::DateTime<chrono::Utc>> = sqlx::query_scalar(
            "SELECT applied_at FROM shift_queue_scope_reconciliation_reviews \
             WHERE shift_queue_id = $1",
        )
        .bind(legacy_id)
        .fetch_one(pool)
        .await
        .expect("read pending collision review");
        assert!(review_applied.is_none());

        sqlx::query("DELETE FROM shift_queue WHERE item_type = $1")
            .bind(&item_type)
            .execute(pool)
            .await
            .expect("cleanup legacy suppression rows");
    }

