    #[tokio::test]
    async fn test_audit_failure_rolls_back_access_review_start() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set");
            return;
        };
        let id = Uuid::new_v4().to_string();
        let actor = format!("dbtest-audit-failure-{}", Uuid::new_v4());
        let actor_principal = caller_principal(&actor);
        seed_review(pool, &id, "Pending", None).await;
        let before_updated_at: chrono::DateTime<chrono::Utc> =
            sqlx::query_scalar("SELECT updated_at FROM access_reviews WHERE id = $1::uuid")
                .bind(&id)
                .fetch_one(pool)
                .await
                .expect("pre-state updated_at");

        install_audit_failure_trigger(pool).await;
        let result = access_review_start(Path(id.clone()), Extension(caller_session(&actor))).await;
        remove_audit_failure_trigger(pool).await;

        let (reviewer, status, after_updated_at): (
            Option<String>,
            String,
            chrono::DateTime<chrono::Utc>,
        ) = sqlx::query_as(
            "SELECT reviewer, status, updated_at FROM access_reviews WHERE id = $1::uuid",
        )
        .bind(&id)
        .fetch_one(pool)
        .await
        .expect("post-state access review");
        let audit_count: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM audit_log \
             WHERE actor_principal = $1 AND action = 'access-review-start'",
        )
        .bind(&actor_principal)
        .fetch_one(pool)
        .await
        .expect("count rejected audit rows");

        assert!(matches!(
            result,
            Err((StatusCode::INTERNAL_SERVER_ERROR, _))
        ));
        assert_eq!(status, "Pending", "domain state must roll back");
        assert_eq!(reviewer, None, "reviewer attribution must roll back");
        assert_eq!(
            after_updated_at, before_updated_at,
            "updated_at must roll back with the failed audit append"
        );
        assert_eq!(audit_count, 0, "the rejected audit row must not persist");
        cleanup_review(pool, &id).await;
    }

