    /// C282: application status writers acquire the authority lock in a
    /// separate statement, before their mutating statement receives its READ
    /// COMMITTED snapshot. If a registry cutover already owns that lock, both
    /// suppress and resolve wait, then observe the new generation and fail
    /// closed instead of mutating the now-stale row.
    #[tokio::test]
    async fn noise_status_writers_refresh_generation_after_registry_cutover() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set");
            return;
        };
        drain_noise_reconciliation(pool).await;
        let tag = Uuid::new_v4().simple().to_string().to_ascii_uppercase();
        let site = format!("NW{}", &tag[..8]);
        let trigger_id = Uuid::new_v4();
        sqlx::query(
            "INSERT INTO site_registry \
             (unlocode, code_system, name, country, country_code, timezone, active) \
             VALUES ($1, 'custom', $2, 'Test country', 'ZZ', 'UTC', TRUE)",
        )
        .bind(&site)
        .bind(format!("Noise writer race site {tag}"))
        .execute(pool)
        .await
        .expect("register writer-race site");
        drain_noise_reconciliation(pool).await;
        sqlx::query(
            "INSERT INTO noisy_triggers \
             (id, trigger_name, host, severity, event_count_last_24h, \
              avg_interval_minutes, flapping, suggested_action, status) \
             VALUES ($1, $2, $3, 'warning', 20, 5.0, FALSE, 'review', 'Active')",
        )
        .bind(trigger_id)
        .bind(format!("noise writer race {tag}"))
        .bind(format!("srv-{}-app01", site.to_ascii_lowercase()))
        .execute(pool)
        .await
        .expect("seed writer-race trigger");

        let mut session = AuthSession::static_dry_run();
        session.site_scope = vec![site.clone()];

        // Hold an uncommitted generation bump, then prove the real suppress
        // handler waits and rechecks against the committed generation.
        let mut registry_tx = pool.begin().await.expect("begin suppress cutover");
        sqlx::query("UPDATE site_registry SET active = FALSE WHERE unlocode = $1")
            .bind(&site)
            .execute(&mut *registry_tx)
            .await
            .expect("stage suppress cutover");
        let suppress_session = session.clone();
        let suppress_id = trigger_id.to_string();
        let (suppress_started_tx, suppress_started_rx) = tokio::sync::oneshot::channel();
        let suppress = tokio::spawn(async move {
            let _ = suppress_started_tx.send(());
            noise_suppress(
                AuthExtractor(suppress_session),
                Path(suppress_id),
                Json(NoiseSuppressRequest {
                    duration_minutes: 60,
                    reason: "must not cross the generation fence".into(),
                }),
            )
            .await
        });
        suppress_started_rx
            .await
            .expect("suppress race task started");
        tokio::time::sleep(std::time::Duration::from_millis(100)).await;
        assert!(
            !suppress.is_finished(),
            "suppress must wait for the registry authority transaction"
        );
        registry_tx.commit().await.expect("commit suppress cutover");
        let suppress_result = tokio::time::timeout(std::time::Duration::from_secs(5), suppress)
            .await
            .expect("suppress unblocks after cutover")
            .expect("suppress race task joins");
        assert!(matches!(suppress_result, Err((StatusCode::NOT_FOUND, _))));
        let after_suppress: (String, Option<String>) =
            sqlx::query_as("SELECT status, suppress_reason FROM noisy_triggers WHERE id = $1")
                .bind(trigger_id)
                .fetch_one(pool)
                .await
                .expect("read trigger after suppress race");
        assert_eq!(after_suppress, ("Active".into(), None));

        // Make the row current again, then run the same two-connection cutover
        // against the real resolve handler.
        drain_noise_reconciliation(pool).await;
        sqlx::query("UPDATE site_registry SET active = TRUE WHERE unlocode = $1")
            .bind(&site)
            .execute(pool)
            .await
            .expect("reactivate writer-race site");
        drain_noise_reconciliation(pool).await;
        let mut registry_tx = pool.begin().await.expect("begin resolve cutover");
        sqlx::query("UPDATE site_registry SET active = FALSE WHERE unlocode = $1")
            .bind(&site)
            .execute(&mut *registry_tx)
            .await
            .expect("stage resolve cutover");
        let resolve_id = trigger_id.to_string();
        let (resolve_started_tx, resolve_started_rx) = tokio::sync::oneshot::channel();
        let resolve = tokio::spawn(async move {
            let _ = resolve_started_tx.send(());
            noise_resolve(
                AuthExtractor(session),
                Path(resolve_id),
                Json(NoiseResolveRequest {
                    resolution: "must not cross the generation fence".into(),
                }),
            )
            .await
        });
        resolve_started_rx.await.expect("resolve race task started");
        tokio::time::sleep(std::time::Duration::from_millis(100)).await;
        assert!(
            !resolve.is_finished(),
            "resolve must wait for the registry authority transaction"
        );
        registry_tx.commit().await.expect("commit resolve cutover");
        let resolve_result = tokio::time::timeout(std::time::Duration::from_secs(5), resolve)
            .await
            .expect("resolve unblocks after cutover")
            .expect("resolve race task joins");
        assert!(matches!(resolve_result, Err((StatusCode::NOT_FOUND, _))));
        let after_resolve: (String, Option<String>) =
            sqlx::query_as("SELECT status, resolution FROM noisy_triggers WHERE id = $1")
                .bind(trigger_id)
                .fetch_one(pool)
                .await
                .expect("read trigger after resolve race");
        assert_eq!(after_resolve, ("Active".into(), None));

        drain_noise_reconciliation(pool).await;
        sqlx::query("DELETE FROM noisy_triggers WHERE id = $1")
            .bind(trigger_id)
            .execute(pool)
            .await
            .expect("clean writer-race trigger");
        sqlx::query("DELETE FROM site_registry WHERE unlocode = $1")
            .bind(&site)
            .execute(pool)
            .await
            .expect("clean writer-race site");
    }

    // ─── DB-gated tests ───

    // ── suppress persists status + fields ──

