    // ── canonical site authority and dynamic registry reclassification ──

    #[tokio::test]
    async fn canonical_noise_site_overrides_callers_and_tracks_active_registry() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set");
            return;
        };

        let tag = Uuid::new_v4().simple().to_string().to_ascii_uppercase();
        let short_site = format!("NS{}", &tag[..6]);
        let long_site = format!("{short_site}LONG");
        for site in [&short_site, &long_site] {
            sqlx::query(
                "INSERT INTO site_registry \
                 (unlocode, code_system, name, country, country_code, timezone, active) \
                 VALUES ($1, 'custom', $2, 'Test country', 'ZZ', 'UTC', true)",
            )
            .bind(site)
            .bind(format!("Canonical noise test {site}"))
            .execute(pool)
            .await
            .expect("register overlapping test site");
        }

        let resolved_id = Uuid::new_v4();
        let quarantined_id = Uuid::new_v4();
        let resolved_host = format!(
            "srv-{}-{}-app01.example.test",
            short_site.to_ascii_lowercase(),
            long_site.to_ascii_lowercase()
        );
        let quarantined_host = format!("srv-unregistered-{tag}.example.test");
        // Deliberately supply the wrong site for both rows. The BEFORE trigger
        // must ignore it, choose the longest active host match, and quarantine
        // the host with no active match rather than defaulting to DEFRA.
        sqlx::query(
            "INSERT INTO noisy_triggers \
             (id, trigger_name, host, severity, event_count_last_24h, \
              avg_interval_minutes, flapping, suggested_action, status, site) \
             VALUES ($1, $2, $3, 'warning', 99, 5.0, false, 'investigate', \
                     'Suppressed', 'GBLON'), \
                    ($4, $5, $6, 'warning', 99, 5.0, false, 'investigate', \
                     'Suppressed', 'GBLON')",
        )
        .bind(resolved_id)
        .bind(format!("canonical resolved {tag}"))
        .bind(&resolved_host)
        .bind(quarantined_id)
        .bind(format!("canonical quarantined {tag}"))
        .bind(&quarantined_host)
        .execute(pool)
        .await
        .expect("insert canonical and quarantined triggers");

        let resolved: (Option<String>, String) =
            sqlx::query_as("SELECT site, site_resolution FROM noisy_triggers WHERE id = $1")
                .bind(resolved_id)
                .fetch_one(pool)
                .await
                .expect("read canonical trigger authority");
        assert_eq!(
            resolved,
            (Some(long_site.clone()), "active_registry".into())
        );
        let quarantined: (Option<String>, String) =
            sqlx::query_as("SELECT site, site_resolution FROM noisy_triggers WHERE id = $1")
                .bind(quarantined_id)
                .fetch_one(pool)
                .await
                .expect("read quarantined trigger authority");
        assert_eq!(quarantined, (None, "quarantined".into()));
        assert!(matches!(
            noise_suggest(
                AuthExtractor(AuthSession::static_dry_run()),
                Path(quarantined_id.to_string())
            )
            .await,
            Err((StatusCode::NOT_FOUND, _))
        ));

        let mut short_session = AuthSession::static_dry_run();
        short_session.site_scope = vec![short_site.clone()];
        let short_read = noise_suggest(
            AuthExtractor(short_session.clone()),
            Path(resolved_id.to_string()),
        )
        .await;
        assert!(matches!(short_read, Err((StatusCode::NOT_FOUND, _))));
        let mut long_session = AuthSession::static_dry_run();
        long_session.site_scope = vec![long_site.clone()];
        assert!(
            noise_suggest(
                AuthExtractor(long_session.clone()),
                Path(resolved_id.to_string())
            )
            .await
            .is_ok(),
            "longest active registry code owns the row"
        );

        // Deactivating the longest match advances the authority generation in
        // the same statement transaction. The stale row becomes invisible
        // immediately, then the bounded worker reclassifies it to the shorter
        // active match.
        sqlx::query("UPDATE site_registry SET active = false WHERE unlocode = $1")
            .bind(&long_site)
            .execute(pool)
            .await
            .expect("deactivate longest site");
        assert!(matches!(
            noise_suggest(
                AuthExtractor(AuthSession::static_dry_run()),
                Path(resolved_id.to_string())
            )
            .await,
            Err((StatusCode::NOT_FOUND, _))
        ));
        drain_noise_reconciliation(pool).await;
        let reclassified: Option<String> =
            sqlx::query_scalar("SELECT site FROM noisy_triggers WHERE id = $1")
                .bind(resolved_id)
                .fetch_one(pool)
                .await
                .expect("read shorter classification");
        assert_eq!(reclassified.as_deref(), Some(short_site.as_str()));
        assert!(
            noise_suggest(AuthExtractor(short_session), Path(resolved_id.to_string()))
                .await
                .is_ok()
        );
        assert!(matches!(
            noise_suggest(AuthExtractor(long_session), Path(resolved_id.to_string())).await,
            Err((StatusCode::NOT_FOUND, _))
        ));

        // With no active match the row is quarantined and invisible even to an
        // unrestricted by-id read. Reactivation restores canonical ownership.
        sqlx::query("UPDATE site_registry SET active = false WHERE unlocode = $1")
            .bind(&short_site)
            .execute(pool)
            .await
            .expect("deactivate shorter site");
        drain_noise_reconciliation(pool).await;
        assert!(matches!(
            noise_suggest(
                AuthExtractor(AuthSession::static_dry_run()),
                Path(resolved_id.to_string())
            )
            .await,
            Err((StatusCode::NOT_FOUND, _))
        ));
        sqlx::query("UPDATE site_registry SET active = true WHERE unlocode = $1")
            .bind(&long_site)
            .execute(pool)
            .await
            .expect("reactivate longest site");
        drain_noise_reconciliation(pool).await;
        sqlx::query("UPDATE noisy_triggers SET site = 'GBLON' WHERE id = $1")
            .bind(resolved_id)
            .execute(pool)
            .await
            .expect("attempt caller site overwrite");
        let restored: Option<String> =
            sqlx::query_scalar("SELECT site FROM noisy_triggers WHERE id = $1")
                .bind(resolved_id)
                .fetch_one(pool)
                .await
                .expect("read restored classification");
        assert_eq!(restored.as_deref(), Some(long_site.as_str()));

        let (_, unrestricted_rows) = suppressed_page(vec![], vec![], Some(1000), None).await;
        assert!(unrestricted_rows
            .iter()
            .any(|row| row["id"] == json!(resolved_id.to_string())));
        assert!(!unrestricted_rows
            .iter()
            .any(|row| row["id"] == json!(quarantined_id.to_string())));

        sqlx::query("DELETE FROM noisy_triggers WHERE id = ANY($1)")
            .bind(vec![resolved_id, quarantined_id])
            .execute(pool)
            .await
            .expect("cleanup canonical noise rows");
        sqlx::query("DELETE FROM site_registry WHERE unlocode = ANY($1)")
            .bind(vec![short_site, long_site])
            .execute(pool)
            .await
            .expect("cleanup canonical noise sites");
    }

