    async fn global_pool() -> Option<&'static PgPool> {
        let url = std::env::var("RYUKI_DATABASE_URL").ok()?;
        crate::database::try_connect_with_url(&url, 5, 1, 300, 30, 1800).await;
        let pool = crate::database::get_db()?;
        crate::database::run_migrations(pool).await.ok()?;
        Some(pool)
    }

    async fn seed_ci(pool: &PgPool, ci_name: &str) -> (Uuid, ServiceNowEnvironmentAuthority) {
        let ci_id: Uuid = sqlx::query_scalar(
            "INSERT INTO configuration_items \
             (id, ci_name, ci_type, criticality, site, owner, environment) \
             VALUES (gen_random_uuid(), $1, 'Server', 'Low', 'DEFRA', \
                     'snow-test-team', 'test') \
             ON CONFLICT (ci_name) DO UPDATE SET \
                 site = EXCLUDED.site, owner = EXCLUDED.owner, \
                 environment = EXCLUDED.environment \
             RETURNING id",
        )
        .bind(ci_name)
        .fetch_one(pool)
        .await
        .expect("seed authoritative ServiceNow test CI");
        let existing: Option<ServiceNowEnvironmentAuthority> = sqlx::query_as(
            "SELECT id, provenance_kind, review_reference \
             FROM configuration_item_environment_authority \
             WHERE configuration_item_id = $1 AND environment = 'test'",
        )
        .bind(ci_id)
        .fetch_optional(pool)
        .await
        .expect("load reviewed ServiceNow test environment authority");
        let authority = match existing {
            Some(authority) => authority,
            None => {
                let id = Uuid::new_v4();
                let review_reference = format!("test://servicenow-fixture/{ci_id}");
                sqlx::query(
                    "INSERT INTO configuration_item_environment_authority \
                     (id, configuration_item_id, environment, provenance_kind, \
                      review_reference) \
                     VALUES ($1, $2, 'test', 'reviewed-fixture-uuid', $3)",
                )
                .bind(id)
                .bind(ci_id)
                .bind(&review_reference)
                .execute(pool)
                .await
                .expect("seed reviewed ServiceNow test environment authority");
                ServiceNowEnvironmentAuthority {
                    id,
                    provenance_kind: "reviewed-fixture-uuid".to_string(),
                    review_reference,
                }
            }
        };
        (ci_id, authority)
    }

    /// Insert a completely-authorized test row. The static test session is an
    /// unscoped auditor/admin and therefore may address these rows.
    async fn seed_row(
        pool: &PgPool,
        id: &str,
        request_type: &str,
        ci_name: &str,
        status: &str,
        external_ref: &str,
        payload_summary: &str,
    ) {
        let (ci_id, environment_authority) = seed_ci(pool, ci_name).await;
        sqlx::query(
            "INSERT INTO servicenow_queue \
             (id, request_type, external_ref, status, ci_name, payload_summary, \
              created_at, submitted_at, metadata, ci_id, environment_authority_id, \
              environment_provenance_kind, environment_review_reference, \
              site, environment, ci_owner, requested_by) \
             VALUES ($1::uuid, $2, $3, $4, $5, $6, NOW(), NULL, '{}', $7, \
                     $8, $9, $10, 'DEFRA', 'test', 'snow-test-team', 'static-user') \
             ON CONFLICT (id) DO UPDATE SET \
                 request_type = EXCLUDED.request_type, \
                 external_ref = EXCLUDED.external_ref, \
                 status = EXCLUDED.status, ci_name = EXCLUDED.ci_name, \
                 payload_summary = EXCLUDED.payload_summary, \
                 ci_id = EXCLUDED.ci_id, \
                 environment_authority_id = EXCLUDED.environment_authority_id, \
                 environment_provenance_kind = EXCLUDED.environment_provenance_kind, \
                 environment_review_reference = EXCLUDED.environment_review_reference, \
                 site = EXCLUDED.site, \
                 environment = EXCLUDED.environment, \
                 ci_owner = EXCLUDED.ci_owner, requested_by = EXCLUDED.requested_by",
        )
        .bind(id)
        .bind(request_type)
        .bind(external_ref)
        .bind(status)
        .bind(ci_name)
        .bind(payload_summary)
        .bind(ci_id)
        .bind(environment_authority.id)
        .bind(&environment_authority.provenance_kind)
        .bind(&environment_authority.review_reference)
        .execute(pool)
        .await
        .expect("seed servicenow_queue row");
    }

    async fn cleanup(pool: &PgPool, id: &str) {
        let binding: Option<(Option<Uuid>, Option<Uuid>)> = sqlx::query_as(
            "SELECT ci_id, environment_authority_id \
             FROM servicenow_queue WHERE id = $1::uuid",
        )
        .bind(id)
        .fetch_optional(pool)
        .await
        .ok()
        .flatten();
        sqlx::query("DELETE FROM servicenow_queue WHERE id = $1::uuid")
            .bind(id)
            .execute(pool)
            .await
            .ok();
        if let Some((ci_id, environment_authority_id)) = binding {
            if let Some(environment_authority_id) = environment_authority_id {
                sqlx::query("DELETE FROM configuration_item_environment_authority WHERE id = $1")
                    .bind(environment_authority_id)
                    .execute(pool)
                    .await
                    .ok();
            }
            let Some(ci_id) = ci_id else {
                return;
            };
            sqlx::query("DELETE FROM configuration_items WHERE id = $1")
                .bind(ci_id)
                .execute(pool)
                .await
                .ok();
        }
    }

