    // ── prepare_incident persists a Draft row ──

    #[tokio::test]
    async fn test_prepare_incident_persists_draft() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set");
            return;
        };

        seed_ci(pool, "srv-test-snow-01.corp.local").await;
        let body = ServicenowIncidentRequest {
            ci_name: "srv-test-snow-01.corp.local".into(),
            description: "High CPU test incident".into(),
            urgency: "2".into(),
            assignment_group: "Wintel-Operations".into(),
        };
        let result =
            servicenow_incident(AuthExtractor(AuthSession::static_dry_run()), Json(body)).await;
        let Ok(Json(v)) = result else {
            panic!("expected Ok, got: {result:?}");
        };
        assert_eq!(v["source"], "database");
        assert_eq!(v["request_type"], "incident");
        assert_eq!(v["status"], "Draft");
        let id = v["id"].as_str().expect("id present");

        // Verify row in DB.
        let row: Option<ServiceNowRow> = sqlx::query_as(&format!(
            "SELECT {SNOW_COLUMNS} FROM servicenow_queue WHERE id = $1::uuid"
        ))
        .bind(id)
        .fetch_optional(pool)
        .await
        .expect("read row");
        cleanup(pool, id).await;

        let row = row.expect("row must exist after prepare_incident");
        assert_eq!(row.request_type, "incident");
        assert_eq!(row.status, "Draft");
        assert_eq!(row.ci_name, "srv-test-snow-01.corp.local");
        assert!(
            row.ci_id.is_some(),
            "queue row must bind the immutable CI id"
        );
        assert!(
            row.environment_authority_id.is_some(),
            "queue row must bind an explicit reviewed environment authority"
        );
        assert_eq!(
            row.environment_provenance_kind.as_deref(),
            Some("reviewed-fixture-uuid")
        );
        assert_eq!(
            row.environment_review_reference.as_deref(),
            Some(format!("test://servicenow-fixture/{}", row.ci_id.unwrap()).as_str())
        );
        assert_eq!(row.site.as_deref(), Some("DEFRA"));
        assert_eq!(row.environment.as_deref(), Some("test"));
        assert_eq!(row.ci_owner.as_deref(), Some("snow-test-team"));
        assert_eq!(row.requested_by.as_deref(), Some("static-user"));
    }

    #[tokio::test]
    async fn test_prepare_incident_rejects_foreign_or_unresolved_ci_authority() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set");
            return;
        };

        let suffix = Uuid::new_v4().simple().to_string();
        let foreign_ci = format!("snow-foreign-{}", &suffix[..8]);
        let unresolved_ci = format!("snow-unresolved-{}", &suffix[..8]);
        let operator_ci = format!("app-portal-operator-{}", &suffix[..8]);
        let foreign_id: Uuid = sqlx::query_scalar(
            "INSERT INTO configuration_items \
             (id, ci_name, ci_type, criticality, site, owner, environment) \
             VALUES (gen_random_uuid(), $1, 'Server', 'Low', 'GBLON', \
                     'foreign-team', 'production') RETURNING id",
        )
        .bind(&foreign_ci)
        .fetch_one(pool)
        .await
        .expect("seed foreign CI");
        let unresolved_id: Uuid = sqlx::query_scalar(
            "INSERT INTO configuration_items \
             (id, ci_name, ci_type, criticality, site, owner, environment) \
             VALUES (gen_random_uuid(), $1, 'Server', 'Low', 'DEFRA', \
                     'local-team', NULL) RETURNING id",
        )
        .bind(&unresolved_ci)
        .fetch_one(pool)
        .await
        .expect("seed unresolved CI");
        let operator_id: Uuid = sqlx::query_scalar(
            "INSERT INTO configuration_items \
             (id, ci_name, ci_type, criticality, site, owner, environment) \
             VALUES (gen_random_uuid(), $1, 'Application', 'Low', 'DEFRA', \
                     'operator-team', 'production') RETURNING id",
        )
        .bind(&operator_ci)
        .fetch_one(pool)
        .await
        .expect("seed unreviewed operator-managed CI with a fixture-like name");

        let mut scoped = AuthSession::static_dry_run();
        scoped.site_scope = vec!["DEFRA".into()];
        scoped.environment_scope = vec!["production".into()];
        let foreign = servicenow_incident(
            AuthExtractor(scoped),
            Json(ServicenowIncidentRequest {
                ci_name: foreign_ci.clone(),
                description: "must not queue".into(),
                urgency: "2".into(),
                assignment_group: "Ops".into(),
            }),
        )
        .await;
        assert!(matches!(foreign, Err((StatusCode::NOT_FOUND, _))));

        let unresolved = servicenow_incident(
            AuthExtractor(AuthSession::static_dry_run()),
            Json(ServicenowIncidentRequest {
                ci_name: unresolved_ci.clone(),
                description: "must not queue".into(),
                urgency: "2".into(),
                assignment_group: "Ops".into(),
            }),
        )
        .await;
        assert!(matches!(unresolved, Err((StatusCode::CONFLICT, _))));
        let operator_managed = servicenow_incident(
            AuthExtractor(AuthSession::static_dry_run()),
            Json(ServicenowIncidentRequest {
                ci_name: operator_ci.clone(),
                description: "name and environment are not reviewed authority".into(),
                urgency: "2".into(),
                assignment_group: "Ops".into(),
            }),
        )
        .await;
        assert!(
            matches!(operator_managed, Err((StatusCode::CONFLICT, _))),
            "an operator row cannot gain ServiceNow authority from a fixture-like name and environment"
        );
        let queued: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM servicenow_queue \
             WHERE ci_name = ANY($1::text[])",
        )
        .bind(vec![foreign_ci, unresolved_ci, operator_ci])
        .fetch_one(pool)
        .await
        .expect("count denied queue rows");
        assert_eq!(queued, 0);

        sqlx::query("DELETE FROM configuration_items WHERE id = ANY($1)")
            .bind(vec![foreign_id, unresolved_id, operator_id])
            .execute(pool)
            .await
            .expect("clean CI authority seeds");
    }

    #[tokio::test]
    async fn test_prepare_incident_rejects_inactive_reviewed_site_authority() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set");
            return;
        };

        let suffix = Uuid::new_v4().simple().to_string();
        let site = format!("SNOW-I-{}", &suffix[..8]).to_uppercase();
        let ci_name = format!("snow-inactive-{}", &suffix[..8]);
        sqlx::query(
            "INSERT INTO site_registry \
             (unlocode, name, country, country_code, timezone, active) \
             VALUES ($1, $1, 'Test', 'ZZ', 'UTC', true)",
        )
        .bind(&site)
        .execute(pool)
        .await
        .expect("seed active canonical ServiceNow site");
        let ci_id: Uuid = sqlx::query_scalar(
            "INSERT INTO configuration_items \
             (id, ci_name, ci_type, criticality, site, owner, environment) \
             VALUES (gen_random_uuid(), $1, 'Server', 'Low', $2, \
                     'inactive-test-team', 'test') RETURNING id",
        )
        .bind(&ci_name)
        .bind(&site)
        .fetch_one(pool)
        .await
        .expect("seed CI at site before deactivation");
        let authority_id = Uuid::new_v4();
        sqlx::query(
            "INSERT INTO configuration_item_environment_authority \
             (id, configuration_item_id, environment, provenance_kind, review_reference) \
             VALUES ($1, $2, 'test', 'reviewed-operator-uuid', $3)",
        )
        .bind(authority_id)
        .bind(ci_id)
        .bind(format!("test://inactive-reviewed-site/{ci_id}"))
        .execute(pool)
        .await
        .expect("seed exact reviewed CI authority while site is active");
        sqlx::query("UPDATE site_registry SET active = false WHERE unlocode = $1")
            .bind(&site)
            .execute(pool)
            .await
            .expect("deactivate reviewed CI site");

        let result = servicenow_incident(
            AuthExtractor(AuthSession::static_dry_run()),
            Json(ServicenowIncidentRequest {
                ci_name: ci_name.clone(),
                description: "inactive current site must fail closed".into(),
                urgency: "2".into(),
                assignment_group: "Ops".into(),
            }),
        )
        .await;
        assert!(matches!(result, Err((StatusCode::CONFLICT, _))));
        let queued: i64 =
            sqlx::query_scalar("SELECT COUNT(*) FROM servicenow_queue WHERE ci_name = $1")
                .bind(&ci_name)
                .fetch_one(pool)
                .await
                .expect("count inactive-site queue rows");
        assert_eq!(queued, 0);

        sqlx::query("DELETE FROM configuration_item_environment_authority WHERE id = $1")
            .bind(authority_id)
            .execute(pool)
            .await
            .expect("clean inactive-site authority");
        sqlx::query("DELETE FROM configuration_items WHERE id = $1")
            .bind(ci_id)
            .execute(pool)
            .await
            .expect("clean inactive-site CI");
        sqlx::query("DELETE FROM site_registry WHERE unlocode = $1")
            .bind(&site)
            .execute(pool)
            .await
            .expect("clean inactive canonical site");
    }

