    #[tokio::test]
    async fn test_current_environment_drift_quarantines_every_servicenow_path() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set");
            return;
        };

        let id = "f0000100-1000-1000-1000-000000000315";
        seed_row(
            pool,
            id,
            "change",
            "srv-authority-drift.local",
            "Ready",
            "CHG-DRIFT",
            "must be quarantined after current authority drift",
        )
        .await;
        let ci_id: Uuid =
            sqlx::query_scalar("SELECT ci_id FROM servicenow_queue WHERE id = $1::uuid")
                .bind(id)
                .fetch_one(pool)
                .await
                .expect("load exact CI binding before drift");
        sqlx::query("UPDATE configuration_items SET environment = 'drifted' WHERE id = $1")
            .bind(ci_id)
            .execute(pool)
            .await
            .expect("drift current CI environment away from reviewed binding");

        let status = servicenow_status(
            AuthExtractor(AuthSession::static_dry_run()),
            Path(id.into()),
        )
        .await;
        assert!(matches!(status, Err((StatusCode::NOT_FOUND, _))));

        let submit = servicenow_submit(
            AuthExtractor(AuthSession::static_dry_run()),
            Path(id.into()),
        )
        .await;
        assert!(matches!(submit, Err((StatusCode::NOT_FOUND, _))));

        let cancel = servicenow_cancel(
            AuthExtractor(AuthSession::static_dry_run()),
            Path(id.into()),
        )
        .await;
        assert!(matches!(cancel, Err((StatusCode::NOT_FOUND, _))));

        let Ok(Json(pending)) =
            servicenow_pending(AuthExtractor(AuthSession::static_dry_run())).await
        else {
            panic!("expected pending list after quarantining drifted row");
        };
        assert!(
            pending["items"]
                .as_array()
                .expect("pending items")
                .iter()
                .all(|item| item["id"] != id),
            "a row whose current environment no longer matches immutable provenance must be absent from lists"
        );

        cleanup(pool, id).await;
    }

