    /// plan → approve → execute → verify: each transition persists in DB.
    /// history SELECT returns the deployment.
    #[tokio::test]
    async fn test_software_lifecycle_plan_approve_execute_verify_persists() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set");
            return;
        };

        let server = format!("srv-test-{}", uuid::Uuid::new_v4());
        let site = unique_site("SOFTWARE-LIFECYCLE");
        let configuration_item_id =
            seed_target(pool, &server, &site, Some("production"), "Server", true).await;
        let body = plan_body(&server);

        // Plan.
        let Ok(Json(planned)) =
            software_plan(AuthExtractor(AuthSession::static_dry_run()), Json(body)).await
        else {
            panic!("plan failed");
        };
        assert_eq!(
            planned["status"], "Planned",
            "status after plan must be Planned"
        );
        assert_eq!(planned["site"], site);
        assert_eq!(planned["environment"], "production");
        assert_eq!(
            planned["configuration_item_id"],
            configuration_item_id.to_string()
        );
        assert_eq!(planned["scope_provenance"], "cmdb-configuration-item");
        assert_eq!(
            planned["maker_user_id"], "static-user",
            "maker provenance must come from the authenticated session"
        );
        assert_eq!(
            planned["requester"], "static-user",
            "legacy requester output must mirror the authenticated maker"
        );
        let id = planned["id"].as_str().expect("id").to_string();
        assert!(
            software_deployment::get_deployment(&id).is_none(),
            "DB-backed planning must not create an ungoverned in-memory twin"
        );

        // Approve.
        let Ok(Json(approved)) = software_approve(
            Path(id.clone()),
            AuthExtractor(approver_session("test-approver")),
        )
        .await
        else {
            cleanup_deployment(pool, &id).await;
            panic!("approve failed");
        };
        assert_eq!(
            approved["status"], "Approved",
            "status after approve must be Approved"
        );
        assert_eq!(approved["approved_by"], "test-approver");

        // Execute.
        let Ok(Json(_executed)) = software_execute(
            AuthExtractor(AuthSession::static_dry_run()),
            Path(id.clone()),
        )
        .await
        else {
            cleanup_deployment(pool, &id).await;
            panic!("execute failed");
        };

        // Confirm DB status after execute.
        let row: Option<SoftwareDeploymentRow> = sqlx::query_as(&format!(
            "SELECT {DEPLOYMENT_COLUMNS} FROM software_deployments WHERE id = $1"
        ))
        .bind(&id)
        .fetch_optional(pool)
        .await
        .expect("db read");
        let row = row.expect("row must exist after execute");
        assert_eq!(row.status, "Executed", "DB status must be Executed");
        assert!(row.executed_at.is_some(), "executed_at must be set");

        // Verify.
        let Ok(Json(verify_result)) = software_verify(
            AuthExtractor(AuthSession::static_dry_run()),
            Path(id.clone()),
        )
        .await
        else {
            cleanup_deployment(pool, &id).await;
            panic!("verify failed");
        };
        assert_eq!(verify_result["passed"], true, "verify must pass");

        // Confirm DB status after verify.
        let row2: Option<SoftwareDeploymentRow> = sqlx::query_as(&format!(
            "SELECT {DEPLOYMENT_COLUMNS} FROM software_deployments WHERE id = $1"
        ))
        .bind(&id)
        .fetch_optional(pool)
        .await
        .expect("db read 2");
        let row2 = row2.expect("row must exist after verify");
        assert_eq!(
            row2.status, "Verified",
            "DB status must be Verified after verify"
        );
        assert!(row2.verified_at.is_some(), "verified_at must be set");

        // History SELECT must include the deployment.
        let Ok(Json(history)) = software_history(
            AuthExtractor(AuthSession::static_dry_run()),
            Path(server.clone()),
        )
        .await
        else {
            cleanup_deployment(pool, &id).await;
            panic!("history failed");
        };
        let records = history.as_array().expect("history must be array");
        let found = records.iter().any(|r| r["id"] == id);
        assert!(found, "history must contain the deployment id");

        cleanup_deployment(pool, &id).await;
        cleanup_target(pool, &server, &site).await;
    }

    /// Planning binds canonical scope + authenticated maker, and every later
    /// lifecycle boundary hides a foreign deployment while allowing an in-scope
    /// distinct checker/operator through the same database row.
    #[tokio::test]
    async fn software_scope_and_maker_checker_are_enforced_across_lifecycle() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set");
            return;
        };

        let server = format!("srv-scope-{}", uuid::Uuid::new_v4());
        let site = unique_site("SOFTWARE-SCOPE");
        let foreign_site = unique_site("SOFTWARE-FOREIGN");
        let configuration_item_id =
            seed_target(pool, &server, &site, Some("production"), "Server", true).await;
        seed_test_site(pool, &foreign_site, true).await;
        let mut body = plan_body(&server);
        body.site = foreign_site.clone();
        body.environment = "staging".into();
        body.target_version = "caller-spoofed-version".into();
        body.requester = "forged-client-maker".into();
        let maker = scoped_session("software-maker", &site, "production");
        let Ok(Json(planned)) = software_plan(AuthExtractor(maker.clone()), Json(body)).await
        else {
            panic!("scoped plan must succeed");
        };
        let id = planned["id"].as_str().expect("id").to_string();
        assert_eq!(
            planned["configuration_item_id"],
            configuration_item_id.to_string()
        );
        assert_eq!(planned["scope_provenance"], "cmdb-configuration-item");
        assert_eq!(planned["site"], site);
        assert_eq!(planned["environment"], "production");
        assert_eq!(planned["target_version"], "7.0.4");
        assert_eq!(planned["maker_user_id"], "software-maker");
        assert_eq!(planned["requester"], "software-maker");

        let same_actor = software_approve(Path(id.clone()), AuthExtractor(maker)).await;
        let Err((status, _)) = same_actor else {
            cleanup_deployment(pool, &id).await;
            panic!("maker must not approve own deployment");
        };
        assert_eq!(status, StatusCode::FORBIDDEN);

        let foreign = scoped_session("foreign-checker", &foreign_site, "production");
        let Err((status, _)) =
            software_approve(Path(id.clone()), AuthExtractor(foreign.clone())).await
        else {
            cleanup_deployment(pool, &id).await;
            panic!("foreign checker must not approve");
        };
        assert_eq!(status, StatusCode::NOT_FOUND);

        let foreign_environment = scoped_session("foreign-environment-checker", &site, "staging");
        let Err((status, _)) =
            software_approve(Path(id.clone()), AuthExtractor(foreign_environment.clone())).await
        else {
            cleanup_deployment(pool, &id).await;
            panic!("wrong-environment checker must not approve");
        };
        assert_eq!(status, StatusCode::NOT_FOUND);

        let checker = scoped_session("software-checker", &site, "production");
        let Ok(Json(approved)) = software_approve(Path(id.clone()), AuthExtractor(checker)).await
        else {
            cleanup_deployment(pool, &id).await;
            panic!("distinct in-scope checker must approve");
        };
        assert_eq!(approved["status"], "Approved");
        assert_eq!(approved["approved_by"], "software-checker");

        let Err((status, _)) =
            software_execute(AuthExtractor(foreign.clone()), Path(id.clone())).await
        else {
            cleanup_deployment(pool, &id).await;
            panic!("foreign operator must not execute");
        };
        assert_eq!(status, StatusCode::NOT_FOUND);

        let operator = scoped_session("software-operator", &site, "production");
        assert!(
            software_execute(AuthExtractor(operator.clone()), Path(id.clone()))
                .await
                .is_ok(),
            "in-scope operator must execute"
        );

        let Err((status, _)) =
            software_verify(AuthExtractor(foreign.clone()), Path(id.clone())).await
        else {
            cleanup_deployment(pool, &id).await;
            panic!("foreign operator must not verify");
        };
        assert_eq!(status, StatusCode::NOT_FOUND);
        assert!(
            software_verify(AuthExtractor(operator.clone()), Path(id.clone()))
                .await
                .is_ok(),
            "in-scope operator must verify"
        );

        let Ok(Json(foreign_history)) =
            software_history(AuthExtractor(foreign), Path(server.clone())).await
        else {
            cleanup_deployment(pool, &id).await;
            panic!("foreign history must return a non-enumerating empty collection");
        };
        assert_eq!(foreign_history, json!([]));

        let Ok(Json(foreign_environment_history)) =
            software_history(AuthExtractor(foreign_environment), Path(server.clone())).await
        else {
            cleanup_deployment(pool, &id).await;
            panic!("wrong-environment history must return an empty collection");
        };
        assert_eq!(foreign_environment_history, json!([]));

        let Ok(Json(own_history)) =
            software_history(AuthExtractor(operator), Path(server.clone())).await
        else {
            cleanup_deployment(pool, &id).await;
            panic!("in-scope history must succeed");
        };
        assert!(
            own_history
                .as_array()
                .is_some_and(|rows| rows.iter().any(|row| row["id"] == id)),
            "in-scope history must contain the deployment"
        );

        cleanup_deployment(pool, &id).await;
        cleanup_target(pool, &server, &site).await;
        cleanup_test_site(pool, &foreign_site).await;
    }

    #[tokio::test]
    async fn software_plan_rejects_foreign_scope_before_persistence() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set");
            return;
        };

        for label in ["site", "environment"] {
            let server = format!("srv-plan-foreign-{label}-{}", uuid::Uuid::new_v4());
            let target_site = unique_site("SOFTWARE-PLAN-TARGET");
            let foreign_site = unique_site("SOFTWARE-PLAN-FOREIGN");
            seed_target(
                pool,
                &server,
                &target_site,
                Some("production"),
                "Server",
                true,
            )
            .await;
            seed_test_site(pool, &foreign_site, true).await;
            let (session_site, session_environment) = if label == "site" {
                (foreign_site.as_str(), "production")
            } else {
                (target_site.as_str(), "staging")
            };
            let mut body = plan_body(&server);
            body.site = session_site.into();
            body.environment = session_environment.into();
            let result = software_plan(
                AuthExtractor(scoped_session(
                    "foreign-software-maker",
                    session_site,
                    session_environment,
                )),
                Json(body),
            )
            .await;
            let Err((status, _)) = result else {
                panic!("foreign {label} scoped plan must fail");
            };
            assert_eq!(status, StatusCode::FORBIDDEN);
            let persisted: i64 = sqlx::query_scalar(
                "SELECT COUNT(*) FROM software_deployments WHERE server_name = $1",
            )
            .bind(&server)
            .fetch_one(pool)
            .await
            .expect("count rejected plan");
            assert_eq!(persisted, 0, "scope rejection must precede persistence");
            cleanup_target(pool, &server, &target_site).await;
            cleanup_test_site(pool, &foreign_site).await;
        }
    }

