    #[tokio::test]
    async fn software_lifecycle_quarantines_inactive_or_changed_target_and_provenance_is_immutable()
    {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set");
            return;
        };

        let server = format!("srv-target-drift-{}", Uuid::new_v4());
        let site = unique_site("SOFTWARE-DRIFT");
        seed_target(pool, &server, &site, Some("production"), "Server", true).await;
        let Json(planned) = software_plan(
            AuthExtractor(AuthSession::static_dry_run()),
            Json(plan_body(&server)),
        )
        .await
        .expect("plan authoritative target");
        let id = planned["id"].as_str().expect("deployment id").to_string();

        let rebind_error =
            sqlx::query("UPDATE software_deployments SET target_version = '9.9.9' WHERE id = $1")
                .bind(&id)
                .execute(pool)
                .await
                .expect_err("persisted deployment authority must be immutable");
        assert!(rebind_error
            .to_string()
            .contains("software deployment authorization provenance is immutable"));

        sqlx::query("UPDATE site_registry SET active = false WHERE unlocode = $1")
            .bind(&site)
            .execute(pool)
            .await
            .expect("deactivate authoritative target site");
        let inactive = software_approve(
            Path(id.clone()),
            AuthExtractor(approver_session("inactive-site-checker")),
        )
        .await
        .expect_err("inactive target site must quarantine lifecycle transition");
        assert_eq!(inactive.0, StatusCode::NOT_FOUND);
        let inactive_direct =
            sqlx::query("UPDATE software_deployments SET status = 'Approved' WHERE id = $1")
                .bind(&id)
                .execute(pool)
                .await
                .expect_err("inactive target site must block direct lifecycle transition");
        assert!(inactive_direct
            .to_string()
            .contains("software deployment requires an exact active CMDB target relation"));
        let Json(inactive_history) = software_history(
            AuthExtractor(AuthSession::static_dry_run()),
            Path(server.clone()),
        )
        .await
        .expect("inactive history is non-enumerating");
        assert_eq!(inactive_history, json!([]));

        sqlx::query("UPDATE site_registry SET active = true WHERE unlocode = $1")
            .bind(&site)
            .execute(pool)
            .await
            .expect("reactivate target site");
        sqlx::query("UPDATE configuration_items SET environment = 'staging' WHERE ci_name = $1")
            .bind(&server)
            .execute(pool)
            .await
            .expect("change current target authority");
        let changed = software_approve(
            Path(id.clone()),
            AuthExtractor(approver_session("changed-target-checker")),
        )
        .await
        .expect_err("changed CMDB tuple must not re-authorize persisted plan");
        assert_eq!(changed.0, StatusCode::NOT_FOUND);
        let changed_direct =
            sqlx::query("UPDATE software_deployments SET status = 'Approved' WHERE id = $1")
                .bind(&id)
                .execute(pool)
                .await
                .expect_err("changed CMDB tuple must block direct lifecycle transition");
        assert!(changed_direct
            .to_string()
            .contains("software deployment requires an exact active CMDB target relation"));
        let Json(changed_history) = software_history(
            AuthExtractor(AuthSession::static_dry_run()),
            Path(server.clone()),
        )
        .await
        .expect("changed-target history is non-enumerating");
        assert_eq!(changed_history, json!([]));
        let status: String =
            sqlx::query_scalar("SELECT status FROM software_deployments WHERE id = $1")
                .bind(&id)
                .fetch_one(pool)
                .await
                .expect("read quarantined deployment status");
        assert_eq!(status, "Planned");

        cleanup_deployment(pool, &id).await;
        cleanup_target(pool, &server, &site).await;
    }

    #[tokio::test]
    async fn software_target_resolution_lock_blocks_concurrent_authority_change() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set");
            return;
        };

        let server = format!("srv-target-lock-{}", Uuid::new_v4());
        let site = unique_site("SOFTWARE-LOCK");
        seed_target(pool, &server, &site, Some("production"), "Server", true).await;

        let mut authority_tx = pool.begin().await.expect("begin target authority lock");
        let resolved = crate::repos::configuration_items::get_authorized_by_name_for_no_key_update(
            &mut authority_tx,
            &server,
            &[],
            &[],
        )
        .await
        .expect("resolve target under lock");
        assert!(resolved.is_some());

        let update_pool = pool.clone();
        let update_server = server.clone();
        let mut concurrent_update = tokio::spawn(async move {
            sqlx::query("UPDATE configuration_items SET environment = 'staging' WHERE ci_name = $1")
                .bind(update_server)
                .execute(&update_pool)
                .await
        });
        let raced = tokio::time::timeout(
            std::time::Duration::from_millis(150),
            &mut concurrent_update,
        )
        .await;
        assert!(
            raced.is_err(),
            "CMDB authority update must block while planning holds its lock"
        );
        authority_tx
            .commit()
            .await
            .expect("release target authority lock");
        concurrent_update
            .await
            .expect("join concurrent target update")
            .expect("target update proceeds after lock release");

        cleanup_target(pool, &server, &site).await;
    }

    /// Double-approve returns 409 (CAS: row already Approved, not Planned).
    #[tokio::test]
    async fn test_software_double_approve_is_conflict() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set");
            return;
        };

        let server = format!("srv-cas-{}", uuid::Uuid::new_v4());
        let site = unique_site("SOFTWARE-CAS");
        seed_target(pool, &server, &site, Some("production"), "Server", true).await;
        let Ok(Json(planned)) = software_plan(
            AuthExtractor(AuthSession::static_dry_run()),
            Json(plan_body(&server)),
        )
        .await
        else {
            panic!("plan failed");
        };
        let id = planned["id"].as_str().expect("id").to_string();

        // First approve: OK.
        let Ok(_) = software_approve(
            Path(id.clone()),
            AuthExtractor(approver_session("approver-1")),
        )
        .await
        else {
            cleanup_deployment(pool, &id).await;
            panic!("first approve failed");
        };

        // Second approve: engine already changed status to Approved so engine
        // rejects it; DB CAS would also reject (row not in Planned). Either way
        // we expect an Err.
        let Err(_) = software_approve(
            Path(id.clone()),
            AuthExtractor(approver_session("approver-2")),
        )
        .await
        else {
            cleanup_deployment(pool, &id).await;
            panic!("expected Err on double-approve");
        };

        cleanup_deployment(pool, &id).await;
        cleanup_target(pool, &server, &site).await;
    }

    /// A trusted DB-seeded row with the complete exact CMDB relation remains
    /// operable after restart; mere old-writer scope fields are tested separately
    /// and never substitute for the authoritative UUID relation.
    #[tokio::test]
    async fn test_direct_sql_insert_deployment_full_lifecycle() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set");
            return;
        };

        let id = format!("dep-direct-{}", uuid::Uuid::new_v4());
        let server = format!("db-srv-direct-{}", Uuid::new_v4());
        let site = unique_site("SOFTWARE-DIRECT");
        let configuration_item_id =
            seed_target(pool, &server, &site, Some("production"), "Server", true).await;
        sqlx::query(
            "INSERT INTO software_deployments \
             (id, configuration_item_id, scope_provenance, server_name, site, \
              environment, package_id, package_name, target_version, \
              scheduled_time, requester, maker_user_id, status, plan_json, \
              evidence_json) \
             VALUES ($1, $2, 'cmdb-configuration-item', $3, $4, 'production', \
                     'pkg-zabbix-agent', 'Zabbix Agent 7.0', '7.0.4', \
                     '2099-12-31T22:00:00Z', 'db-tester', 'db-tester', \
                     'Planned', NULL, '[]'::jsonb)",
        )
        .bind(&id)
        .bind(configuration_item_id)
        .bind(&server)
        .bind(&site)
        .execute(pool)
        .await
        .expect("direct SQL insert");

        // Approve.
        let Ok(Json(approved)) = software_approve(
            Path(id.clone()),
            AuthExtractor(approver_session("db-approver")),
        )
        .await
        else {
            cleanup_deployment(pool, &id).await;
            panic!("approve on direct-insert row must succeed");
        };
        assert_eq!(approved["status"], "Approved");
        assert_eq!(approved["approved_by"], "db-approver");

        // Execute.
        let Ok(Json(_executed)) = software_execute(
            AuthExtractor(AuthSession::static_dry_run()),
            Path(id.clone()),
        )
        .await
        else {
            cleanup_deployment(pool, &id).await;
            panic!("execute on direct-insert row must succeed");
        };

        // Verify.
        let Ok(Json(verified)) = software_verify(
            AuthExtractor(AuthSession::static_dry_run()),
            Path(id.clone()),
        )
        .await
        else {
            cleanup_deployment(pool, &id).await;
            panic!("verify on direct-insert row must succeed");
        };
        assert_eq!(verified["passed"], true, "verify must pass");

        // DB row must reflect Verified status.
        let row: Option<SoftwareDeploymentRow> = sqlx::query_as(&format!(
            "SELECT {DEPLOYMENT_COLUMNS} FROM software_deployments WHERE id = $1"
        ))
        .bind(&id)
        .fetch_optional(pool)
        .await
        .expect("db read");
        cleanup_deployment(pool, &id).await;
        cleanup_target(pool, &server, &site).await;
        assert_eq!(
            row.expect("row must exist").status,
            "Verified",
            "DB status must be Verified"
        );
    }

