    #[tokio::test]
    async fn test_review_rejects_stale_and_remediation_states_without_audit() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL is absent");
            return;
        };

        let suffix = uuid::Uuid::new_v4().to_string();
        let ci_name = format!("ci-test-{suffix}");
        seed_ci(pool, &ci_name, "SNAP-A", Some("production")).await;
        let Ok(Json(created)) = snapshot_plan(
            AuthExtractor(AuthSession::static_dry_run()),
            Json(plan_body(&suffix)),
        )
        .await
        else {
            panic!("snapshot_plan failed");
        };
        let id = created["id"].as_str().expect("id").to_string();
        let snapshot_id = uuid::Uuid::parse_str(&id).expect("snapshot UUID");

        for invalid_status in ["StaleFlagged", "RemediationPlanned"] {
            sqlx::query("UPDATE snapshots SET status = $2 WHERE id = $1")
                .bind(snapshot_id)
                .bind(invalid_status)
                .execute(pool)
                .await
                .expect("seed invalid review predecessor");

            let Err((status, _)) = snapshot_review(
                AuthExtractor(scoped_session("snapshot-reviewer", &[], &[])),
                Json(SnapshotActionRequest {
                    snapshot_id: id.clone(),
                }),
            )
            .await
            else {
                cleanup(pool, &id, &ci_name).await;
                panic!("review must reject {invalid_status}");
            };
            assert_eq!(status, StatusCode::CONFLICT);

            let persisted_status: String =
                sqlx::query_scalar("SELECT status FROM snapshots WHERE id = $1")
                    .bind(snapshot_id)
                    .fetch_one(pool)
                    .await
                    .expect("read unchanged snapshot status");
            assert_eq!(persisted_status, invalid_status);
            let review_audits: i64 = sqlx::query_scalar(
                "SELECT COUNT(*) FROM audit_log \
                 WHERE action = 'snapshot-review' AND detail->>'snapshot_id' = $1",
            )
            .bind(&id)
            .fetch_one(pool)
            .await
            .expect("count review audits");
            assert_eq!(
                review_audits, 0,
                "a rejected transition must not emit a success audit"
            );
        }

        cleanup(pool, &id, &ci_name).await;
    }

