    #[tokio::test]
    async fn restore_planner_self_approval_is_forbidden_and_makerless_rows_fail_closed() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let actor = "same-stable-restore-subject";
        let Ok(Json(created)) = backup_restore_plan(
            AuthExtractor(approver_session(actor)),
            Json(RestorePlanRequest {
                source_ci_key: "ci-self-approval-test".into(),
                restore_type: "full-vm".into(),
                restore_point: "2026-06-10T02:00:00Z".into(),
                target_site: "DEFRA".into(),
                target_environment: "production".into(),
                owner: "different-business-owner".into(),
            }),
        )
        .await
        else {
            panic!("self-approval fixture plan failed");
        };
        let id = created["id"].as_str().expect("id").to_string();

        let denied = backup_restore_approve(
            Extension(approver_session(actor)),
            Json(RestoreActionRequest {
                restore_id: id.clone(),
            }),
        )
        .await;
        assert!(matches!(denied, Err((StatusCode::FORBIDDEN, _))));
        let after_denial = crate::repos::restore_requests::get(pool, &id)
            .await
            .expect("read denied restore")
            .expect("restore exists");
        assert_eq!(
            after_denial.status,
            ryuki_engine::models::RestoreStatus::Planned
        );
        assert!(!after_denial.metadata.contains_key("approver"));

        let mut forged = after_denial.clone();
        forged.status = ryuki_engine::models::RestoreStatus::Approved;
        forged
            .metadata
            .insert("planned_by".into(), "forged-maker".into());
        forged
            .metadata
            .insert("approver".into(), "different-restore-approver".into());
        let forged_applied =
            crate::repos::restore_requests::transition(pool, "Planned", &forged, None)
                .await
                .expect("forged maker transition is evaluated");
        assert!(
            forged_applied.is_none(),
            "the DB predicate must bind approval to the originally persisted maker"
        );

        let legacy_id = uuid::Uuid::new_v4().to_string();
        sqlx::query(
            "INSERT INTO restore_requests ( \
                id, source_ci_key, restore_type, restore_point, target_site, \
                target_environment, owner, status, metadata \
             ) VALUES ( \
                $1::uuid, 'ci-makerless-legacy', 'FullVm', 'legacy-point', \
                'DEFRA', 'production', 'legacy-owner', 'Planned', '{}'::jsonb \
             )",
        )
        .bind(&legacy_id)
        .execute(pool)
        .await
        .expect("insert a makerless quarantined legacy row");
        let legacy_denial = backup_restore_approve(
            Extension(approver_session("different-restore-approver")),
            Json(RestoreActionRequest {
                restore_id: legacy_id.clone(),
            }),
        )
        .await;
        assert!(matches!(legacy_denial, Err((StatusCode::CONFLICT, _))));
        let legacy = crate::repos::restore_requests::get(pool, &legacy_id)
            .await
            .expect("read legacy restore")
            .expect("restore exists");
        assert_eq!(legacy.status, ryuki_engine::models::RestoreStatus::Planned);
        assert!(!legacy.metadata.contains_key("approver"));

        let quarantined_transition = {
            let mut attempted = legacy.clone();
            attempted.status = ryuki_engine::models::RestoreStatus::Approved;
            attempted
                .metadata
                .insert("approver".into(), "different-restore-approver".into());
            crate::repos::restore_requests::transition(pool, "Planned", &attempted, None)
                .await
                .expect("quarantined transition is evaluated")
        };
        assert!(
            quarantined_transition.is_none(),
            "quarantined legacy rows must be replanned, never promoted"
        );

        cleanup_restore(pool, &id).await;
        cleanup_restore(pool, &legacy_id).await;
    }

    /// #2 RBAC: restore requests are DUAL-AXIS (target_site, target_environment). A
    /// principal scoped to a different site cannot read, validate, approve, execute,
    /// or list another scope's restore — by-id 404s (no oracle), plan 403s on a
    /// foreign target, and the list hides it. An in-scope principal is unaffected.
    #[tokio::test]
    async fn backup_restore_is_dual_axis_scoped() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };

        // Plan a GBLON/production restore as an unrestricted admin.
        let Ok(Json(created)) = backup_restore_plan(
            AuthExtractor(AuthSession::static_dry_run()),
            Json(RestorePlanRequest {
                source_ci_key: "ci-scope-test-001".into(),
                restore_type: "full-vm".into(),
                restore_point: "2026-06-10T02:00:00Z".into(),
                target_site: "GBLON".into(),
                target_environment: "production".into(),
                owner: "scope-test-owner".into(),
            }),
        )
        .await
        else {
            panic!("plan failed");
        };
        let id = created["id"].as_str().expect("id").to_string();

        // A DEFRA-site-scoped principal (GBLON out of scope).
        let scoped = || {
            let mut s = AuthSession::static_dry_run();
            s.token_valid = true;
            s.actor_class = ryuki_engine::auth::ActorClass::VerifiedHuman;
            s.provider_mode = "test-verified-human".into();
            s.site_scope = vec!["DEFRA".into()];
            s
        };
        let act = || RestoreActionRequest {
            restore_id: id.clone(),
        };

        assert!(
            matches!(
                backup_restore_get(AuthExtractor(scoped()), Path(id.clone())).await,
                Err((StatusCode::NOT_FOUND, _))
            ),
            "out-of-scope get must 404"
        );
        assert!(
            matches!(
                backup_restore_validate(AuthExtractor(scoped()), Json(act())).await,
                Err((StatusCode::NOT_FOUND, _))
            ),
            "out-of-scope validate must 404"
        );
        assert!(
            matches!(
                backup_restore_approve(Extension(scoped()), Json(act())).await,
                Err((StatusCode::NOT_FOUND, _))
            ),
            "out-of-scope approve must 404"
        );
        assert!(
            matches!(
                backup_restore_execute(AuthExtractor(scoped()), Json(act())).await,
                Err((StatusCode::NOT_FOUND, _))
            ),
            "out-of-scope execute must 404"
        );

        // Planning a foreign-target restore is a 403 (body-supplied target).
        let p = backup_restore_plan(
            AuthExtractor(scoped()),
            Json(RestorePlanRequest {
                source_ci_key: "ci-scope-test-002".into(),
                restore_type: "full-vm".into(),
                restore_point: "2026-06-10T02:00:00Z".into(),
                target_site: "GBLON".into(),
                target_environment: "production".into(),
                owner: "scope-test-owner".into(),
            }),
        )
        .await;
        assert!(
            matches!(p, Err((StatusCode::FORBIDDEN, _))),
            "out-of-scope plan must 403: {p:?}"
        );

        // The scoped list excludes the GBLON restore.
        let (_, Json(listed)) = backup_restores_list(
            AuthExtractor(scoped()),
            Query(BackupRestoreListQuery {
                limit: None,
                offset: None,
            }),
        )
        .await
        .expect("list");
        let ids: Vec<String> = listed
            .as_array()
            .unwrap_or(&vec![])
            .iter()
            .map(|r| r["id"].as_str().unwrap_or("").to_string())
            .collect();
        assert!(
            !ids.contains(&id),
            "scoped list must exclude the GBLON restore: {ids:?}"
        );

        // Positive: a GBLON/production principal CAN read it.
        let mut gblon = AuthSession::static_dry_run();
        gblon.site_scope = vec!["GBLON".into()];
        gblon.environment_scope = vec!["production".into()];
        assert!(
            backup_restore_get(AuthExtractor(gblon), Path(id.clone()))
                .await
                .is_ok(),
            "in-scope GBLON/production get must succeed"
        );

        cleanup_restore(pool, &id).await;
    }

