    /// Overlapping active locks for the same VM/site/environment serialize and
    /// the second lock fails closed without mutating its Approved row.
    #[tokio::test]
    async fn test_overlapping_vm_operation_lock_is_rejected() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let suffix = uuid::Uuid::new_v4().to_string();
        let shared_target = format!("ci-vm-shared-{suffix}");
        let mut first_body = plan_body(&format!("{suffix}-first"));
        first_body.target_ci_key = shared_target.clone();
        let mut second_body = plan_body(&format!("{suffix}-second"));
        second_body.target_ci_key = shared_target;
        let first_id = create_validated(first_body).await;
        let second_id = create_validated(second_body).await;

        for id in [&first_id, &second_id] {
            let approved = vm_day2_approve(
                AuthExtractor(checker_session(&suffix)),
                Json(VmDay2ActionRequest {
                    operation_id: id.clone(),
                }),
            )
            .await;
            assert!(approved.is_ok(), "distinct checker approval must succeed");
        }

        let first_lock = vm_day2_lock(
            AuthExtractor(AuthSession::static_dry_run()),
            Json(VmDay2ActionRequest {
                operation_id: first_id.clone(),
            }),
        )
        .await;
        assert!(first_lock.is_ok());
        let second_lock = vm_day2_lock(
            AuthExtractor(AuthSession::static_dry_run()),
            Json(VmDay2ActionRequest {
                operation_id: second_id.clone(),
            }),
        )
        .await;
        assert!(matches!(second_lock, Err((StatusCode::CONFLICT, _))));

        let second = crate::repos::vm_day2_operations::get(pool, &second_id)
            .await
            .expect("get")
            .expect("second operation");
        assert_eq!(
            second.status,
            ryuki_engine::models::VmChangeStatus::Approved
        );
        assert!(second
            .governance
            .as_ref()
            .expect("governance")
            .operation_lock
            .is_none());
        cleanup(pool, &first_id).await;
        cleanup(pool, &second_id).await;
    }

    /// Even if an application caller supplies internally consistent expired
    /// evidence, the atomic DB-clock predicate refuses the Locked -> Executed
    /// write.
    #[tokio::test]
    async fn test_execute_transition_rechecks_lock_expiry_with_database_clock() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let suffix = uuid::Uuid::new_v4().to_string();
        let id = create_validated(plan_body(&suffix)).await;
        let _ = vm_day2_approve(
            AuthExtractor(checker_session(&suffix)),
            Json(VmDay2ActionRequest {
                operation_id: id.clone(),
            }),
        )
        .await
        .expect("approve");
        let _ = vm_day2_lock(
            AuthExtractor(AuthSession::static_dry_run()),
            Json(VmDay2ActionRequest {
                operation_id: id.clone(),
            }),
        )
        .await
        .expect("lock");

        let mut expired = crate::repos::vm_day2_operations::get(pool, &id)
            .await
            .expect("get")
            .expect("operation");
        expired
            .governance
            .as_mut()
            .and_then(|governance| governance.operation_lock.as_mut())
            .expect("lock evidence")
            .expires_at = (chrono::Utc::now() - chrono::Duration::minutes(1)).to_rfc3339();
        let expired_json = serde_json::to_string(&expired).expect("serialize expired evidence");
        sqlx::query(
            "UPDATE vm_day2_operations SET plan_json = $2::jsonb WHERE id = $1 AND status = 'Locked'",
        )
        .bind(uuid::Uuid::parse_str(&id).expect("uuid"))
        .bind(&expired_json)
        .execute(pool)
        .await
        .expect("seed expired lock");

        expired.status = ryuki_engine::models::VmChangeStatus::Executed;
        let applied = crate::repos::vm_day2_operations::execute_transition(pool, &expired)
            .await
            .expect("execute transition");
        assert!(!applied, "expired lock must fail the database-clock CAS");
        let persisted = crate::repos::vm_day2_operations::get(pool, &id)
            .await
            .expect("get")
            .expect("operation");
        assert_eq!(
            persisted.status,
            ryuki_engine::models::VmChangeStatus::Locked
        );
        cleanup(pool, &id).await;
    }

    /// Missing id must return 404.
